        private class CartEntry
        {
            public string Shortname = "";
            public int ItemId;
            public int Amount;
            public ulong SkinId;
            public string DisplayName = "";

            public bool Blueprint;

            public Item GetItem(ItemDefinition def)
            {
                Item item;
                if (Blueprint)
                {
                    if (def?.Blueprint == null)
                        return null;
                    item = ItemManager.Create(ItemManager.blueprintBaseDef, Mathf.Max(1, Amount), 0uL);
                    if (item == null)
                        return null;
                    item.blueprintTarget = def.itemid;
                }
                else
                {
                    item = ItemManager.CreateByItemID(ItemId, Mathf.Max(1, Amount), SkinId);
                    if (item == null)
                        return null;
                    var baseName = def != null ? ItemName(def) : "";
                    if (!string.IsNullOrEmpty(DisplayName) && DisplayName != baseName)
                        item.name = DisplayName;
                }

                return item;
            }
        }

