        #region Logging

        private class Logger
        {
            private readonly List<LogLine> _lines = new();

            private readonly object _lock = new();

            public volatile int Cap = ConsoleMax;

            public LogLine Add(LogCategory cat, string text)
            {
                if (string.IsNullOrEmpty(text))
                    return null;
                text = text.Replace("\n", " ").Replace("\r", " ");
                if (text.Length > 220)
                    text = text.Substring(0, 220);
                var now = DateTime.Now;
                var line = new LogLine { Time = now.ToString("HH:mm:ss"), Date = now.ToString("dd.MM.yyyy"), Cat = cat, Text = text };
                lock (_lock)
                {
                    _lines.Add(line);
                    Trim();
                }

                return line;
            }

            public void ReplaceAll(IEnumerable<LogLine> lines)
            {
                lock (_lock)
                {
                    _lines.Clear();
                    _lines.AddRange(lines);
                    Trim();
                }
            }

            public void Clear()
            {
                lock (_lock) _lines.Clear();
            }

            public void SetCap(int cap)
            {
                Cap = cap;
                lock (_lock) Trim();
            }

            private void Trim()
            {
                var over = _lines.Count - Cap;
                if (over > 0)
                    _lines.RemoveRange(0, over);
            }

            public List<LogLine> Snapshot(string tab)
            {
                lock (_lock)
                {
                    IEnumerable<LogLine> q = _lines;
                    switch (tab)
                    {
                        case "chat":
                        {
                            q = q.Where(l => l.Cat == LogCategory.Chat);
                            break;
                        }
                        case "cmd":
                        {
                            q = q.Where(l => l.Cat == LogCategory.Cmd);
                            break;
                        }
                        case "conn":
                        {
                            q = q.Where(l => l.Cat == LogCategory.Join || l.Cat == LogCategory.Leave);
                            break;
                        }
                        case "err":
                        {
                            q = q.Where(l => l.Cat == LogCategory.Err || l.Cat == LogCategory.Warn);
                            break;
                        }
                    }

                    return q.ToList();
                }
            }

            public int Count
            {
                get
                {
                    lock (_lock) return _lines.Count;
                }
            }

            public static string Hex(LogCategory cat) => cat switch
            {
                LogCategory.Chat => Colors.LogChat,
                LogCategory.Cmd => Colors.LogCmd,
                LogCategory.Join => Colors.LogJoin,
                LogCategory.Leave => Colors.LogLeave,
                LogCategory.Err => Colors.LogErr,
                LogCategory.Warn => Colors.LogWarn,
                _ => Colors.LogOther
            };

            public static string Tag(LogCategory cat) => cat switch
            {
                LogCategory.Chat => "CHAT",
                LogCategory.Cmd => "CMD",
                LogCategory.Join => "JOIN",
                LogCategory.Leave => "LEAVE",
                LogCategory.Err => "ERR",
                LogCategory.Warn => "WARN",
                _ => "LOG"
            };
        }

