        #region Discord bridge

        private sealed class DiscordBridge
        {
            private readonly Func<Oxide.Core.Plugins.Plugin> _resolve;
            public DiscordBridge(Func<Oxide.Core.Plugins.Plugin> resolve) => _resolve = resolve;
            private Oxide.Core.Plugins.Plugin C => _resolve();

            public bool Loaded => C != null;

            public readonly List<string[]> Roles = new();
            public readonly List<string[]> Channels = new();
            public readonly List<string[]> Guilds = new();

            public void RequestSync() => C?.Call("API_RequestSync");

            public void BotChat(string channelId, string name, string steamId, string message) =>
                C?.Call("API_BotChat", channelId, name, steamId, message);

            public void BotSend(string channelId, string title, string desc, string content, string thumbUrl) =>
                C?.Call("API_BotSend", channelId, title, desc, content, thumbUrl);

            public void BotReconnect() => C?.Call("API_BotReconnect");
            public void BotEnabled(bool on) => C?.Call(on ? "API_BotConnect" : "API_BotDisconnect");
            public void UpdateStatus() => C?.Call("API_UpdateStatus");
        }

