        #region Components

        internal class PaConsoleComponent : FacepunchBehaviour
        {
            private PowerfulAdmin _plugin;
            private BasePlayer _player;

            public void Init(PowerfulAdmin plugin, BasePlayer player)
            {
                _plugin = plugin;
                _player = player;
                StartCoroutine(Loop());
            }

            private IEnumerator Loop()
            {
                var wait = new WaitForSeconds(2f);
                while (true)
                {
                    yield return wait;
                    var keepTicking = true;
                    try
                    {
                        keepTicking = _plugin != null && _player != null && _plugin.NeedsRefreshUiFor(_player);
                    }
                    catch (Exception ex)
                    {
                        _plugin?.PrintWarning($"Console tick failed: {ex.Message}");
                    }

                    if (!keepTicking)
                    {
                        UnityEngine.Object.Destroy(this);
                        yield break;
                    }
                }
            }
        }

        internal class PaHammerComponent : FacepunchBehaviour
        {
            private PowerfulAdmin _plugin;
            private BasePlayer _player;
            private float _accum;

            public void Init(PowerfulAdmin plugin, BasePlayer player)
            {
                _plugin = plugin;
                _player = player;
            }

            private void Update()
            {
                if (_plugin == null || _player == null)
                    return;
                if (!_plugin.Hammer.Allowed(_player))
                {
                    UnityEngine.Object.Destroy(this);
                    return;
                }

                _accum += UnityEngine.Time.deltaTime;
                if (_accum < _plugin.Hammer.Interval())
                    return;
                _accum = 0f;
                try
                {
                    _plugin.Hammer.Tick(_player);
                }
                catch (Exception ex)
                {
                    _plugin?.PrintWarning($"Hammer tick failed: {ex.Message}");
                }
            }

            private void OnDestroy()
            {
                try
                {
                    _plugin?.ClearHammerHud(_player);
                }
                catch (Exception ex)
                {
                    _plugin?.PrintWarning($"Hammer hud cleanup failed: {ex.Message}");
                }
            }
        }

        internal class PaInspectComponent : FacepunchBehaviour
        {
            private PowerfulAdmin _plugin;
            private BasePlayer _player;
            private float _accum;

            public void Init(PowerfulAdmin plugin, BasePlayer player)
            {
                _plugin = plugin;
                _player = player;
            }

            private void Update()
            {
                if (_plugin == null || _player == null)
                    return;
                if (!_plugin.IsInspectAllowed(_player))
                {
                    _plugin.ClearInspectHint(_player);
                    UnityEngine.Object.Destroy(this);
                    return;
                }

                _accum += UnityEngine.Time.deltaTime;
                if (_accum < 0.15f)
                    return;
                _accum = 0f;
                try
                {
                    _plugin.InspectHover(_player);
                }
                catch (Exception ex)
                {
                    _plugin?.PrintWarning($"Inspect hover failed: {ex.Message}");
                }
            }

            private void OnDestroy()
            {
                try
                {
                    _plugin?.ClearInspectHint(_player);
                }
                catch (Exception ex)
                {
                    _plugin?.PrintWarning($"Inspect hint cleanup failed: {ex.Message}");
                }
            }
        }

        internal class PaEspComponent : FacepunchBehaviour
        {
            private struct EspMatch
            {
                public BaseEntity Entity;
                public float Distance;
                public Color Color;
                public string Tag;

                public EspMatch(BaseEntity entity, float distance, Color color, string tag)
                {
                    Entity = entity;
                    Distance = distance;
                    Color = color;
                    Tag = tag;
                }
            }

            private PowerfulAdmin _plugin;
            private BasePlayer _player;

            private readonly List<BaseEntity> _entityBuffer = new();
            private readonly List<CollectibleEntity> _collectibleBuffer = new();
            private readonly List<EspMatch> _matchBuffer = new();

            public void Init(PowerfulAdmin plugin, BasePlayer player)
            {
                _plugin = plugin;
                _player = player;
                StartCoroutine(Loop());
            }

            private IEnumerator Loop()
            {
                var interval = _plugin?.EspInterval() ?? 0.6f;
                var wait = new WaitForSeconds(interval);
                while (true)
                {
                    try
                    {
                        EspTick();
                    }
                    catch (Exception ex)
                    {
                        _plugin?.PrintWarning($"Esp tick failed: {ex.Message}");
                    }

                    var next = _plugin?.EspInterval() ?? 0.6f;
                    if (Mathf.Abs(next - interval) > 0.001f)
                    {
                        interval = next;
                        wait = new WaitForSeconds(interval);
                    }

                    yield return wait;
                }
            }

            private const float EspLookFast = 0.1f;
            private float _fastLook;

            private void Update()
            {
                if (_plugin == null || _player == null)
                    return;
                _fastLook += UnityEngine.Time.deltaTime;
                if (_fastLook < EspLookFast)
                    return;
                _fastLook = 0f;
                try
                {
                    FastLookLines();
                }
                catch (Exception ex)
                {
                    _plugin?.PrintWarning($"Esp look lines failed: {ex.Message}");
                }
            }

            private void FastLookLines()
            {
                var admin = _player;
                if (!_plugin.IsEspAllowed(admin) || !_plugin.GetToggle(admin, "e.on", false) ||
                    !_plugin.GetToggle(admin, "e.players", true))
                    return;
                var radius = Mathf.Clamp01(_plugin.GetSlider(admin, FieldKey.EspRadius, 0.5f)) * 500f;
                var origin = admin.transform.position;
                var duration = EspLookFast * 1.6f;
                var colAdmin = _plugin.EspColor(admin, "e.admin");
                var colTeam = _plugin.EspColor(admin, "e.team");
                var colEnemy = _plugin.EspColor(admin, "e.players");
                foreach (var t in BasePlayer.activePlayerList)
                {
                    if (t == null || t == admin || t.IsSleeping() || !t.IsConnected)
                        continue;
                    if (Vector3Ex.Distance2D(origin, t.transform.position) > radius)
                        continue;
                    var vanished = _plugin.PeekAdmin(t.userID)?.Vanished == true;
                    if (vanished && !_plugin.GetToggle(t, "v.silhouette", true))
                        continue;
                    var col = vanished ? SilColor(_plugin.GetSelect(t, FieldKey.VanishSilcolor, "orange")) :
                        t.IsAdmin ? colAdmin :
                        admin.currentTeam != 0 && admin.currentTeam == t.currentTeam ? colTeam : colEnemy;
                    EspLookLine(admin, duration, col, t);
                }
            }

            private void EspTick()
            {
                var admin = _player;
                if (_plugin == null || !_plugin.IsEspAllowed(admin))
                    return;
                var duration = _plugin.EspInterval() * 1.15f;
                var radius = Mathf.Clamp01(_plugin.GetSlider(admin, FieldKey.EspRadius, 0.5f)) * 500f;
                var origin = admin.transform.position;
                var showDist = _plugin.GetToggle(admin, "e.dist", true);
                var showHp = _plugin.GetToggle(admin, "e.hp", true);
                var showHeld = _plugin.GetToggle(admin, "e.held", false);
                var colAdmin = _plugin.EspColor(admin, "e.admin");
                var colTeam = _plugin.EspColor(admin, "e.team");
                var colEnemy = _plugin.EspColor(admin, "e.players");

                if (_plugin.GetToggle(admin, "e.players", true))
                    foreach (var t in BasePlayer.activePlayerList)
                    {
                        if (t == null || t == admin || t.IsSleeping() || !t.IsConnected)
                            continue;
                        var d = Vector3Ex.Distance2D(origin, t.transform.position);
                        if (d > radius)
                            continue;
                        var vanished = _plugin.PeekAdmin(t.userID)?.Vanished == true;
                        if (vanished && !_plugin.GetToggle(t, "v.silhouette", true))
                            continue;
                        var col = vanished ? SilColor(_plugin.GetSelect(t, FieldKey.VanishSilcolor, "orange")) :
                            t.IsAdmin ? colAdmin :
                            admin.currentTeam != 0 && admin.currentTeam == t.currentTeam ? colTeam : colEnemy;
                        var nm = vanished
                            ? t.displayName + " " + _plugin.GetLocalizedMessage(TranslateKey.EspVanishTag, admin)
                            : t.displayName;
                        EspDrawTarget(admin, t.transform.position, nm, t, d, col, showDist, showHp, showHeld, duration);
                    }

#if DEBUG_SERVER
                if (_plugin.GetToggle(admin, "e.players", true))
                    DebugEspTargets(admin, duration, showDist, showHp, showHeld);
#endif

                if (_plugin.GetToggle(admin, "e.sleepers", false))
                    foreach (var t in BasePlayer.sleepingPlayerList)
                    {
                        if (t == null)
                            continue;
                        var d = Vector3Ex.Distance2D(origin, t.transform.position);
                        if (d > radius)
                            continue;
                        EspDrawTarget(admin, t.transform.position, t.displayName + " (sleep)", t, d,
                            _plugin.EspColor(admin, "e.sleepers"), showDist, showHp, false, duration);
                    }

                var wantLoot = _plugin.GetToggle(admin, "e.loot", false);
                var wantBoxes = _plugin.GetToggle(admin, "e.boxes", false);
                var wantTc = _plugin.GetToggle(admin, "e.tc", false);
                var wantBeds = _plugin.GetToggle(admin, "e.beds", false);
                var wantTraps = _plugin.GetToggle(admin, "e.traps", false);
                var wantStash = _plugin.GetToggle(admin, "e.stash", false);
                var wantDrops = _plugin.GetToggle(admin, "e.drops", false);
                var wantNpc = _plugin.GetToggle(admin, "e.npc", false);
                var wantTurret = _plugin.GetToggle(admin, "e.turrets", false);
                var wantVeh = _plugin.GetToggle(admin, "e.vehicles", false);
                var wantNodes = _plugin.GetToggle(admin, "e.nodes", false);
                var wantForage = _plugin.GetToggle(admin, "e.forage", false);
                var wantScan = wantLoot || wantBoxes || wantTc || wantBeds || wantTraps || wantStash || wantDrops ||
                               wantNpc || wantTurret || wantVeh || wantNodes;
                if (wantScan || wantForage)
                {
                    var colTc = _plugin.EspColor(admin, "e.tc");
                    var colTurret = _plugin.EspColor(admin, "e.turrets");
                    var colTrap = _plugin.EspColor(admin, "e.traps");
                    var colBed = _plugin.EspColor(admin, "e.beds");
                    var colStash = _plugin.EspColor(admin, "e.stash");
                    var colLoot = _plugin.EspColor(admin, "e.loot");
                    var colDrops = _plugin.EspColor(admin, "e.drops");
                    var colBoxes = _plugin.EspColor(admin, "e.boxes");
                    var colNpc = _plugin.EspColor(admin, "e.npc");
                    var colVeh = _plugin.EspColor(admin, "e.vehicles");
                    var colNodes = _plugin.EspColor(admin, "e.nodes");
                    var colForage = _plugin.EspColor(admin, "e.forage");

                    var matches = _matchBuffer;
                    matches.Clear();
                    if (wantScan)
                    {
                        var list = _entityBuffer;
                        list.Clear();
                        Vis.Entities(origin, radius, list);

                        foreach (var e in list)
                        {
                            if (e == null)
                                continue;
                            var d = Vector3Ex.Distance2D(origin, e.transform.position);
                            if (wantTc && e is BuildingPrivlidge)
                                matches.Add(new EspMatch(e, d, colTc, "Tool cupboard"));
                            else if (wantTurret && (e is AutoTurret || e is SamSite))
                                matches.Add(new EspMatch(e, d, colTurret, e.ShortPrefabName));
                            else if (wantTraps && (e is BearTrap || e is Landmine || e is GunTrap || e is FlameTurret ||
                                                   e is TeslaCoil))
                                matches.Add(new EspMatch(e, d, colTrap, "Trap"));
                            else if (wantBeds && e is SleepingBag)
                                matches.Add(new EspMatch(e, d, colBed, e.ShortPrefabName));
                            else if (wantStash && e is StashContainer)
                                matches.Add(new EspMatch(e, d, colStash, "Stash"));
                            else if (wantLoot && e is LootContainer)
                                matches.Add(new EspMatch(e, d, colLoot, e.ShortPrefabName));
                            else if (wantDrops && e is DroppedItemContainer)
                                matches.Add(new EspMatch(e, d, colDrops, "Loot Bag"));
                            else if (wantDrops && e is DroppedItem drop)
                                matches.Add(new EspMatch(e, d, colDrops,
                                    drop.item == null ? "Dropped item" : drop.item.info.displayName.english));
                            else if (wantBoxes && e is StorageContainer && e.OwnerID != 0)
                                matches.Add(new EspMatch(e, d, colBoxes, e.ShortPrefabName));
                            else if (wantNpc && (e is BaseNpc || e is BaseNPC2 || e is NPCPlayer))
                                matches.Add(new EspMatch(e, d, colNpc, e.ShortPrefabName));
                            else if (wantVeh && e is BaseVehicle)
                                matches.Add(new EspMatch(e, d, colVeh, e.ShortPrefabName));
                            else if (wantNodes && e is OreResourceEntity)
                                matches.Add(new EspMatch(e, d, colNodes, e.ShortPrefabName));
                        }
                    }

                    if (wantForage && BaseEntity.Query.Server != null)
                    {
                        var collectibles = _collectibleBuffer;
                        collectibles.Clear();
                        BaseEntity.Query.Server.GetInSphere(origin, radius, collectibles);
                        foreach (var c in collectibles)
                        {
                            if (c == null)
                                continue;
                            matches.Add(new EspMatch(c, Vector3Ex.Distance2D(origin, c.transform.position), colForage,
                                c.ShortPrefabName));
                        }
                    }

                    matches.Sort((a, b) => a.Distance.CompareTo(b.Distance));
                    var cap = Mathf.Min(matches.Count, _plugin.EspMaxObjects());
                    for (var i = 0; i < cap; i++)
                    {
                        var m = matches[i];
                        EspBox(admin, duration, m.Color, m.Entity);
                        var label = showDist ? $"{m.Tag} {(int)m.Distance}m" : m.Tag;
                        EspText(admin, duration, m.Color, m.Entity.transform.position + Vector3.up, label);
                    }
                }
            }

            private void EspText(BasePlayer admin, float duration, Color color, Vector3 pos, string text)
            {
                color.a *= Mathf.Clamp01(_plugin.GetSlider(admin, FieldKey.EspTextop,
                    1f));
                var sized = $"<size={_plugin.EspFontSize(admin)}>{text}</size>";
                DDraw.Text(admin, pos, sized, color, duration);
            }

            private void EspBox(BasePlayer admin, float duration, Color color, BaseEntity entity)
            {
                if (entity == null)
                    return;
                var obb = entity.WorldSpaceBounds();
                if (obb.extents.sqrMagnitude < 0.0004f)
                    return;
                color.a *= Mathf.Clamp01(_plugin.GetSlider(admin, FieldKey.EspBoxop,
                    0.7f));
                DDraw.Box(admin, obb.position, obb.extents * 2f, obb.rotation.eulerAngles, color, duration);
            }

            private void EspLookLine(BasePlayer admin, float duration, Color color, BasePlayer target)
            {
                if (target.eyes == null)
                    return;
                var from = target.eyes.position;
                DDraw.Line(admin, from, from + target.eyes.rotation * Vector3.forward * 4f, color, duration);
            }

            private const float EspHeldMaxDistance = 20f;

            private void EspDrawTarget(BasePlayer admin, Vector3 pos, string name, BaseCombatEntity entity, float dist,
                Color col, bool showDist, bool showHp, bool showHeld, float duration)
            {
                var head = pos + new Vector3(0f, 1.8f, 0f);
                if (entity is BasePlayer)
                {
                    var boxCol = col;
                    boxCol.a *= Mathf.Clamp01(_plugin.GetSlider(admin, FieldKey.EspBoxop, 0.7f));
                    DDraw.Box(admin, pos + new Vector3(0f, 0.9f, 0f), new Vector3(0.6f, 1.8f, 0.6f), Vector3.zero,
                        boxCol, duration);
                }
                else if (entity != null)
                {
                    EspBox(admin, duration, col, entity);
                }
                else
                {
                    DDraw.Box(admin, pos + new Vector3(0f, 0.9f, 0f), Vector3.one * 1.8f, Vector3.zero, col, duration);
                }

                var label = name;
                if (showHp && entity != null)
                    label += $"  {Mathf.RoundToInt(entity.health)}hp";
                if (showDist)
                    label += $"  {(int)dist}m";
                EspText(admin, duration, col, head, label);

                if (entity is BasePlayer player && showHeld && dist <= EspHeldMaxDistance)
                {
                    var item = player.GetActiveItem();
                    if (item != null)
                        EspText(admin, duration, col, pos + new Vector3(0f, 0.5f, 0f), item.info.displayName.english);
                }
            }

#if DEBUG_SERVER
            private void DebugEspTargets(BasePlayer admin, float duration, bool showDist, bool showHp, bool showHeld)
            {
                var origin = admin.transform.position;
                var palette = new[] { EspEnemy, EspTeam, EspAdmin };
                for (var i = 0; i < _plugin._debugBots.Count; i++)
                {
                    var e = _plugin._debugBots[i];
                    if (e == null || e.IsDestroyed)
                        continue;
                    var player = e as BasePlayer;
                    var pos = e.transform.position;
                    var d = Vector3.Distance(origin, pos);
                    var nm = player != null && !string.IsNullOrEmpty(player.displayName) ? player.displayName : "Bot";
                    EspDrawTarget(admin, pos, nm, player, d, palette[i % palette.Length], showDist, showHp, showHeld, duration);
                }
            }
#endif
        }

        internal class PaVanishComponent : FacepunchBehaviour
        {
            private BasePlayer _player;
            private GameObject _probe;
            private float _tempMin;
            private float _tempMax;
            private float _radMax;
            private float _oxygenMin;
            private float _wetnessMax;
            private float _caloriesMin;
            private float _hydrationMin;
            private bool _frozen;

            public void Init(BasePlayer player)
            {
                _player = player;
                if (_player == null)
                    return;
                _player.limitNetworking = true;
                _player.DisablePlayerCollider();
                _player.isInvisible = true;
                if (!BasePlayer.invisPlayers.Contains(_player))
                    BasePlayer.invisPlayers.Add(_player);
                try
                {
                    BaseEntity.Query.Server?.RemovePlayer(_player);
                }
                catch (Exception ex)
                {
                    Instance?.PrintWarning($"Vanish: removing the player from the entity query failed: {ex.Message}");
                }

                Rust.Ai.SimpleAIMemory.AddIgnorePlayer(_player);
                ForgetAi(_player);
                FreezeMetabolism();
                CreateProbe();

                var connections = Facepunch.Pool.Get<List<Connection>>();
                foreach (var con in Net.sv.connections)
                    if (con.connected && con.isAuthenticated && con.player is BasePlayer && con.player != _player)
                        connections.Add(con);
                _player.OnNetworkSubscribersLeave(connections);
                Facepunch.Pool.FreeUnmanaged(ref connections);
                if (ServerOcclusion.OcclusionEnabled)
                    _player.OcclusionMakeSubscribersForget();

                _player.SendNetworkUpdate();
            }

            private const float AiForgetRange = 150f;

            private static readonly BaseEntity[] Brains = new BaseEntity[256];

            private static void ForgetAi(BasePlayer player)
            {
                var query = BaseEntity.Query.Server;
                if (query == null)
                    return;
                var count = query.GetBrainsInSphereFast(player.transform.position, AiForgetRange, Brains);
                for (var i = 0; i < count; i++)
                {
                    var entity = Brains[i];
                    if (entity == null)
                        continue;
                    var brain = entity.GetComponent<BaseAIBrain>();
                    if (brain == null || brain.Senses == null || brain.Senses.Memory == null)
                        continue;
                    var memory = brain.Senses.Memory;
                    memory.Players.Remove(player);
                    memory.Targets.Remove(player);
                    memory.Threats.Remove(player);
                    memory.Friendlies.Remove(player);
                    memory.LOS.Remove(player);
                    for (var j = memory.All.Count - 1; j >= 0; j--)
                        if (memory.All[j].Entity == player)
                            memory.All.RemoveAt(j);
                }
            }

            internal void CreateProbe()
            {
                if (_probe != null || _player == null || _player.IsSpectating())
                    return;
                _probe = new GameObject("pa.vanish.probe");
                _probe.transform.SetParent(_player.transform, false);
                _probe.transform.localPosition = Vector3.up;
                _probe.layer = (int)Rust.Layer.Reserved1;
                var sphere = _probe.AddComponent<SphereCollider>();
                sphere.isTrigger = true;
                sphere.radius = 0.5f;
            }

            private void FreezeMetabolism()
            {
                var metabolism = _player == null ? null : _player.metabolism;
                if (metabolism == null || _frozen)
                    return;
                _frozen = true;
                _tempMin = metabolism.temperature.min;
                _tempMax = metabolism.temperature.max;
                _radMax = metabolism.radiation_poison.max;
                _oxygenMin = metabolism.oxygen.min;
                _wetnessMax = metabolism.wetness.max;
                _caloriesMin = metabolism.calories.min;
                _hydrationMin = metabolism.hydration.min;
                metabolism.temperature.min = 20f;
                metabolism.temperature.max = 20f;
                metabolism.temperature.value = 20f;
                metabolism.radiation_level.value = 0f;
                metabolism.radiation_poison.value = 0f;
                metabolism.radiation_poison.max = 0f;
                metabolism.oxygen.min = 1f;
                metabolism.oxygen.value = 1f;
                metabolism.wetness.max = 0f;
                metabolism.wetness.value = 0f;
                metabolism.calories.min = metabolism.calories.value;
                metabolism.hydration.min = Mathf.Max(0f, metabolism.hydration.value - 1f);
                metabolism.SendChanges();
            }

            private void ThawMetabolism()
            {
                var metabolism = _player == null ? null : _player.metabolism;
                if (metabolism == null || !_frozen)
                    return;
                _frozen = false;
                metabolism.temperature.min = _tempMin;
                metabolism.temperature.max = _tempMax;
                metabolism.radiation_poison.max = _radMax;
                metabolism.oxygen.min = _oxygenMin;
                metabolism.wetness.max = _wetnessMax;
                metabolism.calories.min = _caloriesMin;
                metabolism.hydration.min = _hydrationMin;
                metabolism.timeSinceLastMetabolism = 0f;
                metabolism.SendChanges();
            }

            private void OnTriggerEnter(Collider col)
            {
                if (_player == null || col == null)
                    return;
                var parent = col.GetComponentInParent<TriggerParent>();
                if (parent == null)
                    return;
                parent.OnTriggerEnter(_player.playerCollider);
            }

            private void OnTriggerExit(Collider col)
            {
                if (_player == null || col == null)
                    return;
                var parent = col.GetComponentInParent<TriggerParent>();
                if (parent == null)
                    return;
                parent.OnTriggerExit(_player.playerCollider);
            }

            private void OnDestroy()
            {
                if (_probe != null)
                    Destroy(_probe);
                _probe = null;
                if (_player == null)
                    return;
                try
                {
                    ThawMetabolism();
                    Rust.Ai.SimpleAIMemory.RemoveIgnorePlayer(_player);
                    _player.isInvisible = false;
                    BasePlayer.invisPlayers.Remove(_player);
                    try
                    {
                        BaseEntity.Query.Server?.RemovePlayer(_player);
                        BaseEntity.Query.Server?.AddPlayer(_player);
                    }
                    catch (Exception ex)
                    {
                        Instance?.PrintWarning($"Vanish: restoring the player in the entity query failed: {ex.Message}");
                    }

                    _player.limitNetworking = false;
                    _player.EnablePlayerCollider();
                    if (_player.IsConnected)
                    {
                        _player.UpdateNetworkGroup();
                        _player.SendNetworkUpdate();
                    }
                }
                catch (Exception ex)
                {
                    Instance?.PrintWarning($"Vanish restore failed: {ex.Message}");
                }
            }
        }

