        #region Harmony patches

        [HarmonyPatch(typeof(BasePlayer), nameof(BasePlayer.Server_RequestMarkers))]
        private static class MapOpenedPatch
        {
            [HarmonyPostfix]
            private static void Postfix(BasePlayer __instance)
            {
                if (__instance != null)
                    Instance?.ShowNoteHint(__instance);
            }
        }

        [HarmonyPatch(typeof(BasePlayer), nameof(BasePlayer.IsGod))]
        private static class IsGodPatch
        {
            [HarmonyPostfix]
            private static void Postfix(BasePlayer __instance, ref bool __result)
            {
                if (__instance != null && GodActive.Contains(__instance.userID))
                    __result = true;
            }
        }

        private static bool IsHiddenId(ulong id)
        {
            var hidden = BasePlayer.invisPlayers;
            for (var i = 0; i < hidden.Count; i++)
            {
                var player = hidden[i];
                if (player != null && player.userID == id)
                    return true;
            }

            return false;
        }

        [HarmonyPatch(typeof(BaseEntity), nameof(BaseEntity.SignalBroadcast), typeof(BaseEntity.Signal),
            typeof(string), typeof(Connection), typeof(string), typeof(float))]
        private static class VanishSignalPatch
        {
            [HarmonyPrefix]
            private static bool Prefix(Connection sourceConnection)
            {
                if (sourceConnection == null)
                    return true;
                return !IsHiddenId(sourceConnection.userid);
            }
        }

        [HarmonyPatch(typeof(BaseNetworkable), nameof(BaseNetworkable.GetConnectionsWithin), typeof(Vector3),
            typeof(float), typeof(bool))]
        private static class VanishHearingPatch
        {
            [HarmonyPrefix]
            private static void Prefix(ref bool includeInvisPlayers)
            {
                if (BasePlayer.invisPlayers.Count > 0)
                    includeInvisPlayers = true;
            }
        }

        [HarmonyPatch(typeof(Effect.server), nameof(Effect.server.ImpactEffect), typeof(HitInfo), typeof(string))]
        private static class VanishImpactPatch
        {
            [HarmonyPrefix]
            private static bool Prefix(HitInfo info)
            {
                var attacker = info?.InitiatorPlayer;
                return attacker == null || !attacker.isInvisible;
            }
        }

        [HarmonyPatch(typeof(EffectNetwork), nameof(EffectNetwork.Send), typeof(Effect), typeof(EntityNetworkRange))]
        private static class VanishEffectPatch
        {
            [HarmonyPrefix]
            private static bool Prefix(Effect effect)
            {
                if (effect == null || effect.source == 0)
                    return true;
                return !IsHiddenId(effect.source);
            }
        }

        [HarmonyPatch(typeof(AntiHack), nameof(AntiHack.ShouldIgnore))]
        private static class NoclipAntiHackPatch
        {
            [HarmonyPostfix]
            private static void Postfix(BasePlayer ply, ref bool __result)
            {
                if (ply != null && NoclipActive.Contains(ply.userID))
                    __result = true;
            }
        }

