        #region Database

        private sealed class Db
        {
            private readonly Oxide.Core.Plugins.Plugin _owner;
            private readonly string _sqliteFile;
            private readonly MySqlConf _mysqlConf;
            private readonly Action<LogCategory, string> _log;
            private Oxide.Core.SQLite.Libraries.SQLite _sqlite;
            private Oxide.Core.MySql.Libraries.MySql _mysql;
            private DbConnection _closing;
            private int _pending;

            public DataStorage Backend { get; }
            public bool IsSql => Backend is DataStorage.Sqlite or DataStorage.MySql;
            public DbConnection Conn { get; private set; }

            public Db(DataStorage backend, Oxide.Core.Plugins.Plugin owner, string sqliteFile, MySqlConf mysqlConf,
                Action<LogCategory, string> log)
            {
                Backend = backend;
                _owner = owner;
                _sqliteFile = sqliteFile;
                _mysqlConf = mysqlConf;
                _log = log;
            }

            private Oxide.Core.SQLite.Libraries.SQLite Sqlite =>
                _sqlite ??= Interface.Oxide.GetLibrary<Oxide.Core.SQLite.Libraries.SQLite>();

            private Oxide.Core.MySql.Libraries.MySql Mysql =>
                _mysql ??= Interface.Oxide.GetLibrary<Oxide.Core.MySql.Libraries.MySql>();

            public bool Open()
            {
                if (!IsSql)
                    return true;
                try
                {
                    Conn = Backend == DataStorage.Sqlite
                        ? Sqlite.OpenDb(_sqliteFile, null, true)
                        : Mysql.OpenDb(_mysqlConf.Host, _mysqlConf.Port, _mysqlConf.Database,
                            _mysqlConf.User, _mysqlConf.Password, _owner, true);
                }
                catch (Exception ex)
                {
                    Conn = null;
                    _log?.Invoke(LogCategory.Err, $"DB open ({Backend}) failed: {ex.Message}");
                }

                return Conn != null;
            }

            public void Close()
            {
                if (Conn == null)
                    return;
                _closing = Conn;
                Conn = null;
                if (_pending == 0)
                    CloseNow();
            }

            private void CloseNow()
            {
                var conn = _closing;
                _closing = null;
                if (conn == null)
                    return;
                try
                {
                    if (Backend == DataStorage.Sqlite)
                        Sqlite.CloseDb(conn);
                    else if (Backend == DataStorage.MySql)
                        Mysql.CloseDb(conn);
                }
                catch (Exception ex)
                {
                    Instance?.PrintWarning($"Closing the database connection failed: {ex.Message}");
                }
            }

            private void Done()
            {
                if (--_pending > 0)
                    return;
                if (_closing != null)
                    CloseNow();
            }

            public void Query(Sql sql, Action<List<Dictionary<string, object>>> cb)
            {
                var safe = WrapRows(cb);
                if (!IsSql || Conn == null)
                {
                    safe(null);
                    return;
                }

                _pending++;
                try
                {
                    if (Backend == DataStorage.Sqlite)
                        Sqlite.Query(sql, Conn, rows =>
                        {
                            Done();
                            if (Instance == _owner)
                                safe(rows);
                        });
                    else
                        Mysql.Query(sql, Conn, rows =>
                        {
                            Done();
                            if (Instance == _owner)
                                safe(rows);
                        });
                }
                catch (Exception ex)
                {
                    _log?.Invoke(LogCategory.Err, $"DB query ({Backend}) failed: {ex.Message}");
                    Done();
                    safe(null);
                }
            }

            public void NonQuery(Sql sql, Action<int> cb = null)
            {
                if (!IsSql || Conn == null)
                {
                    cb?.Invoke(0);
                    return;
                }

                _pending++;
                try
                {
                    if (Backend == DataStorage.Sqlite)
                        Sqlite.ExecuteNonQuery(sql, Conn, rows =>
                        {
                            Done();
                            if (Instance != null)
                                cb?.Invoke(rows);
                        });
                    else
                        Mysql.ExecuteNonQuery(sql, Conn, rows =>
                        {
                            Done();
                            if (Instance != null)
                                cb?.Invoke(rows);
                        });
                }
                catch (Exception ex)
                {
                    _log?.Invoke(LogCategory.Err, $"DB nonquery ({Backend}) failed: {ex.Message}");
                    Done();
                    cb?.Invoke(0);
                }
            }

            public void Upsert(string table, string key, string data)
            {
                var q = Backend == DataStorage.MySql
                    ? $"INSERT INTO {table} (steamid, data) VALUES (@0, @1) ON DUPLICATE KEY UPDATE data = @1"
                    : $"INSERT OR REPLACE INTO {table} (steamid, data) VALUES (@0, @1)";
                NonQuery(Sql.Builder.Append(q, key, data));
            }

            private Action<List<Dictionary<string, object>>> WrapRows(Action<List<Dictionary<string, object>>> cb) =>
                rows =>
                {
                    try
                    {
                        cb?.Invoke(rows ?? new List<Dictionary<string, object>>());
                    }
                    catch (Exception ex)
                    {
                        _log?.Invoke(LogCategory.Err, $"DB callback ({Backend}) failed: {ex.Message}");
                    }
                };
        }

