        private sealed class EconomyProvider
        {
            public string Name;
            public Func<Plugin> Plugin;
            public string GetHook;
            public string AddHook;
            public string TakeHook;
            public string SetHook;
            public string CanTakeHook;
            public bool WritesReturnBool;
            public bool IntegerCurrency;
            public bool PlayerArg;
            public bool DisplayCeil;
            public bool HasPoints;
            public string PointsAddHook;
            public int BalanceIndex = -1;
            public object[] AddExtraArgs;
            public object[] TakeExtraArgs;

            public bool Available() => Plugin()?.IsLoaded == true;

            private object Subject(ulong id) => PlayerArg ? BasePlayer.FindByID(id) : id;

            public double Balance(ulong id)
            {
                var raw = Plugin()?.Call(GetHook, id);
                if (BalanceIndex >= 0)
                {
                    if (!(raw is object[] parts) || parts.Length <= BalanceIndex || parts[BalanceIndex] == null)
                        return 0;
                    raw = parts[BalanceIndex];
                }

                return raw == null ? 0 : Convert.ToDouble(raw);
            }

            private object Amount(double value) => IntegerCurrency ? (object)(int)value : value;

            private static object[] Args(object subject, object amount, object[] extra)
            {
                if (extra == null || extra.Length == 0)
                    return new[] { subject, amount };
                var args = new object[extra.Length + 2];
                args[0] = subject;
                args[1] = amount;
                Array.Copy(extra, 0, args, 2, extra.Length);
                return args;
            }

            public bool Add(ulong id, double amount)
            {
                var subject = Subject(id);
                if (subject == null)
                    return false;
                var before = Balance(id);
                var result = Plugin()?.Call(AddHook, Args(subject, Amount(amount), AddExtraArgs));
                if (WritesReturnBool)
                    return result is bool ok && ok;
                return Balance(id) > before;
            }

            public bool Take(ulong id, double amount)
            {
                var subject = Subject(id);
                if (subject == null)
                    return false;
                if (CanTakeHook != null && Plugin()?.Call(CanTakeHook, id, (int)amount) is bool allowed && !allowed)
                    return false;
                var before = Balance(id);
                var result = Plugin()?.Call(TakeHook, Args(subject, Amount(amount), TakeExtraArgs));
                if (WritesReturnBool)
                    return result is bool ok && ok;
                return Balance(id) < before;
            }

            public bool Set(ulong id, double amount)
            {
                if (SetHook != null)
                    return Plugin()?.Call(SetHook, id, amount) is bool r && r;
                var delta = amount - Balance(id);
                if (delta > 0)
                    return Add(id, delta);
                if (delta < 0)
                    return Take(id, -delta);
                return true;
            }

            public bool AddPoints(ulong id, int amount)
            {
                var subject = Subject(id);
                var plugin = Plugin();
                if (subject == null || PointsAddHook == null || plugin == null)
                    return false;
                plugin.Call(PointsAddHook, subject, amount);
                return true;
            }
        }

        private sealed class MapTool
        {
            public readonly struct MapOwnedPoint
            {
                public readonly Vector3 Position;
                public readonly ulong NetId;
                public readonly ulong[] OwnerIds;

                public MapOwnedPoint(Vector3 position, ulong netId, ulong[] ownerIds)
                {
                    Position = position;
                    NetId = netId;
                    OwnerIds = ownerIds;
                }
            }

            private readonly PowerfulAdmin _plugin;

            public MapTool(PowerfulAdmin plugin)
            {
                _plugin = plugin;
            }

            public void Track(BaseNetworkable entity)
            {
                if (entity is StashContainer stash)
                    _stashes.Add(stash);
                if (entity is RHIB rhib)
                    _rhibs.Add(rhib);
                if (entity is ExcavatorSignalComputer signal)
                    _signals.Add(signal);
                if (entity is DeepSeaFloatingCity city)
                    _cities.Add(city);
                if (entity is RidableHorse horse)
                    _horses.Add(horse);
                else if (entity is PlayerHelicopter || entity is HotAirBalloon)
                    _air.Add((BaseEntity)entity);
                else if (entity is BaseVehicle vehicle && !(entity is CH47Helicopter))
                    _cars.Add(vehicle);
            }

            public void Untrack(BaseNetworkable entity)
            {
                if (entity is StashContainer stash)
                    _stashes.Remove(stash);
                if (entity is RHIB rhib)
                    _rhibs.Remove(rhib);
                if (entity is ExcavatorSignalComputer signal)
                    _signals.Remove(signal);
                if (entity is DeepSeaFloatingCity city)
                    _cities.Remove(city);
                if (entity is RidableHorse horse)
                    _horses.Remove(horse);
                else if (entity is PlayerHelicopter || entity is HotAirBalloon)
                    _air.Remove((BaseEntity)entity);
                else if (entity is BaseVehicle vehicle && !(entity is CH47Helicopter))
                    _cars.Remove(vehicle);
            }

            public void BeginFrame() => _mapBudget = MapDrawBudget;

            private readonly List<HeatPoint> _heatPvp = new();
            private readonly List<HeatPoint> _heatRaid = new();

            public struct HeatPoint
            {
                public Vector3 Position;
                public float Time;

                public HeatPoint(Vector3 position)
                {
                    Position = position;
                    Time = UnityEngine.Time.realtimeSinceStartup;
                }
            }

            public const int HeatCap = 3000;

            public float HeatWindow() =>
                Mathf.Max(1f, ParseNumber(_plugin.GetInput(null, FieldKey.SecHeatWindow, "60"), 60f)) * 60f;

            public void HeatAdd(List<HeatPoint> into, Vector3 position)
            {
                into.Add(new HeatPoint(position));
                if (into.Count > HeatCap)
                    into.RemoveRange(0, into.Count - HeatCap);
            }

            public void HeatPvp(List<Vector3> into) => HeatCollect(_heatPvp, into);

            public void HeatRaid(List<Vector3> into) => HeatCollect(_heatRaid, into);

            public void HeatCollect(List<HeatPoint> from, List<Vector3> into)
            {
                var cutoff = UnityEngine.Time.realtimeSinceStartup - HeatWindow();
                var drop = 0;
                for (var i = 0; i < from.Count; i++)
                {
                    if (from[i].Time < cutoff)
                    {
                        drop = i + 1;
                        continue;
                    }

                    into.Add(from[i].Position);
                }

                if (drop > 0)
                    from.RemoveRange(0, drop);
            }

            public void TrackPvp(BasePlayer player, HitInfo info)
            {
                if (player == null || player.IsNpc)
                    return;
                var killer = info?.InitiatorPlayer;
                if (killer == null || killer == player || killer.IsNpc)
                    return;
                HeatAdd(_heatPvp, player.transform.position);
            }

            public void TrackRaid(DecayEntity entity, HitInfo info)
            {
                if (entity == null || info == null)
                    return;
                if (info.damageTypes == null)
                    return;
                if (info.damageTypes.Get(Rust.DamageType.Explosion) <= 0f &&
                    info.damageTypes.Get(Rust.DamageType.Heat) <= 0f)
                    return;
                HeatAdd(_heatRaid, entity.transform.position);
            }

            public uint _mapCrc;
            public bool _mapRendering;
            public readonly HashSet<RidableHorse> _horses = new();
            public readonly HashSet<BaseVehicle> _cars = new();
            public readonly HashSet<BaseEntity> _air = new();
            private readonly List<MapMarkerPoint> _mapHorses = new();
            private readonly List<MapMarkerPoint> _mapCars = new();
            private readonly List<MapMarkerPoint> _mapAir = new();
            private int _horseFrame = -1;
            private int _carFrame = -1;
            private int _airFrame = -1;
            public readonly HashSet<StashContainer> _stashes = new();
            public readonly HashSet<RHIB> _rhibs = new();
            public readonly HashSet<ExcavatorSignalComputer> _signals = new();
            public readonly HashSet<DeepSeaFloatingCity> _cities = new();

            public const float MapMargin = 600f;

            public static float MapScale() => Mathf.Clamp(1024f / World.Size, 0.1f, 4f);

            public static float MapSpan() => World.Size + MapMargin * 2f;

            public static string MapSignature() =>
                $"{World.Seed}:{World.Size}:{World.MapFileName}:m{(int)MapMargin}";

            public void MapImageReady(bool deep)
            {
                foreach (var p in BasePlayer.activePlayerList)
                {
                    if (p == null || !p.IsConnected)
                        continue;
                    var ad = _plugin.PeekAdmin(p.userID);
                    if (ad == null || !ad.UiOpen || ad.MapDeepSea != deep)
                        continue;
                    if (_plugin.GetPage(p) != "map")
                        continue;
                    _plugin.UI_Open(p);
                }
            }

            public void EnsureMapImage()
            {
                if (_mapCrc != 0)
                    return;
                if (_mapRendering)
                    return;
                if (CommunityEntity.ServerInstance == null)
                    return;
                if (_plugin._assets.MapSignature == MapSignature() && _plugin._assets.MapCrc != 0)
                {
                    var cached = FileStorage.server.Get(_plugin._assets.MapCrc, FileStorage.Type.jpg,
                        CommunityEntity.ServerInstance.net.ID);
                    if (cached != null && cached.Length > 0)
                    {
                        _mapCrc = _plugin._assets.MapCrc;
                        return;
                    }
                }

                _mapRendering = true;
                _plugin.NextTick(() =>
                {
                    var started = UnityEngine.Time.realtimeSinceStartup;
                    byte[] bytes = null;
                    try
                    {
                        var scale = MapScale();
                        bytes = MapImageRenderer.Render(out _, out _, out _, scale, true, false,
                            Mathf.RoundToInt(MapMargin * scale));
                    }
                    catch (Exception e)
                    {
                        _plugin.AddLog(LogCategory.Err, "map render failed: " + e.Message);
                    }

                    _mapRendering = false;
                    if (bytes == null || bytes.Length == 0)
                        return;
                    if (_plugin._assets.MapCrc != 0)
                        FileStorage.server.Remove(_plugin._assets.MapCrc, FileStorage.Type.jpg,
                            CommunityEntity.ServerInstance.net.ID);
                    _mapCrc = FileStorage.server.Store(bytes, FileStorage.Type.jpg,
                        CommunityEntity.ServerInstance.net.ID);
                    _plugin._assets.MapCrc = _mapCrc;
                    _plugin._assets.MapSignature = MapSignature();
                    _plugin.SaveAssets();
                    _plugin.AddLog(LogCategory.Info,
                        $"map rendered in {(UnityEngine.Time.realtimeSinceStartup - started).ToString("0.00")}s, {bytes.Length / 1024}kb");
                    MapImageReady(false);
                });
            }

            public const int DeepImageRes = 512;
            public const float DeepSampleTop = 400f;
            public const float DeepSampleRange = 900f;
            public const int DeepRayBudget = 40000;
            public static readonly int DeepMask = DeepLandMask();

            public uint _deepCrc;
            public string _deepSignature = "";
            public bool _deepRendering;

            public static int DeepLandMask()
            {
                Rust.Layer[] layers = { Rust.Layer.Terrain, Rust.Layer.World, Rust.Layer.Default, Rust.Layer.Construction };
                var mask = 0;
                foreach (var layer in layers)
                    mask |= 1 << (int)layer;
                return mask;
            }

            public static string DeepSignature()
            {
                var islands = DeepSeaManager.ServerIslands;
                var hash = 2166136261u;
                var count = 0;
                if (islands != null)
                    for (var i = 0; i < islands.Count; i++)
                    {
                        var island = islands[i];
                        if (island == null)
                            continue;
                        count++;
                        var pos = island.transform.position;
                        hash = (hash ^ (uint)Mathf.RoundToInt(pos.x)) * 16777619u;
                        hash = (hash ^ (uint)Mathf.RoundToInt(pos.z)) * 16777619u;
                    }

                var shoreSize = TerrainTexturing.Instance != null
                    ? TerrainTexturing.Instance.DeepSeaShoreData.ShoreMapSize
                    : 0;
                return $"{World.Seed}:{count}:{hash}:s{shoreSize}:r{DeepImageRes}";
            }

            public void EnsureDeepImage()
            {
                var signature = DeepSignature();
                if (_deepCrc != 0 && _deepSignature == signature)
                    return;

                if (_deepRendering || CommunityEntity.ServerInstance == null || ServerMgr.Instance == null)
                    return;
                if (_deepCrc == 0 && _plugin._assets.DeepSignature == signature && _plugin._assets.DeepCrc != 0)
                {
                    var cached = FileStorage.server.Get(_plugin._assets.DeepCrc, FileStorage.Type.png,
                        CommunityEntity.ServerInstance.net.ID);
                    if (cached != null && cached.Length > 0)
                    {
                        _deepCrc = _plugin._assets.DeepCrc;
                        _deepSignature = signature;
                        return;
                    }
                }

                _deepRendering = true;
                ServerMgr.Instance.StartCoroutine(RenderDeepImage(signature));
            }

            public IEnumerator RenderDeepImage(string signature)
            {
                var started = UnityEngine.Time.realtimeSinceStartup;
                var res = DeepImageRes;
                var bounds = DeepSeaManager.DeepSeaBounds;
                var span = bounds.size.x;
                var step = span / res;
                var originX = bounds.center.x - span * 0.5f;
                var originZ = bounds.center.z - span * 0.5f;
                var texturing = TerrainTexturing.Instance;
                var shore = texturing != null && texturing.DeepSeaShoreData.ShoreDistances.IsCreated;
                var shoreData = shore ? texturing.DeepSeaShoreData : default;
                var distances = new float[res * res];
                var heights = new float[res * res];
                var rays = 0;
                var rects = new List<int[]>();
                if (!shore)
                {
                    var islands = DeepSeaManager.ServerIslands;
                    if (islands != null)
                        for (var i = 0; i < islands.Count; i++)
                        {
                            var island = islands[i];
                            if (island == null || island.IsDestroyed)
                                continue;
                            var box = island.WorldSpaceBounds();
                            rects.Add(new[]
                            {
                                Mathf.Clamp(Mathf.FloorToInt((box.position.x - box.extents.x - 24f - originX) / step), 0,
                                    res - 1),
                                Mathf.Clamp(Mathf.CeilToInt((box.position.x + box.extents.x + 24f - originX) / step), 0,
                                    res - 1),
                                Mathf.Clamp(Mathf.FloorToInt((box.position.z - box.extents.z - 24f - originZ) / step), 0,
                                    res - 1),
                                Mathf.Clamp(Mathf.CeilToInt((box.position.z + box.extents.z + 24f - originZ) / step), 0,
                                    res - 1)
                            });
                        }
                }

                for (var z = 0; z < res; z++)
                {
                    for (var x = 0; x < res; x++)
                    {
                        var index = z * res + x;
                        var world = new Vector3(originX + (x + 0.5f) * step, 0f, originZ + (z + 0.5f) * step);
                        var dist = shore ? shoreData.GetCoarseDistanceToShore(world) : 1f;
                        distances[index] = dist;
                        heights[index] = float.MinValue;
                        var wantRay = shore && dist <= step;
                        if (!shore)
                            foreach (var rect in rects)
                                if (x >= rect[0] && x <= rect[1] && z >= rect[2] && z <= rect[3])
                                {
                                    wantRay = true;
                                    break;
                                }

                        if (!wantRay || rays >= DeepRayBudget)
                            continue;
                        world.y = DeepSampleTop;
                        if (Physics.Raycast(world, Vector3.down, out var hit, DeepSampleRange, DeepMask,
                                QueryTriggerInteraction.Ignore))
                            heights[index] = hit.point.y;
                        rays++;
                    }

                    if (z % 8 == 0)
                        yield return null;
                }

                var pixels = new Color[res * res];
                for (var z = 0; z < res; z++)
                {
                    for (var x = 0; x < res; x++)
                    {
                        var index = z * res + x;
                        var height = heights[index];
                        if (height <= float.MinValue + 1f || height <= 0f)
                        {
                            pixels[index] = DeepWaterColor(distances[index], height);
                            continue;
                        }

                        var left = DeepHeightAt(heights, res, x - 1, z);
                        var right = DeepHeightAt(heights, res, x + 1, z);
                        var down = DeepHeightAt(heights, res, x, z - 1);
                        var up = DeepHeightAt(heights, res, x, z + 1);
                        var normal = new Vector3(left - right, 2f * step, down - up).normalized;
                        pixels[index] = DeepLandColor(height, normal);
                    }

                    if (z % 32 == 0)
                        yield return null;
                }

                byte[] bytes = null;
                try
                {
                    bytes = MapImageRenderer.EncodeToFile(res, res, pixels, false);
                }
                catch (Exception e)
                {
                    _plugin.AddLog(LogCategory.Err, "deep sea render failed: " + e.Message);
                }

                _deepRendering = false;
                if (bytes == null || bytes.Length == 0)
                    yield break;
                if (_plugin._assets.DeepCrc != 0)
                    FileStorage.server.Remove(_plugin._assets.DeepCrc, FileStorage.Type.png,
                        CommunityEntity.ServerInstance.net.ID);
                _deepCrc = FileStorage.server.Store(bytes, FileStorage.Type.png, CommunityEntity.ServerInstance.net.ID);
                _deepSignature = signature;
                _plugin._assets.DeepCrc = _deepCrc;
                _plugin._assets.DeepSignature = signature;
                _plugin.SaveAssets();
                _plugin.AddLog(LogCategory.Info,
                    $"deep sea rendered in {(UnityEngine.Time.realtimeSinceStartup - started).ToString("0.00")}s, {rays} samples, shore {shore}, {bytes.Length / 1024}kb");
                MapImageReady(true);
            }

            public static float DeepHeightAt(float[] heights, int res, int x, int z)
            {
                x = Mathf.Clamp(x, 0, res - 1);
                z = Mathf.Clamp(z, 0, res - 1);
                var h = heights[z * res + x];
                return h <= float.MinValue + 1f ? 0f : h;
            }

            public static Color DeepWaterColor(float shoreDistance, float height)
            {
                var depth = height > float.MinValue + 1f
                    ? Mathf.Clamp01(-height / 40f)
                    : Mathf.Clamp01(shoreDistance / 220f);
                var mix = Vector4.Lerp(MapImageRenderer.WaterColor, MapImageRenderer.OffShoreColor, depth);
                return new Color(mix.x, mix.y, mix.z);
            }

            public static Color DeepLandColor(float height, Vector3 normal)
            {
                var color = MapImageRenderer.SandColor;
                if (height > 2f)
                    color = Vector4.Lerp(color, MapImageRenderer.GrassColor, Mathf.Clamp01((height - 2f) / 8f));
                if (height > 14f)
                    color = Vector4.Lerp(color, MapImageRenderer.ForestColor, Mathf.Clamp01((height - 14f) / 12f));
                if (height > 30f)
                    color = Vector4.Lerp(color, MapImageRenderer.RockColor, Mathf.Clamp01((height - 30f) / 14f));
                if (height > 55f)
                    color = Vector4.Lerp(color, MapImageRenderer.SnowColor, Mathf.Clamp01((height - 55f) / 12f));
                var light = Mathf.Max(Vector3.Dot(normal, MapImageRenderer.SunDirection), 0f);
                color += (light - 0.5f) * 0.65f * color;
                color = (color - MapImageRenderer.Half) * 0.94f + MapImageRenderer.Half;
                color *= 1.05f;
                return new Color(Mathf.Clamp01(color.x), Mathf.Clamp01(color.y), Mathf.Clamp01(color.z));
            }

            public IEnumerator BuildMapRegistry()
            {
                _stashes.Clear();
                _rhibs.Clear();
                _signals.Clear();
                _cities.Clear();
                _horses.Clear();
                _cars.Clear();
                _air.Clear();
                var seen = 0;
                foreach (var net in BaseNetworkable.serverEntities)
                {
                    Track(net);
                    if (++seen % 2000 != 0)
                        continue;
                    yield return null;
                }

                _plugin.AddLog(LogCategory.Info,
                    $"map registry: {_stashes.Count} stashes, {_cars.Count} cars, {_horses.Count} horses, " +
                    $"{_air.Count} aircraft, {_signals.Count} signals");
            }

            public void CollectPrivileges(List<MapOwnedPoint> into)
            {
                if (BuildingManager.server?.buildingDictionary == null)
                    return;
                foreach (var kv in BuildingManager.server.buildingDictionary)
                {
                    var building = kv.Value;
                    if (building?.buildingPrivileges == null)
                        continue;
                    for (var i = 0; i < building.buildingPrivileges.Count; i++)
                    {
                        var tc = building.buildingPrivileges[i];
                        if (tc == null || tc.net == null)
                            continue;
                        into.Add(new MapOwnedPoint(tc.transform.position, tc.net.ID.Value,
                            MapObjectOwners("tc", tc)));
                    }
                }
            }

            public void CollectBags(List<MapOwnedPoint> into)
            {
                for (var i = 0; i < SleepingBag.sleepingBags.Count; i++)
                {
                    var bag = SleepingBag.sleepingBags[i];
                    if (bag == null || bag.net == null || bag.deployerUserID == 0uL)
                        continue;
                    into.Add(new MapOwnedPoint(bag.transform.position, bag.net.ID.Value,
                        MapObjectOwners("bag", bag)));
                }
            }

            public void CollectStashes(List<MapOwnedPoint> into)
            {
                foreach (var stash in _stashes)
                {
                    if (stash == null || stash.net == null)
                        continue;
                    into.Add(new MapOwnedPoint(stash.transform.position, stash.net.ID.Value,
                        MapObjectOwners("st", stash)));
                }
            }

            public const int MapDrawBudget = 900;

            public readonly List<MapOwnedPoint> _mapTc = new();
            public readonly List<MapOwnedPoint> _mapBags = new();
            public readonly List<MapOwnedPoint> _mapStashes = new();
            public readonly List<MapMarkerPoint> _mapMarkersMain = new();
            public readonly List<MapMarkerPoint> _mapMarkersDeep = new();
            public int _tcFrame = -1;
            public int _bagFrame = -1;
            public int _stashFrame = -1;
            public int _markerFrame = -1;
            public int _markerDeepFrame = -1;
            public int _mapBudget;

            public bool MapTake() => _mapBudget-- > 0;

            public List<MapOwnedPoint> MapTcPoints()
            {
                if (_tcFrame == UnityEngine.Time.frameCount)
                    return _mapTc;
                _tcFrame = UnityEngine.Time.frameCount;
                _mapTc.Clear();
                CollectPrivileges(_mapTc);
                return _mapTc;
            }

            public List<MapOwnedPoint> MapBagPoints()
            {
                if (_bagFrame == UnityEngine.Time.frameCount)
                    return _mapBags;
                _bagFrame = UnityEngine.Time.frameCount;
                _mapBags.Clear();
                CollectBags(_mapBags);
                return _mapBags;
            }

            public List<MapOwnedPoint> MapStashPoints()
            {
                if (_stashFrame == UnityEngine.Time.frameCount)
                    return _mapStashes;
                _stashFrame = UnityEngine.Time.frameCount;
                _mapStashes.Clear();
                CollectStashes(_mapStashes);
                return _mapStashes;
            }

            public void InvalidateOwnedPoints(string kind)
            {
                switch (kind)
                {
                    case "tc":
                    {
                        _tcFrame = -1;
                        break;
                    }
                    case "bag":
                    {
                        _bagFrame = -1;
                        break;
                    }
                    case "st":
                    {
                        _stashFrame = -1;
                        break;
                    }
                }
            }

            public List<MapMarkerPoint> HorsePoints(bool deepSea) =>
                VehiclePoints(_horses, deepSea, _mapHorses, ref _horseFrame);

            public List<MapMarkerPoint> CarPoints(bool deepSea) =>
                VehiclePoints(_cars, deepSea, _mapCars, ref _carFrame);

            public List<MapMarkerPoint> AirPoints(bool deepSea) =>
                VehiclePoints(_air, deepSea, _mapAir, ref _airFrame);

            private static List<MapMarkerPoint> VehiclePoints<T>(HashSet<T> source, bool deepSea,
                List<MapMarkerPoint> cache, ref int frame) where T : BaseEntity
            {
                if (frame == UnityEngine.Time.frameCount)
                    return cache;
                frame = UnityEngine.Time.frameCount;
                cache.Clear();
                foreach (var entity in source)
                {
                    if (entity == null || entity.IsDestroyed)
                        continue;
                    var pos = entity.transform.position;
                    if (IsDeepSeaPosition(pos) != deepSea)
                        continue;
                    cache.Add(new MapMarkerPoint(pos, entity.transform.forward, VehicleKind(entity), null));
                    if (cache.Count >= MapPointLimit)
                        break;
                }

                return cache;
            }

            private static MapMarkerKind VehicleKind(BaseEntity entity) => entity switch
            {
                RidableHorse => MapMarkerKind.Horse,
                PlayerHelicopter or HotAirBalloon => MapMarkerKind.Aircraft,
                TrainCar => MapMarkerKind.Train,
                BaseSubmarine => MapMarkerKind.Submarine,
                BaseBoat => MapMarkerKind.Rhib,
                _ => MapMarkerKind.Car
            };

            public List<MapMarkerPoint> MapMarkerPoints(bool deepSea)
            {
                if (deepSea)
                {
                    if (_markerDeepFrame == UnityEngine.Time.frameCount)
                        return _mapMarkersDeep;
                    _markerDeepFrame = UnityEngine.Time.frameCount;
                    _mapMarkersDeep.Clear();
                    CollectMapMarkers(true, _mapMarkersDeep);
                    return _mapMarkersDeep;
                }

                if (_markerFrame == UnityEngine.Time.frameCount)
                    return _mapMarkersMain;
                _markerFrame = UnityEngine.Time.frameCount;
                _mapMarkersMain.Clear();
                CollectMapMarkers(false, _mapMarkersMain);
                return _mapMarkersMain;
            }

            public void CollectMapMarkers(bool deepSea, List<MapMarkerPoint> into)
            {
                CollectMapObjects(deepSea, into);
                var markers = MapMarker.serverMapMarkers;
                for (var i = 0; i < markers.Count; i++)
                {
                    var marker = markers[i];
                    if (marker == null || marker.IsDestroyed || marker.transform == null)
                        continue;
                    var pos = marker.transform.position;
                    if (IsDeepSeaPosition(pos) != deepSea)
                        continue;
                    var kind = MarkerKindOf(marker);
                    if (kind == MapMarkerKind.Other || kind == MapMarkerKind.City)
                        continue;
                    var color = marker is MapMarkerGenericRadius radius
                        ? ColorToRustFormat(new Color(radius.color1.r, radius.color1.g, radius.color1.b,
                            radius.alpha <= 0f ? 1f : radius.alpha))
                        : null;
                    into.Add(new MapMarkerPoint(pos, marker.transform.forward, kind, color));
                    if (into.Count >= MapPointLimit)
                        return;
                }
            }

            public void CollectMapObjects(bool deepSea, List<MapMarkerPoint> into)
            {
                foreach (var city in _cities)
                {
                    if (city == null || city.IsDestroyed)
                        continue;
                    var pos = city.transform.position;
                    if (IsDeepSeaPosition(pos) != deepSea)
                        continue;
                    into.Add(new MapMarkerPoint(pos, city.transform.forward, MapMarkerKind.City, null));
                }

                foreach (var stations in BoatBuildingStation.BBSPerPlayer.Values)
                {
                    if (stations == null)
                        continue;
                    for (var i = 0; i < stations.Count; i++)
                    {
                        var station = stations[i];
                        if (station == null || station.IsDestroyed)
                            continue;
                        var pos = station.transform.position;
                        if (IsDeepSeaPosition(pos) != deepSea)
                            continue;
                        into.Add(new MapMarkerPoint(pos, station.transform.forward, MapMarkerKind.Station, null));
                    }
                }

                if (!deepSea)
                    return;

                foreach (var rhib in _rhibs)
                {
                    if (rhib == null || rhib.IsDestroyed)
                        continue;
                    var pos = rhib.transform.position;
                    if (!IsDeepSeaPosition(pos))
                        continue;
                    into.Add(new MapMarkerPoint(pos, rhib.transform.forward, MapMarkerKind.Rhib, null));
                }

                foreach (var signal in _signals)
                {
                    if (signal == null || signal.IsDestroyed)
                        continue;
                    var pos = signal.transform.position;
                    if (!IsDeepSeaPosition(pos))
                        continue;
                    into.Add(new MapMarkerPoint(pos, signal.transform.forward, MapMarkerKind.Airdrop, null));
                }
            }
        }

