        private enum HammerAction : byte
        {
            None,
            Delete,
            Gibs,
            Parents,
            Unlock,
            Timer,
            Loot
        }

        private sealed class HammerTool
        {
            public sealed class Row
            {
                public string Label = "";
                public string Value = "";
                public string Color = "";
                public int ItemId;
            }

            public sealed class Section
            {
                public string Title = "";
                public readonly List<Row> Rows = new();
                public int Total;
            }

            public sealed class Info
            {
                public string Title = "";
                public string Kind = "";
                public ulong NetId;
                public HammerAction[] Modes = ModesPlain;
                public bool HasLock;
                public string Code = "";
                public string GuestCode = "";
                public readonly List<Section> Sections = new();
            }

            private const int ListLimit = 12;
            private const int KillLimit = 4000;
            private const int CrateSecondsMax = 3600;

            private static readonly HammerAction[] ModesPlain = { HammerAction.Delete, HammerAction.Gibs };

            private static readonly HammerAction[] ModesBuilding = { HammerAction.Delete, HammerAction.Gibs, HammerAction.Parents };

            private static readonly HammerAction[] ModesContainer = { HammerAction.Delete, HammerAction.Gibs, HammerAction.Loot };

            private static readonly HammerAction[] ModesCrate = { HammerAction.Delete, HammerAction.Gibs, HammerAction.Unlock, HammerAction.Timer, HammerAction.Loot };

            private static readonly RaycastHit[] Hits = new RaycastHit[24];
            private static readonly int Mask = BuildMask();

            private readonly PowerfulAdmin _plugin;

            public HammerTool(PowerfulAdmin plugin)
            {
                _plugin = plugin;
            }

            private static int BuildMask()
            {
                Rust.Layer[] layers =
                {
                    Rust.Layer.Default, Rust.Layer.Deployed, Rust.Layer.Ragdoll, Rust.Layer.AI,
                    Rust.Layer.Vehicle_Detailed, Rust.Layer.Vehicle_World, Rust.Layer.World,
                    Rust.Layer.Player_Server, Rust.Layer.Harvestable, Rust.Layer.Construction, Rust.Layer.Clutter,
                    Rust.Layer.Vehicle_Large, Rust.Layer.Prevent_Building, Rust.Layer.Tree
                };
                var mask = 0;
                foreach (var layer in layers)
                    mask |= 1 << (int)layer;
                return mask;
            }

            public static HammerAction[] Modes(BaseEntity ent)
            {
                if (ent is HackableLockedCrate)
                    return ModesCrate;
                if (ent is StorageContainer)
                    return ModesContainer;
                if (ent is BuildingBlock)
                    return ModesBuilding;
                return ModesPlain;
            }

            public static HammerAction ModeAt(HammerAction[] modes, int armed) =>
                armed >= 1 && armed <= modes.Length ? modes[armed - 1] : HammerAction.None;

            public static int ArmedFor(HammerAction[] modes, HammerAction mode)
            {
                if (mode == HammerAction.None)
                    return 0;
                var index = Array.IndexOf(modes, mode);
                return index < 0 ? 0 : index + 1;
            }

            public static string ModeArg(HammerAction mode) =>
                mode == HammerAction.None ? "" : mode.ToString().ToLower();

            public static HammerAction Parse(string raw) =>
                Enum.TryParse<HammerAction>(raw, true, out var mode) ? mode : HammerAction.None;

            public bool Can(BasePlayer p) =>
                p != null && _plugin.permission.UserHasPermission(p.UserIDString, Permissions.Hammer);

            public bool Allowed(BasePlayer p) =>
                p != null && p.IsConnected && Can(p) && _plugin.GetToggle(p, "f.hammer", false);

            public float Interval() =>
                Mathf.Max(0.05f, ParseNumber(_plugin.GetInput(null, FieldKey.SecHammerInt, "0.25"), 0.25f));

            public float Range() =>
                Mathf.Max(1f, ParseNumber(_plugin.GetInput(null, FieldKey.SecHammerDist, "200"), 200f));

            public void Ensure(BasePlayer player)
            {
                if (player == null)
                    return;
                var comp = player.GetComponent<PaHammerComponent>();
                if (Allowed(player))
                {
                    if (comp == null)
                        player.gameObject.AddComponent<PaHammerComponent>().Init(_plugin, player);
                    _plugin.WatchInput(player);
                    return;
                }

                if (comp != null)
                    UnityEngine.Object.Destroy(comp);
                _plugin.ClearHammerHud(player);
                _plugin.UnwatchInput(player);
            }

            private static BaseEntity Raycast(BasePlayer admin, float range)
            {
                var count = Physics.RaycastNonAlloc(admin.eyes.HeadRay(), Hits, range, Mask,
                    QueryTriggerInteraction.Ignore);
                BaseEntity best = null;
                var bestDistance = float.MaxValue;
                for (var i = 0; i < count; i++)
                {
                    var ent = Hits[i].GetEntity();
                    if (ent == null || ent == admin)
                        continue;
                    if (Hits[i].distance >= bestDistance)
                        continue;
                    bestDistance = Hits[i].distance;
                    best = ent;
                }

                return best;
            }

            private static BaseEntity Target(AdminData ad) =>
                ad.HammerTarget == 0uL
                    ? null
                    : BaseNetworkable.serverEntities.Find(new NetworkableId(ad.HammerTarget)) as BaseEntity;

            private const float PieHoldSeconds = 0.2f;

            private bool Armed(BasePlayer player, AdminData ad)
            {
                if (!Allowed(player) || ad.HammerTarget == 0uL)
                    return false;
                var needed = _plugin.GetInput(null, FieldKey.SecHammerItem, "hammer");
                var held = player.GetActiveItem();
                return held != null && held.info != null && held.info.shortname == needed;
            }

            public bool HoldUse(BasePlayer player, AdminData ad, InputState input)
            {
                if (input.IsDown(BUTTON.SPRINT) || !Armed(player, ad))
                {
                    ad.HammerUseSince = 0f;
                    ad.HammerPieShown = false;
                    return false;
                }

                if (!input.IsDown(BUTTON.USE))
                {
                    var shown = ad.HammerPieShown;
                    ad.HammerUseSince = 0f;
                    ad.HammerPieShown = false;
                    return shown;
                }

                if (ad.HammerUseSince <= 0f)
                    ad.HammerUseSince = UnityEngine.Time.realtimeSinceStartup;
                else if (!ad.HammerPieShown &&
                         UnityEngine.Time.realtimeSinceStartup - ad.HammerUseSince >= PieHoldSeconds)
                {
                    ad.HammerPieShown = true;
                    _plugin.OpenHammerPie(player, Target(ad));
                }

                return true;
            }

            public bool Bind(BasePlayer player, AdminData ad, int pressed)
            {
                if (!Armed(player, ad))
                    return false;
                if ((pressed & (int)BUTTON.USE) != 0)
                {
                    if (!_plugin.permission.UserHasPermission(player.UserIDString, Permissions.HammerCodes))
                        return false;
                    ad.HammerReveal = !ad.HammerReveal;
                    ad.HammerSignature = null;
                    return true;
                }

                if ((pressed & (int)BUTTON.FIRE_PRIMARY) == 0 || ad.HammerArmed == 0)
                    return false;
                Run(player, ModeAt(Modes(Target(ad)), ad.HammerArmed));
                return true;
            }

            public void Tick(BasePlayer admin)
            {
                var needed = _plugin.GetInput(null, FieldKey.SecHammerItem, "hammer");
                var held = admin.GetActiveItem();
                if (held == null || held.info == null || held.info.shortname != needed)
                {
                    _plugin.UI_HammerNotice(admin, _plugin.GetLocalizedMessage(TranslateKey.HammerHint, admin), "hint");
                    return;
                }

                var ent = Raycast(admin, Range());
                if (ent == null)
                {
                    _plugin.UI_HammerNotice(admin, _plugin.GetLocalizedMessage(TranslateKey.HammerEmpty, admin),
                        "empty");
                    return;
                }

                var ad = _plugin.GetAdmin(admin.userID);
                var netId = ent.net == null ? 0uL : ent.net.ID.Value;
                if (ad.HammerTarget != netId)
                {
                    ad.HammerReveal = false;
                    ad.HammerArmed = ArmedFor(Modes(ent), ad.HammerMode);
                }

                var info = BuildInfo(admin, ent);
                var sig = Signature(info, ad.HammerReveal) + "|" + ad.HammerArmed;
                if (ad.HammerSignature == sig)
                    return;
                ad.HammerSignature = sig;
                ad.HammerTarget = netId;
                _plugin.UI_HammerHud(admin, info);
            }

            public void Run(BasePlayer player, HammerAction mode)
            {
                var ad = _plugin.GetAdmin(player.userID);
                var target = Target(ad);
                if (target == null)
                    return;
                var label = target.ShortPrefabName;
                if (mode == HammerAction.Unlock || mode == HammerAction.Timer)
                {
                    var crate = target as HackableLockedCrate;
                    if (crate == null)
                        return;
                    if (mode == HammerAction.Timer)
                    {
                        ad.CrateTimerTarget = ad.HammerTarget;
                        ad.CrateTimerBad = false;
                        _plugin.SetInput(player.userID, FieldKey.HammerCrateTime, ClockText(CrateSeconds()));
                        _plugin.UI_CrateTimer(player, label);
                        return;
                    }

                    Unlock(crate);
                    ad.HammerSignature = null;
                    ad.HammerArmed = 0;
                    _plugin.AddLog(LogCategory.Cmd, $"{player.displayName}: hammer crate unlock {label}");
                    return;
                }

                if (mode == HammerAction.Loot)
                {
                    if (!_plugin.permission.UserHasPermission(player.UserIDString, Permissions.HammerLoot))
                    {
                        _plugin.Notify(player, _plugin.GetLocalizedMessage(TranslateKey.MessageNoperm, player),
                            NotifyKind.Error);
                        return;
                    }

                    var storage = target as StorageContainer;
                    if (storage == null)
                        return;
                    _plugin.OpenContainer(player, storage);
                    ad.HammerSignature = null;
                    ad.HammerArmed = 0;
                    return;
                }

                var killed = 1;
                if (mode == HammerAction.Parents)
                    killed = KillLinked(target);
                else
                    target.Kill(mode == HammerAction.Gibs
                        ? BaseNetworkable.DestroyMode.Gib
                        : BaseNetworkable.DestroyMode.None);
                ad.HammerSignature = null;
                ad.HammerTarget = 0uL;
                ad.HammerArmed = 0;
                _plugin.ClearHammerHud(player);
                _plugin.AddLog(LogCategory.Cmd, $"{player.displayName}: hammer delete {ModeArg(mode)} {label} x{killed}");
            }

            public int CrateSeconds()
            {
                var raw = _plugin.GetInput(null, FieldKey.SecHammerCrate, "60");
                return int.TryParse(raw, out var value) ? Mathf.Clamp(value, 0, CrateSecondsMax) : 60;
            }

            public static void Unlock(HackableLockedCrate crate)
            {
                crate.CancelInvoke(crate.HackProgress);
                crate.hackSeconds = HackableLockedCrate.requiredHackSeconds;
                using (var flags = crate.StartSetFlags(BaseEntity.FlagsUpdateMode.SendNetworkUpdate))
                {
                    flags.Set(BaseEntity.Flags.Reserved1, true);
                    flags.Set(BaseEntity.Flags.Reserved2, true);
                }

                crate.isLootable = true;
                crate.ClientRPC(RpcTarget.NetworkGroup("UpdateHackProgress"), (int)crate.hackSeconds,
                    (int)HackableLockedCrate.requiredHackSeconds);
            }

            public static void SetTimer(HackableLockedCrate crate, int remaining)
            {
                if (!crate.HasFlag(BaseEntity.Flags.Reserved1))
                    crate.StartHacking();
                using (var flags = crate.StartSetFlags(BaseEntity.FlagsUpdateMode.SendNetworkUpdate))
                    flags.Set(BaseEntity.Flags.Reserved2, false);
                crate.isLootable = false;
                crate.hackSeconds = HackableLockedCrate.requiredHackSeconds - remaining;
                crate.CancelInvoke(crate.HackProgress);
                crate.InvokeRepeating(crate.HackProgress, 1f, 1f);
                crate.ClientRPC(RpcTarget.NetworkGroup("UpdateHackProgress"), (int)crate.hackSeconds,
                    (int)HackableLockedCrate.requiredHackSeconds);
            }

            private int KillLinked(BaseEntity root)
            {
                var seen = new HashSet<BaseEntity> { root };
                var queue = new Queue<BaseEntity>();
                queue.Enqueue(root);
                while (queue.Count > 0 && seen.Count < KillLimit)
                {
                    var current = queue.Dequeue();
                    var links = current.GetEntityLinks();
                    if (links == null)
                        continue;
                    for (var i = 0; i < links.Count; i++)
                    {
                        var connections = links[i].connections;
                        if (connections == null)
                            continue;
                        for (var j = 0; j < connections.Count; j++)
                        {
                            var neighbour = connections[j]?.owner;
                            if (neighbour == null || neighbour.IsDestroyed)
                                continue;
                            if (!seen.Add(neighbour))
                                continue;
                            queue.Enqueue(neighbour);
                        }
                    }
                }

                var batch = new List<BaseEntity>(seen);
                if (ServerMgr.Instance == null)
                    return 0;
                ServerMgr.Instance.StartCoroutine(KillBatch(batch));
                return batch.Count;
            }

            private static IEnumerator KillBatch(List<BaseEntity> entities)
            {
                for (var i = 0; i < entities.Count; i++)
                {
                    var ent = entities[i];
                    if (ent != null && !ent.IsDestroyed)
                        ent.Kill();
                    if (i % 10 == 9)
                        yield return null;
                }
            }

            private string Name(ulong id)
            {
                if (id == 0)
                    return "-";
                var entry = _plugin.GetDropdownEntry(id);
                return $"{entry.DisplayName} ({id})";
            }

            private static Section Add(Info info, string title)
            {
                var section = new Section { Title = title };
                info.Sections.Add(section);
                return section;
            }

            private static void RowAdd(Section section, string label, string value, string color = null)
            {
                if (string.IsNullOrEmpty(value))
                    return;
                section.Rows.Add(new Row { Label = label, Value = value, Color = color });
                section.Total++;
            }

            private void Players(Section section, IEnumerable<ulong> ids)
            {
                foreach (var uid in ids.Distinct())
                {
                    section.Total++;
                    if (section.Rows.Count >= ListLimit)
                        continue;
                    var online = FindOnline(uid) != null;
                    section.Rows.Add(new Row { Label = "", Value = Name(uid), Color = online ? Colors.CSuccess : null });
                }
            }

            public Info BuildInfo(BasePlayer admin, BaseEntity ent)
            {
                var info = new Info
                {
                    Title = ent.ShortPrefabName,
                    Kind = ent.GetType().Name,
                    NetId = ent.net == null ? 0uL : ent.net.ID.Value,
                    Modes = Modes(ent)
                };

                var general = Add(info, _plugin.GetLocalizedMessage(TranslateKey.HammerGeneral, admin));
                RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerOwner, admin),
                    ent.OwnerID == 0 ? "-" : Name(ent.OwnerID),
                    ent.OwnerID != 0 && FindOnline(ent.OwnerID) != null ? Colors.CSuccess : null);
                RowAdd(general, "NetID", info.NetId == 0 ? "-" : info.NetId.ToString());
                var pos = ent.transform.position;
                RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerPosition, admin),
                    $"{MapHelper.PositionToString(pos)}  {(int)pos.x} {(int)pos.y} {(int)pos.z}");
                RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerDistance, admin),
                    $"{(int)Vector3.Distance(admin.transform.position, pos)} m");
                if (ent is BaseCombatEntity combat)
                    RowAdd(general, "HP",
                        $"{Mathf.RoundToInt(combat.health)} / {Mathf.RoundToInt(combat.MaxHealth())}");
                if (ent.HasParent())
                    RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerParent, admin),
                        ent.GetParentEntity().ShortPrefabName);

                if (ent is BuildingBlock block)
                {
                    RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerGrade, admin),
                        block.grade.ToString());
                    RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerBuilding, admin),
                        block.buildingID.ToString());
                }

                if (ent is BasePlayer target)
                {
                    RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerSteamId, admin),
                        target.UserIDString);
                    RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerState, admin),
                        target.IsDead() ? "dead" :
                        target.IsSleeping() ? "sleeping" :
                        target.IsWounded() ? "wounded" : "alive");
                    if (target.currentTeam != 0)
                        RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerTeam, admin),
                            target.currentTeam.ToString());
                    if (target.IsConnected)
                        RowAdd(general, "ping", _plugin.Ping(target).ToString());
                }

                if (ent is SleepingBag bag)
                    RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerBag, admin),
                        Name(bag.deployerUserID));

                if (ent is BuildingPrivlidge priv)
                {
                    var span = TimeSpan.FromMinutes(priv.GetProtectedMinutes());
                    RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerUpkeep, admin),
                        $"{span.Days}d {span.Hours}h {span.Minutes}m");
                }

                if (ent is IOEntity io)
                {
                    RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerPower, admin),
                        $"{io.currentEnergy} / {io.ConsumptionAmount()}");
                    RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerPowered, admin),
                        io.IsPowered() ? "yes" : "no", io.IsPowered() ? Colors.CSuccess : Palette.CText3);
                }

                if (ent is BaseVehicle vehicle)
                    RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerMounted, admin),
                        vehicle.AnyMounted() ? "yes" : "no");

                if (ent is HackableLockedCrate crate)
                    RowAdd(general, _plugin.GetLocalizedMessage(TranslateKey.HammerCrateOpens, admin),
                        CrateStateText(admin, crate),
                        crate.IsFullyHacked() ? Colors.CSuccess :
                        crate.IsBeingHacked() ? Colors.CWarn : Palette.CText3);

                var showCodes = _plugin.permission.UserHasPermission(admin.UserIDString, Permissions.HammerCodes);
                if (ent.GetSlot(BaseEntity.Slot.Lock) is CodeLock codeLock && showCodes)
                {
                    info.HasLock = true;
                    info.Code = codeLock.code ?? "";
                    info.GuestCode = codeLock.guestCode ?? "";
                    if (codeLock.whitelistPlayers.Count > 0)
                    {
                        var wl = Add(info, _plugin.GetLocalizedMessage(TranslateKey.HammerWhitelist, admin));
                        Players(wl, codeLock.whitelistPlayers);
                    }
                }

                if (ent is BuildingPrivlidge tc && tc.authorizedPlayers.Count > 0)
                {
                    var authed = Add(info, _plugin.GetLocalizedMessage(TranslateKey.HammerAuthed, admin));
                    Players(authed, tc.authorizedPlayers);
                }

                if (ent is AutoTurret turret && turret.authorizedPlayers.Count > 0)
                {
                    var authed = Add(info, _plugin.GetLocalizedMessage(TranslateKey.HammerAuthed, admin));
                    Players(authed, turret.authorizedPlayers);
                }

                if (ent is StorageContainer container && container.inventory != null &&
                    container.inventory.itemList.Count > 0)
                {
                    var items = Add(info, _plugin.GetLocalizedMessage(TranslateKey.HammerItems, admin));
                    foreach (var item in container.inventory.itemList)
                    {
                        items.Total++;
                        if (items.Rows.Count >= ListLimit)
                            continue;
                        items.Rows.Add(new Row { Label = "", Value = $"{item.amount}x {item.info.displayName.english}", ItemId = item.info.itemid });
                    }
                }

                return info;
            }

            private string CrateStateText(BasePlayer admin, HackableLockedCrate crate)
            {
                if (crate.IsFullyHacked())
                    return _plugin.GetLocalizedMessage(TranslateKey.HammerCrateOpened, admin);
                if (!crate.IsBeingHacked())
                    return _plugin.GetLocalizedMessage(TranslateKey.HammerCrateIdle, admin);
                var remaining = Mathf.CeilToInt(HackableLockedCrate.requiredHackSeconds - crate.hackSeconds);
                if (remaining <= 0)
                    return _plugin.GetLocalizedMessage(TranslateKey.HammerCrateOpened, admin);
                return ClockText(remaining);
            }

            private static string Signature(Info info, bool reveal)
            {
                var sig = $"{info.NetId}|{reveal}|{info.Code}|{info.GuestCode}";
                foreach (var section in info.Sections)
                {
                    sig += "|" + section.Title + section.Total;
                    foreach (var row in section.Rows)
                        sig += "/" + row.Value;
                }

                return sig;
            }
        }

