        #region Hooks

        private void OnServerInitialized(bool initial)
        {
            Instance = this;

            foreach (var perm in Permissions.All)
                permission.RegisterPermission(perm, this);
            foreach (var key in Permissions.PlayerActions)
                permission.RegisterPermission(Permissions.GetPlayerActionPermission(key), this);
            LoadAssets();
            SeedQuickButtons();
            RegisterQuickPermissions();
            ServerMgr.Instance.StartCoroutine(Map.BuildMapRegistry());
            _mapTimer = timer.Once(MapInterval(), MapTimerTick);
            _toolSyncTimer = timer.Repeat(2f, 0, ToolSyncTick);
            if (_harmony == null)
            {
                _harmony = new HarmonyLib.Harmony("com.powerfuladmin");
                _harmony.PatchAll();
            }

            LoadManagedConvars(initial);

            Application.logMessageReceived += OnUnityLog;
            _storageBusy = true;
            InitStorage(() =>
            {
                _storageBusy = false;
                RefreshLogCap();
                foreach (var p in BasePlayer.activePlayerList)
                {
                    TouchPlayer(p);
                    var sess = GetAdmin(p.userID);
                    sess.Session = 0f;
                    ApplyFeatures(p);

                    UI_Preload(p);
                }

#if DEBUG_SERVER
                SeedDebugData();
#endif
            });

            if (initial)
                DiscordEvent("d.s5", "d.hact", GetLocalizedMessage(TranslateKey.DiscordMessageRestart, null),
                    GetLocalizedMessage(TranslateKey.DiscordMessageRestartDesc, null));

            timer.Once(8f, () => Discord.RequestSync());
            foreach (var online in BasePlayer.activePlayerList)
                ShowNoteHint(online);
        }

        private void Unload()
        {
            Instance = null;
            foreach (var id in NoclipActive.ToList())
            {
                var np = BasePlayer.FindByID(id);
                if (np != null && np.IsConnected)
                    np.SendConsoleCommand("noclip");
            }

            foreach (var id in GodActive.ToList())
            {
                var gp = BasePlayer.FindByID(id);
                if (gp != null && gp.IsConnected)
                    gp.SendConsoleCommand("global.god", "false");
            }

            foreach (var kv in _admins)
            {
                if (!kv.Value.ToolTempAdmin)
                    continue;
                var np = BasePlayer.FindByID(kv.Key);
                if (np == null || !np.IsConnected)
                    continue;
                np.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, false);
                np.SendNetworkUpdateImmediate();
            }

            NoclipActive.Clear();
            GodActive.Clear();

            try
            {
                _harmony?.UnpatchAll(_harmony.Id);
            }
            catch (Exception ex)
            {
                PrintWarning($"Harmony unpatch failed: {ex.Message}");
            }

            _harmony = null;
            _storageRetryTimer?.Destroy();
            _mapTimer?.Destroy();
            _toolSyncTimer?.Destroy();
            _logFlushTimer?.Destroy();
            _saveConfigTimer?.Destroy();
            _saveDataTimer?.Destroy();
            _savePlayersTimer?.Destroy();
            _saveMutesTimer?.Destroy();
            SaveConfig();
            SaveMutes();
#if DEBUG_SERVER
            DebugClearBots();
#endif
            Application.logMessageReceived -= OnUnityLog;
            foreach (var kv in _admins)
                if (FindOnline(kv.Key) != null && _players.TryGetValue(kv.Key, out var s))
                    s.Playtime += (float)kv.Value.Session;
            foreach (var p in BasePlayer.activePlayerList)
            {
                if (p == null)
                    continue;
                foreach (var t in CleanupComponentTypes)
                {
                    var comp = p.GetComponent(t);
                    if (comp != null)
                        UnityEngine.Object.Destroy(comp);
                }
                CuiHelper.DestroyUi(p, Layers.HammerHud);
                CuiHelper.DestroyUi(p, Layers.HammerNotice);
                CuiHelper.DestroyUi(p, Layers.NoteHint);
                CuiHelper.DestroyUi(p, Layers.CrateTimer);
                var cc = p.GetComponent<PaConsoleComponent>();
                if (cc != null)
                    UnityEngine.Object.Destroy(cc);
                if (p.IsSpectating())
                    StopSpectate(p);
                ClearStatus(p);
            }

            _inputWatch.Clear();
            Map._stashes.Clear();
            FlushLogs();
            SaveData();
            SavePlayers();
            _db?.Close();
            _db = null;

            foreach (var player in BasePlayer.activePlayerList)
            {
                CuiHelper.DestroyUi(player, Layers.Root);
                CuiHelper.DestroyUi(player, Layers.Widget);
            }
        }

        private void OnServerSave()
        {
            SaveData();
            SavePlayers();
            SaveMutes();
            SaveConfig();
            FlushLogs();
        }

        private void OnPlayerConnected(BasePlayer player)
        {
            TouchPlayer(player);
            var sess = GetAdmin(player.userID);
            sess.Session = 0f;
            SavePlayersSoon();
            AddLog(LogCategory.Join, $"{player.displayName} ({player.UserIDString}) connected");
            if (permission.UserHasPermission(player.UserIDString, Permissions.Countable))
                DiscordEvent("d.s3", "d.hact", GetLocalizedMessage(TranslateKey.DiscordMessageConnect, null),
                    DiscordUser(player), player.UserIDString);
            if (GetToggle(player, "v.auto", false) &&
                permission.UserHasPermission(player.UserIDString, Permissions.Use))
                NextTick(() =>
                {
                    if (player != null && player.IsConnected)
                        SetVanish(player, true);
                });
            NextTick(() => ApplyFeatures(player));
            NextTick(() =>
            {
                if (player != null && player.IsConnected)
                    ShowNoteHint(player);
            });

            UI_Preload(player);
        }

        private void OnPlayerSleepEnded(BasePlayer player)
        {
            if (player == null)
                return;

            timer.Once(1f, () =>
            {
                SyncToolFeatures(player);
                RestoreWidget(player);
            });
        }

        private void OnPlayerRespawned(BasePlayer player)
        {
            if (player == null)
                return;
            NextTick(() =>
            {
                if (player != null && player.IsConnected)
                    ApplyVitalOverrides(player);
            });
            NextTick(() =>
            {
                if (player != null && player.IsConnected)
                    ShowNoteHint(player);
            });
        }

        private void OnPlayerDisconnected(BasePlayer player, string reason)
        {
            if (player == null)
                return;
            var sess = PeekAdmin(player.userID);
            if (sess != null && _players.TryGetValue(player.userID, out var s))
            {
                s.Playtime += (float)sess.Session;
                sess.Session = 0f;
            }

            TouchPlayer(player);
            GetAdmin(player.userID).UiOpen = false;
            GetAdmin(player.userID).Vanished = false;
            GodActive.Remove(player.userID);
            NoclipActive.Remove(player.userID);
            GetAdmin(player.userID).ToolTempAdmin = false;
            GetAdmin(player.userID).SpectateReturn = null;
            GetAdmin(player.userID).SpectateShown = 0;
            GetAdmin(player.userID).InputMask = 0;
            GetAdmin(player.userID).HammerSignature = null;
            _inputWatch.Remove(player.userID);
            ClearStatus(player);
            SavePlayersSoon();
            AddLog(LogCategory.Leave, $"{player.displayName} disconnected: {reason}");
        }

        private void OnNewSave(string filename)
        {
            DiscordEvent("d.s7", "d.hact", GetLocalizedMessage(TranslateKey.DiscordMessageWipe, null),
                GetLocalizedMessage(TranslateKey.DiscordMessageWipeDesc, null));
        }

        private object OnEntityTakeDamage(BaseCombatEntity entity, HitInfo info)
        {
            var victim = entity as BasePlayer;
            if (victim == null || info == null)
                return null;
            if (PeekAdmin(victim.userID)?.Vanished == true || GetToggle(victim, "f.god", false))
            {
                info.damageTypes?.ScaleAll(0f);
                info.HitEntity = null;
                info.DoHitEffects = false;
                return true;
            }

            return null;
        }

        private object CanBeTargeted(BasePlayer target, MonoBehaviour behaviour)
        {
            if (target != null && PeekAdmin(target.userID)?.Vanished == true)
                return false;
            return null;
        }

        private void OnMapMarkerAdd(BasePlayer player, ProtoBuf.MapNote note)
        {
            if (player == null || note == null || !Can(player, Permissions.Map))
                return;
            if (player.serverInput == null || !player.serverInput.IsDown(BUTTON.SPRINT))
                return;
            ConVar.Global.TeleportToMarker(note, player);
            AddLog(LogCategory.Cmd,
                $"{player.displayName}: marker teleport to {MapHelper.PositionToString(note.worldPosition)}");
        }

        private object CanUseLockedEntity(BasePlayer player, BaseLock baseLock)
        {
            if (player == null || PeekAdmin(player.userID)?.Vanished != true)
                return null;
            if (!Can(player, Permissions.Vanish) || !Can(player, Permissions.VanishUnlock))
                return null;
            if (!GetToggle(player, VanishUnlockKey, false))
                return null;
            return true;
        }

        private void OnPlayerDeath(BasePlayer player, HitInfo info) => Map.TrackPvp(player, info);

        private void OnEntityDeath(DecayEntity entity, HitInfo info) => Map.TrackRaid(entity, info);

        private void OnEntitySpawned(BaseNetworkable entity)
        {
            Map.Track(entity);
        }

        private void OnEntityKill(BaseNetworkable entity)
        {
            Map.Untrack(entity);
        }

        private void OnPlayerInput(BasePlayer player, InputState input)
        {
            if (_inputWatch.Count == 0 || player == null || input == null)
                return;
            if (!_inputWatch.Contains(player.userID))
                return;
            var ad = PeekAdmin(player.userID);
            if (ad == null)
                return;
            var mask = 0;
            if (input.IsDown(BUTTON.RELOAD))
                mask |= (int)BUTTON.RELOAD;
            if (input.IsDown(BUTTON.USE))
                mask |= (int)BUTTON.USE;
            if (input.IsDown(BUTTON.FIRE_SECONDARY))
                mask |= (int)BUTTON.FIRE_SECONDARY;
            if (input.IsDown(BUTTON.FIRE_PRIMARY))
                mask |= (int)BUTTON.FIRE_PRIMARY;
            var pressed = mask & ~ad.InputMask;
            ad.InputMask = mask;
            if (player.IsSpectating())
            {
                if ((pressed & (int)BUTTON.RELOAD) != 0)
                    StopSpectate(player);
                else if (ad.SpectateShown != (player.SpectatingTarget == null ? 0uL : player.SpectatingTarget.userID))
                {
                    ad.SpectateShown = player.SpectatingTarget == null ? 0uL : player.SpectatingTarget.userID;
                    UpdateSpectateHint(player);
                }

                return;
            }

            if (ad.SpectateReturn != null)
            {
                StopSpectate(player);
                return;
            }

            if (Hammer.HoldUse(player, ad, input))
                return;
            if (pressed == 0)
                return;
            if (input.IsDown(BUTTON.SPRINT) && Hammer.Bind(player, ad, pressed))
                return;
            if ((pressed & (int)BUTTON.USE) != 0)
                InspectOpenInventory(player);
            else if ((pressed & (int)BUTTON.FIRE_SECONDARY) != 0)
                InspectClick(player);
        }

        private void OnCuiDraggableDrag(BasePlayer player, string name, Vector3 position,
            CommunityEntity.DraggablePositionSendType type)
        {
            if (player == null)
                return;
            var pos = $"{Mathf.Clamp01(position.x)} {Mathf.Clamp01(position.y)}";
            if (name == Layers.Widget)
                GetAdmin(player.userID).WidgetPos = pos;
            else if (name == Layers.Root)
                GetAdmin(player.userID).RootPos = pos;
            else if (name == Layers.HammerHud)
                GetAdmin(player.userID).HammerHudPos = pos;
            else if (name == Layers.HammerNotice)
                GetAdmin(player.userID).HammerNoticePos = pos;
            else
                return;
            SaveSoon();
        }

        private void OnPlayerLootEnd(PlayerLoot inventory)
        {
            var admin = inventory?.baseEntity;
            if (admin == null)
                return;
            if (_lootNoInput.TryGetValue(admin.userID, out var restored))
            {
                _lootNoInput.Remove(admin.userID);
                if (restored != null && !restored.IsDestroyed && restored.inventory != null)
                    restored.inventory.SetFlag(ItemContainer.Flag.NoItemInput, true);
            }

            var ir = PeekAdmin(admin.userID);
            if (ir == null || !ir.InvReopen)
                return;
            ir.InvReopen = false;
            NextTick(() =>
            {
                if (admin != null && admin.IsConnected &&
                    permission.UserHasPermission(admin.UserIDString, Permissions.Use))
                    UI_Open(admin);
            });
        }

        private object OnPlayerChat(BasePlayer player, string message, ConVar.Chat.ChatChannel channel)
        {
            if (player == null || string.IsNullOrEmpty(message))
                return null;
            if (IsMuted(player.userID))
            {
                var m = _mutes[player.userID];
                var left = m.Until == 0
                    ? GetLocalizedMessage(TranslateKey.MutePerm, player)
                    : FormatDuration(m.Until - DateTimeOffset.Now.ToUnixTimeSeconds());
                Notify(player, SafeFormat(GetLocalizedMessage(TranslateKey.MuteNotice, player), m.Reason, left));
                return true;
            }

            AddLog(LogCategory.Chat, $"{player.displayName}: {message}");
            DiscordChat(player, message);
            return null;
        }


        private void OnUnityLog(string condition, string stackTrace, LogType type)
        {
            var cat = type == LogType.Error || type == LogType.Exception || type == LogType.Assert ? LogCategory.Err
                : type == LogType.Warning ? LogCategory.Warn : LogCategory.Info;
            if (cat == LogCategory.Err && IsNonPluginError(condition))
                cat = LogCategory.Warn;
            AddLog(cat, condition);
            if (cat == LogCategory.Err && IsDiscordOn() && GetToggle(null, "d.s6", true) && _sinceDiscordError >= 15f)
            {
                _sinceDiscordError = 0f;
                var cond = condition;
                var st = stackTrace;
                NextTick(() => DiscordError(cond, st));
            }
        }

