        private static void ParseIdName(string encoded, List<string[]> into)
        {
            into.Clear();
            if (string.IsNullOrEmpty(encoded))
                return;
            foreach (var line in encoded.Split('\n'))
            {
                var sep = line.IndexOf('\t');
                if (sep <= 0)
                    continue;
                var id = line.Substring(0, sep).Trim();
                var name = line.Substring(sep + 1).Trim();
                if (id.Length > 0)
                    into.Add(new[] { id, name });
            }
        }

        private static long ParseDuration(string s)
        {
            if (string.IsNullOrWhiteSpace(s))
                return -1;
            s = s.Trim().ToLowerInvariant();
            if (s == "perm" || s == "0" || s == "∞")
                return 0;
            if (long.TryParse(s, out var mins))
                return mins <= 0 ? 0 : mins * 60;
            long total = 0, num = 0;
            var sawNum = false;
            var any = false;
            foreach (var ch in s)
                if (ch >= '0' && ch <= '9')
                {
                    num = num * 10 + (ch - '0');
                    sawNum = true;
                }
                else
                {
                    var mult = ch switch { 'd' => 86400L, 'h' => 3600L, 'm' => 60L, 's' => 1L, _ => -1L };
                    if (mult < 0 || !sawNum)
                        return -1;
                    total += num * mult;
                    num = 0;
                    sawNum = false;
                    any = true;
                }

            if (sawNum)
            {
                total += num * 60;
                any = true;
            }

            return any ? total : -1;
        }


        private string GetLocalizedMessage(string key, BasePlayer player) =>
            lang.GetMessage(key, this, player?.UserIDString);

        private static string SafeFormat(string template, params object[] args)
        {
            try
            {
                return string.Format(template, args);
            }
            catch
            {
                return template;
            }
        }

        private void Notify(BasePlayer player, string message) => Notify(player, message, NotifyKind.Success);

        private void Notify(BasePlayer player, string message, NotifyKind kind)
        {
            if (player == null || string.IsNullOrEmpty(message))
                return;
            if (kind == NotifyKind.Success && GetSelect(null, FieldKey.NotifyProvider, "auto") == "off")
                return;
            var plugin = ResolveNotifyPlugin(out var isNcp);
            if (plugin == null)
            {
                NotifyChat(player, message);
                return;
            }

            plugin.Call("SendNotify", player, NotifyTypeId(kind, isNcp), message);
        }

        private void NotifyChat(BasePlayer player, string message)
        {
            var accent = RgbaToHex(Palette.Of(GetThemeKey(player)).CAccent);
            player.ChatMessage(
                $"<color=#{accent}>PowerfulAdmin</color> <color=#9b9ba3>›</color> <color=#d7d9e0>{message}</color>");
        }

        private Plugin ResolveNotifyPlugin(out bool isNcp)
        {
            isNcp = false;
            var mode = GetSelect(null, FieldKey.NotifyProvider, "auto");
            if (mode == "off" || mode == "chat")
                return null;
            if (mode == "ncp")
            {
                if (_ncpPlugin == null || !_ncpPlugin.IsLoaded)
                    return null;
                isNcp = true;
                return _ncpPlugin;
            }
            if (mode == "notify")
                return _notifyPlugin != null && _notifyPlugin.IsLoaded ? _notifyPlugin : null;
            if (_ncpPlugin != null && _ncpPlugin.IsLoaded)
            {
                isNcp = true;
                return _ncpPlugin;
            }
            return _notifyPlugin != null && _notifyPlugin.IsLoaded ? _notifyPlugin : null;
        }

        private int NotifyTypeId(NotifyKind kind, bool isNcp)
        {
            var key = isNcp
                ? kind switch
                {
                    NotifyKind.Error => FieldKey.NcpError,
                    NotifyKind.PlayerNotice => FieldKey.NcpPlayer,
                    _ => FieldKey.NcpSuccess
                }
                : kind switch
                {
                    NotifyKind.Error => FieldKey.NotifyError,
                    NotifyKind.PlayerNotice => FieldKey.NotifyPlayer,
                    _ => FieldKey.NotifySuccess
                };
            var def = isNcp
                ? kind switch { NotifyKind.Error => "2", NotifyKind.PlayerNotice => "0", _ => "3" }
                : kind switch { NotifyKind.Error => "1", NotifyKind.PlayerNotice => "0", _ => "0" };
            return int.TryParse(GetInput(null, key, def), out var id) ? id : int.Parse(def);
        }

