        private static string RgbaToHex(string rgba)
        {
            var p = rgba.Split(' ');
            if (p.Length < 3)
                return "ffffff";
            float.TryParse(p[0], System.Globalization.NumberStyles.Float, Ci, out var r);
            float.TryParse(p[1], System.Globalization.NumberStyles.Float, Ci, out var g);
            float.TryParse(p[2], System.Globalization.NumberStyles.Float, Ci, out var b);
            return UnityEngine.ColorUtility.ToHtmlStringRGB(new Color(r, g, b));
        }

