        private bool CanEditKey(BasePlayer p, string key)
        {
            if (IsSettingsKey(key))
                return Can(p, Permissions.Settings);
            if (key.StartsWith("e.", StringComparison.Ordinal))
                return Can(p, Permissions.Esp);
            if (key == VanishUnlockKey)
                return Can(p, Permissions.Vanish) && Can(p, Permissions.VanishUnlock);
            if (key == VanishNoclipKey)
                return Can(p, Permissions.Vanish) && Can(p, Permissions.Noclip);
            if (key == VanishKey)
                return Can(p, Permissions.Vanish);
            if (key.StartsWith("v.", StringComparison.Ordinal))
                return Can(p, Permissions.Vanish);
            if (key.StartsWith("give.", StringComparison.Ordinal) || key.StartsWith("pop.", StringComparison.Ordinal) ||
                key.StartsWith("dd.", StringComparison.Ordinal) ||
                key.StartsWith("players.", StringComparison.Ordinal) ||
                key.StartsWith("pv.", StringComparison.Ordinal))
                return Can(p, Permissions.Players);
            if (key.StartsWith("logs.", StringComparison.Ordinal))
                return Can(p, Permissions.Logs);
            if (key.StartsWith("perms.", StringComparison.Ordinal) ||
                key.StartsWith("newgroup.", StringComparison.Ordinal) ||
                key.StartsWith("userperm.", StringComparison.Ordinal))
                return Can(p, Permissions.Perms);
            if (key == FieldKey.ConsoleTab)
                return IsConsoleAllowed(p);
            if (key == "f.god")
                return Can(p, Permissions.God);
            if (key == "f.noclip")
                return Can(p, Permissions.Noclip);
            if (key == "f.inspect")
                return Can(p, Permissions.Players);
            if (key == "f.hammer")
                return Hammer.Can(p);
            if (key.StartsWith("vit.", StringComparison.Ordinal))
                return p != null && permission.UserHasPermission(p.UserIDString, Permissions.CanDisableVitals);
            return true;
        }

