        private static UIFont FontDefault(string key) => key switch
        {
            FontKeyTitle => UIFont.RobotoCondensedBold,
            FontKeyBody => UIFont.RobotoCondensedRegular,
            FontKeyLogs => UIFont.DroidSansMono,
            FontKeyConsole => UIFont.DroidSansMono,
            _ => UIFont.RobotoCondensedBold
        };

        private UIFont GetFont(BasePlayer p, string key)
        {
            var def = FontDefault(key);
            if (p == null)
                return def;
            var raw = GetSelect(p, key, "");
            if (string.IsNullOrEmpty(raw))
                return def;
            if (!Enum.TryParse<UIFont>(raw, out var parsed))
                return def;
            if (!Enum.IsDefined(typeof(UIFont), parsed))
                return def;
            if (Array.IndexOf(Fonts.All, parsed) < 0)
                return def;
            return parsed;
        }

