        private string GroupColor(string g)
        {
            if (string.IsNullOrEmpty(g))
                return Palette.CText2;
            var h = 2166136261u;
            foreach (var ch in g.ToLowerInvariant())
            {
                h ^= ch;
                h *= 16777619u;
            }

            return ColorToRustFormat(Color.HSVToRGB(h % 360u / 360f, 0.58f, 0.95f));
        }

        private static string ColorToRustFormat(Color color)
        {
            return
                $"{color.r.ToString("0.###", Ci)} {color.g.ToString("0.###", Ci)} {color.b.ToString("0.###", Ci)} {color.a.ToString("0.###", Ci)}";
        }


