        private string GetGroupOf(BasePlayer p) => p == null ? "player" : p.IsAdmin ? "admin" : GetGroupOf(p.userID);

        private string GetGroupOf(ulong id)
        {
#if DEBUG_SERVER
            if (_debugGroups.TryGetValue(id, out var dbg))
                return dbg;
#endif
            var groups = permission.GetUserGroups(id.ToString());
            if (groups != null)
            {
                var set = new HashSet<string>(groups.Select(g => g.ToLowerInvariant()));
                if (set.Contains("admin") || set.Contains("owner") || set.Contains("root"))
                    return "admin";
                if (set.Contains("moderator") || set.Contains("mod"))
                    return "moderator";
                if (set.Contains("vip"))
                    return "vip";
                if (set.Contains("premium"))
                    return "premium";
            }

            return "player";
        }

