        private static string FormatDuration(double seconds)
        {
            if (seconds < 1)
                return "0m";
            if (seconds < 60)
                return $"{(int)seconds}s";
            if (seconds < 3600)
                return $"{(int)(seconds / 60)}m";
            var h = seconds / 3600.0;
            return h < 10 ? $"{h:0.0}h" : $"{(int)h}h";
        }

