        {
            var pt = _players.TryGetValue(id, out var s) ? s.Playtime : 0;
            var sess = PeekAdmin(id);
            if (FindOnline(id) != null && sess != null)
                pt += (float)sess.Session;
            return pt;
        }

        private string GetLastSeenAgo(ulong id)
        {
            if (!_players.TryGetValue(id, out var s) || s.LastSeen == 0)
                return "-";
            var ago = DateTimeOffset.Now.ToUnixTimeSeconds() - s.LastSeen;
            return ago < 60 ? "now" : FormatDuration(ago);
        }

        private int GetNewToday()
        {
            var midnight = new DateTimeOffset(DateTime.Today).ToUnixTimeSeconds();
            return _players.Values.Count(s => s.FirstSeen >= midnight);
        }

        private static int GetServerFps()
        {
            try
            {
                return Performance.report.frameRate;
            }
            catch (Exception ex)
            {
                Instance?.PrintWarning($"Reading the server fps failed: {ex.Message}");
                return Mathf.RoundToInt(1f / Mathf.Max(0.0001f, Time.smoothDeltaTime));
            }
        }

        private static int ServerQueue(out int joining)
        {
#if DEBUG_SERVER
            joining = 2;
            return 5;
#else
            try
            {
                var q = ServerMgr.Instance?.connectionQueue;
                if (q == null)
                {
                    joining = 0;
                    return 0;
                }

                joining = q.Joining;
                return q.Queued;
            }
            catch (Exception ex)
            {
                Instance?.PrintWarning($"Reading the connection queue failed: {ex.Message}");
                joining = 0;
                return 0;
            }
#endif
        }

        private void TouchPlayer(BasePlayer p)
        {
            if (p == null)
                return;
            var now = DateTimeOffset.Now.ToUnixTimeSeconds();
            if (!_players.TryGetValue(p.userID, out var s))
                _players[p.userID] = s = new StoredPlayer { FirstSeen = now };
            if (!string.IsNullOrEmpty(p.displayName))
                s.Name = p.displayName;
            s.LastSeen = now;
        }


        private static string QuickPermName(string raw)
        {
            var name = (raw ?? "").Replace(" ", "").ToLower();
            var trimmed = true;
            while (trimmed)
            {
                trimmed = false;
                if (name.StartsWith(QuickPermPrefix, StringComparison.Ordinal))
                {
                    name = name.Substring(QuickPermPrefix.Length);
                    trimmed = true;
                }

                if (!name.StartsWith("powerfuladmin.", StringComparison.Ordinal))
                    continue;
                name = name.Substring("powerfuladmin.".Length);
                trimmed = true;
            }

            return name.Trim('.');
        }

        private string QuickPerm(QuickButton qb) => QuickPermPrefix + QuickPermName(qb.Permission);

        private void SeedQuickButtons()
        {
            if (cfg == null || cfg.QuickButtons == null)
                return;
            if (cfg.QuickButtons.Count > 0)
                return;
            cfg.QuickButtons.Add(new QuickButton
            {
                Id = "warn", Name = "Warning", Target = QuickTarget.Player,
                Command = "/pm %STEAM_ID% Follow the server rules", Icon = "assets/icons/warning_2.png",
                Color = Colors.CWarn, Places = QuickPlace.Popup | QuickPlace.Map, Order = 0
            });
            cfg.QuickButtons.Add(new QuickButton
            {
                Id = "tphere", Name = "Teleport to Me", Target = QuickTarget.Player,
                Command = "teleport.topos %STEAM_ID% %ADMIN_X% %ADMIN_Y% %ADMIN_Z%",
                Icon = "assets/icons/pet_move.png", Color = Colors.CInfo, Places = QuickPlace.Map, Order = 1
            });
            cfg.QuickButtons.Add(new QuickButton
            {
                Id = "airdrop", Name = "Airdrop", Target = QuickTarget.Global,
                Command = "spawn cargo_plane", Icon = "assets/icons/descend.png", Color = Colors.CSuccess,
                Places = QuickPlace.Dashboard | QuickPlace.Widget, Order = 2
            });
            SaveConfig();
        }

        private void RegisterQuickPermissions()
        {
            if (cfg?.QuickButtons == null)
                return;
            foreach (var qb in cfg.QuickButtons)
            {
                qb.Permission = QuickPermName(qb.Permission);
                if (string.IsNullOrEmpty(qb.Permission))
                    continue;
                var perm = QuickPerm(qb);
                if (permission.PermissionExists(perm, this))
                    continue;
                permission.RegisterPermission(perm, this);
            }
        }

        private bool CanUseQuick(BasePlayer admin, QuickButton qb)
        {
            if (admin == null || qb == null || !qb.Enabled)
                return false;
            if (string.IsNullOrEmpty(qb.Permission))
                return true;
            return permission.UserHasPermission(admin.UserIDString, QuickPerm(qb));
        }

        private List<QuickButton> QuickFor(BasePlayer admin, QuickTarget target, QuickPlace place)
        {
            if (admin == null || cfg?.QuickButtons == null)
                return new List<QuickButton>();
            return cfg.QuickButtons
                .Where(qb => qb.Target == target && (qb.Places & place) != 0 && CanUseQuick(admin, qb))
                .OrderBy(qb => qb.Order).ToList();
        }

        private QuickButton FindQuick(string id)
        {
            if (string.IsNullOrEmpty(id) || cfg?.QuickButtons == null)
                return null;
            return cfg.QuickButtons.Find(qb => qb.Id == id);
        }

        private string QuickExpand(BasePlayer admin, QuickButton qb, string raw, ulong targetId, Vector3 point)
        {
            var text = raw;
            text = text.Replace("%ADMIN_STEAM_ID%", admin.UserIDString);
            text = text.Replace("%ADMIN_NICKNAME%", admin.displayName);
            var ap = admin.transform.position;
            text = text.Replace("%ADMIN_X%", ap.x.ToString("0.##"));
            text = text.Replace("%ADMIN_Y%", ap.y.ToString("0.##"));
            text = text.Replace("%ADMIN_Z%", ap.z.ToString("0.##"));
            text = text.Replace("%ADMIN_GRID%", MapHelper.PositionToString(ap));
            if (qb.Target == QuickTarget.Player)
            {
                text = text.Replace("%STEAM_ID%", targetId.ToString());
                text = text.Replace("%NICKNAME%", GetDropdownEntry(targetId).DisplayName);
            }

            if (qb.Target == QuickTarget.Player || qb.Target == QuickTarget.Point)
            {
                text = text.Replace("%X%", point.x.ToString("0.##"));
                text = text.Replace("%Y%", point.y.ToString("0.##"));
                text = text.Replace("%Z%", point.z.ToString("0.##"));
                text = text.Replace("%GRID%", MapHelper.PositionToString(point));
            }

            return text;
        }

        private void RunQuick(BasePlayer admin, QuickButton qb, ulong targetId, Vector3 point)
        {
            if (admin == null || qb == null || string.IsNullOrEmpty(qb.Command))
                return;
            foreach (var part in qb.Command.Split('|'))
            {
                var cmd = QuickExpand(admin, qb, part.Trim(), targetId, point);
                if (string.IsNullOrEmpty(cmd))
                    continue;
                if (cmd[0] == '/')
                    admin.SendConsoleCommand("chat.say", cmd);
                else
                    ConsoleSystem.Run(ConsoleSystem.Option.Server.Quiet(), cmd);
                AddLog(LogCategory.Cmd, $"{admin.displayName}: quick '{qb.Name}' -> {cmd}");
            }
        }

        private DropdownEntry GetDropdownEntry(ulong id)
        {
            var player = FindOnline(id);
            var name = player?.displayName ?? (_players.TryGetValue(id, out var s) ? s.Name : id.ToString());
            if (string.IsNullOrEmpty(name))
                name = id.ToString();
            return new DropdownEntry { SteamId = id.ToString(), DisplayName = name };
        }

        private void TeleportPlayer(BasePlayer player, Vector3 dest)
        {
            if (player == null)
                return;
            var wasSleeping = player.IsSleeping();
            player.PauseFlyHackDetection(5f);
            player.PauseSpeedHackDetection(5f);
            player.UpdateActiveItem(default);
            player.EnsureDismounted();
            player.Server_CancelGesture();
            if (player.HasParent())
                player.SetParent(null, true, true);

            if (player.IsConnected)
            {
                if (!player.limitNetworking && !player.isInvisible)
                    player.SendNetworkUpdateImmediate();
                player.StartSleeping();
                player.SetPlayerFlag(BasePlayer.PlayerFlags.ReceivingSnapshot, true);
                player.ClientRPC(RpcTarget.Player("StartLoading", player), true);
            }

            player.Teleport(dest);

            if (player.IsConnected)
            {
                if (!player.limitNetworking && !player.isInvisible)
                {
                    player.UpdateNetworkGroup();
                    player.SendCompleteSnapshot();
                }

                if (!wasSleeping)
                    player.Invoke(() =>
                    {
                        if (player != null && player.IsConnected)
                            player.EndSleeping();
                    }, 0.5f);
            }
        }

        private float CoordAxis(BasePlayer player, string id, float def) =>
            float.TryParse(GetInput(player, id, "").Trim(), System.Globalization.NumberStyles.Float,
                Ci, out var v)
                ? v
                : def;

        private static Vector3 LookPoint(BasePlayer player)
        {
            if (player.eyes == null)
                return player.transform.position;
            var ray = player.eyes.HeadRay();
            const int mask = Rust.Layers.World | Rust.Layers.Terrain | Rust.Layers.Construction;
            if (Physics.Raycast(ray, out var hit, 1000f, mask))
                return hit.point + Vector3.up * 0.2f;
            return ray.origin + ray.direction * 10f;
        }

        private void Broadcast(string msg) =>
            ConsoleSystem.Run(ConsoleSystem.Option.Server.Quiet(), "say", msg);

        private void NotifyBroadcast(string msg)
        {
            foreach (var p in BasePlayer.activePlayerList)
                Notify(p, msg, NotifyKind.PlayerNotice);
        }

        private void BroadcastByMode(string mode, string msg)
        {
            if (mode == "chat")
                Broadcast(msg);
            else
                NotifyBroadcast(msg);
        }


        private void SetVanish(BasePlayer player, bool on)
        {
            if (player == null)
                return;
            var comp = player.GetComponent<PaVanishComponent>();
            if (on)
            {
                GetAdmin(player.userID).Vanished = true;
                if (comp == null)
                {
                    comp = player.gameObject.AddComponent<PaVanishComponent>();
                    comp.Init(player);
                }

                AddLog(LogCategory.Cmd, $"{player.displayName}: vanish ON");
            }
            else
            {
                GetAdmin(player.userID).Vanished = false;
                if (comp != null)
                    UnityEngine.Object.DestroyImmediate(comp);
                AddLog(LogCategory.Cmd, $"{player.displayName}: vanish OFF");
            }

            if (on && !player.IsSpectating() && GetToggle(player, VanishNoclipKey, false) &&
                Can(player, Permissions.Noclip) && !ClientNoclip(player))
            {
                SetToggle(player.userID, "f.noclip", true);
                SetNoclip(player);
            }

            RefreshStatus(player);
        }

        private void StartSpectate(BasePlayer admin, BasePlayer target)
        {
            if (admin == null || target == null || admin == target)
                return;
            if (admin.IsSpectating())
                StopSpectate(admin);
            GetAdmin(admin.userID).SpectateReturn = admin.transform.position;
            admin.spectateFilter = target.UserIDString;
            admin.StartSpectating();
            admin.spectateFilter = "";
            if (PeekAdmin(admin.userID)?.Vanished != true)
                SetVanish(admin, true);
            GetAdmin(admin.userID).SpectateShown = target.userID;
            ShowSpectateHint(admin);
            WatchInput(admin);
            AddLog(LogCategory.Cmd, $"{admin.displayName}: spectating {target.displayName}");
        }


        private void ShowSpectateHint(BasePlayer admin)
        {
            if (admin == null)
                return;
            var container = new CuiElementContainer();
            container.Add(new CuiElement
            {
                Parent = "Hud", Name = Layers.SpectateHint, DestroyUi = Layers.SpectateHint,
                Components =
                {
                    new CuiImageComponent { Color = "0 0 0 0.55" },
                    new CuiRectTransformComponent { AnchorMin = "0.5 0", AnchorMax = "0.5 0", OffsetMin = "-210 66", OffsetMax = "210 118" }
                }
            });
            CuiHelper.AddUi(admin, container);
            UpdateSpectateHint(admin);
        }

        private void UpdateSpectateHint(BasePlayer admin)
        {
            if (admin == null || !admin.IsConnected)
                return;
            var target = admin.SpectatingTarget;
            var name = target == null ? "-" : target.displayName;
            var container = new CuiElementContainer();
            container.Add(new CuiElement
            {
                Parent = Layers.SpectateHint, Name = Layers.SpectateHintText, DestroyUi = Layers.SpectateHintText,
                Components =
                {
                    new CuiTextComponent
                    {
                        Text =
                            $"{SafeFormat(GetLocalizedMessage(TranslateKey.SpectateTarget, admin), name)}\n{GetLocalizedMessage(TranslateKey.SpectateExit, admin)}",
                        FontSize = 12, Font = Fonts.Hud, Align = TextAnchor.MiddleCenter, Color = "1 1 1 1"
                    },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1", OffsetMin = "8 0", OffsetMax = "-8 0" }
                }
            });
            CuiHelper.AddUi(admin, container);
        }

        private void StopSpectate(BasePlayer admin)
        {
            if (admin == null)
                return;
            if (admin.IsConnected)
            {
                CuiHelper.DestroyUi(admin, Layers.SpectateHintText);
                CuiHelper.DestroyUi(admin, Layers.SpectateHint);
            }

            GetAdmin(admin.userID).SpectateShown = 0;
            if (admin.IsSpectating())
                admin.StopSpectating();
            if (PeekAdmin(admin.userID)?.Vanished == true)
                RestoreVanishAfterSpectate(admin);
            var spectateReturn = PeekAdmin(admin.userID)?.SpectateReturn;
            if (spectateReturn != null)
            {
                GetAdmin(admin.userID).SpectateReturn = null;
                if (admin.IsConnected)
                    TeleportPlayer(admin, spectateReturn.Value);
            }

            UnwatchInput(admin);
        }

        private void RestoreVanishAfterSpectate(BasePlayer admin)
        {
            try
            {
                BaseEntity.Query.Server?.RemovePlayer(admin);
            }
            catch (Exception ex)
            {
                PrintWarning($"Vanish: removing the player from the entity query failed: {ex.Message}");
            }

            admin.GetComponent<PaVanishComponent>()?.CreateProbe();
        }


        private bool IsStatusOn(BasePlayer p, string key)
        {
            var on = key switch
            {
                "vanish" => PeekAdmin(p.userID)?.Vanished == true,
                "esp" => IsEspActive(p),
                "god" => GetToggle(p, "f.god", false),
                "noclip" => GetToggle(p, "f.noclip", false),
                _ => false
            };
            return on && IsVitalShown(p, key);
        }

        private bool IsVitalShown(BasePlayer p, string key) =>
            !permission.UserHasPermission(p.UserIDString, Permissions.CanDisableVitals) ||
            GetToggle(p, "vit." + key, true);

        private string StatusText(BasePlayer p, string key)
        {
            if (key != "esp")
                return Array.Find(StatusDefs, s => s.Key == key).Text ?? key.ToUpperInvariant();

            var on = 0;
            foreach (var id in new[]
                     {
                         "e.players", "e.sleepers", "e.npc", "e.boxes", "e.loot", "e.tc", "e.beds",
                         "e.traps", "e.turrets", "e.vehicles", "e.stash", "e.drops", "e.nodes", "e.forage"
                     })
                if (GetToggle(p, id, false))
                    on++;
            return on == 0 ? "ESP" : $"ESP ·{on}";
        }

