        private void SetNoclip(BasePlayer player)
        {
            if (player == null)
                return;
            GetAdmin(player.userID).ToolSyncGrace = UnityEngine.Time.realtimeSinceStartup;
            var on = GetToggle(player, "f.noclip", false);
            if (on)
            {
                NoclipActive.Add(player.userID);
                UpdateToolAdmin(player);
                player.SendConsoleCommand("noclip");
            }
            else
            {
                player.SendConsoleCommand("noclip");
                NoclipActive.Remove(player.userID);
                UpdateToolAdmin(player);
            }
        }

        private void ApplyFeatures(BasePlayer player)
        {
            if (player == null || !player.IsConnected)
                return;
            ApplyVitalOverrides(player);
            EnsureEsp(player);
            EnsureInspect(player);
            Hammer.Ensure(player);
            RefreshStatus(player);
            SyncToolFeatures(player);
            RestoreWidget(player);
        }

        private void RestoreWidget(BasePlayer player)
        {
            if (player == null || !player.IsConnected)
                return;
            if (PeekAdmin(player.userID)?.WidgetOpen != true)
                return;
            if (!permission.UserHasPermission(player.UserIDString, Permissions.Use))
                return;

            UI_Widget(player);
            EnsureConsoleComponent(player);
        }

        private void SyncToolFeatures(BasePlayer player)
        {
            if (player == null || !player.IsConnected)
                return;
            if (!permission.UserHasPermission(player.UserIDString, Permissions.Use))
                return;
            if (GetToggle(player, "f.god", false))
                SetGod(player);
            if (!ClientStateSynced(player))
                return;
            if (GetToggle(player, "f.noclip", false) && !ClientNoclip(player))
                SetNoclip(player);
        }

        private void ToolSyncTick()
        {
            if (_storageBusy)
                return;
            for (var i = BasePlayer.activePlayerList.Count - 1; i >= 0; i--)
            {
                var p = BasePlayer.activePlayerList[i];
                if (p == null)
                    continue;
                if (p.IsSpectating())
                    SpectateRetarget(p);
                else
                    ReconcileGodNoclip(p);
            }
        }

        private BasePlayer NextSpectateTarget(BasePlayer admin)
        {
            foreach (var p in BasePlayer.activePlayerList)
                if (p != null && p != admin && !p.IsNpc && !p.IsSpectating() && !p.IsDead() && !p.IsSleeping() &&
                    PeekAdmin(p.userID)?.Vanished != true)
                    return p;
            return null;
        }

        private void SpectateRetarget(BasePlayer admin)
        {
            if (PeekAdmin(admin.userID)?.SpectateReturn == null)
                return;
            if (admin.SpectatingTarget != null)
                return;
            var next = NextSpectateTarget(admin);
            if (next == null)
            {
                Notify(admin, GetLocalizedMessage(TranslateKey.SpectateLost, admin), NotifyKind.Error);
                StopSpectate(admin);
                return;
            }

            admin.UpdateSpectateTarget(next.userID);
            GetAdmin(admin.userID).SpectateShown = next.userID;
            UpdateSpectateHint(admin);
        }

        private void SetGod(BasePlayer player)
        {
            if (player == null)
                return;
            GetAdmin(player.userID).ToolSyncGrace = UnityEngine.Time.realtimeSinceStartup;
            var on = GetToggle(player, "f.god", false);
            if (on)
            {
                GodActive.Add(player.userID);
                UpdateToolAdmin(player);
                if (player.IsConnected)
                    player.SendConsoleCommand("global.god", "true");
            }
            else
            {
                if (player.IsConnected)
                    player.SendConsoleCommand("global.god", "false");
                GodActive.Remove(player.userID);
                UpdateToolAdmin(player);
            }
        }

        private void UpdateToolAdmin(BasePlayer player)
        {
            if (player == null)
                return;
            var needs = GetToggle(player, "f.noclip", false) || GetToggle(player, "f.god", false);
            var ad = GetAdmin(player.userID);
            if (needs)
            {
                if (player.IsAdmin || ad.ToolTempAdmin)
                    return;
                player.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, true);
                player.SendNetworkUpdateImmediate();
                ad.ToolTempAdmin = true;
            }
            else if (ad.ToolTempAdmin)
            {
                ad.ToolTempAdmin = false;
                if (!player.IsConnected)
                    return;
                player.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, false);
                player.SendNetworkUpdateImmediate();
            }
        }

        private static bool ClientGod(BasePlayer p) =>
            p?.net?.connection?.info?.GetBool("global.god") ?? false;

        private static bool ClientNoclip(BasePlayer p) => p != null && p.IsFlying;

        private static bool ClientStateSynced(BasePlayer p) =>
            p != null && p.IsConnected && !p.IsReceivingSnapshot && !p.IsSleeping();

        private bool IsRealAdmin(BasePlayer p) =>
            p != null && p.IsAdmin && PeekAdmin(p.userID)?.ToolTempAdmin != true;

        private void ReconcileGodNoclip(BasePlayer player)
        {
            if (!ClientStateSynced(player))
                return;
            if (player.IsSpectating())
                return;
            if (!permission.UserHasPermission(player.UserIDString, Permissions.Use))
                return;
            if (UnityEngine.Time.realtimeSinceStartup - (PeekAdmin(player.userID)?.ToolSyncGrace ?? -999f) < 3f)
                return;

            if (IsRealAdmin(player) && ClientGod(player) && !GetToggle(player, "f.god", false))
            {
                SetToggle(player.userID, "f.god", true);
                GodActive.Add(player.userID);
                UpdateToolAdmin(player);
                RefreshStatus(player);
            }

            var cn = ClientNoclip(player);
            if (GetToggle(player, "f.noclip", false) != cn)
            {
                SetToggle(player.userID, "f.noclip", cn);
                if (cn)
                    NoclipActive.Add(player.userID);
                else
                    NoclipActive.Remove(player.userID);
                UpdateToolAdmin(player);
                RefreshStatus(player);
            }
        }

        private bool IsEspActive(BasePlayer p) => GetToggle(p, "e.on", false);

        internal float EspInterval()
        {
            var raw = GetInput(null, FieldKey.SecurityEspint, "2");
            if (!float.TryParse(raw, System.Globalization.NumberStyles.Float,
                    Ci, out var v))
                v = 2f;
            return Mathf.Clamp(v, 0.1f, 5f);
        }

        internal int EspMaxObjects()
        {
            var raw = GetInput(null, FieldKey.SecEspmax, "150");
            return int.TryParse(raw, out var v) ? Mathf.Clamp(v, 10, 2000) : 150;
        }

        private static readonly string[] EspColorKeys =
        {
            "e.players", "e.team", "e.admin", "e.sleepers", "e.npc", "e.boxes", "e.loot", "e.tc", "e.beds",
            "e.traps", "e.turrets", "e.vehicles", "e.stash", "e.drops", "e.nodes", "e.forage"
        };

        private static Color EspDefaultColor(string id) => id switch
        {
            "e.players" => EspEnemy,
            "e.team" => EspTeam,
            "e.admin" => EspAdmin,
            "e.sleepers" => EspSleeper,
            "e.npc" => EspNpc,
            "e.boxes" => EspStorage,
            "e.loot" => EspLoot,
            "e.tc" => EspTC,
            "e.beds" => EspBed,
            "e.traps" => EspTrap,
            "e.turrets" => EspTurret,
            "e.vehicles" => EspVehicle,
            "e.stash" => EspStash,
            "e.drops" => EspDrops,
            "e.nodes" => EspNodes,
            "e.forage" => EspForage,
            _ => Color.white
        };

        private static string EspColorKey(string id) => id + ".col";

        internal Color EspColor(BasePlayer admin, string id)
        {
            var raw = GetInput(admin, EspColorKey(id), null);
            if (string.IsNullOrEmpty(raw))
                return EspDefaultColor(id);

            var parts = raw.Split(' ');
            if (parts.Length < 3)
                return EspDefaultColor(id);
            if (!TryFloat(parts[0], out var r) || !TryFloat(parts[1], out var g) || !TryFloat(parts[2], out var b))
                return EspDefaultColor(id);

            var a = 1f;
            if (parts.Length > 3 && !TryFloat(parts[3], out a))
                a = 1f;
            return new Color(Mathf.Clamp01(r), Mathf.Clamp01(g), Mathf.Clamp01(b), Mathf.Clamp01(a));
        }

        private static Color SilColor(string key) => key switch
        {
            "red" => new Color(0.847f, 0.314f, 0.341f),
            "green" => new Color(0.404f, 0.745f, 0.494f),
            "cyan" => new Color(0.337f, 0.749f, 0.776f),
            "blue" => new Color(0.388f, 0.580f, 0.886f),
            "purple" => new Color(0.643f, 0.451f, 0.851f),
            _ => new Color(0.906f, 0.580f, 0.290f)
        };

        private void EnsureEsp(BasePlayer player)
        {
            if (player == null)
                return;
            var comp = player.GetComponent<PaEspComponent>();
            if (IsEspAllowed(player))
            {
                if (comp == null)
                {
                    comp = player.gameObject.AddComponent<PaEspComponent>();
                    comp.Init(this, player);
                }
            }
            else if (comp != null)
                UnityEngine.Object.Destroy(comp);
        }

        internal bool IsEspAllowed(BasePlayer player) =>
            player != null && player.IsConnected &&
            permission.UserHasPermission(player.UserIDString, Permissions.Use) && IsEspActive(player);


        private static float ParseNumber(string raw, float fallback) =>
            float.TryParse(raw, out var value) ? value : fallback;

        internal void ClearHammerHud(BasePlayer player)
        {
            if (player == null || !player.IsConnected)
                return;
            var ad = PeekAdmin(player.userID);
            if (ad != null)
                ad.HammerSignature = null;
            CuiHelper.DestroyUi(player, Layers.HammerHud);
            CuiHelper.DestroyUi(player, Layers.HammerNotice);
        }

        private void EnsureInspect(BasePlayer player)
        {
            if (player == null)
                return;
            var comp = player.GetComponent<PaInspectComponent>();
            if (IsInspectAllowed(player))
            {
                if (comp == null)
                    player.gameObject.AddComponent<PaInspectComponent>().Init(this, player);
                WatchInput(player);
            }
            else
            {
                if (comp != null)
                    UnityEngine.Object.Destroy(comp);
                UnwatchInput(player);
            }
        }

        private void WatchInput(BasePlayer player)
        {
            if (player == null)
                return;
            _inputWatch.Add(player.userID);
        }

        private void UnwatchInput(BasePlayer player)
        {
            if (player == null)
                return;
            if (player.IsSpectating())
                return;
            if (IsInspectAllowed(player))
                return;
            if (Hammer.Allowed(player))
                return;
            _inputWatch.Remove(player.userID);
            var ad = PeekAdmin(player.userID);
            if (ad != null)
                ad.InputMask = 0;
        }

        internal static bool IsSteamPlayer(BasePlayer p) => p != null && (ulong)p.userID > 76561197960265728UL;

        internal bool IsInspectAllowed(BasePlayer p) =>
            p != null && p.IsConnected && permission.UserHasPermission(p.UserIDString, Permissions.Use) &&
            Can(p, Permissions.Players) && GetToggle(p, "f.inspect", false);

        private bool IsInspectLive(BasePlayer p) =>
            IsInspectAllowed(p) && PeekAdmin(p.userID)?.UiOpen != true && !p.IsSleeping() && !p.IsDead() &&
            !p.IsSpectating();

        private BasePlayer InspectRaycast(BasePlayer admin)
        {
            if (admin == null || admin.eyes == null)
                return null;
            var mask = Rust.Layers.Solid | (1 << (int)Rust.Layer.Player_Server);
            if (!Physics.Raycast(admin.eyes.HeadRay(), out var hit, InspectRange, mask))
                return null;
            var t = hit.GetEntity() as BasePlayer;
            if (t == null || t == admin || t.IsDead())
                return null;
            return t;
        }

        internal void InspectHover(BasePlayer admin)
        {
            if (!IsInspectLive(admin))
            {
                ClearInspectHint(admin);
                return;
            }

            var ad = GetAdmin(admin.userID);
            var t = InspectRaycast(admin);
            var newId = t?.userID ?? 0;
            if (newId == ad.InspectHintTarget)
                return;
            ad.InspectHintTarget = newId;
            if (newId == 0)
            {
                HideInspectHint(admin);
                HideInspectDot(admin);
            }
            else
            {
                ShowInspectHint(admin, t.displayName, IsSteamPlayer(t));
                ShowInspectDot(admin);
            }
        }

        internal void ClearInspectHint(BasePlayer admin)
        {
            var ad = admin == null ? null : PeekAdmin(admin.userID);
            if (ad == null)
                return;
            HideInspectDot(admin);
            if (ad.InspectHintTarget == 0)
                return;
            ad.InspectHintTarget = 0;
            HideInspectHint(admin);
        }

        internal void InspectClick(BasePlayer admin)
        {
            if (!IsInspectLive(admin))
                return;
            var t = InspectRaycast(admin);
            if (t == null || !IsSteamPlayer(t))
                return;
            ClearInspectHint(admin);
            var ad = GetAdmin(admin.userID);
            ad.ActivePage = "players";
            ad.Popup = t.userID;
            ad.PopupAction = null;
            ad.IpRevealed = false;
            UI_Open(admin);
        }

        internal void InspectOpenInventory(BasePlayer admin)
        {
            if (!IsInspectLive(admin))
                return;
            var t = InspectRaycast(admin);
            if (t == null || t.IsDead())
                return;
            ClearInspectHint(admin);
            OpenInventory(admin, t, reopenPanel: false);
        }

