        private static string GenName(System.Random rnd, string[] syl)
        {
            var parts = rnd.Next(2, 4);
            var s = "";
            for (var p = 0; p < parts; p++)
                s += syl[rnd.Next(syl.Length)];
            return char.ToUpper(s[0]) + s.Substring(1) + rnd.Next(0, 100);
        }

        [ConsoleCommand("pa.debugspawn")]
        private void CommandDebugSpawn(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !permission.UserHasPermission(player.UserIDString, Permissions.Use))
                return;
            var count = Mathf.Clamp(arg.GetInt(0, 3), 1, 20);
            var origin = player.transform.position;
            var spawned = 0;
            for (var i = 0; i < count; i++)
            {
                var ang = i * (360f / count);
                var pos = origin + Quaternion.Euler(0, ang, 0) * Vector3.forward * 6f + Vector3.up * 0.5f;
                var ent = GameManager.server.CreateEntity("assets/prefabs/player/player.prefab", pos);
                if (ent == null)
                    continue;
                ent.Spawn();
                _debugBots.Add(ent);
                spawned++;
            }

            Notify(player, $"[debug] spawned {spawned} player bot(s) - enable ESP players to see them");
        }

        [ConsoleCommand("pa.debugclear")]
        private void CommandDebugClear(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !permission.UserHasPermission(player.UserIDString, Permissions.Use))
                return;
            DebugClearBots();
            Notify(player, "[debug] cleared spawned bots");
        }

        private void DebugClearBots()
        {
            foreach (var e in _debugBots)
                if (e != null && !e.IsDestroyed)
                    e.Kill();
            _debugBots.Clear();
        }
