        private void AddLog(LogCategory cat, string text)
        {
            var line = _log.Add(cat, text);
            if (line == null)
                return;

            if (_db != null && _db.IsSql &&
                (cat == LogCategory.Cmd || cat == LogCategory.Chat || cat == LogCategory.Join ||
                 cat == LogCategory.Leave))
            {
                lock (_logQueue)
                    _logQueue.Add(new object[] { line.Time, cat.ToString().ToLowerInvariant(), line.Text });
                ScheduleLogFlush();
            }
        }

        private void RefreshLogCap()
        {
            var raw = GetInput(null, FieldKey.SecLogmax, ConsoleMax.ToString());
            _log.SetCap(int.TryParse(raw, out var n) ? Mathf.Clamp(n, 50, ConsoleHardMax) : ConsoleMax);
        }

        private void ScheduleLogFlush()
        {
            if (_logFlushTimer != null)
                return;
            _logFlushTimer = timer.Once(3f, () =>
            {
                _logFlushTimer = null;
                FlushLogs();
            });
        }

        private void FlushLogs()
        {
            List<object[]> batch;
            lock (_logQueue)
            {
                if (_logQueue.Count == 0)
                    return;
                if (_db == null || !_db.IsSql)
                {
                    _logQueue.Clear();
                    return;
                }

                batch = new List<object[]>(_logQueue);
                _logQueue.Clear();
            }

            var sb = Facepunch.Pool.Get<System.Text.StringBuilder>();
            sb.Append("INSERT INTO pa_logs (ts, cat, msg) VALUES ");
            var args = new List<object>(batch.Count * 3);
            for (var i = 0; i < batch.Count; i++)
            {
                var b = i * 3;
                if (i > 0)
                    sb.Append(", ");
                sb.Append("(@").Append(b).Append(", @").Append(b + 1).Append(", @").Append(b + 2).Append(')');
                args.Add(batch[i][0]);
                args.Add(batch[i][1]);
                args.Add(batch[i][2]);
            }

            var query = sb.ToString();
            Facepunch.Pool.FreeUnmanaged(ref sb);
            _db.NonQuery(Sql.Builder.Append(query, args.ToArray()));
            if (++_logFlushes % 25 == 0)
                TrimLogs();
        }

        private void TrimLogs()
        {
            var keep = Mathf.Clamp(_log.Cap, 200, ConsoleHardMax);
            _db.NonQuery(Sql.Builder.Append(
                "DELETE FROM pa_logs WHERE id NOT IN (SELECT id FROM (SELECT id FROM pa_logs ORDER BY id DESC LIMIT @0) AS keep)",
                keep));
        }

        private List<LogLine> ConsoleSnapshot(string tab) => _log.Snapshot(tab);

        private int ConsoleCount() => _log.Count;


        private static int MonoCharsPerLine(float pixelWidth, int fontSize) =>
            Math.Max(8, Mathf.FloorToInt(pixelWidth / (fontSize * 0.62f)));

        private static List<string> WrapWords(string text, int firstMax, int restMax)
        {
            var lines = new List<string>();
            if (string.IsNullOrEmpty(text))
            {
                lines.Add("");
                return lines;
            }

            var max = firstMax;
            var cur = "";
            foreach (var word in text.Split(' '))
            {
                var w = word;
                while (w.Length > max)
                {
                    if (cur.Length > 0)
                    {
                        lines.Add(cur);
                        cur = "";
                        max = restMax;
                        if (w.Length <= max)
                            break;
                    }

                    lines.Add(w.Substring(0, max));
                    w = w.Substring(max);
                    max = restMax;
                }

                if (cur.Length == 0)
                    cur = w;
                else if (cur.Length + 1 + w.Length <= max)
                    cur += " " + w;
                else
                {
                    lines.Add(cur);
                    cur = w;
                    max = restMax;
                }
            }

            if (cur.Length > 0 || lines.Count == 0)
                lines.Add(cur);
            return lines;
        }

        private static List<string> ConsoleWrapVisual(LogLine l, int maxChars, bool tag, bool date = false)
        {
            var stamp = l.Stamp(date);
            var prefix = tag ? $"{stamp} [{Logger.Tag(l.Cat)}] " : $"{stamp} ";
            var chunks = WrapWords(l.Text.EscapeRichText(), Math.Max(8, maxChars - prefix.Length), maxChars);
            var outp = new List<string>(chunks.Count);
            for (var i = 0; i < chunks.Count; i++)
                outp.Add(i == 0
                    ? (tag
                        ? $"<color=#6b6258>{stamp}</color> <color={Logger.Hex(l.Cat)}>[{Logger.Tag(l.Cat)}]</color> {chunks[i]}"
                        : $"<color=#6b6258>{stamp}</color> <color={Logger.Hex(l.Cat)}>{chunks[i]}</color>")
                    : (tag ? chunks[i] : $"<color={Logger.Hex(l.Cat)}>{chunks[i]}</color>"));
            return outp;
        }


