        private List<ItemDefinition> AllItems()
        {
            if (_itemDefinitionsCache == null)
            {
                var src = ItemManager.GetItemDefinitions() ?? new List<ItemDefinition>();
                _itemDefinitionsCache = src.Where(d => d != null && !d.hidden && !string.IsNullOrEmpty(d.shortname))
                    .OrderBy(ItemName, StringComparer.OrdinalIgnoreCase).ToList();
            }

            return _itemDefinitionsCache;
        }

        private static string ItemName(ItemDefinition d)
        {
            var n = d.displayName.english;
            return string.IsNullOrEmpty(n) ? d.shortname : n;
        }

        private List<string> GiveCategories()
        {
            if (_giveCategoriesCache == null)
            {
                _giveCategoriesCache =
                    AllItems().Select(d => d.category.ToString()).Distinct().OrderBy(s => s).ToList();
                if (_giveCategoriesCache.Count == 0)
                    _giveCategoriesCache.Add("Items");
            }

            return _giveCategoriesCache;
        }

