        private ItemDefinition FindItem(string sn) =>
            AllItems().FirstOrDefault(d => string.Equals(d.shortname, sn, StringComparison.OrdinalIgnoreCase));

        private HashSet<string> GiveFav(ulong uid) => GetAdmin(uid).GiveFav ??= new HashSet<string>();

        private List<CartEntry> SavedCustoms(ulong uid) => GetAdmin(uid).Customs ??= new List<CartEntry>();

        private List<CartEntry> GiveFiltered(BasePlayer player)
        {
            var curCat = GetSelect(player, FieldKey.GiveCat, GiveCategories().FirstOrDefault() ?? "_fav");
            var sl = GetInput(player, FieldKey.GiveSearch, "").Trim().ToLowerInvariant();
            var fav = GiveFav(player.userID);
            var key = curCat + "" + sl;
            if (curCat == "_fav")
                key += "" + fav.Count + "" + string.Join(",", fav);
            var ad = GetAdmin(player.userID);
            if (ad.GiveFilterKey == key && ad.GiveFilterCache != null)
                return ad.GiveFilterCache;

            var result = AllItems()
                .Where(d => (curCat == "_fav" ? fav.Contains(d.shortname) : d.category.ToString() == curCat) &&
                            (sl.Length == 0 || ItemName(d).ToLowerInvariant().Contains(sl) ||
                             d.shortname.ToLowerInvariant().Contains(sl)))
                .Select(d => new CartEntry { Shortname = d.shortname, ItemId = d.itemid, Amount = 1, SkinId = 0, DisplayName = ItemName(d) })
                .ToList();
            ad.GiveFilterKey = key;
            ad.GiveFilterCache = result;
            return result;
        }


        private PickerLayout GiveLayout()
        {
            const int cw = 700,
                ch = 470,
                top = -96,
                botPad = 12,
                catX = 12,
                catW = 132,
                cartW = 196,
                gcols = 4,
                gap = 6;
            var colH = ch + top - botPad;
            var midX = catX + catW + 10;
            var cartX = cw - 12 - cartW;
            var midW = cartX - 10 - midX;
            var cellW = (midW - 8 - (gcols - 1) * gap) / gcols;
            var card = Layers.Root + ".pop.card";
            return new PickerLayout
            {
                MidX = midX, MidW = midW, Top = top, ColH = colH, Gcols = gcols, CellW = cellW,
                Gap = gap, CartX = cartX, CartW = cartW, Card = card
            };
        }

        private bool IsMuted(ulong id)
        {
            if (!_mutes.TryGetValue(id, out var m))
                return false;
            if (m.Until != 0 && m.Until <= DateTimeOffset.Now.ToUnixTimeSeconds())
            {
                _mutes.Remove(id);
                MutePersistRemove(id);
                return false;
            }

            return true;
        }

        private void ApplyMute(BasePlayer admin, ulong targetId, string targetName, string reason, long durSeconds,
            string comment = "", string byOverride = null)
        {
            if (string.IsNullOrWhiteSpace(reason))
                reason = GetLocalizedMessage(TranslateKey.MuteDefault, admin);
            reason = reason.Trim();
            var byName = !string.IsNullOrEmpty(byOverride) ? byOverride : admin?.displayName ?? "";
            var full = string.IsNullOrWhiteSpace(comment) ? reason : reason + " | " + comment.Trim();
            var until = durSeconds <= 0 ? 0 : DateTimeOffset.Now.ToUnixTimeSeconds() + durSeconds;
            var entry = new MuteEntry { Reason = reason, Until = until, By = byName };
            _mutes[targetId] = entry;
            MutePersistUpsert(targetId, entry);
            var durTxt = until == 0 ? GetLocalizedMessage(TranslateKey.MutePerm, admin) : FormatDuration(durSeconds);
            Notify(admin, SafeFormat(GetLocalizedMessage(TranslateKey.MessageMuted, admin), targetName, durTxt));
            AddLog(LogCategory.Cmd, $"{byName}: muted {targetName} for {durTxt} ({full})");
            DiscordEvent("d.s2", "d.hact", GetLocalizedMessage(TranslateKey.DiscordMessageMute, null),
                $"**{DiscordUser(targetName, targetId.ToString())}** · {durTxt} · {full}\n" +
                $"{GetLocalizedMessage(TranslateKey.DiscordMessageBy, null)} {(admin != null ? DiscordUser(admin) : byName)}",
                targetId.ToString());
            var target = FindOnline(targetId);
            if (target != null)
                Notify(target, SafeFormat(GetLocalizedMessage(TranslateKey.MuteNotice, target), reason, durTxt));
        }

        private void Unmute(BasePlayer admin, ulong targetId, string targetName)
        {
            _mutes.Remove(targetId);
            MutePersistRemove(targetId);
            Notify(admin, SafeFormat(GetLocalizedMessage(TranslateKey.MessageUnmuted, admin), targetName));
            AddLog(LogCategory.Cmd, $"{admin?.displayName}: unmuted {targetName}");
        }


        private static long DurationToSeconds(string token) => token switch
        {
            "1h" => 3600,
            "1d" => 86400,
            "7d" => 604800,
            "30d" => 2592000,
            _ => 0
        };


        private static bool IsNonPluginError(string condition)
        {
            if (string.IsNullOrEmpty(condition))
                return false;
            return condition.IndexOf("Rust+ companion server connectivity", StringComparison.OrdinalIgnoreCase) >= 0
                   || condition.IndexOf("Could not establish a TCP connection", StringComparison.OrdinalIgnoreCase) >= 0
                   || condition.IndexOf("Disabling Rust+ features", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private void ReconcilePlayerPerms(BasePlayer p)
        {
            if (p == null)
                return;
            var hasUse = permission.UserHasPermission(p.UserIDString, Permissions.Use);
            var changed = false;
            if (PeekAdmin(p.userID)?.Vanished == true && (!hasUse || !Can(p, Permissions.Vanish)))
            {
                SetVanish(p, false);
                changed = true;
            }

            if (GetToggle(p, "e.on", false) && (!hasUse || !Can(p, Permissions.Esp)))
            {
                SetToggle(p.userID, "e.on", false);
                EnsureEsp(p);
                changed = true;
            }

            if (GetToggle(p, "f.god", false) && (!hasUse || !Can(p, Permissions.God)))
            {
                SetToggle(p.userID, "f.god", false);
                changed = true;
            }

            if (GetToggle(p, "f.noclip", false) && (!hasUse || !Can(p, Permissions.Noclip)))
            {
                SetToggle(p.userID, "f.noclip", false);
                SetNoclip(p);
                changed = true;
            }

            if (GetToggle(p, "f.inspect", false) && (!hasUse || !Can(p, Permissions.Players)))
            {
                SetToggle(p.userID, "f.inspect", false);
                EnsureInspect(p);
                changed = true;
            }

            if (GetToggle(p, "f.hammer", false) && (!hasUse || !Hammer.Can(p)))
            {
                SetToggle(p.userID, "f.hammer", false);
                Hammer.Ensure(p);
                changed = true;
            }

            if (!changed)
                return;
            RefreshStatus(p);
            if (PeekAdmin(p.userID)?.UiOpen == true)
                UI_Open(p);
            if (PeekAdmin(p.userID)?.WidgetOpen == true)
                UI_Widget(p);
        }

        private void ReconcileByIdSoon(string id)
        {
            NextTick(() =>
            {
                if (ulong.TryParse(id, out var uid))
                {
                    var p = FindOnline(uid);
                    if (p != null)
                        ReconcilePlayerPerms(p);
                }
            });
        }

        private void RefreshConsoleFor(BasePlayer player)
        {
            if (player == null || PeekAdmin(player.userID)?.UiOpen != true)
                return;
            if (GetPage(player) != "console")
                return;
            if (!IsConsoleAllowed(player))
                return;
            if ((PeekAdmin(player.userID)?.Popup ?? 0) != 0 || PeekAdmin(player.userID)?.OpenDropdown != null)
                return;
            var tab = GetSelect(player, FieldKey.ConsoleTab, "all");
            var snap = ConsoleSnapshot(tab);
            var sig = snap.Count == 0
                ? tab + "/0"
                : $"{tab}/{snap.Count}/{snap[snap.Count - 1].Time}{snap[snap.Count - 1].Text}";
            if (PeekAdmin(player.userID)?.ConsoleSignature == sig)
                return;
            GetAdmin(player.userID).ConsoleSignature = sig;
            ApplyTheme(player);
            var container = new CuiElementContainer();
            UI_ConsoleLog(container, player);
            CuiHelper.AddUi(player, container);
        }

        #region Discord (webhooks)

        private void DiscordChat(BasePlayer player, string message)
        {
            if (!IsDiscordOn() || !GetToggle(null, "d.s4", false))
                return;
            var sid = player.UserIDString;
            var name = player.displayName;
            if (IsDiscordViaWebhook())
                DiscordPostChatEmbed(DiscordUrl("d.hchat"), name, sid, message);
            if (IsDiscordViaBot())
                Discord.BotChat(DiscordInput("d.cchat"), name, sid, message);
        }


        private static string SanitizeChat(string s)
        {
            if (string.IsNullOrEmpty(s))
                return "";
            s = s.Replace('<', '‹').Replace('>', '›').Replace('\n', ' ').Replace('\r', ' ').Trim();
            return s.Length > 240 ? s.Substring(0, 240) + "..." : s;
        }


        private void DiscordPostChatEmbed(string url, string name, string steamId, string message)
        {
            if (string.IsNullOrEmpty(url) || !url.StartsWith("http", StringComparison.OrdinalIgnoreCase))
                return;
            var botname = WebhookName("d.hchat");
            var avatar = WebhookAvatar("d.hchat");
            var profile = "https://steamcommunity.com/profiles/" + steamId;
            var icon = "https://companion-rust.facepunch.com/api/avatar/" + steamId;
            var sb = Facepunch.Pool.Get<System.Text.StringBuilder>();
            sb.Append('{');
            if (botname.Length > 0)
                sb.Append("\"username\":").Append(JsonStr(botname)).Append(',');
            if (avatar.Length > 0)
                sb.Append("\"avatar_url\":").Append(JsonStr(avatar)).Append(',');
            sb.Append("\"allowed_mentions\":{\"parse\":[]},\"embeds\":[{")
                .Append("\"author\":{\"name\":").Append(JsonStr(name))
                .Append(",\"url\":").Append(JsonStr(profile))
                .Append(",\"icon_url\":").Append(JsonStr(icon)).Append('}')
                .Append(",\"description\":").Append(JsonStr(message))
                .Append(",\"color\":").Append(DiscordColor());
            if (GetToggle(null, "d.ts", true))
                sb.Append(",\"timestamp\":").Append(JsonStr(DateTime.UtcNow.ToString("o")));
            sb.Append("}]}");
            var body = sb.ToString();
            Facepunch.Pool.FreeUnmanaged(ref sb);
            webrequest.Enqueue(url, body, (code, response) =>
                {
                    if (code != 200 && code != 204)
                        PrintWarning($"[PowerfulAdmin/Discord] chat webhook failed: HTTP {code} {response}");
                }, this, Oxide.Core.Libraries.RequestMethod.POST,
                new Dictionary<string, string> { ["Content-Type"] = "application/json" });
        }

        private bool IsDiscordOn() => GetToggle(null, "d.enabled", true);
        private string DiscordInput(string id) => GetInput(null, id, "").Trim();

        private int DiscordColor()
        {
            var hex = DiscordInput(FieldKey.DiscordColor).TrimStart('#');
            return hex.Length == 6 && int.TryParse(hex, System.Globalization.NumberStyles.HexNumber,
                Ci, out var v)
                ? v
                : 0xD08A60;
        }

        private string DiscordColorString()
        {
            var s = HexToRustFormat(DiscordInput(FieldKey.DiscordColor));
            return s ?? Palette.CAccent;
        }

        private static string HexToRustFormat(string hex)
        {
            hex = (hex ?? "").TrimStart('#');
            if (hex.Length == 6
                && int.TryParse(hex.Substring(0, 2), System.Globalization.NumberStyles.HexNumber, Ci, out var r)
                && int.TryParse(hex.Substring(2, 2), System.Globalization.NumberStyles.HexNumber, Ci, out var g)
                && int.TryParse(hex.Substring(4, 2), System.Globalization.NumberStyles.HexNumber, Ci, out var b))
                return $"{(r / 255f).ToString(Ci)} {(g / 255f).ToString(Ci)} {(b / 255f).ToString(Ci)} 1";
            return null;
        }

        private static string JsonStr(string s) => JsonConvert.ToString(s ?? "");

        private string WebhookName(string urlId)
        {
            var v = DiscordInput(urlId switch
            {
                "d.hbans" => "d.nbans", "d.hchat" => "d.nchat", "d.herr" => "d.nerr", _ => "d.nact"
            });
            return v.Length > 0 ? v : DiscordInput(FieldKey.DiscordBotname);
        }

        private string WebhookAvatar(string urlId)
        {
            var v = DiscordInput(urlId switch
            {
                "d.hbans" => "d.abans", "d.hchat" => "d.achat", "d.herr" => "d.aerr", _ => "d.aact"
            });
            return v.Length > 0 ? v : DiscordInput(FieldKey.DiscordAvatar);
        }

        private static string SteamAvatar(string steamId) =>
            string.IsNullOrEmpty(steamId) ? "" : "https://companion-rust.facepunch.com/api/avatar/" + steamId;

        private void DiscordPost(string url, string urlId, string title, string desc, string targetSteamId = null)
        {
            if (string.IsNullOrEmpty(url) || !url.StartsWith("http", StringComparison.OrdinalIgnoreCase))
                return;
            var botname = WebhookName(urlId);
            var avatar = WebhookAvatar(urlId);
            var footer = DiscordInput(FieldKey.DiscordFooter);
            var server = ConVar.Server.hostname ?? "";
            if (server.Length > 100)
                server = server.Substring(0, 100);
            var targetAvatar = SteamAvatar(targetSteamId);
            var thumb = targetAvatar.Length > 0 ? targetAvatar : (GetToggle(null, "d.thumb", true) ? avatar : "");

            var sb = Facepunch.Pool.Get<System.Text.StringBuilder>();
            sb.Append('{');
            if (botname.Length > 0)
                sb.Append("\"username\":").Append(JsonStr(botname)).Append(',');
            if (avatar.Length > 0)
                sb.Append("\"avatar_url\":").Append(JsonStr(avatar)).Append(',');
            sb.Append("\"allowed_mentions\":{\"parse\":[]},\"embeds\":[{");
            if (server.Length > 0)
            {
                sb.Append("\"author\":{\"name\":").Append(JsonStr(server));
                if (avatar.Length > 0)
                    sb.Append(",\"icon_url\":").Append(JsonStr(avatar));
                sb.Append("},");
            }

            sb.Append("\"title\":").Append(JsonStr(title))
                .Append(",\"description\":").Append(JsonStr(desc))
                .Append(",\"color\":").Append(DiscordColor());
            if (footer.Length > 0)
            {
                sb.Append(",\"footer\":{\"text\":").Append(JsonStr(footer));
                if (avatar.Length > 0)
                    sb.Append(",\"icon_url\":").Append(JsonStr(avatar));
                sb.Append('}');
            }

            if (thumb.Length > 0)
                sb.Append(",\"thumbnail\":{\"url\":").Append(JsonStr(thumb)).Append('}');
            if (GetToggle(null, "d.ts", true))
                sb.Append(",\"timestamp\":").Append(JsonStr(DateTime.UtcNow.ToString("o")));
            sb.Append("}]}");
            var body = sb.ToString();
            Facepunch.Pool.FreeUnmanaged(ref sb);
            webrequest.Enqueue(url, body, (code, response) =>
                {
                    if (code != 200 && code != 204)
                        PrintWarning($"[PowerfulAdmin/Discord] webhook POST failed: HTTP {code} {response}");
                }, this, Oxide.Core.Libraries.RequestMethod.POST,
                new Dictionary<string, string> { ["Content-Type"] = "application/json" });
        }

        private bool IsDiscordViaWebhook()
        {
            var d = GetSelect(null, FieldKey.DiscordDelivery, "webhook");
            return (d == "webhook" || d == "both") && GetToggle(null, "d.wh", true);
        }

        private bool IsDiscordViaBot()
        {
            var d = GetSelect(null, FieldKey.DiscordDelivery, "webhook");
            return (d == "bot" || d == "both") && GetToggle(null, "d.bot", false);
        }

        private static string BotChannelFor(string urlId) => urlId switch
        {
            "d.hbans" => "d.cbans",
            "d.hchat" => "d.cchat",
            "d.herr" => "d.cerr",
            _ => "d.cact"
        };

        private string EventDest(string urlId)
        {
            var viaBot = IsDiscordViaBot() && DiscordInput(BotChannelFor(urlId)).Length > 0;
            var viaWh = IsDiscordViaWebhook() && DiscordUrl(urlId).Length > 0;
            var chan = viaBot ? ChannelName(DiscordInput(BotChannelFor(urlId))) : "";
            if (viaBot && viaWh)
                return chan + " and Webhooked";
            if (viaBot)
                return chan;
            if (viaWh)
                return "Webhooked";
            return GetLocalizedMessage(TranslateKey.DiscordNotset, null);
        }

        private void DiscordBotSend(string channelKey, string title, string desc, string content,
            string targetSteamId = null)
        {
            var ch = DiscordInput(channelKey);
            if (ch.Length == 0)
                return;
            Discord.BotSend(ch, title ?? "", desc ?? "", content ?? "", SteamAvatar(targetSteamId));
        }

        private string DiscordUrl(string primaryId) =>
            new[] { primaryId, "d.hact", "d.hbans", "d.hchat", "d.herr" }
                .Select(DiscordInput).FirstOrDefault(u => u.Length > 0) ?? "";

        private void DiscordEvent(string toggleId, string urlId, string title, string desc, string targetSteamId = null)
        {
            if (!IsDiscordOn() || !GetToggle(null, toggleId, true))
                return;
            if (IsDiscordViaWebhook())
                DiscordPost(DiscordUrl(urlId), urlId, title, desc, targetSteamId);
            if (IsDiscordViaBot())
                DiscordBotSend(BotChannelFor(urlId), title, desc, "", targetSteamId);
        }

        private static string DiscordProfile(string steamId) =>
            !string.IsNullOrEmpty(steamId) && steamId.All(char.IsDigit)
                ? $"[{steamId}](https://steamcommunity.com/profiles/{steamId})"
                : steamId;

        private static string DiscordUser(string displayName, string steamId) =>
            string.IsNullOrEmpty(steamId)
                ? displayName ?? "?"
                : $"{(string.IsNullOrEmpty(displayName) ? "?" : displayName)} ({DiscordProfile(steamId)})";

        private static string DiscordUser(BasePlayer p) =>
            p == null ? "?" : DiscordUser(p.displayName, p.UserIDString);

        private void DiscordError(string condition, string stackTrace)
        {
            var title = GetLocalizedMessage(TranslateKey.DiscordMessageError, null);
            var desc = condition ?? "";
            if (!string.IsNullOrEmpty(stackTrace))
            {
                var st = stackTrace.Length > 1500 ? stackTrace.Substring(0, 1500) + "..." : stackTrace;
                desc += "\n```\n" + st + "\n```";
            }

            if (IsDiscordViaWebhook())
                DiscordPost(DiscordUrl("d.herr"), "d.herr", title, desc);
            if (IsDiscordViaBot())
                DiscordBotSend("d.cerr", title, desc, "");
        }

        private void DiscordPostContent(string url, string content, string urlId = null)
        {
            if (string.IsNullOrEmpty(url) || !url.StartsWith("http", StringComparison.OrdinalIgnoreCase))
                return;
            var botname = urlId == null ? DiscordInput(FieldKey.DiscordBotname) : WebhookName(urlId);
            var avatar = urlId == null ? DiscordInput(FieldKey.DiscordAvatar) : WebhookAvatar(urlId);
            var sb = Facepunch.Pool.Get<System.Text.StringBuilder>();
            sb.Append('{');
            if (botname.Length > 0)
                sb.Append("\"username\":").Append(JsonStr(botname)).Append(',');
            if (avatar.Length > 0)
                sb.Append("\"avatar_url\":").Append(JsonStr(avatar)).Append(',');
            sb.Append("\"allowed_mentions\":{\"parse\":[]},\"content\":").Append(JsonStr(content)).Append('}');
            var body = sb.ToString();
            Facepunch.Pool.FreeUnmanaged(ref sb);
            webrequest.Enqueue(url, body, (code, response) =>
                {
                    if (code != 200 && code != 204)
                        PrintWarning($"[PowerfulAdmin/Discord] webhook POST failed: HTTP {code} {response}");
                }, this, Oxide.Core.Libraries.RequestMethod.POST,
                new Dictionary<string, string> { ["Content-Type"] = "application/json" });
        }


        private void RefreshSettingsRoles()
        {
            foreach (var b in BasePlayer.activePlayerList)
                if (b != null && GetPage(b) == "settings" && PeekAdmin(b.userID)?.OpenDropdown == null &&
                    (PeekAdmin(b.userID)?.Popup ?? 0) == 0)
                    RefreshSettings(b);
        }

        private static string ColorWrap(string name, string hex)
        {
            hex = (hex ?? "").TrimStart('#');
            return hex.Length == 6 && hex != "000000" ? $"<color=#{hex}>{name}</color>" : name;
        }

        private string RoleColored(string id)
        {
            if (string.IsNullOrEmpty(id))
                return "";
            var r = Discord.Roles.FirstOrDefault(x => x[0] == id);
            return r != null ? ColorWrap(r[1], r.Length > 2 ? r[2] : "") : "role " + id;
        }


        private string ChannelName(string id)
        {
            if (string.IsNullOrEmpty(id))
                return "";
            var ch = Discord.Channels.FirstOrDefault(x => x[0] == id);
            return ch != null ? "#" + ch[1] : "#" + id;
        }

        private string GuildName(string id)
        {
            if (string.IsNullOrEmpty(id))
                return "";
            var g = Discord.Guilds.FirstOrDefault(x => x[0] == id);
            return g != null ? g[1] : id;
        }


        private string BotStatusLabel(BasePlayer player, out string color)
        {
            if (!Discord.Loaded)
            {
                color = Palette.CText3;
                return GetLocalizedMessage(TranslateKey.DiscordStatusNoExt, player);
            }

            switch (_botStatus)
            {
                case BotStatus.Connecting:
                {
                    color = Colors.CWarn;
                    return GetLocalizedMessage(TranslateKey.DiscordStatusConnecting, player);
                }
                case BotStatus.Online:
                {
                    color = Colors.CSuccess;
                    return GetLocalizedMessage(TranslateKey.DiscordStatusOnline, player);
                }
                case BotStatus.Error:
                {
                    color = Colors.CDanger;
                    return GetLocalizedMessage(TranslateKey.DiscordStatusError, player);
                }
                default:
                {
                    color = Palette.CText3;
                    return GetLocalizedMessage(TranslateKey.DiscordStatusOffline, player);
                }
            }
        }

        private bool IsBotConnected() => _botStatus == BotStatus.Online;


        private HashSet<string> RoleSet(string key) =>
            new(DiscordInput(key).Split(',').Select(p => p.Trim()).Where(p => p.Length > 0));

        private List<string> KickMuteTemplates()
        {
            var list = GetInput(null, FieldKey.SecurityTemplates, "").Split('|')
                .Select(p => p.Trim()).Where(p => p.Length > 0).ToList();
            if (list.Count == 0)
                list.AddRange(new[] { "AFK", "Toxicity", "Cheating", "Suspicious" });
            return list;
        }

