        #region Commands

        [ChatCommand("padmin")]
        private void CommandOpenChat(BasePlayer player, string command, string[] args)
        {
            if (player == null)
                return;
            if (!permission.UserHasPermission(player.UserIDString, Permissions.Use))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageNoperm, player), NotifyKind.Error);
                return;
            }

            GetAdmin(player.userID).ActivePage = "dashboard";
            UI_Open(player);
        }

        private static bool BindRelease(ConsoleSystem.Arg arg)
        {
            var count = arg?.Args?.Length ?? 0;
            if (count == 0)
                return false;
            return arg.GetString(count - 1) == "False";
        }

        private static string CommandArg(ConsoleSystem.Arg arg, int index)
        {
            if (arg == null || !arg.HasArgs(index + 1))
                return null;
            var raw = arg.GetString(index);
            if (raw == "True" || raw == "False")
                return null;
            return raw;
        }

        private bool TryAuth(ConsoleSystem.Arg arg, out BasePlayer player, int minArgs = 0, string perm = null)
        {
            player = arg?.Player();
            if (player == null || (minArgs > 0 && !arg.HasArgs(minArgs)) ||
                !permission.UserHasPermission(player.UserIDString, Permissions.Use))
                return false;
            return perm == null || Can(player, perm);
        }

        private static bool TryFloat(string s, out float f) => float.TryParse(s,
            System.Globalization.NumberStyles.Float, Ci, out f);

        [ConsoleCommand("pa.open")]
        private void CommandOpen(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player))
                return;
            if (BindRelease(arg))
                return;
            var page = CommandArg(arg, 0);
            if (!string.IsNullOrEmpty(page) && HasNavPerm(player, page))
            {
                GetAdmin(player.userID).ActivePage = page;
                GetAdmin(player.userID).LastPage = page;
            }

            UI_Open(player);
        }

        [ConsoleCommand("pa.setup")]
        private void CommandSetup(ConsoleSystem.Arg arg)
        {
            if (arg?.Player() != null)
                return;
            if (cfg != null && (cfg.SetupDone || cfg.PanelOpened))
            {
                PrintWarning(
                    "pa.setup is disabled (already used, or the panel has been opened). Manage access from the panel or via oxide.grant.");
                return;
            }

            var who = arg.GetString(0);
            if (string.IsNullOrWhiteSpace(who))
            {
                PrintWarning(
                    "Usage: pa.setup <steamid|name>  -  grants the full PowerfulAdmin permission set to that player (one-time).");
                return;
            }

            string id, name;
            if (ulong.TryParse(who.Trim(), out var sid))
            {
                id = sid.ToString();
                name = GetDropdownEntry(sid).DisplayName;
            }
            else
            {
                var target = BasePlayer.FindAwakeOrSleeping(who);
                if (target == null)
                {
                    PrintError($"No online player matches '{who}'. Pass a steamid to set up an offline player.");
                    return;
                }

                id = target.UserIDString;
                name = target.displayName;
            }

            var grant = new HashSet<string>(Permissions.All);
            foreach (var key in Permissions.PlayerActions)
                grant.Add(Permissions.GetPlayerActionPermission(key));
            foreach (var perm in permission.GetPermissions())
                if (perm != null && perm.StartsWith(Permissions.Prefix, StringComparison.OrdinalIgnoreCase))
                    grant.Add(perm);
            foreach (var perm in grant)
                permission.GrantUserPermission(id, perm, this);
            cfg ??= new ConfigData();
            cfg.SetupDone = true;
            SaveConfig();
            AddLog(LogCategory.Cmd, $"[console] pa.setup granted {grant.Count} permissions to {name} ({id})");
            PrintWarning(
                $"Granted the full PowerfulAdmin permission set ({grant.Count} permissions) to {name} ({id}). pa.setup is now disabled.");
        }

        [ServiceCommand("pa.nav")]
        private void CommandNav(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player, 1))
                return;
            var to = arg.GetString(0);
            if (GetPage(player) == to && PeekAdmin(player.userID)?.OpenDropdown == null &&
                (PeekAdmin(player.userID)?.Popup ?? 0) == 0 &&
                PeekAdmin(player.userID)?.FontPick == null &&
                PeekAdmin(player.userID)?.Search == null)
                return;
            GetAdmin(player.userID).ActivePage = to;
            GetAdmin(player.userID).LastPage = to;
            SaveSoon();
            GetAdmin(player.userID).OpenDropdown = null;
            GetAdmin(player.userID).FontPick = null;
            GetAdmin(player.userID).QuickDraft = null;
            GetAdmin(player.userID).Popup = 0;
            GetAdmin(player.userID).Search = null;
            UI_Navigate(player);
        }

        [ServiceCommand("pa.theme")]
        private void CommandTheme(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player, 1))
                return;
            if (Enum.TryParse(arg.GetString(0), out UITheme theme))
                SetTheme(player.userID, theme);
            UI_Build(player);
            if (PeekAdmin(player.userID)?.WidgetOpen == true)
                UI_Widget(player);
        }

        [ServiceCommand("pa.notetp")]
        private void CommandNoteTeleport(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() || !Can(player, Permissions.Map))
                return;
            var notes = MapNotes(player);
            var index = arg.GetInt(0, -1);
            if (index < 0 || index >= notes.Count || notes[index] == null)
            {
                RefreshBody(player);
                return;
            }

            ConVar.Global.TeleportToMarker(notes[index], player);
            AddLog(LogCategory.Cmd,
                $"{player.displayName}: marker teleport to {MapHelper.PositionToString(notes[index].worldPosition)}");
            RefreshBody(player);
        }

        [ServiceCommand("pa.mapzone")]
        private void CommandMapZone(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() || !Can(player, Permissions.Map))
                return;
            var deep = arg.GetInt(0) == 1;
            if (deep && !DeepSeaReady())
                return;
            GetAdmin(player.userID).MapDeepSea = deep;
            RefreshBody(player);
        }

        [ServiceCommand("pa.maptab")]
        private void CommandMapTab(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() || !Can(player, Permissions.Map))
                return;
            var ad = GetAdmin(player.userID);
            ad.MapNotesTab = arg.GetInt(0) == 1;
            RefreshBody(player);
        }

        [ServiceCommand("pa.notetpp")]
        private void CommandNoteTeleportPlayer(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(2) || !Can(player, Permissions.Map) || !Can(player, Permissions.Players))
                return;
            var target = FindOnline(arg.GetULong(0));
            if (target == null)
                return;
            var notes = NotesOf(target);
            var index = arg.GetInt(1, -1);
            if (index < 0 || index >= notes.Count || notes[index] == null)
            {
                RefreshBody(player);
                return;
            }

            ConVar.Global.TeleportToMarker(notes[index], player);
            AddLog(LogCategory.Cmd,
