            pie.menus = Facepunch.Pool.Get<List<ProtoBuf.CustomPieMenu>>();
            CommunityEntity.AddPieMenu(pie, GetLocalizedMessage(TranslateKey.HammerModeNone, admin),
                GetLocalizedMessage(TranslateKey.HammerModeNoneD, admin), ProtectCommand("pa.hammode none"),
                "assets/icons/close.png", false, ad.HammerMode == HammerAction.None, "", "");
            foreach (var mode in HammerTool.Modes(target))
                CommunityEntity.AddPieMenu(pie, HammerModeName(admin, mode), HammerModeHint(admin, mode),
                    ProtectCommand("pa.hammode " + HammerTool.ModeArg(mode)), HammerModeIcon(mode), false,
                    ad.HammerMode == mode, "", "");
            CommunityEntity.ServerInstance.SendPie(admin, pie);
        }

        private static string HammerModeIcon(HammerAction mode) => mode switch
        {
            HammerAction.Gibs => "assets/icons/explosion_sprite.png",
            HammerAction.Parents => "assets/icons/tools.png",
            HammerAction.Unlock => "assets/icons/lock.png",
            HammerAction.Timer => "assets/icons/timer.png",
            HammerAction.Loot => "assets/icons/inventory.png",
            _ => "assets/icons/close.png"
        };

        private static string ClockPart(int value) => value.ToString("D2");

        private static string ClockText(int seconds) =>
            ClockPart(Mathf.Clamp(seconds, 0, CrateTimerMax) / 60) + ":" +
            ClockPart(Mathf.Clamp(seconds, 0, CrateTimerMax) % 60);

        private static bool TryParseClock(string raw, out int seconds)
        {
            seconds = 0;
            if (string.IsNullOrEmpty(raw))
                return false;
            raw = raw.Trim();
            var colon = raw.IndexOf(':');
            if (colon < 0)
                return int.TryParse(raw, out seconds) && seconds >= 0 && seconds <= CrateTimerMax;
            if (!int.TryParse(raw.Substring(0, colon), out var minutes) ||
                !int.TryParse(raw.Substring(colon + 1), out var rest))
                return false;
            if (minutes < 0 || rest < 0 || rest > 59)
                return false;
            seconds = minutes * 60 + rest;
            return seconds <= CrateTimerMax;
        }

