        [ServiceCommand("pa.cratetimer")]
        private void CommandCrateTimer(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() || !Hammer.Can(player))
                return;
            var ad = GetAdmin(player.userID);
            var action = arg.GetString(0);
            if (action == "close")
            {
                ad.CrateTimerTarget = 0uL;
                ad.CrateTimerBad = false;
                CuiHelper.DestroyUi(player, Layers.CrateTimer);
                return;
            }

            var target = ad.CrateTimerTarget == 0uL
                ? null
                : BaseNetworkable.serverEntities.Find(new NetworkableId(ad.CrateTimerTarget)) as HackableLockedCrate;
            if (target == null)
            {
                ad.CrateTimerTarget = 0uL;
                CuiHelper.DestroyUi(player, Layers.CrateTimer);
                return;
            }

            if (action == "set")
            {
                var raw = arg.HasArgs(2) ? string.Join(" ", arg.Args.Skip(1).Select(a => a.ToString())) : "";
                SetInput(player.userID, FieldKey.HammerCrateTime, raw);
                ad.CrateTimerBad = !TryParseClock(raw, out _);
                UI_CrateTimer(player, target.ShortPrefabName);
                return;
            }

            if (action != "apply")
                return;
            if (!TryParseClock(GetInput(player, FieldKey.HammerCrateTime, ""), out var seconds))
            {
                ad.CrateTimerBad = true;
                UI_CrateTimer(player, target.ShortPrefabName);
                return;
            }

            HammerTool.SetTimer(target, seconds);
            ad.CrateTimerTarget = 0uL;
            ad.CrateTimerBad = false;
            ad.HammerSignature = null;
            ad.HammerArmed = 0;
            CuiHelper.DestroyUi(player, Layers.CrateTimer);
            Notify(player, SafeFormat(GetLocalizedMessage(TranslateKey.HammerCrateTimeDone, player),
                ClockText(seconds)));
            AddLog(LogCategory.Cmd,
                $"{player.displayName}: hammer crate timer {ClockText(seconds)} {target.ShortPrefabName}");
        }

