        [ServiceCommand("pa.qbrun")]
        private void CommandQuickRun(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player, 1))
                return;
            var qb = FindQuick(arg.GetString(0));
            if (qb == null || !CanUseQuick(player, qb))
                return;
            var targetId = arg.HasArgs(2) ? arg.GetULong(1) : 0uL;
            if (qb.Target == QuickTarget.Player && targetId == 0)
                return;
            if (qb.Target == QuickTarget.Player && !Can(player, Permissions.Players))
                return;
            if (qb.Confirm && !(arg.HasArgs(3) && arg.GetInt(2) == 1))
            {
                GetAdmin(player.userID).QuickConfirm = $"{qb.Id} {targetId}";
                UI_Open(player);
                return;
            }

            GetAdmin(player.userID).QuickConfirm = null;
            var point = Vector3.zero;
            if (qb.Target == QuickTarget.Player)
            {
                var body = FindActiveOrSleeping(targetId);
                if (body != null)
                    point = body.transform.position;
            }

            RunQuick(player, qb, targetId, point);
            Notify(player, SafeFormat(GetLocalizedMessage(TranslateKey.QbDone, player), qb.Name));
            UI_Open(player);
        }

