        [ServiceCommand("pa.qbset")]
        private void CommandQuickSet(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() || !Can(player, Permissions.Settings) || !Can(player, Permissions.QuickButtons))
                return;
            var draft = PeekAdmin(player.userID)?.QuickDraft;
            if (draft == null)
                return;
            var field = arg.GetString(0);
            var rest = arg.Args != null && arg.Args.Length > 1 ? string.Join(" ", arg.Args.Skip(1)) : "";
            if (field == "name")
                draft.Name = rest;
            else if (field == "cmd")
                draft.Command = rest;
            else if (field == "perm")
                draft.Permission = QuickPermName(rest);
            else if (field == "icon")
                draft.Icon = rest;
            else if (field == "confirm")
                draft.Confirm = !draft.Confirm;
            else if (field == "target" && Enum.TryParse<QuickTarget>(rest, out var target))
                draft.Target = target;
            else if (field == "place" && Enum.TryParse<QuickPlace>(rest, out var place))
                draft.Places ^= place;

            UI_Open(player);
        }

        [ServiceCommand("pa.qbsave")]
        private void CommandQuickSave(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !Can(player, Permissions.Settings) || !Can(player, Permissions.QuickButtons))
                return;
            var draft = PeekAdmin(player.userID)?.QuickDraft;
            if (draft == null)
                return;
            if (string.IsNullOrEmpty(draft.Name))
                draft.Name = draft.Id;
            var existing = FindQuick(draft.Id);
            if (existing == null)
            {
                draft.Order = cfg.QuickButtons.Count;
                cfg.QuickButtons.Add(draft);
            }
            else
                cfg.QuickButtons[cfg.QuickButtons.IndexOf(existing)] = draft;

            GetAdmin(player.userID).QuickDraft = null;
            RegisterQuickPermissions();
            SaveConfig();
            UI_Open(player);
        }

        [ServiceCommand("pa.qbdel")]
        private void CommandQuickDelete(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() || !Can(player, Permissions.Settings) || !Can(player, Permissions.QuickButtons))
                return;
            var qb = FindQuick(arg.GetString(0));
            if (qb == null)
                return;
            cfg.QuickButtons.Remove(qb);
            NormalizeQuickOrder();
            SaveConfig();
            UI_Open(player);
        }

        [ServiceCommand("pa.qbtoggle")]
        private void CommandQuickToggle(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() || !Can(player, Permissions.Settings) || !Can(player, Permissions.QuickButtons))
                return;
            var qb = FindQuick(arg.GetString(0));
            if (qb == null)
                return;
            qb.Enabled = !qb.Enabled;
            SaveConfig();
            UI_Open(player);
        }

        [ServiceCommand("pa.qbmove")]
        private void CommandQuickMove(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(2) || !Can(player, Permissions.Settings) || !Can(player, Permissions.QuickButtons))
                return;
            var qb = FindQuick(arg.GetString(0));
            if (qb == null)
                return;
            var index = cfg.QuickButtons.IndexOf(qb);
            var next = index + arg.GetInt(1);
            if (next < 0 || next >= cfg.QuickButtons.Count)
                return;
            cfg.QuickButtons.RemoveAt(index);
            cfg.QuickButtons.Insert(next, qb);
            NormalizeQuickOrder();
            SaveConfig();
            UI_Open(player);
        }

        private void NormalizeQuickOrder()
        {
            for (var i = 0; i < cfg.QuickButtons.Count; i++)
                cfg.QuickButtons[i].Order = i;
        }

