        [ConsoleCommand("pa.toggle")]
        private void CommandToggle(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player, 1))
                return;
            if (BindRelease(arg))
                return;
            var id = arg.GetString(0);
            if (!CanEditKey(player, id))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageNoperm, player), NotifyKind.Error);
                return;
            }

            var flag = CommandArg(arg, 1);
            if (id == VanishKey)
            {
                var on = flag != null ? flag != "0" : PeekAdmin(player.userID)?.Vanished != true;
                SetVanish(player, on);
                RefreshWidgetControls(player);
                if (GetPage(player) == "dashboard")
                    UI_FeatureRepaint(player, VanishKey, on, $"pa.toggle {VanishKey}");
                else
                    RefreshBody(player);
                return;
            }

            var val = flag != null ? flag != "0" : !GetToggle(player, id, false);
            SetToggle(player.userID, id, val);
            if (id == "f.god")
                SetGod(player);
            if (id == "f.noclip")
                SetNoclip(player);
            if (id == "f.inspect")
                EnsureInspect(player);
            if (id == "f.hammer")
                Hammer.Ensure(player);
            if (id.StartsWith("e."))
                EnsureEsp(player);
            if (id == "f.god" || id == "f.noclip" || id.StartsWith("e.") || id.StartsWith("vit."))
                RefreshStatus(player);
            if (id == "f.god" || id == "f.noclip" || id == "f.hammer" || id.StartsWith("e."))
                RefreshWidgetControls(player);
            if (id == DragKey)
            {
                foreach (var admin in BasePlayer.activePlayerList)
                    if (PeekAdmin(admin.userID)?.UiOpen == true)
                        UI_Build(admin);
                return;
            }

            if (GetPage(player) == "settings")
            {
                if (id == "d.wh" || id == "d.bot")
                    FixDelivery(player.userID);
                if (id == "d.bot")
                    Discord.BotEnabled(val);
                if (id == "d.dcgame")
                    Discord.BotReconnect();
                if (IsFlatToggle(id))
                    UI_ToggleRepaint(player, id, val);
                else
                    RefreshSettings(player);
            }
            else if (GetPage(player) == "dashboard")
                UI_FeatureRepaint(player, id, val, $"pa.toggle {id} {(val ? 0 : 1)}");
            else if (IsFlatToggle(id))
                UI_ToggleRepaint(player, id, val);
            else
                RefreshBody(player);
        }

        private static bool IsFlatToggle(string id) =>
            id.StartsWith("sec.", StringComparison.Ordinal) || id.StartsWith("ui.", StringComparison.Ordinal) ||
            id.StartsWith("vit.", StringComparison.Ordinal) || id.StartsWith(PieKeyPrefix, StringComparison.Ordinal) ||
            id.StartsWith("e.", StringComparison.Ordinal);

