        [ServiceCommand("pa.input")]
        private void CommandInput(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player, 1))
                return;
            var id = arg.GetString(0);
            if (!CanEditKey(player, id))
                return;
            var value = arg.HasArgs(2) ? string.Join(" ", arg.Args.Skip(1).Select(a => a.ToString())) : "";
            var phMap = PeekAdmin(player.userID)?.InputPlaceholders;
            if (phMap != null && phMap.TryGetValue(id, out var ph) && value == ph && !string.IsNullOrEmpty(ph))
                return;
            if (id == FieldKey.Search)
            {
                if (value == GetLocalizedMessage(TranslateKey.TopSearch, player))
                    value = "";
                if (string.IsNullOrWhiteSpace(value))
                    GetAdmin(player.userID).Search = null;
                else
                    GetAdmin(player.userID).Search = value.Trim();
                UI_Open(player);
                return;
            }

            SetInput(player.userID, id, value);
            if (id == FieldKey.PermsSearch || id == FieldKey.UserpermSearch)
                UI_Open(player);
            else if (id == FieldKey.MapSearch)
                RefreshBody(player);
            else if (id.StartsWith(BindKeyPrefix, StringComparison.Ordinal))
                RefreshBody(player);
            else if (id == FieldKey.SecLogmax)
            {
                RefreshLogCap();
                RefreshSettings(player);
            }
            else if (id.StartsWith("e.", StringComparison.Ordinal) && id.EndsWith(".col", StringComparison.Ordinal))
                RefreshBody(player);
            else if (id == FieldKey.DiscordColor)
                RefreshSettings(player);
            else if (id == FieldKey.DiscordActext)
                Discord.UpdateStatus();
            else if (IsWebhookIdentityKey(id))
                RefreshSettings(player);
        }

        private static bool IsWebhookIdentityKey(string id) =>
            id == "d.nbans" || id == "d.nchat" || id == "d.nact" || id == "d.nerr" ||
            id == "d.abans" || id == "d.achat" || id == "d.aact" || id == "d.aerr";

