        [ServiceCommand("pa.creategroup")]
        private void CommandCreateGroup(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player, 0, Permissions.Perms))
                return;
            var name = GetInput(player, FieldKey.NewgroupName, "").Trim().ToLowerInvariant().Replace(' ', '_');
            var parent = GetSelect(player, FieldKey.NewgroupParent, "none");
            if (name.Length > 0 && name.Length <= 24 && !permission.GroupExists(name))
            {
                permission.CreateGroup(name, name, 0);
                if (parent != "none" && parent != name && permission.GroupExists(parent))
                    permission.SetGroupParent(name, parent);
                SetSelect(player.userID, FieldKey.PermsGroup, name);
                AddLog(LogCategory.Cmd, $"{player.displayName}: created group {name}" +
                                        (parent != "none" ? $" (inherits {parent})" : ""));
            }

            SetInput(player.userID, FieldKey.NewgroupName, "");
            SetSelect(player.userID, FieldKey.NewgroupParent, "none");
            GetAdmin(player.userID).NewGroupOpen = false;
            UI_Open(player);
        }

        [ServiceCommand("pa.permgroup")]
        private void CommandPermGroup(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player, 1, Permissions.Perms))
                return;
            var g = CurrentPermGroup(player);
            var perm = arg.GetString(0);
            if (GroupInheritedFrom(g, perm) != null)
                return;
            if (PaPermLocked(perm))
                return;
            if (permission.GroupHasPermission(g, perm))
            {
                permission.RevokeGroupPermission(g, perm);
                AddLog(LogCategory.Cmd, $"{player.displayName}: -{perm} from {g}");
            }
            else
            {
                permission.GrantGroupPermission(g, perm, FindPermOwner(perm));
                AddLog(LogCategory.Cmd, $"{player.displayName}: +{perm} to {g}");
            }

            PermRefreshRow(player, PermTabContent, perm, p => permission.GroupHasPermission(g, p), "pa.permgroup",
                p => GroupInheritedFrom(g, p));
        }

