        private ExtSection FindPopupSection(string key)
        {
            if (string.IsNullOrEmpty(key))
                return null;
            return _extSections.FirstOrDefault(sec =>
                sec.PopupActions != null && sec.PopupActions.TryGetValue(key, out var action) && action != null);
        }

        private bool CanPopupAction(BasePlayer admin, string key)
        {
            if (admin == null)
                return false;
            var sec = FindPopupSection(key);
            if (sec == null)
                return false;
            return string.IsNullOrEmpty(sec.Permission) ||
                   permission.UserHasPermission(admin.UserIDString, sec.Permission);
        }

        private bool CanAction(BasePlayer admin, string key)
        {
            if (admin == null || string.IsNullOrEmpty(key))
                return false;
            if (Array.IndexOf(Permissions.PlayerActions, key) >= 0 &&
                !permission.UserHasPermission(admin.UserIDString, Permissions.GetPlayerActionPermission(key)))
                return false;
            if (key == "perms")
                return Can(admin, Permissions.Perms);
            if (key == "showmap")
                return Can(admin, Permissions.Map);
            if (key == "ban" || key == "freeze")
                return CanPopupAction(admin, key);
            if (key == "eco")
                return HasPerm(admin, Permissions.Economy);
            return true;
        }

        private Action<BasePlayer, ulong, string> FindPopupAction(string key)
        {
            var sec = FindPopupSection(key);
            return sec != null ? sec.PopupActions[key] : null;
        }

        [ServiceCommand("pa.act")]
        private void CommandPopupAction(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player, 1, Permissions.Players))
                return;
            var act = arg.GetString(0);
            if (act != "back" && !CanAction(player, act))
                return;
            var sectionAction = FindPopupAction(act);
            if (act == "back")
            {
                GetAdmin(player.userID).PopupAction = null;
                GetAdmin(player.userID).GiveCustomOpen = false;
                if (GetPage(player) == "map")
                    GetAdmin(player.userID).Popup = 0;
            }
            else if (act == "inv")
            {
                if (PeekAdmin(player.userID)?.Popup is ulong isid && isid != 0)
                {
                    var t = FindOnline(isid);
                    if (t != null)
                        OpenInventory(player, t);
                }

                GetAdmin(player.userID).Popup = 0;
                GetAdmin(player.userID).PopupAction = null;
                GetAdmin(player.userID).UiOpen = false;
                CuiHelper.DestroyUi(player, Layers.Root);
                return;
            }
            else if (act == "showmap")
            {
                var msid = PeekAdmin(player.userID)?.Popup ?? 0;
                var body = msid != 0 ? FindActiveOrSleeping(msid) : null;
                if (body == null || body.IsDead() || !Can(player, Permissions.Map))
                    return;
                var ad = GetAdmin(player.userID);
                ad.Popup = 0;
                ad.PopupAction = null;
                ad.MapSelected = msid;
                ad.MapDeepSea = IsDeepSeaPosition(body.transform.position) && DeepSeaReady();
                ad.ActivePage = "map";
                ad.LastPage = "map";
                SaveSoon();
                UI_Navigate(player);
                return;
            }
            else if (act == "spectate")
            {
                if (PeekAdmin(player.userID)?.Popup is ulong ssid && ssid != 0)
                {
                    var t = FindOnline(ssid);
                    if (t != null && t != player)
                        StartSpectate(player, t);
                }

                GetAdmin(player.userID).Popup = 0;
                GetAdmin(player.userID).PopupAction = null;
                GetAdmin(player.userID).UiOpen = false;
                CuiHelper.DestroyUi(player, Layers.Root);
                return;
            }
            else if (act == "mute" && PeekAdmin(player.userID)?.Popup is ulong msid && msid != 0 && IsMuted(msid))
            {
                Unmute(player, msid, GetDropdownEntry(msid).DisplayName);
            }
            else if (sectionAction != null)
            {
                var bsid = PeekAdmin(player.userID)?.Popup ?? 0;
                GetAdmin(player.userID).Popup = 0;
                GetAdmin(player.userID).PopupAction = null;
                if (bsid != 0)
                    sectionAction(player, bsid, GetDropdownEntry(bsid).DisplayName);
                return;
            }
            else
            {
                GetAdmin(player.userID).PopupAction = act;
                if (act == "heal")
                {
                    SetSelect(player.userID, FieldKey.PopupHealmode, "set");
                    SetInput(player.userID, FieldKey.PopupHealAmt, "");
                }
                else if (act == "tp")
                    SetSelect(player.userID, FieldKey.PopupTpmode, "tome");
                else if (act == "mute")
                {
                    SetSelect(player.userID, FieldKey.PopupDur, "1d");
                    SetInput(player.userID, FieldKey.PopupMutecustom, "");
                }
            }

            UI_Open(player);
        }

        private static void OpenLoot(BasePlayer admin, BaseEntity entitySource, string panelName,
            params ItemContainer[] containers)
        {
            var loot = admin.inventory.loot;
            loot.Clear();
            loot.PositionChecks = false;
            loot.entitySource = entitySource;
            loot.itemSource = null;
            foreach (var container in containers)
                loot.AddContainer(container);
            loot.MarkDirty();
            loot.SendImmediate();
            admin.ClientRPC(RpcTarget.Player("RPC_OpenLootPanel", admin), panelName);
        }

        private void OpenInventory(BasePlayer admin, BasePlayer target, bool reopenPanel = true)
        {
            if (admin?.inventory?.loot == null || target?.inventory == null)
                return;
            OpenLoot(admin, RelationshipManager.ServerInstance, "player_corpse",
                target.inventory.containerMain, target.inventory.containerWear, target.inventory.containerBelt);
            GetAdmin(admin.userID).InvReopen = reopenPanel;
            AddLog(LogCategory.Cmd, $"{admin.displayName}: opened inventory of {target.displayName}");
        }

        private void OpenContainer(BasePlayer admin, StorageContainer container)
        {
            if (admin?.inventory?.loot == null || container?.inventory == null)
                return;
            if (container.inventory.HasFlag(ItemContainer.Flag.NoItemInput))
            {
                container.inventory.SetFlag(ItemContainer.Flag.NoItemInput, false);
                _lootNoInput[admin.userID] = container;
            }

            OpenLoot(admin, container, container.panelName, container.inventory);
            AddLog(LogCategory.Cmd, $"{admin.displayName}: opened container {container.ShortPrefabName}");
        }

        [ServiceCommand("pa.mute")]
        private void CommandMute(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player, 1))
                return;
            if (!Can(player, Permissions.Players))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageNoperm, player), NotifyKind.Error);
                return;
            }

            if (!CanAction(player, "mute"))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageNoperm, player), NotifyKind.Error);
                return;
            }

            ulong.TryParse(arg.GetString(0), out var sid);
            if (sid == 0)
            {
                UI_Open(player);
                return;
            }

            if (IsMuted(sid))
                Unmute(player, sid, GetDropdownEntry(sid).DisplayName);
            else
                GetAdmin(player.userID).OpenDropdown = $"players.mute.{sid}";
            UI_Open(player);
        }

        [ServiceCommand("pa.do")]
        private void CommandDo(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player, 1))
                return;
            if (!Can(player, Permissions.Players))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageNoperm, player), NotifyKind.Error);
                return;
            }

            var parts = arg.GetString(0).Split('.');
            GetAdmin(player.userID).OpenDropdown = null;
            if (parts.Length < 3 || parts[0] != "players")
            {
                UI_Open(player);
                return;
            }

            var kind = parts[1];
            if (!CanAction(player, kind))
                return;
            ulong.TryParse(parts[2], out var sid);

            if (kind == "mute")
            {
                var reason = GetInput(player, FieldKey.DropdownReason, "").Trim();
                var comment = GetInput(player, FieldKey.DropdownComment, "").Trim();
                var custom = ParseDuration(GetInput(player, FieldKey.DropdownMutecustom, "").Trim());
                var dur = custom >= 0 ? custom : DurationToSeconds(GetSelect(player, FieldKey.DropdownDur, "1d"));
                var mname = GetDropdownEntry(sid).DisplayName;
                ApplyMute(player, sid, mname, reason, dur, comment);
                var muteNotifyMode = GetSelect(player, FieldKey.DropdownNotify, "player");
                if (muteNotifyMode == "chat" || muteNotifyMode == "notify")
                {
                    var muteMsg = SafeFormat(GetLocalizedMessage(TranslateKey.MuteBroadcast, player), mname,
                        string.IsNullOrWhiteSpace(reason)
                            ? GetLocalizedMessage(TranslateKey.MuteDefault, player)
                            : reason);
                    BroadcastByMode(muteNotifyMode, muteMsg);
                }

                SetInput(player.userID, FieldKey.DropdownReason, "");
                SetInput(player.userID, FieldKey.DropdownMutecustom, "");
                SetInput(player.userID, FieldKey.DropdownComment, "");
                UI_Open(player);
                return;
            }

            var target = FindActiveOrSleeping(sid);
            if (target == null)
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageNotfound, player), NotifyKind.Error);
                UI_Open(player);
                return;
            }

            if (kind == "tp")
            {
                switch (GetSelect(player, FieldKey.DropdownMode, "tome"))
                {
                    case "toplayer":
                    {
                        TeleportPlayer(player, target.transform.position);
                        Notify(player,
                            SafeFormat(GetLocalizedMessage(TranslateKey.MessageTpTo, player), target.displayName));
                        AddLog(LogCategory.Cmd, $"{player.displayName}: teleported to {target.displayName}");
                        break;
                    }
                    case "coords":
                    {
                        var cur = player.transform.position;
                        var dest = new Vector3(CoordAxis(player, FieldKey.TeleportX, cur.x),
                            CoordAxis(player, FieldKey.TeleportY, cur.y),
                            CoordAxis(player, FieldKey.TeleportZ, cur.z));
                        TeleportPlayer(target, dest);
                        Notify(player,
                            SafeFormat(GetLocalizedMessage(TranslateKey.MessageTpCoords, player), target.displayName,
                                Grid(dest)));
                        AddLog(LogCategory.Cmd, $"{player.displayName}: teleported {target.displayName} to {dest}");
                        break;
                    }
                    case "look":
                    {
                        var look = LookPoint(player);
                        TeleportPlayer(target, look);
                        Notify(player,
                            SafeFormat(GetLocalizedMessage(TranslateKey.MessageTpLook, player), target.displayName));
                        AddLog(LogCategory.Cmd,
                            $"{player.displayName}: teleported {target.displayName} along line of sight");
                        break;
                    }
                    default:
                    {
                        TeleportPlayer(target, player.transform.position);
                        Notify(player,
                            SafeFormat(GetLocalizedMessage(TranslateKey.MessageTpHere, player), target.displayName));
                        AddLog(LogCategory.Cmd, $"{player.displayName}: brought {target.displayName}");
                        break;
                    }
                }
            }
            else if (kind == "kick")
            {
                var reason = GetInput(player, FieldKey.DropdownReason, "").Trim();
                if (reason.Length == 0)
                    reason = GetLocalizedMessage(TranslateKey.KickDefault, player);
                var comment = GetInput(player, FieldKey.DropdownComment, "").Trim();
                var full = comment.Length > 0 ? reason + " | " + comment : reason;
                var kickNotifyMode = GetSelect(player, FieldKey.DropdownNotify, "player");
                if (kickNotifyMode == "chat" || kickNotifyMode == "notify")
                {
                    var kickMsg = SafeFormat(GetLocalizedMessage(TranslateKey.KickBroadcast, player),
                        target.displayName, reason);
                    BroadcastByMode(kickNotifyMode, kickMsg);
                }

                AddLog(LogCategory.Cmd, $"{player.displayName}: kicked {target.displayName} ({full})");
                Notify(player,
                    SafeFormat(GetLocalizedMessage(TranslateKey.MessageKicked, player), target.displayName));
                DiscordEvent("d.s1", "d.hbans", GetLocalizedMessage(TranslateKey.DiscordMessageKick, null),
                    $"**{DiscordUser(target)}** · {full}\n{GetLocalizedMessage(TranslateKey.DiscordMessageBy, null)} {DiscordUser(player)}",
                    target.UserIDString);
                target.Kick(reason);
                SetInput(player.userID, FieldKey.DropdownReason, "");
                SetInput(player.userID, FieldKey.DropdownComment, "");
            }
            else if (kind == "ban")
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageBanDisabled, player), NotifyKind.Error);
            }

            UI_Open(player);
        }

        [ServiceCommand("pa.exec")]
        private void CommandExecute(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player, 1))
                return;
            if (!Can(player, Permissions.Players))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageNoperm, player), NotifyKind.Error);
                return;
            }

            var sid = PeekAdmin(player.userID)?.Popup ?? 0;
            if (sid == 0)
                return;
            var key = arg.GetString(0);
            if (!CanAction(player, key))
                return;
            var target = FindActiveOrSleeping(sid);
            if (target == null)
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageNotfound, player), NotifyKind.Error);
                GetAdmin(player.userID).Popup = 0;
                GetAdmin(player.userID).PopupAction = null;
                UI_Open(player);
                return;
            }

            var name = target.displayName;

            switch (key)
            {
                case "heal":
                {
                    var max = target.MaxHealth();
                    var amtTxt = GetInput(player, FieldKey.PopupHealAmt, "").Trim();
                    var hmode = GetSelect(player, FieldKey.PopupHealmode, "set");
                    if (!TryFloat(amtTxt, out var amt))
                        amt = hmode == "set" ? target.health : 0f;
                    var newHp = hmode switch
                    {
                        "max" => max,
                        "add" => target.health + amt,
                        "sub" => target.health - amt,
                        _ => amt
                    };
                    target.health = Mathf.Clamp(newHp, 1f, max);
                    target.SendNetworkUpdate();
                    SetInput(player.userID, FieldKey.PopupHealAmt, "");
                    Notify(player,
                        SafeFormat(GetLocalizedMessage(TranslateKey.MessageHealed, player), name,
                            Mathf.RoundToInt(target.health)));
                    AddLog(LogCategory.Cmd,
                        $"{player.displayName}: healed {name} -> {Mathf.RoundToInt(target.health)}hp");
                    break;
                }
                case "kill":
                {
                    AddLog(LogCategory.Cmd, $"{player.displayName}: killed {name}");
                    Notify(player, SafeFormat(GetLocalizedMessage(TranslateKey.MessageKilled, player), name));
                    target.Die();
                    break;
                }
                case "strip":
                {
                    target.inventory?.Strip();
                    Notify(player, SafeFormat(GetLocalizedMessage(TranslateKey.MessageStripped, player), name));
                    AddLog(LogCategory.Cmd, $"{player.displayName}: stripped {name}");
                    break;
                }
                case "tp":
                {
                    switch (GetSelect(player, FieldKey.PopupTpmode, "tome"))
                    {
                        case "toplayer":
                        {
                            TeleportPlayer(player, target.transform.position);
                            Notify(player, SafeFormat(GetLocalizedMessage(TranslateKey.MessageTpTo, player), name));
                            AddLog(LogCategory.Cmd, $"{player.displayName}: teleported to {name}");
                            break;
                        }
                        case "coords":
                        {
                            var cur = player.transform.position;
                            var dest = new Vector3(CoordAxis(player, FieldKey.PopupTpX, cur.x),
                                CoordAxis(player, FieldKey.PopupTpY, cur.y),
                                CoordAxis(player, FieldKey.PopupTpZ, cur.z));
                            TeleportPlayer(target, dest);
                            Notify(player,
                                SafeFormat(GetLocalizedMessage(TranslateKey.MessageTpCoords, player), name,
                                    Grid(dest)));
                            AddLog(LogCategory.Cmd, $"{player.displayName}: teleported {name} to {dest}");
                            break;
                        }
                        case "look":
                        {
                            TeleportPlayer(target, LookPoint(player));
                            Notify(player,
                                SafeFormat(GetLocalizedMessage(TranslateKey.MessageTpLook, player), name));
                            AddLog(LogCategory.Cmd, $"{player.displayName}: teleported {name} along line of sight");
                            break;
                        }
                        default:
                        {
                            TeleportPlayer(target, player.transform.position);
                            Notify(player,
                                SafeFormat(GetLocalizedMessage(TranslateKey.MessageTpHere, player), name));
                            AddLog(LogCategory.Cmd, $"{player.displayName}: brought {name}");
                            break;
                        }
                    }

                    break;
                }
                case "kick":
                {
                    var kr = GetInput(player, FieldKey.PopupReason, "").Trim();
                    if (kr.Length == 0)
                        kr = GetLocalizedMessage(TranslateKey.KickDefault, player);
                    var kc = GetInput(player, FieldKey.PopupComment, "").Trim();
                    var kFull = kc.Length > 0
                        ? kr + " | " + kc
                        : kr;
                    var kickNotifyMode = GetSelect(player, FieldKey.PopupNotify, "player");
                    if (kickNotifyMode == "chat" || kickNotifyMode == "notify")
                    {
                        var kickMsg = SafeFormat(GetLocalizedMessage(TranslateKey.KickBroadcast, player), name, kr);
                        BroadcastByMode(kickNotifyMode, kickMsg);
                    }

                    AddLog(LogCategory.Cmd, $"{player.displayName}: kicked {name} ({kFull})");
                    Notify(player, SafeFormat(GetLocalizedMessage(TranslateKey.MessageKicked, player), name));
                    DiscordEvent("d.s1", "d.hbans", GetLocalizedMessage(TranslateKey.DiscordMessageKick, null),
                        $"**{DiscordUser(target)}** · {kFull}\n{GetLocalizedMessage(TranslateKey.DiscordMessageBy, null)} {DiscordUser(player)}",
                        target.UserIDString);
                    target.Kick(kr);
                    SetInput(player.userID, FieldKey.PopupReason, "");
                    SetInput(player.userID, FieldKey.PopupComment, "");
                    break;
                }
                case "mute":
                {
                    var custom = ParseDuration(GetInput(player, FieldKey.PopupMutecustom, "").Trim());
                    var dur = custom >= 0 ? custom : DurationToSeconds(GetSelect(player, FieldKey.PopupDur, "1d"));
                    var mreason = GetInput(player, FieldKey.PopupReason, "").Trim();
                    var mcomment = GetInput(player, FieldKey.PopupComment, "").Trim();
                    ApplyMute(player, target.userID, name, mreason, dur, mcomment);
                    var muteNotifyMode = GetSelect(player, FieldKey.PopupNotify, "player");
                    if (muteNotifyMode == "chat" || muteNotifyMode == "notify")
                    {
                        var muteMsg = SafeFormat(GetLocalizedMessage(TranslateKey.MuteBroadcast, player), name,
                            string.IsNullOrWhiteSpace(mreason)
                                ? GetLocalizedMessage(TranslateKey.MuteDefault, player)
                                : mreason);
                        BroadcastByMode(muteNotifyMode, muteMsg);
                    }

                    SetInput(player.userID, FieldKey.PopupReason, "");
                    SetInput(player.userID, FieldKey.PopupMutecustom, "");
                    SetInput(player.userID, FieldKey.PopupComment, "");
                    break;
                }
                case "ban":
                {
                    Notify(player, GetLocalizedMessage(TranslateKey.MessageBanDisabled, player), NotifyKind.Error);
                    break;
                }
                default:
                {
                    Notify(player, GetLocalizedMessage(TranslateKey.MessageSoon, player));
                    break;
                }
            }

            GetAdmin(player.userID).Popup = 0;
            GetAdmin(player.userID).PopupAction = null;
            UI_Open(player);
        }

