        [ServiceCommand("pa.give")]
        private void CommandGive(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player, 1))
                return;
            if (!Can(player, Permissions.Players))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageNoperm, player), NotifyKind.Error);
                return;
            }

            if (!CanAction(player, "give"))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageNoperm, player), NotifyKind.Error);
                return;
            }

            var op = arg.GetString(0);
            var cart = GiveCart(player.userID);
            var curCat = GetSelect(player, FieldKey.GiveCat, GiveCategories().FirstOrDefault() ?? "_fav");
            var partial = false;
            string partialItem = null;
            if (op == "fav" && arg.HasArgs(2))
            {
                var fav = GiveFav(player.userID);
                if (!fav.Remove(arg.GetString(1)))
                    fav.Add(arg.GetString(1));
                partial = curCat != "_fav";
                partialItem = arg.GetString(1);
            }
            else if (op == "addcustom")
            {
                var saved = SavedCustoms(player.userID);
                var cidx = arg.GetInt(1, -1);
                if (cidx >= 0 && cidx < saved.Count)
                {
                    var s = saved[cidx];
                    cart.Add(new CartEntry
                    {
                        Shortname = s.Shortname, ItemId = s.ItemId, Amount = s.Amount < 1 ? 1 : s.Amount,
                        SkinId = s.SkinId,
                        DisplayName = s.DisplayName
                    });
                    partial = true;
                    partialItem = "";
                }
            }
            else if (op == "delcustom")
            {
                var saved = SavedCustoms(player.userID);
                var didx = arg.GetInt(1, -1);
                if (didx >= 0 && didx < saved.Count)
                {
                    saved.RemoveAt(didx);
                    SaveSoon();
                }
            }
            else if (op == "confirm" || op == "clear")
            {
                if (op == "confirm" && cart.Count > 0 && PeekAdmin(player.userID)?.Popup is ulong sid && sid != 0)
                {
                    var target = FindOnline(sid);
                    if (target != null)
                    {
                        var total = 0;
                        foreach (var e in cart)
                        {
                            var item = e.GetItem(FindItem(e.Shortname));
                            if (item == null)
                                continue;

                            target.GiveItem(item, BaseEntity.GiveItemReason.PickedUp);
                            total++;
                        }

                        Notify(player,
                            SafeFormat(GetLocalizedMessage(TranslateKey.MessageGave, player), target.displayName));
                        AddLog(LogCategory.Cmd, $"{player.displayName}: gave {total} stack(s) to {target.displayName}");
                    }
                    else
                        Notify(player, GetLocalizedMessage(TranslateKey.MessageNotfound, player), NotifyKind.Error);
                }

                cart.Clear();
                if (op == "confirm")
                {
                    GetAdmin(player.userID).PopupAction = null;
                    GetAdmin(player.userID).Popup = 0;
                    GetAdmin(player.userID).GiveCustomOpen = false;
                }
            }
            else if (op == "customadd")
            {
                var def = FindItem(GetInput(player, FieldKey.GiveCustShort, "").Trim());
                if (def != null)
                {
                    if (!int.TryParse(GetInput(player, FieldKey.GiveCustQty, ""), out var q) || q < 1)
                        q = 1;
                    ulong.TryParse(GetInput(player, FieldKey.GiveCustSkin, ""), out var skin);
                    var nm = GetInput(player, FieldKey.GiveCustName, "").Trim();
                    var entry = new CartEntry
                    {
                        Shortname = def.shortname, ItemId = def.itemid, Amount = q, SkinId = skin,
                        DisplayName = nm.Length > 0 ? nm : ItemName(def)
                    };
                    cart.Add(entry);
                    if (GetToggle(player, "give.cust.save", false))
                    {
                        SavedCustoms(player.userID).Add(new CartEntry
                        {
                            Shortname = entry.Shortname, ItemId = entry.ItemId, Amount = entry.Amount,
                            SkinId = entry.SkinId,
                            DisplayName = entry.DisplayName
                        });
                        SaveSoon();
                    }

                    SetInput(player.userID, FieldKey.GiveCustShort, "");
                    SetInput(player.userID, FieldKey.GiveCustName, "");
                    SetInput(player.userID, FieldKey.GiveCustSkin, "");
                    SetInput(player.userID, FieldKey.GiveCustQty, "");
                    GetAdmin(player.userID).GiveCustomOpen = false;
                }
            }
            else if (op == "add" && arg.HasArgs(2))
            {
                var def = FindItem(arg.GetString(1));
                if (def != null)
                {
                    var amt = arg.GetInt(2, 1);
                    var asBp = GetSelect(player, FieldKey.GiveBpmode, "item") == "bp" && def.Blueprint != null;
                    var e = cart.FirstOrDefault(x =>
                        x.Shortname == def.shortname && x.SkinId == 0 && x.Blueprint == asBp);
                    if (e != null)
                        e.Amount += amt;
                    else
                        cart.Add(new CartEntry
                        {
                            Shortname = def.shortname, ItemId = def.itemid, Amount = amt, SkinId = 0,
                            DisplayName = ItemName(def), Blueprint = asBp
                        });
                    partial = true;
                    partialItem = def.shortname;
                }
            }
            else if (op == "bp")
            {
                var idx = arg.GetInt(1, -1);
                if (idx >= 0 && idx < cart.Count)
                {
                    if (FindItem(cart[idx].Shortname)?.Blueprint != null)
                        cart[idx].Blueprint = !cart[idx].Blueprint;
                    partial = true;
                    partialItem = cart[idx].Shortname;
                }
            }
            else if (op == "setamt")
            {
                var idx = arg.GetInt(1, -1);
                if (idx >= 0 && idx < cart.Count)
                {
                    var raw = arg.GetString(2, "").Trim();
                    if (int.TryParse(raw, out var qty) && qty > 0)
                        cart[idx].Amount = qty;
                    else
                        Notify(player, GetLocalizedMessage(TranslateKey.GiveAmtBad, player), NotifyKind.Error);
                    partial = true;
                    partialItem = cart[idx].Shortname;
                }
            }
            else
            {
                var idx = arg.GetInt(1, -1);
                if (idx >= 0 && idx < cart.Count)
                {
                    var sn = cart[idx].Shortname;
                    var amt = arg.GetInt(2, 1);
                    if (op == "inc")
                        cart[idx].Amount += amt;
                    else if (op == "dec")
                    {
                        cart[idx].Amount -= amt;
                        if (cart[idx].Amount <= 0)
                            cart.RemoveAt(idx);
                    }
                    else if (op == "rem")
                        cart.RemoveAt(idx);

                    partial = true;
                    partialItem = sn;
                }
            }

            if (partial)
                GivePartial(player, partialItem);
            else
                UI_Open(player);
        }

        [ServiceCommand("pa.bp")]
        private void CommandBlueprint(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() || !Can(player, Permissions.Players) || !CanAction(player, "bp"))
                return;
            var op = arg.GetString(0);
            if (op == "cat")
            {
                SetSelect(player.userID, FieldKey.BlueprintCat, arg.GetString(1));
                UI_Open(player);
                return;
            }

            if (op == "search")
            {
                var q = arg.HasArgs(2) ? string.Join(" ", arg.Args.Skip(1)) : "";
                SetInput(player.userID, FieldKey.BlueprintSearch, q.Trim());
                UI_Open(player);
                return;
            }

            if (op == "cancel")
            {
                CuiHelper.DestroyUi(player, Layers.Root + ".pop.card.bpconfirm");
                return;
            }

            var sid = PeekAdmin(player.userID)?.Popup ?? 0;
            if (sid == 0)
                return;
            var target = FindOnline(sid);
            if (target == null)
            {
                Notify(player, GetLocalizedMessage(TranslateKey.BlueprintOffline, player), NotifyKind.Error);
                return;
            }

            if (op == "unlock")
            {
                var def = FindItem(arg.GetString(1));
                if (def?.Blueprint != null)
                {
                    if (target.blueprints.IsUnlocked(def))
                    {
                        RevokeBlueprint(target, def);
                        AddLog(LogCategory.Cmd,
                            $"{player.displayName}: revoked blueprint {def.shortname} from {target.displayName}");
                    }
                    else
                    {
                        target.blueprints.Unlock(def);
                        AddLog(LogCategory.Cmd,
                            $"{player.displayName}: unlocked blueprint {def.shortname} for {target.displayName}");
                    }

                    RefreshBlueprintCell(player, def.shortname);
                }

                return;
            }

            if (op == "all" || op == "reset")
            {
                ApplyTheme(player);
                var cc = new CuiElementContainer();
                UI_BpConfirm(cc, Layers.Root + ".pop.card", player, op);
                CuiHelper.AddUi(player, cc);
                return;
            }

            if (op == "allyes")
            {
                target.blueprints.UnlockAll();
                AddLog(LogCategory.Cmd, $"{player.displayName}: unlocked ALL blueprints for {target.displayName}");
                UI_Open(player);
                return;
            }

            if (op == "resetyes")
            {
                target.blueprints.Reset();
                AddLog(LogCategory.Cmd, $"{player.displayName}: reset blueprints for {target.displayName}");
                UI_Open(player);
            }
        }

        private void RefreshBlueprintCell(BasePlayer player, string shortname)
        {
            if (PeekAdmin(player.userID)?.PopupAction != "bp")
                return;
            var sid = PeekAdmin(player.userID)?.Popup ?? 0;
            var target = sid != 0 ? FindOnline(sid) : null;
            if (target == null)
                return;
            var def = FindItem(shortname);
            if (def == null)
                return;
            var cats = GiveCategories();
            var curCat = GetSelect(player, FieldKey.BlueprintCat, cats.Count > 0 ? cats[0] : "");
            var search = GetInput(player, FieldKey.BlueprintSearch, "").Trim().ToLowerInvariant();
            var items = AllItems().Where(d => IsTogglableBlueprint(d) && d.category.ToString() == curCat &&
                                              (search.Length == 0 || ItemName(d).ToLowerInvariant().Contains(search) ||
                                               d.shortname.ToLowerInvariant().Contains(search))).ToList();
            var j = items.FindIndex(d => d.itemid == def.itemid);
            if (j < 0)
                return;
            ApplyTheme(player);
            var card = Layers.Root + ".pop.card";
            var container = new CuiElementContainer();
            UI_BlueprintCellState(container, card + ".bpitems.c.l.b" + j, target.blueprints.IsUnlocked(items[j]));
            var unlocked = CountUnlockedBlueprints(target);
            UI_BpCount(container, card + ".bpcol", player, unlocked);
            CuiHelper.AddUi(player, container);
        }

        private void UI_BpCount(CuiElementContainer container, string colName, BasePlayer player, int unlocked)
        {
            var cnt = colName + ".cnt";
            container.Add(new CuiElement
            {
                Parent = colName, Name = cnt, DestroyUi = cnt,
                Components =
                {
                    new CuiTextComponent
                    {
                        Text = SafeFormat(GetLocalizedMessage(TranslateKey.BlueprintUnlockedCount, player),
                            unlocked),
                        FontSize = 11, Font = Fonts.Title, Align = TextAnchor.MiddleLeft, Color = Palette.CText
                    },
                    new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = "0 -22", OffsetMax = "0 0" }
                }
            });
        }

        private void UI_BpConfirm(CuiElementContainer container, string card, BasePlayer player, string op)
        {
            var ov = card + ".bpconfirm";
            container.Add(new CuiElement
            {
                Parent = card, Name = ov, DestroyUi = ov,
                Components =
                {
                    new CuiImageComponent { Color = "0 0 0 0.7" }, new CuiNeedsCursorComponent(),
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1" }
                }
            });
            var box = ov + ".box";
            container.Add(new CuiElement
            {
                Parent = ov, Name = box,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CSurface },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = "-180 -72", OffsetMax = "180 72" }
                }
            });
            UI_Text(container, box,
                GetLocalizedMessage(op == "reset" ? TranslateKey.BlueprintResetConfirm : TranslateKey.BlueprintAllConfirm, player),
                12, Fonts.Title, TextAnchor.MiddleCenter, Palette.CText, "0 1", "1 1", "16 -68", "-16 -16");
            UI_Btn(container, box, GetLocalizedMessage(TranslateKey.BlueprintConfirmCancel, player), "pa.bp cancel",
                Palette.CElev, 11, Fonts.Title, TextAnchor.MiddleCenter, Palette.CText2, "0 0", "0.5 0", "16 16",
                "-6 44");
            UI_Btn(container, box, GetLocalizedMessage(TranslateKey.BlueprintConfirmYes, player),
                op == "reset" ? "pa.bp resetyes" : "pa.bp allyes",
                op == "reset" ? Colors.CDangerSoft : Colors.CSuccessSoft, 11, Fonts.Title, TextAnchor.MiddleCenter,
                op == "reset" ? Colors.CDanger : Colors.CSuccess, "0.5 0", "1 0", "6 16", "-16 44");
        }

        private void RevokeBlueprint(BasePlayer target, ItemDefinition def)
        {
            var info = target.PersistantPlayerInfo;
            if (info.unlockedItems == null || !info.unlockedItems.Remove(def.itemid))
                return;
            target.PersistantPlayerInfo = info;
            target.SendNetworkUpdateImmediate();
            target.ClientRPC(RpcTarget.Player("UnlockedBlueprint", target), 0);
        }

        [ServiceCommand("pa.mod")]
        private void CommandModifier(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() || !Can(player, Permissions.Players) || !CanAction(player, "mod"))
                return;
            var op = arg.GetString(0);
            var sid = PeekAdmin(player.userID)?.Popup ?? 0;
            if (sid == 0)
                return;
            var target = FindOnline(sid);
            if (target == null || target.modifiers == null)
            {
                Notify(player, GetLocalizedMessage(TranslateKey.BlueprintOffline, player), NotifyKind.Error);
                return;
            }

            if (op == "clear")
            {
                target.modifiers.RemoveAll();
                target.modifiers.SendChangesToClient();
                AddLog(LogCategory.Cmd, $"{player.displayName}: cleared all modifiers on {target.displayName}");
                UI_Open(player);
                return;
            }

            var types = (Modifier.ModifierType[])Enum.GetValues(typeof(Modifier.ModifierType));
            if (!int.TryParse(arg.GetString(1), out var idx) || idx < 0 || idx >= types.Length)
                return;
            var type = types[idx];

            if (op == "set")
            {
                var cur = target.modifiers.GetValue(type, 0f);
                if (!TryFloat(GetInput(player, FieldKey.PrefixModVal + idx, ModValueDefault(cur)), out var val))
                    return;
                if (!TryFloat(GetInput(player, FieldKey.PrefixModDur + idx, "600"), out var dur) || dur <= 0)
                    dur = 600f;
                RemoveModifierType(target, type);
                var m = new Modifier();
                m.Init(type, Modifier.ModifierSource.Tea, val, dur, dur);
                target.modifiers.Add(m);
                AddLog(LogCategory.Cmd,
                    $"{player.displayName}: set modifier {type} = {val} ({dur}s) on {target.displayName}");
            }
            else if (op == "del")
            {
                RemoveModifierType(target, type);
                SetInput(player.userID, FieldKey.PrefixModVal + idx, "");
                SetInput(player.userID, FieldKey.PrefixModDur + idx, "");
                AddLog(LogCategory.Cmd, $"{player.displayName}: removed modifier {type} from {target.displayName}");
            }
            else
                return;

            target.modifiers.SendChangesToClient();
            RefreshModifierRow(player, idx);
        }

        private static void RemoveModifierType(BasePlayer target, Modifier.ModifierType type)
        {
            for (var i = target.modifiers.All.Count - 1; i >= 0; i--)
                if (target.modifiers.All[i] != null && target.modifiers.All[i].Type == type)
                    target.modifiers.Remove(target.modifiers.All[i]);
        }

        [ServiceCommand("pa.vital")]
        private void CommandVital(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() || !Can(player, Permissions.Players) || !CanAction(player, "vitals"))
                return;
            if (arg.GetString(0) != "set")
                return;
            var sid = PeekAdmin(player.userID)?.Popup ?? 0;
            if (sid == 0)
                return;
            var target = FindOnline(sid);
            if (target == null || target.metabolism == null)
            {
                Notify(player, GetLocalizedMessage(TranslateKey.BlueprintOffline, player), NotifyKind.Error);
                return;
            }

            var key = arg.GetString(1);
            var def = VitalDefs.FirstOrDefault(d => d.Key == key);
            if (def == null)
                return;

            VitalRead(target, def, out var curVal, out var curMax, out _);
            if (!TryFloat(GetInput(player, FieldKey.PrefixVitalVal + key, VitFmt(curVal, def.Integer)), out var val))
            {
                RefreshVitalRow(player, key);
                return;
            }

            switch (def.Kind)
            {
                case VitalKind.MaxHealth:
                {
                    var newMax = Mathf.Max(1f, val);
                    target.OverrideMaxHealth(newMax);
                    StoreVitalMax(target.userID, "maxhp", newMax);
                    AddLog(LogCategory.Cmd,
                        $"{player.displayName}: set max HP = {Mathf.RoundToInt(newMax)} on {target.displayName}");
                    break;
                }
                case VitalKind.Health:
                {
                    target.health = Mathf.Clamp(val, 0f, target.MaxHealth());
                    target.SendNetworkUpdate();
                    AddLog(LogCategory.Cmd,
                        $"{player.displayName}: set HP = {Mathf.RoundToInt(target.health)} on {target.displayName}");
                    break;
                }
                default:
                {
                    var a = def.Attr(target.metabolism);
                    var prevMax = a.max;
                    var maxChanged = false;
                    if (def.HasMax &&
                        TryFloat(GetInput(player, FieldKey.PrefixVitalMax + key, VitFmt(curMax, def.Integer)),
                            out var maxVal))
                    {
                        a.max = maxVal;
                        maxChanged = !Mathf.Approximately(maxVal, prevMax);
                    }

                    a.value = Mathf.Clamp(val, a.min, a.max);
                    target.metabolism.isDirty = true;
                    target.metabolism.SendChanges();
                    target.SendNetworkUpdate();
                    if (def.HasMax && maxChanged)
                        StoreVitalMax(target.userID, def.Key, a.max);
                    AddLog(LogCategory.Cmd,
                        $"{player.displayName}: set {def.Label} = {VitFmt(a.value, def.Integer)} (max {VitFmt(a.max, def.Integer)}) on {target.displayName}");
                    break;
                }
            }

            RefreshVitalRow(player, key);
        }

        private void StoreVitalMax(ulong id, string key, float max)
        {
            if (!_players.TryGetValue(id, out var s))
                _players[id] = s = new StoredPlayer { FirstSeen = DateTimeOffset.Now.ToUnixTimeSeconds() };
            s.VitalMax ??= new Dictionary<string, float>();
            s.VitalMax[key] = max;
            SavePlayersSoon();
        }

        private void ApplyVitalOverrides(BasePlayer player)
        {
            if (player == null)
                return;
            if (!_players.TryGetValue(player.userID, out var s) || s.VitalMax == null || s.VitalMax.Count == 0)
                return;
            var touchedMetabolism = false;
            foreach (var kv in s.VitalMax)
            {
                if (kv.Key == "maxhp")
                {
                    player.OverrideMaxHealth(Mathf.Max(1f, kv.Value));
                    continue;
                }

                var def = VitalDefs.FirstOrDefault(d => d.Key == kv.Key);
                if (def == null || def.Kind != VitalKind.Metabolism || player.metabolism == null)
                    continue;
                var a = def.Attr(player.metabolism);
                if (a == null)
                    continue;
                a.max = kv.Value;
                a.value = Mathf.Clamp(a.value, a.min, a.max);
                touchedMetabolism = true;
            }

            if (touchedMetabolism && player.metabolism != null)
            {
                player.metabolism.isDirty = true;
                player.metabolism.SendChanges();
            }

            player.SendNetworkUpdate();
        }

