#if CARBON
        private bool OpenEspColorPicker(BasePlayer player, string id)
        {
            try
            {
                var picker = Carbon.Base.BaseModule.GetModule<Carbon.Modules.ColorPickerModule>();
                if (picker == null)
                    return false;

                picker.Open(player, (hex, rust, alpha) =>
                {
                    if (player == null || !player.IsConnected)
                        return;
                    if (string.IsNullOrEmpty(hex))
                    {
                        OpenEspColorInput(player, id);
                        return;
                    }

                    if (!ColorUtility.TryParseHtmlString(hex.StartsWith("#") ? hex : "#" + hex, out var picked))
                        return;

                    picked.a = Mathf.Clamp01(alpha);
                    SetInput(player.userID, EspColorKey(id), ColorToRustFormat(picked));
                    RefreshBody(player);
                });
                return true;
            }
            catch (Exception ex)
            {
                PrintWarning($"Color picker failed: {ex.Message}");
                return false;
            }
        }
#endif

