        private void RunConsoleInput(BasePlayer player, string id)
        {
            var text = GetInput(player, id, "").Trim();
            if (text.Length == 0)
                return;

            var asPlayer = GetToggle(player, "sec.console_player", false);
            if (text.StartsWith("/"))
            {
                var msg = text.Substring(1).Trim();
                if (msg.Length > 0)
                {
                    if (asPlayer)
                    {
                        ConsoleSystem.Run(ConsoleSystem.Option.Server.FromConnection(player.Connection).Quiet(),
                            "chat.say", msg);
                        AddLog(LogCategory.Chat, $"{player.displayName}: {msg}");
                    }
                    else
                    {
                        Broadcast(msg);
                        AddLog(LogCategory.Chat, $"SERVER: {msg}");
                    }
                }
            }
            else
            {
                AddLog(LogCategory.Cmd, $"{(asPlayer ? player.displayName : "SERVER")}: {text}");
                var opt = asPlayer
                    ? ConsoleSystem.Option.Server.FromConnection(player.Connection).Quiet()
                    : ConsoleSystem.Option.Server.Quiet();
                var result = ConsoleSystem.Run(opt, text);
                if (result != null)
                {
                    var rs = result.ToString();
                    if (!string.IsNullOrEmpty(rs))
                        AddLog(LogCategory.Info, rs);
                }
            }

            SetInput(player.userID, id, "");
        }

