        [ServiceCommand("pa.cfgnewlang")]
        private void CommandCfgNewLang(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(1) || !CanEditPlugins(player))
                return;
            var admin = GetAdmin(player.userID);
            if (admin.CfgEditPlugin == null || !admin.CfgEditIsLang || admin.CfgEditLang == null)
                return;
            var code = arg.GetString(0).Trim();
            if (!IsKnownLangCode(code))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.CfgLangBad, player), NotifyKind.Error);
                return;
            }

            code = LangCodeList.First(known => string.Equals(known, code, StringComparison.OrdinalIgnoreCase));

            var target = LangFilePath(admin.CfgEditPlugin, code);
            if (System.IO.File.Exists(target))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.CfgLangExists, player), NotifyKind.Error);
                return;
            }

            try
            {
                System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(target));
                System.IO.File.Copy(LangFilePath(admin.CfgEditPlugin, admin.CfgEditLang), target);
            }
            catch (Exception ex)
            {
                PrintError($"Creating the lang file {target} failed: {ex.Message}");
                Notify(player, GetLocalizedMessage(TranslateKey.CfgWriteError, player), NotifyKind.Error);
                return;
            }

            AddLog(LogCategory.Cmd, $"{player.displayName}: created lang {code} for {admin.CfgEditPlugin}");
            LoadCfgRows(player, admin.CfgEditPlugin, true, code, target);
        }

        [ServiceCommand("pa.cfgfield")]
        private void CommandCfgField(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(1) || !CanEditPlugins(player))
                return;
            var admin = GetAdmin(player.userID);
            if (admin.CfgEditPlugin == null || !admin.CfgEditIsLang || admin.CfgEditLang == null)
                return;
            var rest = arg.HasArgs(2) ? string.Join(" ", arg.Args.Skip(1).Select(a => a.ToString())) : "";
            switch (arg.GetString(0).ToLower())
            {
                case "key":
                {
                    admin.CfgFieldKey = rest.Trim();
                    break;
                }
                case "value":
                {
                    admin.CfgFieldValue = rest;
                    break;
                }
                case "add":
                {
                    AddCfgLangField(player, admin);
                    break;
                }
            }
        }

        private void AddCfgLangField(BasePlayer player, AdminData admin)
        {
            var key = admin.CfgFieldKey?.Trim() ?? "";
            var rows = admin.CfgEditRows;
            if (key.Length == 0 || rows == null)
            {
                Notify(player, GetLocalizedMessage(TranslateKey.CfgFieldBad, player), NotifyKind.Error);
                return;
            }

            if (rows.Any(row => string.Equals(row.Label, key, StringComparison.Ordinal)))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.CfgFieldExists, player), NotifyKind.Error);
                return;
            }

            var value = admin.CfgFieldValue ?? "";
            var path = LangFilePath(admin.CfgEditPlugin, admin.CfgEditLang);
            if (!WriteLangField(path, key, value))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.CfgWriteError, player), NotifyKind.Error);
                return;
            }

            var written = 1;
            foreach (var code in LangCodesFor(admin.CfgEditPlugin))
                if (code != admin.CfgEditLang && WriteLangField(LangFilePath(admin.CfgEditPlugin, code), key, value))
                    written++;

            AddLog(LogCategory.Cmd,
                $"{player.displayName}: added lang key {key} to {admin.CfgEditPlugin} in {written} file(s)");
            Notify(player, SafeFormat(GetLocalizedMessage(TranslateKey.CfgFieldAdded, player), key, written));
            LoadCfgRows(player, admin.CfgEditPlugin, true, admin.CfgEditLang, path);
        }

        private static bool WriteLangField(string path, string key, string value)
        {
            try
            {
                var root = JObject.Parse(System.IO.File.ReadAllText(path));
                if (root[key] != null)
                    return false;
                root[key] = value;
                System.IO.File.WriteAllText(path, root.ToString(Newtonsoft.Json.Formatting.Indented));
                return true;
            }
            catch (Exception ex)
            {
                Instance?.PrintError($"Writing the lang key {key} to {path} failed: {ex.Message}");
                return false;
            }
        }

        [ServiceCommand("pa.cfgset")]
        private void CommandCfgSet(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(1) || !CanEditPlugins(player))
                return;
            var admin = GetAdmin(player.userID);
            if (admin.CfgEditRows == null || !int.TryParse(arg.GetString(0), out var idx) || idx < 0 ||
                idx >= admin.CfgEditRows.Count)
                return;
            var value = arg.HasArgs(2) ? string.Join(" ", arg.Args.Skip(1).Select(a => a.ToString())) : "";
            var clean = SanitizeCfgValue(admin.CfgEditRows[idx].Kind, value);
            admin.CfgEditRows[idx].Value = clean;
            if (clean != value)
                RefreshCfgEditor(player);
        }

        private static string SanitizeCfgValue(JTokenType kind, string raw)
        {
            if (kind != JTokenType.Integer && kind != JTokenType.Float)
                return raw;
            var buffer = new char[raw.Length];
            var len = 0;
            var dot = false;
            foreach (var ch in raw)
            {
                if (char.IsDigit(ch))
                    buffer[len++] = ch;
                else if (ch == '-' && len == 0)
                    buffer[len++] = ch;
                else if ((ch == '.' || ch == ',') && kind == JTokenType.Float && !dot && len > 0)
                {
                    buffer[len++] = '.';
                    dot = true;
                }
            }

            return new string(buffer, 0, len);
        }

        [ServiceCommand("pa.cfgtoggle")]
        private void CommandCfgToggle(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(1) || !CanEditPlugins(player))
