            var admin = GetAdmin(player.userID);
            if (admin.CfgEditRows == null || !int.TryParse(arg.GetString(0), out var idx) || idx < 0 ||
                idx >= admin.CfgEditRows.Count)
                return;
            var flag = arg.HasArgs(2) ? arg.GetString(1) : null;
            var was = string.Equals(admin.CfgEditRows[idx].Value, "true", StringComparison.OrdinalIgnoreCase);
            var on = flag != null ? flag != "0" : !was;
            admin.CfgEditRows[idx].Value = on ? "True" : "False";
            RefreshCfgEditor(player);
        }

