                idx >= admin.CfgEditRows.Count || admin.CfgEditRows[idx].Kind != JTokenType.Array)
                return;
            JArray data;
            try
            {
                data = JArray.Parse(admin.CfgEditRows[idx].Value ?? "[]");
            }
            catch (Exception ex)
            {
                PrintWarning($"Parsing the config array failed: {ex.Message}");
                Notify(player, GetLocalizedMessage(TranslateKey.CfgParseError, player), NotifyKind.Error);
                return;
            }

            admin.CfgArrRow = idx;
            admin.CfgArrData = data;
            admin.CfgArrOpen = new HashSet<int>();
            admin.CfgArrDelete = -1;
            RefreshCfgEditor(player);
        }

        [ServiceCommand("pa.cfgarrclose")]
        private void CommandCfgArrayClose(ConsoleSystem.Arg arg)
