        [ServiceCommand("pa.cfgarrdel")]
        private void CommandCfgArrayDelete(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(1) || !CanEditPlugins(player))
                return;
            var admin = GetAdmin(player.userID);
            if (admin.CfgArrData == null || !int.TryParse(arg.GetString(0), out var idx) || idx < 0 ||
                idx >= admin.CfgArrData.Count)
                return;
            if (admin.CfgArrDelete != idx)
            {
                admin.CfgArrDelete = idx;
                RefreshCfgEditor(player);
                return;
            }

            admin.CfgArrData.RemoveAt(idx);
            admin.CfgArrDelete = -1;
            if (admin.CfgArrOpen != null)
            {
                var shifted = new HashSet<int>();
                foreach (var open in admin.CfgArrOpen)
                    if (open < idx)
                        shifted.Add(open);
                    else if (open > idx)
                        shifted.Add(open - 1);
                admin.CfgArrOpen = shifted;
            }

            RefreshCfgEditor(player);
        }

        [ServiceCommand("pa.cfgarrset")]
        private void CommandCfgArraySet(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(1) || !CanEditPlugins(player))
                return;
            var admin = GetAdmin(player.userID);
            var leaves = CfgArrayLeaves(admin);
            if (!int.TryParse(arg.GetString(0), out var idx) || idx < 0 || idx >= leaves.Count)
                return;
            var value = arg.HasArgs(2) ? string.Join(" ", arg.Args.Skip(1).Select(a => a.ToString())) : "";
            var clean = SanitizeCfgValue(leaves[idx].Kind, value);
            var element = leaves[idx].Element;
            ApplyCfgArrayValue(admin, leaves[idx], clean);
            if (clean != value || leaves[idx].Kind == JTokenType.Array)
                RefreshCfgEditor(player);
            else if (leaves[idx].Depth == 0)
                RefreshCfgArrayCaption(player, admin, element);
        }

        private void RefreshCfgArrayCaption(BasePlayer player, AdminData admin, int element)
        {
            if (player == null || admin.CfgArrData == null || element < 0 || element >= admin.CfgArrData.Count)
                return;
            var head = Layers.CfgArrRoot + ".card.arrlist.c.h" + element;
            var open = admin.CfgArrOpen != null && admin.CfgArrOpen.Contains(element);
            var container = new CuiElementContainer();
            UI_Text(container, head, CfgArrayCaption(admin.CfgArrData[element], element), 10, Fonts.Body,
                TextAnchor.MiddleLeft, open ? Palette.CText : Palette.CText2, "0 0", "1 1", "28 0", "-34 0",
                head + ".cap");
            CuiHelper.AddUi(player, container);
        }

