        [ServiceCommand("pa.cfglangdel")]
        private void CommandCfgLangDelete(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !CanEditPlugins(player))
                return;
            var admin = GetAdmin(player.userID);
            if (admin.CfgEditPlugin == null || !admin.CfgEditIsLang || admin.CfgEditLang == null)
                return;
            var codes = LangCodesFor(admin.CfgEditPlugin);
            if (codes.Count < 2)
            {
                Notify(player, GetLocalizedMessage(TranslateKey.CfgLangLast, player), NotifyKind.Error);
                return;
            }

            if (!admin.CfgLangDelete)
            {
                admin.CfgLangDelete = true;
                RefreshCfgEditor(player);
                return;
            }

            var gone = admin.CfgEditLang;
            try
            {
                System.IO.File.Delete(LangFilePath(admin.CfgEditPlugin, gone));
            }
            catch (Exception ex)
            {
                PrintError($"Deleting the lang file {gone} failed: {ex.Message}");
                Notify(player, GetLocalizedMessage(TranslateKey.CfgWriteError, player), NotifyKind.Error);
                return;
            }

            AddLog(LogCategory.Cmd, $"{player.displayName}: deleted lang {gone} of {admin.CfgEditPlugin}");
            Notify(player, SafeFormat(GetLocalizedMessage(TranslateKey.CfgLangDeleted, player), gone));
            var next = codes.FirstOrDefault(code => code != gone) ?? "en";
            LoadCfgRows(player, admin.CfgEditPlugin, true, next, LangFilePath(admin.CfgEditPlugin, next));
        }

