        [ServiceCommand("pa.cvset")]
        private void CommandConvarSet(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() || !Can(player, Permissions.Convars))
                return;
            var full = arg.GetString(0);
            if (string.IsNullOrEmpty(full))
                return;
            var value = arg.HasArgs(2) ? string.Join(" ", arg.Args.Skip(1)) : "";
            if (ConVarList().All(v => !string.Equals(v.FullName, full, StringComparison.OrdinalIgnoreCase)))
                return;
            try
            {
                ConsoleSystem.Run(ConsoleSystem.Option.Server, full, value);
                StoreManagedConvar(full, value);
            }
            catch (Exception ex)
            {
                PrintWarning($"Setting the convar {full} failed: {ex.Message}");
            }

            AddLog(LogCategory.Cmd, $"{player.displayName}: set convar {full} = {value}");
        }

        [ServiceCommand("pa.cvtoggle")]
        private void CommandConvarToggle(ConsoleSystem.Arg arg)
        {
