            var full = arg.GetString(0);
            if (string.IsNullOrEmpty(full))
                return;
            var convar = ConVarList()
                .FirstOrDefault(v => string.Equals(v.FullName, full, StringComparison.OrdinalIgnoreCase));
            if (convar == null)
                return;
            bool.TryParse(convar.String, out var isOn);
            var next = !isOn;
            try
            {
                ConsoleSystem.Run(ConsoleSystem.Option.Server, full, next ? "true" : "false");
                StoreManagedConvar(full, next ? "true" : "false");
            }
            catch (Exception ex)
            {
                PrintWarning($"Setting the convar {full} failed: {ex.Message}");
            }

            AddLog(LogCategory.Cmd, $"{player.displayName}: set convar {full} = {next}");
            RefreshConvarRow(player, full);
        }

        private static string ManagedConvarsFile() =>
            System.IO.Path.Combine(ConVar.Server.GetServerFolder("cfg"), "powerfuladmin.cfg");

        private void StoreManagedConvar(string fullName, string value)
        {
            if (string.IsNullOrEmpty(fullName))
                return;
            _managedConvars[fullName] = value ?? "";
            SaveManagedConvars();
        }

        private void SaveManagedConvars()
        {
            try
            {
                var lines = _managedConvars.Select(pair =>
                    pair.Key + " " + pair.Value.Replace("\r", " ").Replace("\n", " "));
                var content = "// PowerfulAdmin managed convars - re-applied on server start. Do not edit manually.\n" +
                              string.Join("\n", lines) + "\n";
                System.IO.File.WriteAllText(ManagedConvarsFile(), content);
            }
            catch (Exception exception)
            {
                PrintWarning($"PowerfulAdmin: failed to save managed convars - {exception.Message}");
            }
        }

        private void LoadManagedConvars(bool apply)
        {
            _managedConvars.Clear();
            string[] lines;
            try
            {
                var file = ManagedConvarsFile();
                if (!System.IO.File.Exists(file))
                    return;
                lines = System.IO.File.ReadAllLines(file);
            }
            catch (Exception exception)
            {
                PrintWarning($"PowerfulAdmin: failed to read managed convars - {exception.Message}");
                return;
            }

            foreach (var raw in lines)
            {
                var line = raw.Trim();
                if (line.Length == 0 || line.StartsWith("//") || line.StartsWith("#"))
                    continue;
                var space = line.IndexOf(' ');
                var name = space < 0 ? line : line.Substring(0, space);
                var value = space < 0 ? "" : line.Substring(space + 1);
                _managedConvars[name] = value;
                if (!apply)
                    continue;
                try
                {
                    ConsoleSystem.Run(ConsoleSystem.Option.Server.Quiet(), name, value);
                }
                catch (Exception ex)
                {
                    PrintWarning($"Applying the stored convar {name} failed: {ex.Message}");
                }
            }
        }

        [ServiceCommand("pa.conexport")]
        private void CommandConsoleExport(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player))
                return;
            var snap = ConsoleSnapshot("all");
            var sb = Facepunch.Pool.Get<System.Text.StringBuilder>();
            foreach (var l in snap)
            {
                if (sb.Length > 0)
                    sb.Append('\n');
                sb.Append(l.GetFormattedLog());
            }

            LogToFile("console", sb.ToString(), this, false);
            Facepunch.Pool.FreeUnmanaged(ref sb);
            Notify(player, GetLocalizedMessage(TranslateKey.ConsoleExported, player));
            UI_Open(player);
        }

        [ServiceCommand("pa.storagesel")]
        private void CommandStorageSelect(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() ||
                !permission.UserHasPermission(player.UserIDString, Permissions.Settings))
                return;
            if (_storageBusy)
                return;
            var sel = arg.GetString(0).ToLowerInvariant();
            if (sel != "json" && sel != "sqlite" && sel != "mysql")
                return;
            if (GetSelect(player, FieldKey.StorageBackend, StorageId(cfg.Storage)) == sel)
                return;
            SetSelect(player.userID, FieldKey.StorageBackend, sel);
            GetAdmin(player.userID).StorageStatus = null;
            GetAdmin(player.userID).StorageConfirm = false;
            RefreshSettings(
                player);
        }

        [ServiceCommand("pa.storagemig")]
        private void CommandStorageMigrate(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !permission.UserHasPermission(player.UserIDString, Permissions.Settings))
                return;
            if (_storageBusy)
                return;
            var to = GetSelect(player, FieldKey.StorageBackend, StorageId(cfg.Storage));
            if (to == StorageId(cfg.Storage))
            {
                GetAdmin(player.userID).StorageConfirm = false;
                RefreshSettings(player);
                return;
            }

            if (!arg.HasArgs())
            {
                GetAdmin(player.userID).StorageConfirm = true;
                RefreshSettings(player);
                return;
            }

            GetAdmin(player.userID).StorageConfirm = false;
            if (arg.GetBool(0))
            {
                ExecuteSwitch(player, StorageId(cfg.Storage), to);
                return;
            }

            RefreshSettings(player);
        }

        private void ExecuteSwitch(BasePlayer player, string from, string to)
        {
            if (to == "mysql")
            {
                _storageBusy = true;
                SetStorageStatus(player, StorageState.Connecting);
                var test = NewDatabase(DataStorage.MySql);
                if (!test.Open())
                {
                    _storageBusy = false;
                    SetStorageStatus(player, StorageState.Failed);
                    return;
                }

                test.Query(Sql.Builder.Append("SELECT 1"), rows =>
                {
                    test.Close();
                    if (rows.Count == 0)
                    {
                        _storageBusy = false;
                        SetStorageStatus(player, StorageState.Failed);
                        return;
                    }

                    SetStorageStatus(player, StorageState.Connected);
                    timer.Once(0.5f, () =>
                    {
                        if (player == null || !player.IsConnected)
                        {
                            _storageBusy = false;
                            return;
                        }

                        SetStorageStatus(player, StorageState.Migrating);
                        DoStorageSwitch(player, from, to);
                    });
                });
                return;
            }

            _storageBusy = true;
            DoStorageSwitch(player, from, to);
        }

        private void DoStorageSwitch(BasePlayer player, string from, string to)
        {
            SaveData();
            SavePlayers();
            _db?.Close();
            _db = null;

            cfg.Storage = ParseStorage(to);
            SetSelect(player.userID, FieldKey.StorageBackend, to);
            SaveConfig();
            if (to != "mysql")
                RefreshSettings(player);
            InitStorage(() =>
            {
                if (to == "mysql" && _db != null)
                    _db.Query(Sql.Builder.Append("SELECT 1"), rows =>
                    {
                        _storageBusy = false;
                        SetStorageStatus(player, rows.Count > 0 ? StorageState.Connected : StorageState.MigrateFailed);
                    });
                else
                {
                    _storageBusy = false;
                    RefreshSettings(player);
                }
            });
        }

        [ServiceCommand("pa.dbset")]
        private void CommandDatabaseSet(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() ||
                !permission.UserHasPermission(player.UserIDString, Permissions.Settings))
                return;
            var field = arg.GetString(0);
            var val = arg.HasArgs(2) ? string.Join(" ", arg.Args.Skip(1).Select(a => a.ToString())) : "";
            switch (field)
            {
                case "host":
                {
                    cfg.MySql.Host = val;
                    break;
                }
                case "port":
                {
                    if (int.TryParse(val, out var p))
                        cfg.MySql.Port = p;
                    break;
                }
                case "database":
                {
                    cfg.MySql.Database = val;
                    break;
                }
                case "user":
                {
                    cfg.MySql.User = val;
                    break;
                }
                case "password":
                {
                    cfg.MySql.Password = val;
                    break;
                }
                default:
                {
                    return;
                }
            }

            SaveConfig();
            GetAdmin(player.userID).StorageStatus = null;
            if (GetPage(player) == "settings")
                RefreshSettings(player);
            else
                UI_Open(player);
        }

        [ServiceCommand("pa.dbtest")]
        private void CommandDatabaseTest(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !permission.UserHasPermission(player.UserIDString, Permissions.Settings))
                return;
            if (_storageBusy)
                return;
            var live = Backend == DataStorage.MySql && _db != null && _db.IsSql;
            var test = live ? _db : NewDatabase(DataStorage.MySql);
            if (!live && !test.Open())
            {
                SetStorageStatus(player, StorageState.Failed);
                return;
            }

            SetStorageStatus(player, StorageState.Connecting);
            test.Query(Sql.Builder.Append("SELECT 1"), rows =>
            {
                if (!live)
                    test.Close();
                SetStorageStatus(player, rows.Count > 0 ? StorageState.Connected : StorageState.Failed);
            });
        }

