                }
            });
            UI_Btn(container, Layers.Root + ".cp", "pa.dccolorclose", Colors.Clear, "0 0", "1 1");
            var card = Layers.Root + ".cp.card";
            container.Add(new CuiElement
            {
                Parent = Layers.Root + ".cp", Name = card,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CSurface },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = "-210 -150", OffsetMax = "210 150" }
                }
            });
            UI_Text(container, card, GetLocalizedMessage(TranslateKey.DiscordEmbedcolor, player), 14, Fonts.Title,
                TextAnchor.UpperLeft, Palette.CText, "0 1", "1 1", "16 -34", "-16 -14");
            const int cols = 8;
            var sw = (420 - 32 - (cols - 1) * 6) / cols;
            var cur = DiscordInput(FieldKey.DiscordColor).TrimStart('#').ToUpperInvariant();
            var swatchRows = (EmbedPalette.Length + cols - 1) / cols;
            var swatches = card + ".pal";
            container.Add(new CuiElement
            {
                Parent = card, Name = swatches, DestroyUi = swatches,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{sw} {sw}", Spacing = "6 6",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = cols
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"16 {-44 - (swatchRows * (sw + 6) - 6)}",
                        OffsetMax = $"{16 + (420 - 32)} -44"
                    }
                }
            });
            for (var i = 0; i < EmbedPalette.Length; i++)
            {
                var hex = EmbedPalette[i];
                var swatch = swatches + ".s" + i;
                container.Add(new CuiElement
                {
                    Parent = swatches, Name = swatch,
                    Components =
                    {
                        new CuiImageComponent { Color = HexToRustFormat(hex) ?? "0.5 0.5 0.5 1" },
                        new CuiOutlineComponent { Color = hex == cur ? Palette.CAccent : Palette.CBorder, Distance = hex == cur ? "2 2" : "1 1" }
                    }
                });
                UI_Btn(container, swatch, $"pa.dccolorset {hex}", Colors.Clear, "0 0", "1 1");
            }

            var hexY = -44 - 3 * (sw + 6) - 6;
            UI_Input(container, card, player, FieldKey.DiscordColor, "#D08A60", 16, hexY, 200, 26);
            UI_Btn(container, card, GetLocalizedMessage(TranslateKey.DiscordColorClose, player), "pa.dccolorclose",
                Palette.CElev, 11, Fonts.Title, TextAnchor.MiddleCenter, Palette.CText, "1 0", "1 0", "-104 14",
                "-16 40");
            CuiHelper.AddUi(player, container);
        }

        [ServiceCommand("pa.dccolorset")]
        private void CommandDiscordColorSet(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs() ||
                !permission.UserHasPermission(player.UserIDString, Permissions.Use))
                return;
            if (!Can(player, Permissions.Settings))
                return;
            var hex = arg.GetString(0).TrimStart('#');
            if (hex.Length == 6)
                SetInput(0, FieldKey.DiscordColor, "#" + hex.ToUpperInvariant());
            CuiHelper.DestroyUi(player, Layers.Root + ".cp");
            RefreshSettings(player);
        }

        [ServiceCommand("pa.dccolorclose")]
        private void CommandDiscordColorClose(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null)
                return;
            CuiHelper.DestroyUi(player, Layers.Root + ".cp");
            RefreshSettings(player);
        }

