        #region UI

        private void UI_Open(BasePlayer player)
        {
            if (player != null && PeekAdmin(player.userID)?.UiOpen == true)
            {
                UI_Navigate(player);
                return;
            }

            UI_Build(player);
        }

        private void UI_Preload(BasePlayer player)
        {
            if (player == null || !permission.UserHasPermission(player.UserIDString, Permissions.Use))
                return;
            UI_Open(player);
            NextTick(() =>
            {
                var sess = GetAdmin(player.userID);
                sess.OpenDropdown = null;
                sess.Popup = 0;
                sess.UiOpen = false;
                CuiHelper.DestroyUi(player, Layers.Root);
            });
        }

        private void UI_Build(BasePlayer player)
        {
            if (player != null)
                ReconcileGodNoclip(player);
            if (cfg != null && !cfg.PanelOpened)
            {
                cfg.PanelOpened = true;
                SaveConfig();
            }

            ApplyTheme(player);
            var container = new CuiElementContainer();

            var dragOn = IsPanelDraggable(player);
            var rootAnchor = "0.5 0.5";
            var savedRoot = PeekAdmin(player.userID)?.RootPos;
            if (dragOn && !string.IsNullOrEmpty(savedRoot))
                rootAnchor = savedRoot;
            var root = new CuiElement
            {
                Name = Layers.Root, Parent = "Overlay", DestroyUi = Layers.Root,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CBg },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = rootAnchor, AnchorMax = rootAnchor,
                        OffsetMin = $"{-Positions.PanelW / 2} {-Positions.PanelH / 2}",
                        OffsetMax = $"{Positions.PanelW / 2} {Positions.PanelH / 2}"
                    },
                    new CuiNeedsCursorComponent()
                }
            };
            if (dragOn)
                root.Components.Add(new CuiDraggableComponent
                {
                    LimitToParent = true, KeepOnTop = true,
                    PositionRPC = CommunityEntity.DraggablePositionSendType.NormalizedScreen
                });
            container.Add(root);

            container.Add(new CuiPanel
            {
                Image = { Color = Palette.CSurface },
                RectTransform = { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = $"0 {-Positions.TopbarH}", OffsetMax = "0 0" }
            }, Layers.Root, Layers.Root + ".top");
            container.Add(new CuiPanel
            {
                Image = { Color = Palette.CBorder },
                RectTransform = { AnchorMin = "0 0", AnchorMax = "1 0", OffsetMin = "0 -1", OffsetMax = "0 0" }
            }, Layers.Root + ".top");

            container.Add(new CuiPanel
            {
                Image = { Color = Palette.CAccent },
                RectTransform = { AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = "14 -12", OffsetMax = "38 12" }
            }, Layers.Root + ".top", Layers.Root + ".logo");
            UI_Text(container, Layers.Root + ".logo", "P", 13, Fonts.Title, TextAnchor.MiddleCenter, Palette.CAccentText,
                "0 0", "1 1");
            var host = ConVar.Server.hostname ?? "";
            if (host.Length > 30)
                host = host.Substring(0, 29).TrimEnd() + "...";
            UI_Text(container, Layers.Root + ".top",
                string.IsNullOrEmpty(host) ? "PowerfulAdmin" : $"PowerfulAdmin <color=#7E8AA0>|  {host}</color>", 14,
                Fonts.Title, TextAnchor.MiddleLeft, Palette.CText, "0 0.5", "0 0.5", "46 -12", "560 12");

#if DEBUG_SERVER
            container.Add(new CuiElement
            {
                Parent = Layers.Root + ".top", Name = Layers.Root + ".debug",
                Components =
                {
                    new CuiImageComponent { Color = Colors.CDanger },
                    new CuiRectTransformComponent { AnchorMin = "1 0.5", AnchorMax = "1 0.5", OffsetMin = "-412 -12", OffsetMax = "-292 12" }
                }
            });
            UI_Text(container, Layers.Root + ".debug", "DEBUG MODE", 11, Fonts.Title, TextAnchor.MiddleCenter,
                "0.98 0.96 0.94 1", "0 0", "1 1");
#endif

            container.Add(new CuiElement
            {
                Parent = Layers.Root + ".top", Name = Layers.Root + ".search",
                Components =
                {
                    new CuiImageComponent { Color = Palette.CPage },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "1 0.5", AnchorMax = "1 0.5", OffsetMin = "-280 -14", OffsetMax = "-52 14" }
                }
            });
            container.Add(new CuiElement
            {
                Parent = Layers.Root + ".search",
                Components =
                {
                    new CuiInputFieldComponent
                    {
                        Text = GetLocalizedMessage(TranslateKey.TopSearch, player), FontSize = 11,
                        Font = Fonts.Body,
                        Align = TextAnchor.MiddleLeft, Color = Palette.CText3, CharsLimit = 64,
                        NeedsKeyboard = true, Command = ProtectCommand($"pa.input {FieldKey.Search} ")
                    },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1", OffsetMin = "10 0", OffsetMax = "-8 0" }
                }
            });

            UI_Btn(container, Layers.Root + ".top", "pa.close", Palette.CElev, "1 0.5", "1 0.5", "-42 -14", "-14 14",
                Layers.Root + ".close");
            container.Add(new CuiElement
            {
                Parent = Layers.Root + ".close",
                Components =
                {
                    new CuiImageComponent { Color = Palette.CText2, Sprite = "assets/icons/close.png" },
                    new CuiRectTransformComponent { AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = "-7 -7", OffsetMax = "7 7" }
                }
            });

            UI_Sidebar(container, player);
            UI_BodyShell(container);
            UI_BodyContent(container, player);
            UI_Welcome(container, player);

            CuiHelper.AddUi(player, container);
            GetAdmin(player.userID).UiOpen = true;
            EnsureConsoleComponent(player);
            var openSec = _extSections.FirstOrDefault(x => x.Id == GetPage(player));
            if (openSec != null && (openSec.Permission == null ||
                                    permission.UserHasPermission(player.UserIDString, openSec.Permission)))
                openSec.Open?.Invoke(player);
        }

        private void UI_Navigate(BasePlayer player)
        {
            if (player == null || PeekAdmin(player.userID)?.UiOpen != true)
            {
                UI_Open(player);
                return;
            }

            ApplyTheme(player);
            var container = new CuiElementContainer();
            UI_NavBody(container, player);
            UI_BodyShell(container);
            foreach (var stray in StrayModals)
                container.Add(new CuiElement
                {
                    Parent = Layers.Root, Name = stray, DestroyUi = stray,
                    Components =
                    {
                        new CuiImageComponent { Color = Colors.Clear },
                        new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "0 0", OffsetMin = "0 0", OffsetMax = "0 0" }
                    }
                });
            UI_BodyContent(container, player);
            CuiHelper.AddUi(player, container);
            var openSec = _extSections.FirstOrDefault(x => x.Id == GetPage(player));
            if (openSec != null && (openSec.Permission == null ||
                                    permission.UserHasPermission(player.UserIDString, openSec.Permission)))
                openSec.Open?.Invoke(player);
        }

