        private void UI_SearchDrop(CuiElementContainer container, BasePlayer player)
        {
            var q = PeekAdmin(player.userID)?.Search;
            if (string.IsNullOrWhiteSpace(q))
            {
                container.Add(new CuiElement
                {
                    Parent = Layers.Root, Name = Layers.SearchDrop, DestroyUi = Layers.SearchDrop,
                    Components =
                    {
                        new CuiImageComponent { Color = Colors.Clear },
                        new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "0 0", OffsetMin = "0 0", OffsetMax = "0 0" }
                    }
                });
                return;
            }
            var rows = BuildPlayerRows("all", q.ToLowerInvariant());
            const int rowH = 30, maxRows = 5;
            var shown = Math.Min(rows.Count, maxRows);
            var h = (shown > 0 ? shown * rowH : rowH) + 8;
            var panel = Layers.SearchDrop;
            container.Add(new CuiElement
            {
                Parent = Layers.Root, Name = panel, DestroyUi = panel,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CSurface },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "1 1", AnchorMax = "1 1",
                        OffsetMin = $"-280 {-Positions.TopbarH - h}", OffsetMax = $"-52 {-Positions.TopbarH - 2}"
                    }
                }
            });
            container.Add(new CuiElement
            {
                Parent = panel,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1" }
                }
            });
            if (shown == 0)
            {
                UI_Text(container, panel, GetLocalizedMessage(TranslateKey.TopSearchNone, player), 11, Fonts.Body,
                    TextAnchor.MiddleCenter, Palette.CText3, "0 0", "1 1");
                return;
            }

            var y = -4;
            for (var i = 0; i < shown; i++)
            {
                var r = rows[i];
                var row = panel + "." + i;
                UI_Btn(container, panel, $"pa.popup {r.Id}", i % 2 == 0 ? Colors.Clear : Palette.CElev, "0 1", "1 1",
                    $"3 {y - rowH}", $"-3 {y}", row);
                container.Add(new CuiPanel
                {
                    Image = { Color = r.Online ? Colors.CSuccess : Palette.CText3 },
                    RectTransform = { AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = "8 -3", OffsetMax = "14 3" }
                }, row);
                UI_Text(container, row, r.Name, 11, Fonts.Title, TextAnchor.MiddleLeft, Palette.CText, "0 0", "0.7 1", "22 0",
                    "0 0");
                UI_Text(container, row, r.Id.ToString(), 9, Fonts.Body, TextAnchor.MiddleRight, Palette.CText3, "0.7 0", "1 1",
                    "0 0", "-8 0");
                y -= rowH;
            }
        }

        private void UI_Sidebar(CuiElementContainer container, BasePlayer player)
        {
            container.Add(new CuiPanel
            {
                Image = { Color = Palette.CSurface },
                RectTransform = { AnchorMin = "0 0", AnchorMax = "0 1", OffsetMin = "0 0", OffsetMax = $"{Positions.SidebarW} {-Positions.TopbarH}" }
            }, Layers.Root, Layers.Root + ".side");
            container.Add(new CuiPanel
            {
                Image = { Color = Palette.CBorder },
                RectTransform = { AnchorMin = "0 0", AnchorMax = "0 1", OffsetMin = "0 0", OffsetMax = "1 0" }
            }, Layers.Root + ".side");

            var navCatKeys = new HashSet<string>(_nav.Select(cat => cat.TitleKey));
            var newCatCount = _extSections.Select(s => s.Category)
                .Where(cat => !string.IsNullOrEmpty(cat) && !navCatKeys.Contains(cat)).Distinct().Count();
            var rowCount = _nav.Count + _nav.Sum(cat => cat.Items.Count) + _extSections.Count + newCatCount;
            var contentHeight = Math.Max(Positions.PanelH - Positions.TopbarH - 26, 16 + rowCount * 32);
            container.Add(new CuiElement
            {
                Parent = Layers.Root + ".side", Name = Layers.Root + ".side.sv",
                Components =
                {
                    new CuiScrollViewComponent
                    {
                        Vertical = true, Horizontal = false,
                        MovementType = UnityEngine.UI.ScrollRect.MovementType.Clamped, Inertia = true,
                        DecelerationRate = 0.2f, ScrollSensitivity = 24f, VerticalNormalizedPosition = 1f,
                        ContentTransform = new CuiRectTransform { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = $"0 {-contentHeight}", OffsetMax = "0 0" },
                        VerticalScrollbar = new CuiScrollbar { AutoHide = true, Size = 3f, HandleColor = Palette.CBorder, TrackColor = Colors.Clear }
                    },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1", OffsetMin = "0 12", OffsetMax = "0 -14" }
                }
            });

            UI_NavBody(container, player);
        }

        private void UI_NavBody(CuiElementContainer container, BasePlayer player)
        {
            var active = GetPage(player);
            container.Add(new CuiElement
            {
                Parent = Layers.Root + ".side.sv", Name = Layers.Root + ".side.sv.body",
                DestroyUi = Layers.Root + ".side.sv.body",
                Components = { new CuiImageComponent { Color = Colors.Clear }, new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1" } }
            });

            var y = -2;
            foreach (var cat in _nav)
            {
                UI_Text(container, Layers.Root + ".side.sv.body", GetLocalizedMessage(cat.TitleKey, player), 9, Fonts.Title,
                    TextAnchor.LowerLeft, Palette.CText2, "0 1", "1 1", $"16 {y - 18}", $"-8 {y}");
                y -= 24;

                foreach (var item in cat.Items)
                {
                    var badgeText = item.Badge == null
                        ? null
                        : item.Id == "players"
                            ? BasePlayer.activePlayerList.Count.ToString()
                            : item.Id == "console"
                                ? ConsoleCount().ToString()
                                : item.Badge;
                    UI_NavRow(container, player, item.Id, item.Icon, GetLocalizedMessage(item.LabelKey, player),
                        item.Id == active, IsNavLocked(player, item), item.Disabled, badgeText, item.BadgeColor, ref y);

                    if (item.Id != "perms")
                        continue;
                    foreach (var sec in _extSections)
                    {
                        if (sec.Category != cat.TitleKey)
                            continue;
                        var locked = sec.Permission != null &&
                                     !permission.UserHasPermission(player.UserIDString, sec.Permission);
                        UI_NavRow(container, player, sec.Id, sec.Icon, sec.Title?.Invoke(player) ?? sec.Id, sec.Id == active,
                            locked, false, null, null, ref y);
                    }
                }

                foreach (var sec in _extSections)
                {
                    if (sec.Category != cat.TitleKey || cat.Items.Any(it => it.Id == "perms"))
                        continue;
                    var locked = sec.Permission != null &&
                                 !permission.UserHasPermission(player.UserIDString, sec.Permission);
                    UI_NavRow(container, player, sec.Id, sec.Icon, sec.Title?.Invoke(player) ?? sec.Id, sec.Id == active,
                        locked, false, null, null, ref y);
                }

                y -= 8;
            }

            var navCats = new HashSet<string>(_nav.Select(cat => cat.TitleKey));
            foreach (var newCat in _extSections.Select(s => s.Category)
                         .Where(cat => !string.IsNullOrEmpty(cat) && !navCats.Contains(cat)).Distinct())
            {
                UI_Text(container, Layers.Root + ".side.sv.body", GetLocalizedMessage(newCat, player), 9, Fonts.Title,
                    TextAnchor.LowerLeft, Palette.CText2, "0 1", "1 1", $"16 {y - 18}", $"-8 {y}");
                y -= 24;

                foreach (var sec in _extSections)
                {
                    if (sec.Category != newCat)
                        continue;
                    var locked = sec.Permission != null &&
                                 !permission.UserHasPermission(player.UserIDString, sec.Permission);
                    UI_NavRow(container, player, sec.Id, sec.Icon, sec.Title?.Invoke(player) ?? sec.Id, sec.Id == active,
                        locked, false, null, null, ref y);
                }

                y -= 8;
            }
        }

        private void UI_NavRow(CuiElementContainer container, BasePlayer player, string id, string icon, string label,
            bool on, bool navLocked, bool disabled, string badgeText, string badgeColor, ref int y)
        {
            var row = Layers.Root + ".nav." + id;
            UI_Btn(container, Layers.Root + ".side.sv.body", disabled || on ? "" : $"pa.nav {id}",
                on ? Palette.CElev : Colors.Clear, "0 1", "1 1", $"8 {y - 32}", $"-8 {y}", row);
            var hintKey = NavHintKey(id);
            if (hintKey != null)
                UI_Tip(container, GetLocalizedMessage(hintKey, player));
            else
            {
                var hint = _extSections.FirstOrDefault(s => s.Id == id)?.Hint?.Invoke(player);
                if (!string.IsNullOrEmpty(hint))
                    UI_Tip(container, hint);
            }

            if (on)
                container.Add(new CuiPanel
                {
                    Image = { Color = Palette.CAccent },
                    RectTransform = { AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = "0 -9", OffsetMax = "3 9" }
                }, row);

            var tint = disabled ? Palette.CText3 : on ? Palette.CAccent : Palette.CText2;
            container.Add(new CuiElement
            {
                Parent = row,
                Components =
                {
                    new CuiImageComponent { Color = tint, Sprite = icon },
                    new CuiRectTransformComponent { AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = "10 -8", OffsetMax = "26 8" }
                }
            });
            UI_Text(container, row, label, 12, Fonts.Title, TextAnchor.MiddleLeft,
                disabled ? Palette.CText3 : on ? Palette.CAccent : Palette.CText, "0 0", "1 1", "34 0", "-26 0");

            if (navLocked)
                container.Add(new CuiElement
                {
                    Parent = row,
                    Components =
                    {
                        new CuiImageComponent { Color = Palette.CText3, Sprite = "assets/icons/lock.png" },
                        new CuiRectTransformComponent { AnchorMin = "1 0.5", AnchorMax = "1 0.5", OffsetMin = "-24 -7", OffsetMax = "-10 7" }
                    }
                });
            else if (badgeText != null)
            {
                container.Add(new CuiPanel
                {
                    Image = { Color = badgeColor },
                    RectTransform = { AnchorMin = "1 0.5", AnchorMax = "1 0.5", OffsetMin = "-40 -8", OffsetMax = "-10 8" }
                }, row, row + ".badge");
                UI_Text(container, row + ".badge", badgeText, 9, Fonts.Title, TextAnchor.MiddleCenter, Palette.CAccentText,
                    "0 0", "1 1");
            }

            y -= 32;
        }

