            "vanish" => TranslateKey.TipNavVanish,
            "esp" => TranslateKey.TipNavEsp,
            "perms" => TranslateKey.TipNavPerms,
            "logs" => TranslateKey.TipNavLogs,
            "plugins" => TranslateKey.TipNavPlugins,
            "convars" => TranslateKey.TipNavConvars,
            "appearance" => TranslateKey.TipNavAppearance,
            "settings" => TranslateKey.TipNavSettings,
            "map" => TranslateKey.TipNavMap,
            "binds" => TranslateKey.TipNavBinds,
            "quickbuttons" => TranslateKey.TipNavQuickButtons,
            _ => null
        };

        private static string ProtectCommand(string command)
        {
#if CARBON
            if (string.IsNullOrEmpty(command))
                return command;
            var space = command.IndexOf(' ');
            var name = space < 0 ? command : command.Substring(0, space);
            if (PublicCommands.Contains(name))
                return command;
            return Carbon.Community.Protect(command);
#else
            return command;
#endif
        }

