        private string UI_Card(CuiElementContainer container, string parent, string title, int x, int y, int w, int h,
            string fixedName = null)
        {
            var name = fixedName ?? parent + "." + CuiHelper.GetGuid();
            container.Add(new CuiElement
            {
                Parent = parent, Name = name,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CSurface },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{x} {y - h}", OffsetMax = $"{x + w} {y}" }
                }
            });
            if (title != null)
            {
                UI_Text(container, name, title, 12, Fonts.Title, TextAnchor.MiddleLeft, Palette.CText, "0 1", "1 1", "16 -36",
                    "-16 0");
                container.Add(new CuiPanel
                {
                    Image = { Color = Palette.CBorder },
                    RectTransform = { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = "0 -37", OffsetMax = "0 -36" }
                }, name);
            }

            return name;
        }

        private void UI_Tip(CuiElementContainer container, string text)
        {
            if (string.IsNullOrEmpty(text))
                return;
            for (var i = container.Count - 1; i >= 0; i--)
            {
                if (!container[i].Components.Any(x => x is CuiButtonComponent || x is CuiImageComponent))
                    continue;
                container[i].Components.Add(new CuiTooltipComponent
                {
                    Text = text,
                    Delay = Tooltip.DelayType.Short,
                    Position = TooltipContainer.PositionMode.Auto
                });
                return;
            }
        }

        private void UI_Text(CuiElementContainer container, string parent, string text, int size, string font,
            TextAnchor align, string color, string aMin, string aMax, string oMin = null, string oMax = null,
            string name = null)
        {
            var label = new CuiLabel
            {
                Text = { Text = text, FontSize = size, Font = font, Align = align, Color = color },
                RectTransform = { AnchorMin = aMin, AnchorMax = aMax }
            };
            if (oMin != null)
                label.RectTransform.OffsetMin = oMin;
            if (oMax != null)
                label.RectTransform.OffsetMax = oMax;
            if (name == null)
                container.Add(label, parent);
            else
                container.Add(label, parent, name, name);
        }

        private void UI_Btn(CuiElementContainer container, string parent, string command, string color, string aMin,
            string aMax, string oMin = null, string oMax = null, string name = null)
        {
            var button = new CuiButton
            {
                Button = { Command = ProtectCommand(command), Color = color },
                Text = { Text = "" },
                RectTransform = { AnchorMin = aMin, AnchorMax = aMax }
            };
            if (oMin != null)
                button.RectTransform.OffsetMin = oMin;
            if (oMax != null)
                button.RectTransform.OffsetMax = oMax;
            if (name == null)
                container.Add(button, parent);
            else
                container.Add(button, parent, name, name);
        }

