        private void FixDelivery(ulong uid)
        {
            var d = GetSelect(null, FieldKey.DiscordDelivery, "webhook");
            var wh = GetToggle(null, "d.wh", true);
            var bot = GetToggle(null, "d.bot", false);
            var ok = d switch { "webhook" => wh, "bot" => bot, "both" => wh && bot, _ => true };
            if (ok)
                return;
            SetSelect(uid, FieldKey.DiscordDelivery, wh && bot ? "both" : wh ? "webhook" : bot ? "bot" : "none");
        }

