        private void UI_Slider(CuiElementContainer container, string parent, BasePlayer player, string id, string label,
            float def, int x, int y, int w, string unit, int max)
        {
            var pct = Mathf.Clamp01(GetSlider(player, id, def));
            var valText = unit == "%" ? $"{Mathf.RoundToInt(pct * 100f)}%" : $"{Mathf.RoundToInt(pct * max)} {unit}";
            UI_Text(container, parent, label, 11, Fonts.Body, TextAnchor.UpperLeft, Palette.CText, "0 1", "0 1",
                $"{x} {y - 14}", $"{x + w - 60} {y}");
            UI_Text(container, parent, valText, 11, Fonts.Title, TextAnchor.UpperRight, Palette.CAccent, "0 1", "0 1",
                $"{x + w - 60} {y - 14}", $"{x + w} {y}");
            var ty = y - 20;
            container.Add(new CuiPanel
            {
                Image = { Color = Palette.CElev },
                RectTransform = { AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{x} {ty - 6}", OffsetMax = $"{x + w} {ty}" }
            }, parent);
            var fillW = Mathf.RoundToInt(pct * w);
            container.Add(new CuiPanel
            {
                Image = { Color = Palette.CAccent },
                RectTransform = { AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{x} {ty - 6}", OffsetMax = $"{x + fillW} {ty}" }
            }, parent);
            container.Add(new CuiElement
            {
                Parent = parent,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CAccentH, Sprite = "assets/icons/circle_closed.png" },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{x + fillW - 7} {ty - 10}",
                        OffsetMax = $"{x + fillW + 7} {ty + 4}"
                    }
                }
            });
            for (var i = 0; i <= 20; i++)
            {
                var sp = (i / 20f).ToString("0.###", Ci);
                var sx = x + Mathf.RoundToInt(i * (w / 20f)) - 9;
                UI_Btn(container, parent, $"pa.slider {id} {sp}", Colors.Clear, "0 1", "0 1", $"{sx} {ty - 12}",
                    $"{sx + 18} {ty + 10}");
            }
        }

