        private string UI_Scroll(CuiElementContainer container, string parent, string name, int x, int y, int w, int h,
            int contentH, string bg, string border, float? vpos = null, bool vertical = true, bool scrollbar = false,
            float sensitivity = 26f)
        {
            var clip = parent + "." + name;
            var el = new CuiElement { Parent = parent, Name = clip, DestroyUi = clip, Components = { new CuiImageComponent { Color = bg ?? Colors.Clear } } };
            if (border != null)
                el.Components.Add(new CuiOutlineComponent { Color = border, Distance = "1 1" });
            el.Components.Add(new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{x} {y - h}", OffsetMax = $"{x + w} {y}" });
            container.Add(el);

            var pad = border != null ? 1 : 0;
            var viewH = h - 2 * pad;
            var content = clip + ".c";
            container.Add(new CuiElement
            {
                Parent = clip, Name = content,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiScrollViewComponent
                    {
                        Horizontal = false, Vertical = vertical,
                        MovementType = ScrollRect.MovementType.Clamped, Inertia = true, ScrollSensitivity = sensitivity,
                        VerticalNormalizedPosition = vpos,
                        VerticalScrollbar = scrollbar
                            ? new CuiScrollbar
                            {
                                AutoHide = true, Size = 5f, HandleColor = Palette.CAccent,
                                HighlightColor = Palette.CAccentH, PressedColor = Palette.CAccentH,
                                TrackColor = Palette.CPage
                            }
                            : null,
                        ContentTransform = new CuiRectTransform
                        {
                            AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = $"0 {-Mathf.Max(contentH, viewH)}",
                            OffsetMax = "0 0"
                        }
                    },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1", OffsetMin = $"{pad} {pad}", OffsetMax = $"-{pad} -{pad}" }
                }
            });
            return content;
        }

        private string UI_ScrollList(CuiElementContainer container, string parent, string name, int x, int y, int w, int h,
            int cellH, int gap, int count, int inset, int cols, string bg, string border, float? vpos = null,
            bool scrollbar = false, float sensitivity = 26f)
        {
            cols = Mathf.Max(1, cols);
            var rows = (count + cols - 1) / cols;
            var contentH = Mathf.Max(rows * (cellH + gap) - gap + inset * 2, h);
            var pad = border != null ? 2 : 0;
            var cellW = (w - pad - inset * 2 - (cols - 1) * gap) / cols;
            var content = UI_Scroll(container, parent, name, x, y, w, h, contentH, bg, border, vpos, contentH > h, scrollbar,
                sensitivity);
            var list = content + ".l";
            container.Add(new CuiElement
            {
                Parent = content, Name = list,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{cellW} {cellH}", Spacing = $"{gap} {gap}",
                        Padding = $"{inset} {inset} {inset} {inset}",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft, Constraint = GridLayoutGroup.Constraint.FixedColumnCount,
                        ConstraintCount = cols
                    },
                    new CuiContentSizeFitterComponent { VerticalFit = ContentSizeFitter.FitMode.PreferredSize },
                    new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "1 1", Pivot = "0.5 1", OffsetMin = "0 0", OffsetMax = "0 0" }
                }
            });
            return list;
        }

        private static string ScrollOf(string list) =>
            list.EndsWith(".l", StringComparison.Ordinal) ? list.Substring(0, list.Length - 2) : list;

        private string UI_ScrollStack(CuiElementContainer container, string parent, string name, int x, int y, int w, int h,
            int contentH, int gap, int inset, string bg, string border, float? vpos = null)
        {
            var content = UI_Scroll(container, parent, name, x, y, w, h, Mathf.Max(contentH, h), bg, border, vpos,
                contentH > h);
            var list = content + ".l";
            container.Add(new CuiElement
            {
                Parent = content, Name = list,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiVerticalLayoutGroupComponent
                    {
                        Spacing = gap, ChildAlignment = TextAnchor.UpperLeft, ChildControlWidth = true,
                        ChildControlHeight = true, ChildForceExpandWidth = true, ChildForceExpandHeight = false,
                        Padding = $"{inset} {inset} {inset} {inset}"
                    },
                    new CuiContentSizeFitterComponent { VerticalFit = ContentSizeFitter.FitMode.PreferredSize },
                    new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "1 1", Pivot = "0.5 1", OffsetMin = "0 0", OffsetMax = "0 0" }
                }
            });
            return list;
        }

        private void UI_Page(CuiElementContainer container, BasePlayer player, string page)
        {
            switch (page)
            {
                case "console":
                {
                    UI_PageConsole(container, player);
                    break;
                }
                case "players":
                {
                    UI_PagePlayers(container, player);
                    break;
                }
                case "vanish":
                {
                    UI_PageVanish(container, player);
                    break;
                }
                case "esp":
                {
                    UI_PageEsp(container, player);
                    break;
                }
                case "perms":
                {
                    UI_PagePerms(container, player);
                    break;
                }
                case "logs":
                {
                    UI_PageLogs(container, player);
                    break;
                }
                case "plugins":
                {
                    UI_PagePlugins(container, player);
                    break;
                }
                case "convars":
                {
                    UI_PageConvars(container, player);
                    break;
                }
                case "map":
                {
                    UI_PageMap(container, player);
                    break;
                }
                case "binds":
                {
                    UI_PageBinds(container, player);
                    break;
                }
                case "quickbuttons":
                {
                    UI_PageQuickButtons(container, player);
                    break;
                }
                case "appearance":
                {
                    UI_PageAppearance(container, player);
                    break;
                }
                case "settings":
                {
                    UI_PageSettings(container, player);
                    break;
                }
                default:
                {
                    var sec = _extSections.FirstOrDefault(x => x.Id == page);
                    if (sec != null)
                        UI_PageExt(container, player, sec);
                    else
                        UI_PageDashboard(container, player);
                    break;
                }
            }
        }

        private bool CanBind(BasePlayer player, string id) => id switch
        {
            "vanish" => Can(player, Permissions.Vanish),
            "god" => Can(player, Permissions.God),
            "noclip" => Can(player, Permissions.Noclip),
            "esp" => Can(player, Permissions.Esp),
            "hammer" => Hammer.Can(player),
            "inspect" => Can(player, Permissions.Players),
            "map" => Can(player, Permissions.Map),
            _ => true
        };

        private List<string[]> PieRows(BasePlayer player)
        {
            var list = new List<string[]>();
            foreach (var def in BindDefs)
                if (def[0] != "pie" && CanBind(player, def[0]))
                    list.Add(def);
            return list;
        }

        private List<string[]> PieEntries(BasePlayer player) =>
            PieRows(player).FindAll(def => GetToggle(player, PieKeyPrefix + def[0], true));

        private void OpenPie(BasePlayer admin)
        {
            if (admin == null || !admin.IsConnected || CommunityEntity.ServerInstance == null)
                return;
            var entries = PieEntries(admin);
            if (entries.Count == 0)
                return;
            using var pie = Facepunch.Pool.Get<ProtoBuf.CustomPie>();
            pie.menus = Facepunch.Pool.Get<List<ProtoBuf.CustomPieMenu>>();
            foreach (var def in entries)
                CommunityEntity.AddPieMenu(pie, GetLocalizedMessage(def[2], admin),
                    GetLocalizedMessage(def[3], admin), ProtectCommand(def[4]), def[1], false,
                    WidgetState(admin, def[0]), "", "");
            CommunityEntity.ServerInstance.SendPie(admin, pie);
        }

        [ConsoleCommand("pa.pie")]
        private void CommandPie(ConsoleSystem.Arg arg)
        {
            if (!TryAuth(arg, out var player))
                return;
            if (BindRelease(arg))
                return;
            if (player.IsSpectating())
                return;

            OpenPie(player);
        }

