        private void UI_BindCard(CuiElementContainer container, BasePlayer player, string grid, string[] def, int index)
        {
            var allowed = CanBind(player, def[0]);
            var tint = allowed ? Palette.CAccent : Palette.CText3;
            var card = grid + ".c" + index;
            container.Add(new CuiElement
            {
                Parent = grid, Name = card,
                Components = { new CuiImageComponent { Color = Palette.CSurface }, new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" } }
            });
            container.Add(
                new CuiPanel
                {
                    Image = { Color = tint },
                    RectTransform = { AnchorMin = "0 0", AnchorMax = "0 1", OffsetMin = "0 0", OffsetMax = "3 0" }
                }, card);
            var icon = card + ".ic";
            container.Add(new CuiElement
            {
                Parent = card, Name = icon,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CElev },
                    new CuiOutlineComponent { Color = tint, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = "12 -33", OffsetMax = "34 -11" }
                }
            });
            container.Add(new CuiElement
            {
                Parent = icon,
                Components =
                {
                    new CuiImageComponent { Color = tint, Sprite = def[1] },
                    new CuiRectTransformComponent { AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = "-7 -7", OffsetMax = "7 7" }
                }
            });
            UI_Text(container, card, GetLocalizedMessage(def[2], player), 13, Fonts.Title, TextAnchor.MiddleLeft,
                allowed ? Palette.CText : Palette.CText3, "0 1", "1 1", "43 -26", "-10 -8");
            UI_Text(container, card, GetLocalizedMessage(def[3], player), 10, Fonts.Body, TextAnchor.MiddleLeft,
                Palette.CText2, "0 1", "1 1", "43 -42", "-10 -26");
            if (!allowed)
            {
                UI_Text(container, card, GetLocalizedMessage(TranslateKey.BindsLocked, player), 10, Fonts.Title,
                    TextAnchor.MiddleLeft, Palette.CText3, "0 0", "1 0", "12 7", "-12 27");
                return;
            }

            UI_Text(container, card, GetLocalizedMessage(TranslateKey.BindsCopy, player), 8, Fonts.Title,
                TextAnchor.MiddleLeft, Palette.CText3, "0 0", "1 0", "12 29", "-12 39");
            UI_Text(container, card, GetLocalizedMessage(TranslateKey.BindsKey, player), 8, Fonts.Title,
                TextAnchor.MiddleRight, Palette.CText3, "0 0", "1 0", "12 29", "-12 39");

            var key = BindKeyOf(player, def);
            container.Add(new CuiElement
            {
                Parent = card, Name = card + ".line",
                Components =
                {
                    new CuiImageComponent { Color = Palette.CPage },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "0 0", OffsetMin = "12 7", OffsetMax = "248 27" }
                }
            });
            container.Add(new CuiElement
            {
                Parent = card + ".line",
                Components =
                {
                    new CuiInputFieldComponent
                    {
                        Text = BindLine(key, def[4]), FontSize = 10, Font = Fonts.Console,
                        Align = TextAnchor.MiddleLeft, Color = Palette.CText, CharsLimit = 128, NeedsKeyboard = true,
                        ReadOnly = true
                    },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1", OffsetMin = "6 0", OffsetMax = "-4 0" }
                }
            });
            container.Add(new CuiElement
            {
                Parent = card, Name = card + ".key",
                Components =
                {
                    new CuiImageComponent { Color = Palette.CElev },
                    new CuiOutlineComponent { Color = Palette.CBorderSoft, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "1 0", AnchorMax = "1 0", OffsetMin = "-94 7", OffsetMax = "-12 27" }
                }
            });
            container.Add(new CuiElement
            {
                Parent = card + ".key",
                Components =
                {
                    new CuiInputFieldComponent
                    {
                        Text = key, FontSize = 10, Font = Fonts.Console, Align = TextAnchor.MiddleLeft,
                        Color = Palette.CAccent, CharsLimit = 16, NeedsKeyboard = true,
                        Command = ProtectCommand($"pa.input {BindKeyPrefix}{def[0]} ")
                    },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1", OffsetMin = "6 0", OffsetMax = "-4 0" }
                }
            });
        }

        private string BindKeyOf(BasePlayer player, string[] def)
        {
            var key = GetInput(player, BindKeyPrefix + def[0], "").Trim();
            return key.Length == 0 ? def[5] : key;
        }

        private static string BindLine(string key, string command) => $"bind {key} {command}";

