        private int GetCountableAdmins() =>
            BasePlayer.activePlayerList.Count(b => b != null && permission.UserHasPermission(b.UserIDString, Permissions.Countable));

        private string GetDashboardSignature(out int online, out int max, out int sleepers, out int admins,
            out int fps, out int ents)
        {
            online = BasePlayer.activePlayerList.Count;
            max = ConVar.Server.maxplayers;
            sleepers = BasePlayer.sleepingPlayerList?.Count ?? 0;
            admins = GetCountableAdmins();
            fps = GetServerFps();
            ents = BaseNetworkable.serverEntities != null ? BaseNetworkable.serverEntities.Count : 0;
            return $"{online}/{max}/{sleepers}/{admins}/{GetNewToday()}/{fps}/{ents}";
        }

        private string GetDashboardSignature() => GetDashboardSignature(out _, out _, out _, out _, out _, out _);

        private void UI_DashboardStats(CuiElementContainer container, BasePlayer player, string parent, int y)
        {
            var sig = GetDashboardSignature(out var online, out var max, out var sleepers, out var admins,
                out var fps, out var ents);
            var queue = ServerQueue(out var joining);
            GetAdmin(player.userID).DashboardSignature = $"{sig}/{queue}/{joining}";

            var onlineSub = $"{sleepers} {GetLocalizedMessage(TranslateKey.DashboardSleeping, player)}";
            if (queue > 0 || joining > 0)
                onlineSub +=
                    $"  ·  {SafeFormat(GetLocalizedMessage(TranslateKey.DashboardQueue, player), queue, joining)}";

            var cards = new[]
            {
                new[] { GetLocalizedMessage(TranslateKey.DashboardOnline, player), $"{online} / {max}", onlineSub, Colors.CInfo },
                new[]
                {
                    GetLocalizedMessage(TranslateKey.DashboardAdmins, player), admins.ToString(),
                    GetLocalizedMessage(TranslateKey.DashboardAllonline, player), Colors.CSuccess
                },
                new[]
                {
                    GetLocalizedMessage(TranslateKey.DashboardNewplayers, player), GetNewToday().ToString(),
                    GetLocalizedMessage(TranslateKey.DashboardNewplayersD, player), Colors.CInfo
                },
                new[]
                {
                    GetLocalizedMessage(TranslateKey.DashboardFps, player), fps.ToString(),
                    $"{ents} {GetLocalizedMessage(TranslateKey.DashboardEntities, player)}",
                    fps >= 60 ? Colors.CSuccess : fps >= 30 ? Colors.CWarn : Colors.CDanger
                }
            };
            var cw = (Positions.BodyW - Positions.Pad * 2 - 3 * 12) / 4;
            var strip = parent + ".dcards";
            container.Add(new CuiElement
            {
                Parent = parent, Name = strip, DestroyUi = strip,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{cw} {Positions.Dash.StatsH}", Spacing = "12 12",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = 4
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{Positions.Pad} {y - Positions.Dash.StatsH}",
                        OffsetMax = $"{Positions.Pad + (Positions.BodyW - Positions.Pad * 2)} {y}"
                    }
                }
            });
            for (var i = 0; i < cards.Length; i++)
            {
                var card = strip + ".dcard" + i;
                container.Add(new CuiElement
                {
                    Parent = strip, Name = card,
                    Components = { new CuiImageComponent { Color = Palette.CSurface }, new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" } }
                });
                UI_Text(container, card, cards[i][0], 9, Fonts.Title, TextAnchor.UpperLeft, Palette.CText2, "0 1", "1 1",
                    "12 -24", "-12 -10");
                UI_Text(container, card, cards[i][1], 20, Fonts.Title, TextAnchor.UpperLeft, Palette.CText, "0 1", "1 1",
                    "12 -52", "-12 -24");
                UI_Text(container, card, cards[i][2], 9, Fonts.Body, TextAnchor.UpperLeft, cards[i][3], "0 1", "1 1", "12 -70",
                    "-12 -56");
            }
        }

        private void RefreshDashboardFor(BasePlayer player)
        {
            if (player == null || PeekAdmin(player.userID)?.UiOpen != true)
                return;
            if (GetPage(player) != "dashboard")
                return;
            if ((PeekAdmin(player.userID)?.Popup ?? 0) != 0 || PeekAdmin(player.userID)?.OpenDropdown != null)
                return;
            var sig = GetDashboardSignature();
            if (PeekAdmin(player.userID)?.DashboardSignature == sig)
                return;
            ApplyTheme(player);
            var container = new CuiElementContainer();
            UI_DashboardStats(container, player, DashContent, Positions.Dash.StatsY);
            CuiHelper.AddUi(player, container);
        }

        private void UI_PageDashboard(CuiElementContainer container, BasePlayer player)
        {
            UI_Head(container, player, TranslateKey.DashboardTitle, TranslateKey.DashboardSub);

            const int rowH = Positions.Dash.RowH;
            var canPlayersEarly = Can(player, Permissions.Players);
            var toggleCount = 5 + (canPlayersEarly ? 1 : 0) + (Hammer.Can(player) ? 1 : 0);
            var togH = 46 + DashToggleRows(toggleCount) * 30 + 12;
            var togY = Positions.Dash.RowY - rowH - 12;
            var qbList = QuickFor(player, QuickTarget.Global, QuickPlace.Dashboard);
            var qbY = togY - togH - 12;
            var qbH = qbList.Count == 0 ? 0 : 46 + QuickBlockH(qbList.Count, 3);
            var contentH = -(qbList.Count == 0 ? togY - togH : qbY - qbH) + 12;

            UI_Scroll(container, Layers.Body, "dash", 0, -54, Positions.BodyW, Positions.BodyH - 54,
                Math.Max(contentH, Positions.BodyH - 54), null, null);
            UI_DashboardStats(container, player, DashContent, Positions.Dash.StatsY);

            var leftW = (int)((Positions.BodyW - Positions.Pad * 2 - 14) * 0.58f);
            var rightW = Positions.BodyW - Positions.Pad * 2 - 14 - leftW;

            var con = UI_Card(container, DashContent,
                $"{GetLocalizedMessage(TranslateKey.DashboardLiveconsole, player)}  ·  {ConsoleCount()}", Positions.Pad,
                Positions.Dash.RowY, leftW,
                Positions.Dash.RowH, DashConsoleCard);
            if (IsConsoleAllowed(player))
            {
                UI_DashConsoleBox(container, player, leftW);
                UI_Input(container, con, player, FieldKey.DashboardCmd,
                    GetLocalizedMessage(TranslateKey.ConsolePlaceholder, player), 12,
                    -(rowH - 42), leftW - 104,
                    28);
                UI_Btn(container, con, GetLocalizedMessage(TranslateKey.ButtonSend, player), "pa.consend dash.cmd",
                    Palette.CAccent, 11, Fonts.Title, TextAnchor.MiddleCenter, Palette.CAccentText, "0 1", "0 1",
                    $"{leftW - 88} {-(rowH - 42) - 28}", $"{leftW - 12} {-(rowH - 42)}");
            }
            else
            {
                UI_Text(container, con, GetLocalizedMessage(TranslateKey.WidgetConsoleOff, player), 11, Fonts.Body,
                    TextAnchor.MiddleCenter, Palette.CText3, "0 0", "1 1", "12 12", "-12 -40");
            }

            var near = UI_Card(container, DashContent,
                $"{GetLocalizedMessage(TranslateKey.DashboardNearby, player)}  ·  {BasePlayer.activePlayerList.Count}",
                Positions.Pad + leftW + 14, Positions.Dash.RowY, rightW, rowH);
            var me = player.transform.position;
            var canPlayers = canPlayersEarly;
            var nearby = !canPlayers
                ? new List<BasePlayer>()
                : BasePlayer.activePlayerList
                    .Where(b => b != null && b != player)
                    .OrderBy(b => Vector3.Distance(b.transform.position, me))
                    .Take(3).ToList();
            if (nearby.Count == 0)
                UI_Text(container, near,
                    canPlayers ? GetLocalizedMessage(TranslateKey.DashboardNonearby, player) : GetLocalizedMessage(TranslateKey.LockedTitle, player),
                    10, Fonts.Body, TextAnchor.UpperLeft, Palette.CText3, "0 1", "1 1", "12 -64", "-12 -46");
            for (var i = 0; i < nearby.Count; i++)
            {
                var b = nearby[i];
                var g = GetGroupOf(b);
                var py = -46 - i * 40;
                UI_Avatar(container, near, b.UserIDString, 12, py, 30);
                UI_Text(container, near, b.displayName, 12, Fonts.Title, TextAnchor.UpperLeft, Palette.CText, "0 1", "1 1",
                    $"50 {py - 16}", $"-90 {py - 1}");
                UI_Text(container, near,
                    $"{FormatDuration(GetPlaytimeOf(b.userID))} · ping {Ping(b)} · {Grid(b.transform.position)}", 9,
                    Fonts.Body, TextAnchor.UpperLeft, Palette.CText2, "0 1", "1 1", $"50 {py - 30}", $"-90 {py - 16}");
                UI_Chip(container, near, g, GroupColor(g), rightW - 84, py - 5, 72);
            }

            UI_Btn(container, near, GetLocalizedMessage(TranslateKey.NearbyAll, player), canPlayers ? "pa.nav players" : "",
                canPlayers ? Palette.CAccent : Palette.CElev, 11, Fonts.Title, TextAnchor.MiddleCenter,
                canPlayers ? Palette.CAccentText : Palette.CText3, "0 1", "1 1", $"12 {-(rowH - 42) - 30}",
                $"-12 {-(rowH - 42)}");

            var quick = UI_Card(container, DashContent, GetLocalizedMessage(TranslateKey.DashboardQuicktoggles, player),
                Positions.Pad, togY, Positions.BodyW - Positions.Pad * 2, togH);
            var qw = (Positions.BodyW - Positions.Pad * 2 - 32) / Positions.Dash.ToggleCols;
            bool vanishOn = PeekAdmin(player.userID)?.Vanished == true,
                espOn = GetToggle(player, "e.on", false),
                noclipOn = GetToggle(player, "f.noclip", false),
                godOn = GetToggle(player, "f.god", false),
                widgetOn = PeekAdmin(player.userID)?.WidgetOpen == true;
            var qt = new List<object[]>
            {
                new object[]
                {
                    GetLocalizedMessage(TranslateKey.ToggleVanish, player),
                    GetLocalizedMessage(TranslateKey.ToggleVanishD, player), vanishOn, "pa.toggle vanish", "vanish"
                },
                new object[]
                {
                    GetLocalizedMessage(TranslateKey.ToggleEsp, player),
                    GetLocalizedMessage(TranslateKey.ToggleEspD, player),
                    espOn, $"pa.toggle e.on {(espOn ? 0 : 1)}", "e.on"
                },
                new object[]
                {
                    GetLocalizedMessage(TranslateKey.ToggleGodmode, player),
                    GetLocalizedMessage(TranslateKey.ToggleGodmodeD, player), godOn,
                    $"pa.toggle f.god {(godOn ? 0 : 1)}", "f.god"
                },
                new object[]
                {
                    GetLocalizedMessage(TranslateKey.ToggleNoclip, player),
                    GetLocalizedMessage(TranslateKey.ToggleNoclipD, player), noclipOn,
                    $"pa.toggle f.noclip {(noclipOn ? 0 : 1)}", "f.noclip"
                },
                new object[]
                {
                    GetLocalizedMessage(TranslateKey.ToggleWidget, player),
                    GetLocalizedMessage(TranslateKey.ToggleWidgetD, player), widgetOn, "pa.widget", "widget"
                }
            };
            if (canPlayers)
            {
                var inspectOn = GetToggle(player, "f.inspect", false);
                qt.Add(new object[]
                {
                    GetLocalizedMessage(TranslateKey.ToggleInspect, player),
                    GetLocalizedMessage(TranslateKey.ToggleInspectD, player), inspectOn,
                    $"pa.toggle f.inspect {(inspectOn ? 0 : 1)}", "f.inspect"
                });
            }

            if (Hammer.Can(player))
            {
                var hammerOn = GetToggle(player, "f.hammer", false);
                qt.Add(new object[]
                {
                    GetLocalizedMessage(TranslateKey.HammerToggle, player),
                    GetLocalizedMessage(TranslateKey.HammerToggleD, player), hammerOn,
                    $"pa.toggle f.hammer {(hammerOn ? 0 : 1)}", "f.hammer"
                });
            }

            var qrows = (qt.Count + Positions.Dash.ToggleCols - 1) / Positions.Dash.ToggleCols;
            var qgrid = quick + ".qtog";
            container.Add(new CuiElement
            {
                Parent = quick, Name = qgrid, DestroyUi = qgrid,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{qw - 8} 28", Spacing = "16 2",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = Positions.Dash.ToggleCols
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"16 {-46 - (qrows * 30 - 2)}",
                        OffsetMax = $"{16 + (Positions.Dash.ToggleCols * (qw + 8) - 16)} -46"
                    }
                }
            });
            for (var i = 0; i < qt.Count; i++)
            {
                var key = (string)qt[i][4];
                var cell = qgrid + ".c" + i;
                container.Add(new CuiElement { Parent = qgrid, Name = cell, Components = { new CuiImageComponent { Color = Colors.Clear } } });
                UI_FeatureToggle(container, cell, (string)qt[i][0], (string)qt[i][1], (bool)qt[i][2], (string)qt[i][3], key);
            }

            if (qbList.Count == 0)
                return;
            var qbw = Positions.BodyW - Positions.Pad * 2;
            var qbCard = UI_Card(container, DashContent,
                GetLocalizedMessage(TranslateKey.DashboardQuickButtons, player), Positions.Pad, qbY, qbw, qbH);
            UI_QuickRow(container, qbCard, qbList, 0, 16, -44, qbw - 32, 3);
        }


