                    "1 1", $"8 {-6 - (i + 1) * lineH}", $"-8 {-6 - i * lineH}");
        }


        private List<PRow> BuildPlayerRows(string filter, string search)
        {
            var list = new List<PRow>();
            foreach (var b in BasePlayer.activePlayerList)
                if (b != null)
                    list.Add(new PRow { Id = b.userID, Name = b.displayName, Online = true, Bp = b, Group = GetGroupOf(b) });
            if (filter == "all")
            {
                var onlineIds = new HashSet<ulong>(BasePlayer.activePlayerList.Where(b => b != null)
                    .Select(b => (ulong)b.userID));
                foreach (var kv in _players)
                    if (!onlineIds.Contains(kv.Key))
                        list.Add(new PRow
                        {
                            Id = kv.Key,
                            Name = string.IsNullOrEmpty(kv.Value.Name) ? kv.Key.ToString() : kv.Value.Name,
                            Online = false, Group = GetGroupOf(kv.Key)
                        });
            }

            if (!string.IsNullOrEmpty(search))
                list = list.Where(r => r.Name.ToLowerInvariant().Contains(search) || r.Id.ToString().Contains(search))
                    .ToList();
            return list.OrderByDescending(r => r.Online).ThenBy(r => r.Name, StringComparer.OrdinalIgnoreCase).ToList();
        }

