        private static string WithAlpha(string rgba, float a)
        {
            var parts = rgba.Split(' ');
            if (parts.Length < 3)
                return rgba;
            return $"{parts[0]} {parts[1]} {parts[2]} {a.ToString(Ci)}";
        }

        private void UI_RowAction(CuiElementContainer container, string parent, string cmd, string sprite, string col, int x,
            int y, bool on = false, bool enabled = true)
        {
            var b = parent + ".ra." + CuiHelper.GetGuid();
            var bgColor = !enabled ? WithAlpha(col, 0.08f) : on ? col : WithAlpha(col, 0.22f);
            var iconColor = !enabled ? Palette.CText3 : on ? Palette.CAccentText : col;
            UI_Btn(container, parent, enabled ? cmd : "", bgColor, "0 1", "0 1", $"{x} {y - 26}", $"{x + 26} {y}", b);
            container.Add(new CuiElement
            {
                Name = b + ".sprite" + ".AGR4ZQN=",
                Parent = b,
                Components =
                {
                    new CuiImageComponent { Color = iconColor, Sprite = sprite },
                    new CuiRectTransformComponent { AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = "-7 -7", OffsetMax = "7 7" }
                }
            });
        }

        private void UI_Pagination(CuiElementContainer container, string parent, BasePlayer player, string group, int total)
        {
            var cur = int.TryParse(GetSelect(player, group, "1"), out var cp) ? cp : 1;
            var tokens = new List<string> { "◀" };
            for (var p = 1; p <= total; p++)
            {
                if (p == 1 || p == total || (p >= cur - 1 && p <= cur + 1))
                    tokens.Add(p.ToString());
                else if (tokens[tokens.Count - 1] != "...")
                    tokens.Add("...");
            }

            tokens.Add("▶");

            var bw = 26;
            var x = 0;
            for (var i = 0; i < tokens.Count; i++)
            {
                var tk = tokens[i];
                var bx = -16 - (tokens.Count - i) * (bw + 4);
                if (tk == "...")
                {
                    UI_Text(container, parent, "...", 12, Fonts.Title, TextAnchor.MiddleCenter, Palette.CText3, "1 0", "1 0",
                        $"{bx} 12", $"{bx + bw} 40");
                    continue;
                }

                var isNum = tk != "◀" && tk != "▶";
                var on = isNum && tk == cur.ToString();
                var cmd = tk == "◀" ? $"pa.select {group} {Mathf.Max(1, cur - 1)}" :
                    tk == "▶" ? $"pa.select {group} {Mathf.Min(total, cur + 1)}" : $"pa.select {group} {tk}";
                UI_Btn(container, parent, tk, cmd, on ? Palette.CAccent : Palette.CPage, 11, Fonts.Title,
                    TextAnchor.MiddleCenter, on ? Palette.CAccentText : Palette.CText2, "1 0", "1 0", $"{bx} 12",
                    $"{bx + bw} 40");
                x++;
            }
        }

        private void UI_PlayerDropdown(CuiElementContainer container, BasePlayer player)
        {
            var dd = PeekAdmin(player.userID)?.OpenDropdown;
            if (dd == null || !dd.StartsWith("players."))
                return;
            var parts = dd.Split('.');
            if (parts.Length < 3)
                return;
            var kind = parts[1];
            if (kind != "tp" && kind != "kick" && kind != "mute")
                return;
            ulong.TryParse(parts[2], out var sid);
            var t = GetDropdownEntry(sid);

            var ddW = 330;
            var tpCoords = kind == "tp" && GetSelect(player, FieldKey.DropdownMode, "tome") == "coords";
            var ddH = kind switch
            {
                "tp" => tpCoords ? 252 : 182,
                "kick" => 268,
                "mute" => 360,
                _ => 318
            };
            var x = Positions.BodyW - Positions.Pad - ddW;
            var p = Layers.Body + ".dd";
            container.Add(new CuiElement
            {
                Parent = Layers.Body, Name = p,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CSurface },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiNeedsCursorComponent(),
                    new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{x} {-56 - ddH}", OffsetMax = $"{x + ddW} -56" }
                }
            });

            var title = kind == "tp" ? GetLocalizedMessage(TranslateKey.DropdownTpTitle, player) :
                kind == "kick" ? GetLocalizedMessage(TranslateKey.DropdownKickTitle, player) :
                GetLocalizedMessage(TranslateKey.DropdownMuteTitle, player);
            UI_Text(container, p, title, 11, Fonts.Title, TextAnchor.UpperLeft, Palette.CText2, "0 1", "1 1", "14 -26",
                "-14 -12");
            UI_Avatar(container, p, t.SteamId, 14, -30, 24);
            UI_Text(container, p, t.DisplayName, 11, Fonts.Title, TextAnchor.UpperLeft, Palette.CText, "0 1", "1 1", "44 -43",
                "-14 -30");
            UI_Text(container, p, t.SteamId, 9, Fonts.Console, TextAnchor.UpperLeft, Palette.CText3, "0 1", "1 1", "44 -55",
                "-14 -43");
            container.Add(
                new CuiPanel
                {
                    Image = { Color = Palette.CBorderSoft },
                    RectTransform = { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = "14 -63", OffsetMax = "-14 -62" }
                }, p);

            if (kind == "tp")
            {
                UI_Text(container, p, GetLocalizedMessage(TranslateKey.DropdownMode, player), 10, Fonts.Body,
                    TextAnchor.UpperLeft, Palette.CText2, "0 1", "1 1", "14 -76", "-14 -62");
                string[] mk = { "tome", "toplayer", "coords", "look" };
                string[] ml =
                {
                    GetLocalizedMessage(TranslateKey.DropdownTome, player),
                    GetLocalizedMessage(TranslateKey.DropdownToplayer, player),
                    GetLocalizedMessage(TranslateKey.DropdownTocoords, player),
                    GetLocalizedMessage(TranslateKey.DropdownTolook, player)
                };
                UI_SegmentRow(container, p, player, FieldKey.DropdownMode, "tome", mk, ml, 14, -80, ddW - 28, 26, 8, 2, 4);
                if (tpCoords)
                {
                    var pos = player.transform.position;
                    UI_Text(container, p, GetLocalizedMessage(TranslateKey.DropdownCoords, player), 10, Fonts.Body,
                        TextAnchor.UpperLeft, Palette.CText2, "0 1", "1 1", "14 -156", "-14 -142");
                    var iw = (ddW - 28 - 12) / 3;
                    UI_Input(container, p, player, FieldKey.TeleportX, pos.x.ToString("0.0", Ci), 14, -160, iw, 26);
                    UI_Input(container, p, player, FieldKey.TeleportY, pos.y.ToString("0.0", Ci), 14 + iw + 6, -160, iw, 26);
                    UI_Input(container, p, player, FieldKey.TeleportZ, pos.z.ToString("0.0", Ci), 14 + 2 * (iw + 6), -160, iw,
                        26);
                }

                UI_DropdownFooter(container, p, player, dd, GetLocalizedMessage(TranslateKey.DropdownTpOk, player),
                    Palette.CAccent,
                    ddH);
                return;
            }

            if (kind == "mute")
            {
                UI_Text(container, p, GetLocalizedMessage(TranslateKey.DropdownDuration, player), 10, Fonts.Body,
                    TextAnchor.UpperLeft, Palette.CText2, "0 1", "1 1", "14 -78", "-14 -64");
                string[] mdk = { "1h", "1d", "7d", "30d", "perm" };
