        private void UI_SegmentRow(CuiElementContainer container, string parent, BasePlayer player, string group, string def,
            string[] values, string[] labels, int x, int y, int w, int h, int gap = 4, int cols = 0, int gapY = -1)
        {
            if (cols <= 0)
                cols = values.Length;
            if (gapY < 0)
                gapY = gap;
            var rows = (values.Length + cols - 1) / cols;
            var cell = (w - (cols - 1) * gap) / cols;
            var total = rows * h + (rows - 1) * gapY;
            var row = parent + ".seg." + group;
            container.Add(new CuiElement
            {
                Parent = parent, Name = row, DestroyUi = row,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{cell} {h}", Spacing = $"{gap} {gapY}",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = cols
                    },
                    new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{x} {y - total}", OffsetMax = $"{x + w} {y}" }
                }
            });
            for (var i = 0; i < values.Length; i++)
                UI_Segment(container, row, player, group, values[i], labels[i], def);
        }

        private void UI_Segment(CuiElementContainer container, string parent, BasePlayer player, string group, string val,
            string label, string def)
        {
            var on = GetSelect(player, group, def) == val;
            UI_Btn(container, parent, label, on ? "" : $"pa.select {group} {val}", on ? Palette.CAccent : Palette.CElev, 9,
                Fonts.Title, TextAnchor.MiddleCenter, on ? Palette.CAccentText : Palette.CText2, "0 0", "1 1");
        }

        private void UI_Segment(CuiElementContainer container, string parent, BasePlayer player, string group, string val,
