        private Oxide.Core.Plugins.Plugin FindPermOwner(string perm)
        {
            if (string.IsNullOrEmpty(perm))
                return null;
            if (_permOwnerCache.TryGetValue(perm, out var cached))
            {
                if (cached != null && plugins.Find(cached.Name) == cached)
                    return cached;
                _permOwnerCache.Remove(perm);
            }

            foreach (var pl in plugins.GetAll())
            {
                if (pl == null)
                    continue;
                try
                {
                    if (permission.PermissionExists(perm, pl))
                    {
                        _permOwnerCache[perm] = pl;
                        return pl;
                    }
                }
                catch (Exception ex)
                {
                    PrintWarning($"Looking up the owner of the permission {perm} failed: {ex.Message}");
                }
            }

            return null;
        }

        private string PermGroupKey(string perm)
        {
            var owner = FindPermOwner(perm);
            if (owner != null)
                return owner.Title ?? owner.Name;
            var i = perm.IndexOf('.');
            return i > 0 ? perm.Substring(0, i) : "other";
        }

        private List<PermEntry> PermEntries(string search)
        {
            var list = new List<PermEntry>();
            var perms = (permission.GetPermissions() ?? Array.Empty<string>())
                .Where(p => !string.IsNullOrEmpty(p) && (search.Length == 0 || p.ToLowerInvariant().Contains(search)));
            foreach (var grp in perms.GroupBy(PermGroupKey).OrderBy(g => g.Key, StringComparer.OrdinalIgnoreCase))
            {
                list.Add(new PermEntry(true, grp.Key + "\x01" + grp.Count()));
                foreach (var p in grp.OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
                    list.Add(new PermEntry(false, p));
            }

            return list;
        }

        private int PermContentHeight(List<PermEntry> entries) =>
            entries.Sum(e => e.Header ? Positions.Perm.HdrH : Positions.Perm.RowH) + 8;

        private void UI_PermList(CuiElementContainer container, string content, List<PermEntry> entries,
            Func<string, bool> isOn, string cmd, Func<string, string> inheritedFrom = null)
        {
            var index = 0;
            foreach (var e in entries)
            {
                if (e.Header)
                {
                    var parts = e.Text.Split('\x01');
                    var title = parts[0];
                    var count = parts.Length > 1 ? parts[1] : "";
                    var hn = content + ".hbar." + title;
                    var headerEl = new CuiElement
                    {
                        Parent = content, Name = hn,
                        Components = { new CuiImageComponent { Color = Palette.CElev2 }, new CuiRectTransformComponent { SetTransformIndex = index } }
                    };
                    var headerH = Positions.Perm.HdrH - 6;
