        private string CurrentPermGroup(BasePlayer player)
        {
            var groups = (permission.GetGroups() ?? Array.Empty<string>())
                .OrderBy(g => g, StringComparer.OrdinalIgnoreCase).ToList();
            if (groups.Count == 0)
                return "default";
            var cur = GetSelect(player, FieldKey.PermsGroup, groups[0]);
            return groups.Contains(cur) ? cur : groups[0];
        }

        private string GroupInheritedFrom(string group, string perm)
        {
            var g = permission.GetGroupParent(group);
            var guard = 0;
            while (!string.IsNullOrEmpty(g) && guard++ < 16)
            {
                if (permission.GroupHasPermission(g, perm))
                    return g;
                g = permission.GetGroupParent(g);
            }

            return null;
        }

        private string UserInheritedFrom(string userId, string perm)
        {
            foreach (var g in permission.GetUserGroups(userId) ?? Array.Empty<string>())
                if (permission.GroupHasPermission(g, perm))
                    return g;
            return null;
        }

