            };
            var cur = GetSelect(player, FieldKey.LogsFilter, "all");
            const int tabW = 84;
            for (var i = 0; i < fk.Length; i++)
            {
                var on = cur == fk[i];
                var off = -(fk.Length - i) * (tabW + 4) + 4;
                UI_Btn(container, Layers.Body, fl[i], on ? "" : $"pa.select {FieldKey.LogsFilter} {fk[i]}",
                    on ? Palette.CAccent : Palette.CElev, 10, Fonts.Title, TextAnchor.MiddleCenter,
                    on ? Palette.CAccentText : Palette.CText2, "1 1", "1 1", $"{off - Positions.Pad} -40",
                    $"{off - Positions.Pad + tabW} -14", Layers.Body + ".lf." + fk[i]);
            }

            var pw = Positions.BodyW - Positions.Pad * 2;
            var ph = Positions.BodyH - 84;
            var card = UI_Card(container, Layers.Body, GetLocalizedMessage(TranslateKey.LogsJournal, player), Positions.Pad,
                -60, pw, ph);

            var allEntries = ConsoleSnapshot(cur);
            allEntries.Reverse();
            var sh = PeekAdmin(player.userID)?.LogsShown ?? 0;
            var shown = sh > 0 ? sh : LogsPageSize;
            var hasMore = allEntries.Count > shown;
            var entries = hasMore ? allEntries.GetRange(0, shown) : allEntries;
            var svH = ph - 50;
            const int lineH = 15;
            var maxChars = MonoCharsPerLine(pw - 4 - 28, 11);
            var blocks = new List<List<string>>();
            var total = 8 + (hasMore ? 32 : 0);
            foreach (var e in entries)
            {
                var v = ConsoleWrapVisual(e, maxChars, true, true);
                blocks.Add(v);
                total += v.Count * lineH + 12;
            }

            var jumpBottom = PeekAdmin(player.userID)?.LogsJumpBottom == true;
            if (jumpBottom)
                GetAdmin(player.userID).LogsJumpBottom = false;
            var logsVpos = jumpBottom ? 0f : (float?)null;
            var content = UI_ScrollStack(container, card, "sv", 2, -44, pw - 4, svH, total, 2, 4, null, null, logsVpos);
            if (entries.Count == 0)
            {
                UI_Text(container, ScrollOf(content), GetLocalizedMessage(TranslateKey.ConsoleEmpty, player), 12, Fonts.Body,
                    TextAnchor.UpperLeft, Palette.CText3, "0 1", "1 1", "12 -34", "-12 -12");
                return;
            }

            for (var i = 0; i < blocks.Count; i++)
            {
                var v = blocks[i];
                var hh = v.Count * lineH + 10;
                var block = content + ".b" + i;
                var blockEl = new CuiElement
                {
                    Parent = content, Name = block,
                    Components = { new CuiImageComponent { Color = i % 2 == 1 ? Palette.CElev : Colors.Clear } }
                };
                blockEl.Components.Add(new CuiLayoutElementComponent { MinHeight = hh, PreferredHeight = hh });
                container.Add(blockEl);
                for (var k = 0; k < v.Count; k++)
                    UI_Text(container, block, v[k], 11, Fonts.Logs, TextAnchor.UpperLeft, Palette.CText, "0 1", "1 1",
                        $"12 {-5 - (k + 1) * lineH}", $"-12 {-5 - k * lineH}");
            }

            if (hasMore)
            {
                var more = content + ".more";
                var moreEl = new CuiElement { Parent = content, Name = more, Components = { new CuiImageComponent { Color = Colors.Clear } } };
                moreEl.Components.Add(new CuiLayoutElementComponent { MinHeight = 30, PreferredHeight = 30 });
                container.Add(moreEl);
                UI_Btn(container, more,
                    SafeFormat(GetLocalizedMessage(TranslateKey.LogsShowMore, player), allEntries.Count - shown),
                    "pa.logsmore", Palette.CElev, 11, Fonts.Title, TextAnchor.MiddleCenter, Palette.CAccent, "0 0",
                    "1 1", "12 0", "-12 0");
            }
        }


        private List<PluginRow> PluginRows()
        {
            var rows = new List<PluginRow>();
            var loaded = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var pl in plugins.GetAll())
            {
                if (pl == null)
                    continue;
                loaded.Add(pl.Name);
                rows.Add(new PluginRow
                {
                    Name = pl.Name, Title = string.IsNullOrEmpty(pl.Title) ? pl.Name : pl.Title,
                    Author = pl.Author ?? "", Version = pl.Version.ToString(), Loaded = true
                });
            }

            try
            {
                var dir = Interface.Oxide?.PluginDirectory;
                if (!string.IsNullOrEmpty(dir) && System.IO.Directory.Exists(dir))
                    foreach (var f in System.IO.Directory.GetFiles(dir, "*.cs"))
                    {
                        var nm = System.IO.Path.GetFileNameWithoutExtension(f);
                        if (!loaded.Contains(nm))
                            rows.Add(new PluginRow { Name = nm, Title = nm, Author = "", Version = "", Loaded = false });
                    }
            }
            catch (Exception ex)
            {
                PrintWarning($"Reading the plugin directory failed: {ex.Message}");
            }

            return rows.OrderByDescending(r => r.Loaded).ThenBy(r => r.Title, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

