        private bool IsSelfPlugin(string pluginName) =>
            string.Equals(pluginName, Name, StringComparison.OrdinalIgnoreCase);

        private string CfgFilePath(string pluginName) =>
            System.IO.Path.Combine(Interface.Oxide.ConfigDirectory, pluginName + ".json");

        private string LangFilePath(string pluginName, string langCode) =>
            System.IO.Path.Combine(Interface.Oxide.LangDirectory, langCode, pluginName + ".json");

        private List<string> LangCodesFor(string pluginName)
        {
            var list = new List<string>();
            try
            {
                var root = Interface.Oxide.LangDirectory;
                if (!string.IsNullOrEmpty(root) && System.IO.Directory.Exists(root))
                    foreach (var dir in System.IO.Directory.GetDirectories(root))
                        if (System.IO.File.Exists(System.IO.Path.Combine(dir, pluginName + ".json")))
                            list.Add(System.IO.Path.GetFileName(dir));
            }
            catch (Exception ex)
            {
                PrintWarning($"Reading the lang directories of {pluginName} failed: {ex.Message}");
            }

            list.Sort(StringComparer.OrdinalIgnoreCase);
            return list;
        }

        private static string CfgSegment(string name)
        {
            foreach (var ch in name)
                if (!char.IsLetterOrDigit(ch) && ch != '_')
                    return "['" + name.Replace("'", "\\'") + "']";
            return name;
        }

        private static string CfgGroupLabel(string name, JToken value)
        {
            if (name.Length == 0 || !name.All(char.IsDigit) || !int.TryParse(name, out var index))
                return name;
            var label = "#" + (index + 1);
            if (value is JObject obj)
                foreach (var key in CfgArrayTitleKeys)
                    if (obj.TryGetValue(key, out var found) && found.Type == JTokenType.String &&
                        found.ToString().Length > 0)
                        return label + " · " + found;
            return label;
        }

        private static void FlattenConfig(JToken node, string path, int depth, List<CfgRow> rows, int element = -1)
        {
            if (node is JObject obj)
            {
                foreach (var prop in obj.Properties())
                {
                    var seg = CfgSegment(prop.Name);
                    var child = path.Length == 0
                        ? seg
                        : seg.StartsWith("[")
                            ? path + seg
                            : path + "." + seg;
                    if (prop.Value is JObject)
                    {
                        rows.Add(new CfgRow
                        {
                            Path = child, Label = element < 0 ? CfgGroupLabel(prop.Name, prop.Value) : prop.Name,
                            Kind = JTokenType.Object, Depth = depth, Element = element
                        });
                        FlattenConfig(prop.Value, child, depth + 1, rows, element);
                        continue;
                    }

                    rows.Add(new CfgRow
                    {
                        Path = child, Label = prop.Name, Kind = prop.Value.Type,
                        Value = CfgTokenText(prop.Value), Depth = depth, Element = element
                    });
                }

                return;
            }

            if (element < 0)
                return;

            rows.Add(new CfgRow
            {
                Path = "", Label = "value", Kind = node?.Type ?? JTokenType.String,
                Value = node == null ? "" : CfgTokenText(node), Depth = depth, Element = element
            });
        }

        private static string CfgTokenText(JToken token) => token.Type == JTokenType.Array
            ? token.ToString(Newtonsoft.Json.Formatting.None)
            : token.ToString();

        private bool ApplyCfgValue(JObject root, string path, JTokenType kind, string raw)
        {
            var token = root.SelectToken(path);
            if (token == null)
                return false;
            var value = CfgValueToken(kind, raw, token);
            if (ReferenceEquals(value, token))
                return false;
            token.Replace(value);
            return true;
        }

        private void OpenCfgEditor(BasePlayer player, string pluginName, bool isLang)
        {
            if (IsSelfPlugin(pluginName))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.CfgSelf, player), NotifyKind.Error);
                return;
            }

            string lang = null;
            string path;
            if (isLang)
            {
                var codes = LangCodesFor(pluginName);
                lang = codes.Contains("en") ? "en" : codes.FirstOrDefault();
                if (lang == null)
                {
                    Notify(player, GetLocalizedMessage(TranslateKey.CfgNoLang, player), NotifyKind.Error);
                    return;
                }

                path = LangFilePath(pluginName, lang);
            }
            else
                path = CfgFilePath(pluginName);

            LoadCfgRows(player, pluginName, isLang, lang, path);
        }

        private void LoadCfgRows(BasePlayer player, string pluginName, bool isLang, string lang, string path)
        {
            JObject root;
            try
            {
                root = JObject.Parse(System.IO.File.ReadAllText(path));
            }
            catch (Exception ex)
            {
                PrintError($"Parsing {path} failed: {ex.Message}");
                Notify(player, GetLocalizedMessage(TranslateKey.CfgParseError, player), NotifyKind.Error);
                return;
            }

            var rows = new List<CfgRow>();
            FlattenConfig(root, "", 0, rows);
            var admin = GetAdmin(player.userID);
            admin.CfgEditPlugin = pluginName;
            admin.CfgEditIsLang = isLang;
            admin.CfgEditLang = lang;
            admin.CfgEditRows = rows;
            CloseCfgArray(admin);
            admin.CfgLangDelete = false;
            admin.CfgFieldKey = null;
            admin.CfgFieldValue = null;
            RefreshCfgEditor(player);
        }

        private void SaveCfgEditor(BasePlayer player)
        {
            var admin = GetAdmin(player.userID);
            var pluginName = admin.CfgEditPlugin;
            var rows = admin.CfgEditRows;
            if (pluginName == null || rows == null)
                return;
            var path = admin.CfgEditIsLang ? LangFilePath(pluginName, admin.CfgEditLang) : CfgFilePath(pluginName);
            JObject root;
            try
            {
                root = JObject.Parse(System.IO.File.ReadAllText(path));
            }
            catch (Exception ex)
            {
                PrintError($"Parsing {path} failed: {ex.Message}");
                Notify(player, GetLocalizedMessage(TranslateKey.CfgParseError, player), NotifyKind.Error);
                return;
            }

            foreach (var row in rows)
            {
                if (row.Kind == JTokenType.Object)
                    continue;
                if (!ApplyCfgValue(root, row.Path, row.Kind, row.Value ?? ""))
                {
                    Notify(player, SafeFormat(GetLocalizedMessage(TranslateKey.CfgBadValue, player), row.Label),
                        NotifyKind.Error);
                    return;
                }
            }

            try
            {
                System.IO.File.WriteAllText(path, root.ToString(Newtonsoft.Json.Formatting.Indented));
            }
            catch (Exception ex)
            {
                PrintError($"Writing {path} failed: {ex.Message}");
                Notify(player, GetLocalizedMessage(TranslateKey.CfgWriteError, player), NotifyKind.Error);
                return;
            }

            AddLog(LogCategory.Cmd,
                $"{player.displayName}: edited {(admin.CfgEditIsLang ? "lang" : "config")} of {pluginName}");
            Notify(player, GetLocalizedMessage(TranslateKey.CfgSaved, player));
            if (admin.CfgReloadAfterSave)
                RunFrameworkPlugin("reload", pluginName);
            LoadCfgRows(player, pluginName, admin.CfgEditIsLang, admin.CfgEditLang, path);
        }

        private void CloseCfgEditor(BasePlayer player)
        {
            var admin = GetAdmin(player.userID);
            admin.CfgEditPlugin = null;
            admin.CfgEditRows = null;
            admin.CfgEditLang = null;
            CloseCfgArray(admin);
            admin.CfgLangDelete = false;
            RefreshCfgEditor(player);
        }

        private static void CloseCfgArray(AdminData admin)
        {
            admin.CfgArrRow = -1;
            admin.CfgArrData = null;
            admin.CfgArrOpen = null;
            admin.CfgArrDelete = -1;
        }

        private void RefreshCfgEditor(BasePlayer player)
        {
            if (player == null || PeekAdmin(player.userID)?.UiOpen != true)
                return;
            var container = new CuiElementContainer();
            UI_CfgEditor(container, player);
            CuiHelper.AddUi(player, container);
        }

        private static List<CfgBlock> CfgBlocks(List<CfgRow> rows)
        {
            var blocks = new List<CfgBlock>();
            CfgBlock current = null;
            for (var i = 0; i < rows.Count; i++)
            {
                if (rows[i].Kind == JTokenType.Object)
                {
                    current = new CfgBlock { Title = rows[i].Label };
                    blocks.Add(current);
                    continue;
                }

                if (current == null)
                {
                    current = new CfgBlock();
                    blocks.Add(current);
                }

                current.Rows.Add(i);
            }

            foreach (var block in blocks)
            {
                var height = block.Title == null ? 12 : 30;
                foreach (var index in block.Rows)
                    height += 26;
                block.Height = height + 10;
            }

            return blocks;
        }

