        private static string CfgArrayPreview(string value)
        {
            var text = value ?? "";
            return text.Length > 90 ? text.Substring(0, 87) + "..." : text;
        }

        private static string CfgArrayCaption(JToken element, int index)
        {
            var head = "#" + (index + 1);
            if (element is JObject obj)
            {
                foreach (var key in CfgArrayTitleKeys)
                    if (obj.TryGetValue(key, out var found) && found.Type == JTokenType.String &&
                        found.ToString().Length > 0)
                        return head + "  " + found;
                return head + "  " + string.Format("{{{0}}}", obj.Count);
            }

            var raw = element == null ? "" : element.ToString(Newtonsoft.Json.Formatting.None);
            return head + "  " + (raw.Length > 64 ? raw.Substring(0, 61) + "..." : raw);
        }

        private static List<CfgRow> CfgArrayLeaves(AdminData admin)
        {
            var leaves = new List<CfgRow>();
            var data = admin?.CfgArrData;
            if (data == null)
                return leaves;
            for (var i = 0; i < data.Count; i++)
                if (admin.CfgArrOpen != null && admin.CfgArrOpen.Contains(i))
                    FlattenConfig(data[i], "", 0, leaves, i);
            return leaves;
        }

        private static JToken CfgValueToken(JTokenType kind, string raw, JToken fallback)
        {
            if (kind == JTokenType.Boolean)
                return new JValue(raw == "1" || string.Equals(raw, "true", StringComparison.OrdinalIgnoreCase));
            if (kind == JTokenType.Integer)
                return long.TryParse(raw, out var whole) ? new JValue(whole) : fallback;
            if (kind == JTokenType.Float)
                return double.TryParse(raw, out var real) ? new JValue(real) : fallback;
            if (kind != JTokenType.Array)
                return new JValue(raw);
            try
            {
                return JArray.Parse(raw);
            }
            catch (Exception ex)
            {
                Instance?.PrintWarning($"Parsing the config array value failed: {ex.Message}");
                return fallback;
            }
        }

        private static void ApplyCfgArrayValue(AdminData admin, CfgRow leaf, string raw)
        {
            var data = admin.CfgArrData;
            if (data == null || leaf.Element < 0 || leaf.Element >= data.Count)
                return;
            var element = data[leaf.Element];
            if (leaf.Path.Length == 0)
            {
                data[leaf.Element] = CfgValueToken(leaf.Kind, raw, element);
                return;
            }

            var token = element.SelectToken(leaf.Path);
            if (token != null)
                token.Replace(CfgValueToken(leaf.Kind, raw, token));
        }

        private static JToken CfgArrayBlank(JToken source)
        {
            if (source is JObject obj)
            {
                var blank = new JObject();
                foreach (var prop in obj.Properties())
                    blank[prop.Name] = CfgArrayBlank(prop.Value);
                return blank;
            }

            if (source.Type == JTokenType.Array)
                return new JArray();
            if (source.Type == JTokenType.Boolean)
                return new JValue(false);
            if (source.Type == JTokenType.Integer)
                return new JValue(0L);
            if (source.Type == JTokenType.Float)
                return new JValue(0d);
            return new JValue("");
        }

        private static int CfgArrayBlockHeight(AdminData admin, int index, List<CfgRow> leaves)
        {
            if (admin.CfgArrOpen == null || !admin.CfgArrOpen.Contains(index))
                return 28;
            var count = 0;
            foreach (var leaf in leaves)
                if (leaf.Element == index)
                    count++;
            return 34 + count * 24;
        }

