                UI_Text(container, card, p.Title.Length > 0 ? p.Title.Substring(0, 1).ToUpperInvariant() : "?", 16,
                    Fonts.Title, TextAnchor.MiddleCenter, p.Loaded ? Palette.CAccent : Palette.CText3, "0 1",
                    "0 1", "12 -48", "48 -12");
                UI_Text(container, card, p.Title, 12, Fonts.Title, TextAnchor.MiddleLeft, Palette.CText, "0 1", "1 1",
                    "58 -30", "-200 -10");
