        private List<string> ConvarCats(List<ConsoleSystem.Command> all)
        {
            var cats = new List<string> { "all" };
            cats.AddRange(all.Select(v => v.Parent).Where(s => !string.IsNullOrEmpty(s)).Distinct()
                .OrderBy(s => s, StringComparer.OrdinalIgnoreCase));
            return cats;
        }

        private void UI_ConvarCats(CuiElementContainer container, BasePlayer player, List<string> cats, string curCat)
        {
            for (var i = 0; i < cats.Count; i++)
            {
                var sel = cats[i] == curCat;
                var label = cats[i] == "all" ? GetLocalizedMessage(TranslateKey.ConvarsAll, player) : cats[i];
                UI_Btn(container, ConvarCatList, "  " + label, $"pa.cvcat {cats[i]}",
                    sel ? Palette.CAccentSoft : Palette.CElev, 10, Fonts.Title, TextAnchor.MiddleLeft,
                    sel ? Palette.CAccent : Palette.CText2, "0 0", "1 1", name: ConvarCatList + "." + i);
            }
        }

        private void UI_ConvarList(CuiElementContainer container, BasePlayer player, List<ConsoleSystem.Command> all,
            string curCat, string search)
        {
            var pw = Positions.BodyW - Positions.Pad * 2;
            var ph = Positions.BodyH - 84;
            var listX = Positions.Pad + 180;
            var listW = pw - 180;
            var items = all.Where(v => (curCat == "all" || v.Parent == curCat) &&
                                       (search.Length == 0 || v.FullName.ToLowerInvariant().Contains(search))).ToList();

            var pages = Math.Max(1, Mathf.CeilToInt(items.Count / (float)ConvarsPerPage));
            var page = Mathf.Clamp(int.TryParse(GetSelect(player, FieldKey.ConvarPage, "1"), out var pp) ? pp : 1, 1,
                pages);
            var listAreaH = ph - 32 - 44;
            container.Add(new CuiElement
            {
                Parent = Layers.Body, Name = ConvarListPanel, DestroyUi = ConvarListPanel,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CPage },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{listW - 8} 40", Spacing = "2 2", Padding = "4 4 2 2",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft, Constraint = GridLayoutGroup.Constraint.FixedColumnCount,
                        ConstraintCount = 1
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{listX} {-92 - listAreaH}",
                        OffsetMax = $"{listX + listW} -92"
                    }
                }
            });
            for (var k = 0; k < ConvarsPerPage; k++)
            {
                var gi = (page - 1) * ConvarsPerPage + k;
                if (gi >= items.Count)
                    break;
                UI_ConvarRow(container, player, items[gi], k);
            }

            container.Add(new CuiElement
            {
                Parent = Layers.Body, Name = ConvarFooter, DestroyUi = ConvarFooter,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 0", AnchorMax = "1 0", OffsetMin = "0 0", OffsetMax = "0 48"
                    }
                }
            });
            UI_Text(container, ConvarFooter, $"{items.Count} · {page}/{pages}", 10, Fonts.Body, TextAnchor.LowerLeft,
                Palette.CText3, "0 0", "0 0", $"{listX} 12", $"{listX + 160} 36");
            if (pages > 1)
                UI_Pagination(container, ConvarFooter, player, FieldKey.ConvarPage, pages);
        }

