                "-196 -2");
            var desc = (v.Description ?? "").Trim();
            if (desc.Length > 0)
                UI_Text(container, rn, desc.Length > 150 ? desc.Substring(0, 150) + "..." : desc, 8, Fonts.Body,
                    TextAnchor.UpperLeft, Palette.CText3, "0 1", "1 1", "10 -39", "-196 -16");

            if (IsBoolConvar(v))
            {
                bool.TryParse(v.String, out var on);
                var tr = rn + ".sw";
                container.Add(new CuiElement
                {
                    Parent = rn, Name = tr,
                    Components =
                    {
                        new CuiImageComponent { Color = on ? Palette.CAccent : Palette.CElev },
                        new CuiOutlineComponent { Color = on ? Palette.CAccent : Palette.CBorder, Distance = "1 1" },
