        private void RefreshConvarRow(BasePlayer player, string full)
        {
            if (GetPage(player) != "convars")
                return;
            var all = ConVarList();
            var curCat = GetSelect(player, FieldKey.ConvarCat, "all");
            var search = GetInput(player, FieldKey.ConvarSearch, "").Trim().ToLowerInvariant();
            var items = all.Where(v => (curCat == "all" || v.Parent == curCat) &&
                                       (search.Length == 0 || v.FullName.ToLowerInvariant().Contains(search))).ToList();
            var gi = items.FindIndex(v => v.FullName == full);
            if (gi < 0)
                return;
            var pages = Math.Max(1, Mathf.CeilToInt(items.Count / (float)ConvarsPerPage));
            var page = Mathf.Clamp(int.TryParse(GetSelect(player, FieldKey.ConvarPage, "1"), out var pp) ? pp : 1, 1,
                pages);
            var k = gi - (page - 1) * ConvarsPerPage;
            if (k < 0 || k >= ConvarsPerPage)
                return;
            ApplyTheme(player);
            var container = new CuiElementContainer();
            if (!IsBoolConvar(items[gi]))
            {
                UI_ConvarRow(container, player, items[gi], k);
                CuiHelper.AddUi(player, container);
                return;
            }

            bool.TryParse(items[gi].String, out var on);
            var tr = ConvarRowName(full) + ".sw";
            container.Add(new CuiElement
            {
                Name = tr, Update = true,
                Components =
                {
                    new CuiImageComponent { Color = on ? Palette.CAccent : Palette.CElev },
                    new CuiOutlineComponent { Color = on ? Palette.CAccent : Palette.CBorder, Distance = "1 1" }
                }
            });
            container.Add(new CuiElement
            {
                Name = tr + ".k", Update = true,
                Components =
                {
                    new CuiImageComponent { Color = on ? Palette.CAccentText : Palette.CText2 },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = on ? "1 0" : "0 0", AnchorMax = on ? "1 0" : "0 0",
                        OffsetMin = on ? "-18 2" : "2 2", OffsetMax = on ? "-2 18" : "18 18"
                    }
                }
            });
            CuiHelper.AddUi(player, container);
        }

        private List<string> PluginCommands(Oxide.Core.Plugins.Plugin pl)
        {
            var result = new List<string>();
            if (pl == null)
                return result;
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            MethodInfo[] methods;
            try
            {
                methods = pl.GetType().GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic |
                                                  BindingFlags.DeclaredOnly);
            }
            catch (Exception ex)
            {
                PrintWarning($"Reading the commands of {pl.Name} failed: {ex.Message}");
                return result;
            }

            foreach (var m in methods)
            foreach (var attr in m.GetCustomAttributes(false))
            {
                var an = attr.GetType().Name;
                if (an != "ConsoleCommandAttribute" && an != "ChatCommandAttribute" && an != "CommandAttribute")
                    continue;
                var chat = an == "ChatCommandAttribute";
                foreach (var nm in AttrCommandNames(attr))
                {
                    if (string.IsNullOrEmpty(nm))
                        continue;
                    var label = chat ? "/" + nm : nm;
                    if (seen.Add(label))
                        result.Add(label);
                }
            }

            result.Sort(StringComparer.OrdinalIgnoreCase);
            return result;
        }

        private static List<string> AttrCommandNames(object attr)
        {
            var names = new List<string>();
            var t = attr.GetType();
            foreach (var single in new[] { "Name", "Command" })
            {
                var v = (t.GetProperty(single)?.GetValue(attr) ?? t.GetField(single)?.GetValue(attr)) as string;
                if (!string.IsNullOrEmpty(v))
                    names.Add(v);
            }

            foreach (var multi in new[] { "Names", "Commands" })
                if ((t.GetProperty(multi)?.GetValue(attr) ?? t.GetField(multi)?.GetValue(attr)) is string[] arr)
                    foreach (var s in arr)
                        if (!string.IsNullOrEmpty(s))
                            names.Add(s);

            return names;
        }

        private void UI_PluginCommandsPopup(BasePlayer player, string pluginName)
        {
            ApplyTheme(player);
            var pl = plugins.Find(pluginName);
            var cmds = PluginCommands(pl);
            var container = new CuiElementContainer();
