                }
            });
            UI_Btn(container, root, "pa.plcmds close", Colors.Clear, "0 0", "1 1");

            const int cw = 460, ch = 440;
            var card = root + ".card";
            container.Add(new CuiElement
            {
                Parent = root, Name = card,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CSurface },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = $"{-cw / 2} {-ch / 2}",
                        OffsetMax = $"{cw / 2} {ch / 2}"
                    }
                }
            });
            container.Add(
                new CuiPanel
                {
                    Image = { Color = Palette.CElev },
                    RectTransform = { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = "0 -44", OffsetMax = "0 0" }
                }, card);
            var title = (string.IsNullOrEmpty(pl?.Title) ? pluginName : pl.Title) +
                        $"  ·  {GetLocalizedMessage(TranslateKey.ButtonCommands, player)} ({cmds.Count})";
            UI_Text(container, card, title, 13, Fonts.Title, TextAnchor.MiddleLeft, Palette.CText, "0 1", "1 1", "14 -44",
