            UI_CloseX(container, card, "pa.plcmds close", "1 1", "1 1", "-38 -38", "-10 -10", card + ".x", 6);

            var listH = ch - 56;
            if (cmds.Count == 0)
                UI_Text(container, card, GetLocalizedMessage(TranslateKey.PluginsNoCommands, player), 11, Fonts.Body,
                    TextAnchor.MiddleCenter, Palette.CText3, "0 0", "1 1", "8 8", "-8 -50");
            else
            {
