                var content = UI_ScrollList(container, card, "cmds", 8, -50, cw - 16, listH, rowH, 0, cmds.Count, 6, 1,
                    Palette.CPage, Palette.CBorder);
                for (var i = 0; i < cmds.Count; i++)
                    UI_Text(container, content, cmds[i], 11, Fonts.Console, TextAnchor.MiddleLeft, Palette.CText, "0 1", "1 1",
                        $"10 {-6 - (i + 1) * rowH}", $"-10 {-6 - i * rowH}");
            }

            CuiHelper.AddUi(player, container);
        }

