        private static Vector2 WorldToNorm(Vector3 pos)
        {
            var span = MapTool.MapSpan();
            return new Vector2(Mathf.Clamp01((pos.x + span * 0.5f) / span),
                Mathf.Clamp01((pos.z + span * 0.5f) / span));
        }

        private static Vector2 DeepToNorm(Vector3 pos) =>
            new(Mathf.Clamp01(DeepSeaManager.NormalizeX(pos.x)), Mathf.Clamp01(DeepSeaManager.NormalizeZ(pos.z)));

        private static int MapCanvasSize(int zoom) => Positions.Map.FrameSize * Mathf.Max(1, zoom);

