        private static Vector2 NormToCanvas(Vector2 norm, int zoom)
        {
            var size = MapCanvasSize(zoom);
            return new Vector2(norm.x * size, norm.y * size);
        }

        private static string TeamColor(ulong teamId)
        {
            if (teamId == 0)
                return "0.60 0.72 0.86 1";
            var h = 2166136261u;
            var raw = teamId.ToString();
            foreach (var ch in raw)
                h = (h ^ ch) * 16777619u;
            return ColorToRustFormat(Color.HSVToRGB(h % 360u / 360f, 0.62f, 0.95f));
        }

