        private static MapMarkerKind MarkerKindOf(MapMarker marker)
        {
            var kind = marker switch
            {
                UIDeepSeaIslandMapMarker => MapMarkerKind.Island,
                DeepSeaFloatingCityMapMarker => MapMarkerKind.City,
                GhostShipMapMarker => MapMarkerKind.GhostShip,
                VendingMachineMapMarker => MapMarkerKind.Vending,
                MapMarkerCH47 => MapMarkerKind.Chinook,
                MapMarkerExplosion => MapMarkerKind.Event,
                MapMarkerMLRSRocket => MapMarkerKind.Rocket,
                MapMarkerDeliveryDrone => MapMarkerKind.Air,
                MapMarkerHelicopterFlee => MapMarkerKind.Heli,
                MapMarkerMissionProvider => MapMarkerKind.Other,
                MapMarkerPet => MapMarkerKind.Other,
                TutorialIsland_MapMarker => MapMarkerKind.Other,
                StaticMapMarker => MapMarkerKind.Other,
                _ => MapMarkerKind.Other
            };
            if (kind != MapMarkerKind.Other)
                return kind;
            return marker.GetParentEntity() switch
            {
                CargoShip => MapMarkerKind.Cargo,
                CH47Helicopter => MapMarkerKind.Chinook,
                PatrolHelicopter => MapMarkerKind.Heli,
                CargoPlane => MapMarkerKind.Plane,
                BaseSubmarine => MapMarkerKind.Submarine,
                RHIB => MapMarkerKind.Rhib,
                HackableLockedCrate => MapMarkerKind.Crate,
                _ => MapMarkerKind.Vehicle
            };
        }

