        private List<string[]> MapActionsFor(BasePlayer admin)
        {
            var result = new List<string[]>();
            if (cfg?.MapActions == null || !Can(admin, Permissions.Players))
                return result;
            foreach (var def in MapActionDefs)
            {
                if (!cfg.MapActions.Contains(def[0]))
                    continue;
                if (!CanAction(admin, def[0]))
                    continue;
                result.Add(def);
            }

            return result;
        }

        private bool MapActionEnabled(string id, ulong sid, BasePlayer admin)
        {
            if (sid == admin.userID && (id == "inv" || id == "spectate"))
                return false;
            var online = FindOnline(sid) != null;
            if (!online && (id == "kick" || id == "spectate" || id == "inv" || id == "give" || id == "bp" ||
                            id == "mod" || id == "vitals" || id == "notes"))
                return false;
            var body = FindActiveOrSleeping(sid);
            var alive = body != null && !body.IsDead();
            if (!alive && (id == "heal" || id == "kill" || id == "strip" || id == "tp" || id == "give" ||
                           id == "inv" || id == "showmap"))
                return false;
            return true;
        }

