        private string QuickPlacesLabel(BasePlayer player, QuickPlace places)
        {
            var flags = new[] { QuickPlace.Popup, QuickPlace.Map, QuickPlace.Widget, QuickPlace.Dashboard };
            string[] keys = { TranslateKey.QbPlacePopup, TranslateKey.QbPlaceMap, TranslateKey.QbPlaceWidget, TranslateKey.QbPlaceDashboard };
            var parts = new List<string>();
            for (var i = 0; i < flags.Length; i++)
                if ((places & flags[i]) != 0)
                    parts.Add(GetLocalizedMessage(keys[i], player));
            if (parts.Count == 0)
                return GetLocalizedMessage(TranslateKey.QbPlaceNone, player);
            return string.Join(", ", parts);
        }


