        private static int HammerSectionRowsH(HammerTool.Section section)
        {
            var items = 0;
            foreach (var row in section.Rows)
                if (row.ItemId != 0)
                    items++;
            return (section.Rows.Count - items) * Positions.Hammer.RowH + (items + 1) / 2 * Positions.Hammer.ItemRowH;
        }

        private void UI_HammerHud(BasePlayer admin, HammerTool.Info info)
        {
            var ad = GetAdmin(admin.userID);
            var bodyH = 0;
            foreach (var section in info.Sections)
                bodyH += HammerSectionH(section);
            if (info.HasLock)
                bodyH += Positions.Hammer.LockH;
            var chipCount = info.Modes.Length;
            var armed = ad.HammerArmed <= chipCount ? ad.HammerArmed : 0;
            var height = Positions.Hammer.HeadH + bodyH + Positions.Hammer.FootH;
            var accent = armed == 0 ? Palette.CAccent : HammerModeColor(info.Modes[armed - 1]);

            CuiHelper.DestroyUi(admin, Layers.HammerNotice);
            var container = new CuiElementContainer();
            var root = UI_HammerShell(container, admin, height);
            container.Add(
                new CuiPanel
                {
                    Image = { Color = accent },
                    RectTransform = { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = "0 -2", OffsetMax = "0 0" }
                }, root);
            UI_Text(container, root, info.Title, 16, Fonts.Hud, TextAnchor.MiddleLeft, Palette.CText, "0 1", "1 1", "14 -30",
                "-90 -10");
            UI_Text(container, root, info.Kind, 9, Fonts.Console, TextAnchor.MiddleLeft, Palette.CText3, "0 1", "1 1",
                "14 -44", "-90 -30");
            if (armed != 0)
                UI_Text(container, root, HammerModeName(admin, info.Modes[armed - 1]), 9, Fonts.Title, TextAnchor.MiddleRight,
                    accent, "1 1", "1 1", "-84 -28", "-14 -12");
            container.Add(
                new CuiPanel
                {
                    Image = { Color = Palette.CBorderSoft },
                    RectTransform = { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = $"14 {-Positions.Hammer.HeadH + 2 - 1}", OffsetMax = $"-14 {-Positions.Hammer.HeadH + 2}" }
                }, root);

            var stack = root + ".body";
            var stackX = Positions.Hammer.Pad;
            var stackY = -Positions.Hammer.HeadH - 8;
            container.Add(new CuiElement
            {
                Parent = root, Name = stack, DestroyUi = stack,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiVerticalLayoutGroupComponent
                    {
                        Spacing = 0, ChildAlignment = TextAnchor.UpperLeft, ChildControlWidth = true,
                        ChildControlHeight = true, ChildForceExpandWidth = true, ChildForceExpandHeight = false
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{stackX} {stackY - bodyH}",
                        OffsetMax = $"{Positions.Hammer.HudW - Positions.Hammer.Pad} {stackY}"
                    }
                }
            });
            for (var i = 0; i < info.Sections.Count; i++)
                UI_HammerSection(container, stack, info.Sections[i], i);
            if (info.HasLock)
                UI_HammerLock(container, stack, admin, ad, info);

            container.Add(
                new CuiPanel
                {
                    Image = { Color = Palette.CBorderSoft },
                    RectTransform = { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = $"14 {-Positions.Hammer.HeadH - 8 - bodyH - 1}", OffsetMax = $"-14 {-Positions.Hammer.HeadH - 8 - bodyH}" }
                }, root);
            var modeBar = root + ".mode";
            container.Add(new CuiElement
            {
                Parent = root, Name = modeBar,
                Components =
                {
                    new CuiImageComponent { Color = armed == 0 ? Palette.CPage : accent },
                    new CuiOutlineComponent
                    {
                        Color = armed == 0 ? Palette.CBorderSoft : accent, Distance = "1 1"
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 0", AnchorMax = "1 0", OffsetMin = $"{Positions.Hammer.Pad} 40",
                        OffsetMax = $"{-Positions.Hammer.Pad} {40 + Positions.Hammer.ChipH}"
                    }
                }
            });
            if (armed != 0)
            {
                container.Add(new CuiElement
                {
                    Parent = modeBar,
                    Components =
                    {
                        new CuiImageComponent { Color = Palette.CPage, Sprite = HammerModeIcon(info.Modes[armed - 1]) },
                        new CuiRectTransformComponent
                        {
                            AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = "7 -6", OffsetMax = "19 6"
                        }
                    }
                });
                UI_Text(container, modeBar, HammerModeName(admin, info.Modes[armed - 1]), 10, Fonts.Title,
                    TextAnchor.MiddleLeft, Palette.CPage, "0 0", "1 1", "25 0", "-8 0");
            }
            else
                UI_Text(container, modeBar, GetLocalizedMessage(TranslateKey.HammerPieHint, admin), 9, Fonts.Body,
                    TextAnchor.MiddleLeft, Palette.CText2, "0 0", "1 1", "8 0", "-8 0");

            var hintBox = root + ".hint";
            container.Add(new CuiElement
            {
                Parent = root, Name = hintBox,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CPage },
                    new CuiOutlineComponent { Color = Palette.CBorderSoft, Distance = "1 1" },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 0", AnchorMax = "1 0", OffsetMin = $"{Positions.Hammer.Pad} 14",
                        OffsetMax = $"{-Positions.Hammer.Pad} 34"
                    }
                }
            });
            UI_Text(container, hintBox,
                armed == 0 ? GetLocalizedMessage(TranslateKey.HammerNotArmed, admin) : HammerModeHint(admin, info.Modes[armed - 1]),
                9, Fonts.Body, TextAnchor.MiddleLeft, armed == 0 ? Palette.CText2 : accent, "0 0", "1 1", "7 0",
                "-7 0");
            UI_Text(container, root, GetLocalizedMessage(TranslateKey.HammerBinds, admin), 9, Fonts.Console,
                TextAnchor.MiddleLeft, Palette.CText3, "0 0", "1 0", $"{Positions.Hammer.Pad} 0",
                $"{-Positions.Hammer.Pad} 14");

            CuiHelper.AddUi(admin, container);
        }

        private void UI_HammerSection(CuiElementContainer container, string stack, HammerTool.Section section, int index)
        {
            var head = new CuiElement { Parent = stack, Name = stack + ".h" + index, Components = { new CuiImageComponent { Color = Colors.Clear } } };
            head.Components.Add(new CuiLayoutElementComponent { MinHeight = Positions.Hammer.RowH, PreferredHeight = Positions.Hammer.RowH });
            container.Add(head);
            UI_Text(container, head.Name, section.Title, 9, Fonts.Title, TextAnchor.MiddleLeft, Palette.CText3, "0 0", "1 1");
            if (section.Total > section.Rows.Count)
                UI_Text(container, head.Name, $"{section.Rows.Count} / {section.Total}", 9, Fonts.Console,
                    TextAnchor.MiddleRight, Palette.CText3, "0 0", "1 1");

            var items = 0;
            foreach (var row in section.Rows)
                if (row.ItemId != 0)
                    items++;
            if (items > 0)
                UI_HammerItems(container, stack, section, index, items);
            else
                for (var i = 0; i < section.Rows.Count; i++)
                    UI_HammerRow(container, stack, section.Rows[i], index, i);

            var gap = new CuiElement { Parent = stack, Name = stack + ".g" + index, Components = { new CuiImageComponent { Color = Colors.Clear } } };
            gap.Components.Add(new CuiLayoutElementComponent { MinHeight = Positions.Hammer.SectionGap, PreferredHeight = Positions.Hammer.SectionGap });
            container.Add(gap);
        }

        private void UI_HammerRow(CuiElementContainer container, string stack, HammerTool.Row row, int section, int index)
        {
            var el = new CuiElement { Parent = stack, Name = stack + $".r{section}_{index}", Components = { new CuiImageComponent { Color = Colors.Clear } } };
            el.Components.Add(new CuiLayoutElementComponent { MinHeight = Positions.Hammer.RowH, PreferredHeight = Positions.Hammer.RowH });
            container.Add(el);
            var titled = !string.IsNullOrEmpty(row.Label);
            if (titled)
                UI_Text(container, el.Name, row.Label, 9, Fonts.Title, TextAnchor.MiddleLeft, Palette.CText3, "0 0", "0.45 1");
            UI_Text(container, el.Name, row.Value, 10, Fonts.Console, titled ? TextAnchor.MiddleRight : TextAnchor.MiddleLeft,
                string.IsNullOrEmpty(row.Color) ? Palette.CText : row.Color, titled ? "0.45 0" : "0 0", "1 1");
        }

        private void UI_HammerItems(CuiElementContainer container, string stack, HammerTool.Section section, int index,
            int items)
        {
            var rows = (items + 1) / 2;
            var cellW = (Positions.Hammer.HudW - Positions.Hammer.Pad * 2 - Positions.Hammer.ChipGap) / 2;
            var grid = stack + ".i" + index;
            var gridEl = new CuiElement
            {
                Parent = stack, Name = grid,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{cellW} {Positions.Hammer.ItemRowH - 2}", Spacing = $"{Positions.Hammer.ChipGap} 2",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = 2
                    }
                }
            };
            var gridH = rows * Positions.Hammer.ItemRowH;
            gridEl.Components.Add(new CuiLayoutElementComponent { MinHeight = gridH, PreferredHeight = gridH });
            container.Add(gridEl);
            for (var i = 0; i < section.Rows.Count; i++)
            {
                var row = section.Rows[i];
                if (row.ItemId == 0)
                    continue;
                var cell = grid + ".c" + i;
                container.Add(new CuiElement
                {
                    Parent = grid, Name = cell,
                    Components = { new CuiImageComponent { Color = Palette.CPage }, new CuiOutlineComponent { Color = Palette.CBorderSoft, Distance = "1 1" } }
                });
                container.Add(new CuiElement
                {
                    Parent = cell,
                    Components =
                    {
                        new CuiImageComponent { ItemId = row.ItemId },
                        new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "0 1", OffsetMin = "3 2", OffsetMax = "19 -2" }
                    }
                });
                UI_Text(container, cell, row.Value, 10, Fonts.Body, TextAnchor.MiddleLeft, Palette.CText, "0 0", "1 1", "23 0",
                    "-4 0");
            }
        }

        private void UI_HammerLock(CuiElementContainer container, string stack, BasePlayer admin, AdminData ad,
            HammerTool.Info info)
        {
            var lockBox = stack + ".lock";
            var lockEl = new CuiElement
            {
                Parent = stack, Name = lockBox,
                Components = { new CuiImageComponent { Color = Palette.CPage }, new CuiOutlineComponent { Color = Palette.CBorderSoft, Distance = "1 1" } }
            };
            var lockH = Positions.Hammer.LockH - 6;
            lockEl.Components.Add(new CuiLayoutElementComponent { MinHeight = lockH, PreferredHeight = lockH });
            container.Add(lockEl);
            UI_Text(container, lockBox, GetLocalizedMessage(TranslateKey.HammerCode, admin), 9, Fonts.Title,
                TextAnchor.MiddleLeft, Palette.CText3, "0 0", "0 1", "6 0", "56 0");
            UI_Text(container, lockBox,
                ad.HammerReveal ? info.Code + (string.IsNullOrEmpty(info.GuestCode) ? "" : $"   {GetLocalizedMessage(TranslateKey.HammerGuest, admin)} {info.GuestCode}") : GetLocalizedMessage(TranslateKey.HammerHidden, admin),
                10, Fonts.Console, TextAnchor.MiddleLeft, ad.HammerReveal ? Colors.CWarn : Palette.CText2, "0 0",
                "1 1", "58 0", "-78 0");
            UI_Btn(container, lockBox,
                GetLocalizedMessage(ad.HammerReveal ? TranslateKey.HammerHide : TranslateKey.HammerReveal, admin),
                "pa.hamreveal", ad.HammerReveal ? Palette.CElev : Colors.CSuccess, 8, Fonts.Title,
                TextAnchor.MiddleCenter, ad.HammerReveal ? Palette.CText2 : Palette.CPage, "1 0.5", "1 0.5", "-72 -7",
                "-6 7");
        }

        private void UI_PageMap(CuiElementContainer container, BasePlayer player)
        {
            UI_Head(container, player, TranslateKey.MapTitle, TranslateKey.MapSub);
            if (!Can(player, Permissions.Map))
            {
                UI_Locked(container, player, TranslateKey.LockedFeat, "assets/icons/terrain.png");
                return;
            }

            var ad = GetAdmin(player.userID);
            if (ad.MapDeepSea && !DeepSeaReady())
                ad.MapDeepSea = false;
            var canvas = MapCanvasSize(ad.MapZoom);

            container.Add(new CuiElement
            {
                Parent = Layers.Body, Name = Layers.MapView,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CPage },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1",
                        OffsetMin = $"{Positions.Pad} {Positions.Map.FrameTop - Positions.Map.FrameSize}",
                        OffsetMax = $"{Positions.Pad + Positions.Map.FrameSize} {Positions.Map.FrameTop}"
                    }
                }
            });

            if (ad.MapDeepSea)
            {
                UI_MapDeepBackground(container, player, ad);
                UI_MapDeepMarkers(container, player, ad);
                UI_MapLayerBar(container, player, ad);
                UI_MapControlBar(container, player, ad);
                UI_MapLegendToggle(container, player, ad);
                UI_MapSide(container, player, ad);
                UI_MapCard(container, player);
                return;
            }

            if (Map._mapCrc == 0)
                Map.EnsureMapImage();
            if (Map._mapCrc == 0)
            {
                UI_Text(container, Layers.MapView, GetLocalizedMessage(TranslateKey.MapPreparing, player), 12, Fonts.Body,
                    TextAnchor.MiddleCenter, Palette.CText3, "0 0", "1 1");
                UI_MapLayerBar(container, player, ad);
                UI_MapControlBar(container, player, ad);
                UI_MapLegendToggle(container, player, ad);
                UI_MapSide(container, player, ad);
                UI_MapCard(container, player);
                return;
            }

            container.Add(new CuiElement
            {
                Parent = Layers.MapView, Name = Layers.MapCanvas,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiScrollViewComponent
                    {
                        Horizontal = true, Vertical = true, MovementType = ScrollRect.MovementType.Clamped,
                        Inertia = true, ScrollSensitivity = 24f,
                        ContentTransform = MapContent(canvas),
                        HorizontalScrollbar = new CuiScrollbar
                        {
                            AutoHide = true, Size = 5f, HandleColor = Palette.CAccent,
                            HighlightColor = Palette.CAccentH, PressedColor = Palette.CAccentH,
                            TrackColor = Palette.CPage
                        },
                        VerticalScrollbar = new CuiScrollbar
                        {
                            AutoHide = true, Size = 5f, HandleColor = Palette.CAccent,
                            HighlightColor = Palette.CAccentH, PressedColor = Palette.CAccentH,
                            TrackColor = Palette.CPage
                        }
                    },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1" }
                }
            });
            container.Add(new CuiElement
            {
                Parent = Layers.MapCanvas,
                Components =
                {
                    new CuiRawImageComponent { Png = Map._mapCrc.ToString(), Color = "1 1 1 1" },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1" }
                }
            });

            UI_MapLayerBar(container, player, ad);
            UI_MapControlBar(container, player, ad);
            UI_MapMarkers(container, player);
            UI_MapObjMenu(container, player, ad);
            UI_MapLegendToggle(container, player, ad);
            UI_MapSide(container, player, ad);
            UI_MapCard(container, player);
        }

        private void UI_MapLayerBar(CuiElementContainer container, BasePlayer player, AdminData ad)
        {
            int[] bits = ad.MapDeepSea
                ? new[] { LayerPlayers, LayerSleepers, LayerCars, LayerAir, LayerShops, LayerEvents }
                : new[]
                {
                    LayerPlayers, LayerSleepers, LayerTc, LayerBags, LayerStashes, LayerCars, LayerHorses, LayerAir,
                    LayerShops, LayerEvents, LayerPvp, LayerRaid, LayerNotes
                };
            string[] keys = ad.MapDeepSea
                ? new[]
                {
                    TranslateKey.MapLayerPlayers, TranslateKey.MapLayerSleepers, TranslateKey.MapLayerCars,
                    TranslateKey.MapLayerAir, TranslateKey.MapLayerShops, TranslateKey.MapLayerEvents
                }
                : new[]
                {
                    TranslateKey.MapLayerPlayers, TranslateKey.MapLayerSleepers, TranslateKey.MapLayerTc,
                    TranslateKey.MapLayerBags, TranslateKey.MapLayerStashes, TranslateKey.MapLayerCars,
                    TranslateKey.MapLayerHorses, TranslateKey.MapLayerAir, TranslateKey.MapLayerShops,
                    TranslateKey.MapLayerEvents, TranslateKey.MapLayerPvp, TranslateKey.MapLayerRaid,
                    TranslateKey.MapLayerNotes
                };
            var layers = ad.MapDeepSea ? ad.MapLayersDeep : ad.MapLayers;
            const int gap = 3;
            var w = (Positions.Map.FrameSize - gap * (bits.Length - 1)) / bits.Length;
            var bar = Layers.Body + ".mapchips";
            container.Add(new CuiElement
            {
                Parent = Layers.Body, Name = bar,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{w} 24", Spacing = $"{gap} {gap}", StartCorner = GridLayoutGroup.Corner.UpperLeft,
                        StartAxis = GridLayoutGroup.Axis.Horizontal, ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = bits.Length
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{Positions.Pad} -80",
                        OffsetMax = $"{Positions.Pad + Positions.Map.FrameSize} -56"
                    }
                }
            });
            for (var i = 0; i < bits.Length; i++)
            {
                var accent = bits[i] == LayerPvp ? Colors.CDanger :
                    bits[i] == LayerRaid ? Colors.CWarn : Palette.CAccent;
                var on = (layers & bits[i]) != 0;
                var chip = Layers.Body + ".mapchip" + bits[i];
                container.Add(new CuiElement
                {
                    Parent = bar, Name = chip,
                    Components =
                    {
                        new CuiImageComponent { Color = on ? accent : Palette.CElev },
                        new CuiOutlineComponent { Color = on ? accent : Palette.CBorderSoft, Distance = "1 1" }
                    }
                });
                UI_Text(container, chip, GetLocalizedMessage(keys[i], player), 8, Fonts.Title, TextAnchor.MiddleCenter,
                    on ? Palette.CAccentText : Palette.CText2, "0 0", "1 1", "3 0", "-3 0", chip + ".lbl");
                UI_Btn(container, chip, $"pa.maplayer {bits[i]}", Colors.Clear, "0 0", "1 1");
            }
        }

