            var chip = Layers.Body + ".mapchip" + bit;
            var container = new CuiElementContainer();
            container.Add(new CuiElement
            {
                Name = chip, Update = true,
                Components =
                {
                    new CuiImageComponent { Color = on ? accent : Palette.CElev },
                    new CuiOutlineComponent { Color = on ? accent : Palette.CBorderSoft, Distance = "1 1" }
                }
            });
            container.Add(new CuiElement
            {
                Name = chip + ".lbl", Update = true,
                Components = { new CuiTextComponent { Color = on ? Palette.CAccentText : Palette.CText2 } }
            });
            CuiHelper.AddUi(player, container);
        }

