        private void UI_MapLegendPanel(CuiElementContainer container, BasePlayer player, AdminData ad)
        {
            var extra = ad.MapDeepSea ? MapLegendDeep : MapLegendIsland;
            const int rowH = 16;
            const int width = 168;
            var count = MapLegendCommon.Length + extra.Length;
            var height = count * rowH + 30;
            var right = Positions.Pad + Positions.Map.FrameSize - 8;
            var top = Positions.Map.FrameTop - 36;
            container.Add(new CuiElement
            {
                Parent = Layers.Body, Name = Layers.MapLegend, DestroyUi = Layers.MapLegend,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CSurface },
                    new CuiOutlineComponent { Color = Palette.CBorderSoft, Distance = "1 1" },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{right - width} {top - height}",
                        OffsetMax = $"{right} {top}"
                    }
                }
            });
            UI_Text(container, Layers.MapLegend, GetLocalizedMessage(TranslateKey.MapLegend, player), 10, Fonts.Title,
                TextAnchor.MiddleLeft, Palette.CText2, "0 1", "1 1", "10 -24", "-8 -6");
            for (var i = 0; i < count; i++)
            {
                var row = i < MapLegendCommon.Length
                    ? MapLegendCommon[i]
                    : extra[i - MapLegendCommon.Length];
                var y = -26 - i * rowH;
                var iconH = Mathf.Min(SpriteHeight(row[0], 12), 16);
                var iconY = y - 7 - iconH / 2;
                container.Add(new CuiElement
                {
                    Parent = Layers.MapLegend,
                    Components =
                    {
                        new CuiImageComponent { Color = row[1] ?? Palette.CAccent, Sprite = row[0] },
                        new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"11 {iconY}", OffsetMax = $"23 {iconY + iconH}" }
                    }
                });
                UI_Text(container, Layers.MapLegend, GetLocalizedMessage(row[2], player), 9, Fonts.Body, TextAnchor.MiddleLeft,
                    Palette.CText2, "0 1", "1 1", $"28 {y - 13}", $"-8 {y}");
            }
        }

