        private static bool IsDeepSeaGeography(MapMarkerKind kind) => MarkerMetaByKind[kind].DeepSea;

        private void UI_MapDeepMarkers(CuiElementContainer container, BasePlayer player, AdminData ad)
        {
            container.Add(new CuiElement
            {
                Parent = Layers.MapCanvas, Name = Layers.MapMarkers, DestroyUi = Layers.MapMarkers,
                Components = { new CuiImageComponent { Color = Colors.Clear }, new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1" } }
            });
            var zoom = ad.MapZoom;
            Map.BeginFrame();
            var markers = Map.MapMarkerPoints(true);
            for (var i = 0; i < markers.Count && Map.MapTake(); i++)
            {
                var marker = markers[i];
                if (!IsDeepSeaGeography(marker.Kind) && (ad.MapLayersDeep & MarkerLayer(marker.Kind)) == 0)
                    continue;
                var px = NormToCanvas(DeepToNorm(marker.Position), zoom);
                var size = ZoomedSize(MarkerSize(marker.Kind), zoom);
                var color = marker.Color ?? MarkerColor(marker.Kind);
                UI_MapSprite(container, Layers.MapMarkers, $"{Layers.MapMarkers}.dm{i}", px, size, color,
                    MarkerSprite(marker.Kind), null, MarkerRotation(marker.Kind, marker.Forward));
                UI_MapHeading(container, Layers.MapMarkers, $"{Layers.MapMarkers}.dh{i}", px, size, color, marker.Kind,
                    marker.Forward);
            }

            if ((ad.MapLayersDeep & LayerSleepers) != 0)
                UI_DrawSleepers(container, zoom, true, "ds");

            if ((ad.MapLayersDeep & LayerPlayers) == 0)
                return;
            UI_DrawPlayerMarkers(container, ad, zoom, true, "dp", true);
        }

        private void UI_MapSide(CuiElementContainer container, BasePlayer player, AdminData ad)
        {
            var search = GetInput(player, FieldKey.MapSearch, "");
            var online = new List<BasePlayer>();
            foreach (var target in BasePlayer.activePlayerList)
            {
                if (target == null || target.IsNpc)
                    continue;
                if (IsDeepSeaPosition(target.transform.position) != ad.MapDeepSea)
                    continue;
                if (!string.IsNullOrEmpty(search) &&
                    target.displayName.IndexOf(search, StringComparison.OrdinalIgnoreCase) < 0 &&
                    !target.UserIDString.Contains(search))
                    continue;
                online.Add(target);
            }

            online.Sort((a, b) => string.Compare(a.displayName, b.displayName, StringComparison.OrdinalIgnoreCase));
#if DEBUG_SERVER
            var fakeCount = MapDebugNames.Length;
#else
            var fakeCount = 0;
#endif

            var deepReady = DeepSeaReady();
            var manager = DeepSea();
            var zw = (Positions.Map.ColW - 4) / 2;
            var zones = Layers.Body + ".mapzone";
            container.Add(new CuiElement
            {
                Parent = Layers.Body, Name = zones, DestroyUi = zones,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{zw} 24", Spacing = "4 4",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = 2
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{Positions.Map.ColX} {-56 - 24}",
                        OffsetMax = $"{Positions.Map.ColX + Positions.Map.ColW} -56"
                    }
                }
            });
            for (var i = 0; i < 2; i++)
            {
                var deep = i == 1;
                var on = ad.MapDeepSea == deep;
                var enabled = !deep || deepReady;
                var label = GetLocalizedMessage(deep ? TranslateKey.MapZoneDeep : TranslateKey.MapZoneMain, player);
                if (deep && !enabled && manager != null)
                    label += "  <color=#7E8AA0>" + FormatDuration(manager.TimeToNextOpening) + "</color>";
                else if (deep && DeepSeaClosing())
                    label += "  <color=#D6B26A>" + FormatDuration(manager.TimeToWipe) + "</color>";
                UI_Btn(container, zones, label, enabled ? $"pa.mapzone {i}" : "", on ? Palette.CAccent : Palette.CElev, 10,
                    Fonts.Title, TextAnchor.MiddleCenter,
                    !enabled ? Palette.CText3 : on ? Palette.CAccentText : Palette.CText2, "0 0", "1 1",
                    name: zones + ".z" + i);
            }

            UI_Input(container, Layers.Body, player, FieldKey.MapSearch,
                GetLocalizedMessage(TranslateKey.MapSearch, player), Positions.Map.ColX, -88, Positions.Map.ColW, 26);

            var notes = MapNotes(player);
            UI_MapTab(container, player, TranslateKey.MapOnline, online.Count, !ad.MapNotesTab, "pa.maptab 0", Positions.Map.ColX);
            UI_MapTab(container, player, TranslateKey.MapLayerNotes, notes.Count, ad.MapNotesTab, "pa.maptab 1",
                Positions.Map.ColX + Positions.Map.ColW / 2 + 2);
            if (ad.MapNotesTab)
            {
                UI_MapNotesList(container, player, ad, notes);
                return;
            }

            var rows = online.Count + fakeCount;
            var scroll = UI_MapListBox(container, rows);
#if DEBUG_SERVER
            for (var i = 0; i < MapDebugNames.Length; i++)
            {
                var row = scroll + ".dbg" + i;
                var dbgEl = new CuiElement { Parent = scroll, Name = row, Components = { new CuiImageComponent { Color = Colors.Clear } } };
                container.Add(dbgEl);
                container.Add(new CuiElement
                {
                    Parent = row,
                    Components =
                    {
                        new CuiImageComponent { Color = TeamColor((ulong)(i % 4 + 1)), Sprite = "assets/icons/circle_closed.png" },
                        new CuiRectTransformComponent { AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = "8 -4", OffsetMax = "16 4" }
                    }
                });
                UI_Text(container, row, MapDebugNames[i], 10, Fonts.Body, TextAnchor.MiddleLeft, Palette.CText3, "0 0", "1 1",
                    "24 0", "-96 0");
            }
#endif
            for (var i = 0; i < online.Count; i++)
            {
                var target = online[i];
                var on = ad.MapSelected == target.userID;
                var row = scroll + ".r" + i;
                var rowEl = new CuiElement
                {
                    Parent = scroll, Name = row,
                    Components =
                    {
                        new CuiImageComponent { Color = on ? Palette.CElev : Colors.Clear },
                        new CuiOutlineComponent { Color = on ? Palette.CAccent : Palette.CBorderSoft, Distance = "1 1" }
                    }
                };
                container.Add(rowEl);
                container.Add(new CuiElement
                {
                    Parent = row,
                    Components =
                    {
                        new CuiImageComponent { Color = TeamColor(target.currentTeam), Sprite = "assets/icons/circle_closed.png" },
                        new CuiRectTransformComponent { AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = "8 -4", OffsetMax = "16 4" }
                    }
                });
                UI_Text(container, row, target.displayName, 10, Fonts.Body, TextAnchor.MiddleLeft,
                    on ? Palette.CAccent : Palette.CText, "0 0", "1 1", "24 0", "-96 0");
                UI_Text(container, row, MapHelper.PositionToString(target.transform.position), 9, Fonts.Console,
                    TextAnchor.MiddleRight, Palette.CText3, "0 0", "1 1", "0 0", "-46 0");
                UI_Text(container, row, Ping(target).ToString(), 9, Fonts.Console, TextAnchor.MiddleRight, Palette.CText3,
                    "0 0", "1 1", "0 0", "-8 0");
                UI_Btn(container, row, $"pa.mapsel {target.userID}", Colors.Clear, "0 0", "1 1");
            }
        }


