        private string UI_MapListBox(CuiElementContainer container, int rows, int rowH = 0)
        {
            if (rowH <= 0)
                rowH = Positions.Map.SideRowH;
            var box = Layers.Body + ".maplistbox";
            container.Add(new CuiElement
            {
                Parent = Layers.Body, Name = box, DestroyUi = box,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CSurface },
                    new CuiOutlineComponent { Color = Palette.CBorderSoft, Distance = "1 1" },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1",
                        OffsetMin = $"{Positions.Map.ColX} {Positions.Map.SideListY - Positions.Map.SideListH}",
                        OffsetMax = $"{Positions.Map.ColX + Positions.Map.ColW} {Positions.Map.SideListY}"
                    }
                }
            });
            return UI_ScrollList(container, box, "maplist", 2, -2, Positions.Map.ColW - 6, Positions.Map.SideListH - 6,
                rowH, 2, rows, 2, 1, null, null);
        }

        private void UI_MapNotesList(CuiElementContainer container, BasePlayer player, AdminData ad,
            List<ProtoBuf.MapNote> notes)
        {
            var scroll = UI_MapListBox(container, notes.Count, Positions.Map.NoteRowH);

            if (notes.Count == 0)
            {
                var empty = ScrollOf(scroll);
                container.Add(new CuiElement
                {
                    Parent = empty,
                    Components =
                    {
                        new CuiImageComponent { Color = Palette.CAccent, Sprite = NoteSprite },
                        new CuiOutlineComponent { Color = MarkerOutline, Distance = "1 1" },
                        new CuiRectTransformComponent { AnchorMin = "0.5 1", AnchorMax = "0.5 1", OffsetMin = "-16 -52", OffsetMax = "16 -20" }
                    }
                });
                UI_Text(container, empty, GetLocalizedMessage(TranslateKey.MapNotesEmpty, player), 10, Fonts.Title,
                    TextAnchor.UpperCenter, Palette.CText2, "0 1", "1 1", "10 -84", "-10 -64");
                UI_Text(container, empty, GetLocalizedMessage(TranslateKey.MapNotesEmptyHint, player), 9, Fonts.Body,
                    TextAnchor.UpperCenter, Palette.CText3, "0 1", "1 1", "10 -102", "-10 -84");
                return;
            }

            for (var i = 0; i < notes.Count; i++)
            {
                var note = notes[i];
                if (note == null)
                    continue;
                var tint = NoteColor(note.colourIndex);
                var grid = MapHelper.PositionToString(note.worldPosition);
                var row = scroll + ".n" + i;
                container.Add(new CuiElement
                {
                    Parent = scroll, Name = row,
                    Components =
                    {
                        new CuiImageComponent { Color = Palette.CElev },
                        new CuiOutlineComponent { Color = Palette.CBorderSoft, Distance = "1 1" },
                        new CuiRectTransformComponent { SetTransformIndex = i }
                    }
                });
                container.Add(
                    new CuiPanel
                    {
                        Image = { Color = tint },
                        RectTransform = { AnchorMin = "0 0", AnchorMax = "0 1", OffsetMin = "0 0", OffsetMax = "2 0" }
                    }, row);
                var icon = NoteIcon(note);
                var iconH = Mathf.Min(SpriteHeight(icon, 16), 26) / 2;
                container.Add(new CuiElement
                {
                    Parent = row,
                    Components =
                    {
                        new CuiImageComponent { Color = tint, Sprite = icon },
                        new CuiRectTransformComponent { AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = $"8 {-iconH}", OffsetMax = $"24 {iconH}" }
                    }
                });
                UI_Text(container, row, string.IsNullOrEmpty(note.label) ? grid : note.label, 10, Fonts.Title,
                    TextAnchor.LowerLeft, Palette.CText, "0 0.5", "1 1", "30 0", "-84 -4");
                UI_Text(container, row, grid, 8, Fonts.Console, TextAnchor.UpperLeft, Palette.CText3, "0 0", "1 0.5", "30 4",
                    "-84 0");
                UI_MapNoteButton(container, row, $"pa.notetp {i}", "assets/icons/pet_move.png", Palette.CAccent, -42);
                UI_MapNoteButton(container, row, $"pa.notedel {i}", "assets/icons/close.png", Colors.CDanger, -8);
            }
        }

