        private void UI_MapObjMenu(CuiElementContainer container, BasePlayer player, AdminData ad)
        {
            if (string.IsNullOrEmpty(ad.MapObjSelected))
                return;
            var parts = ad.MapObjSelected.Split(':');
            if (parts.Length != 2 || !ulong.TryParse(parts[1], out var netId))
            {
                ad.MapObjSelected = null;
                return;
            }

            var kind = parts[0];
            var entity = FindMapObject(kind, netId);
            if (entity == null)
            {
                ad.MapObjSelected = null;
                ad.MapObjDeleteConfirm = null;
                return;
            }

            var owners = MapObjectOwners(kind, entity);
            var canJumpToPlayer = Can(player, Permissions.Players);
            var canTeleport = Can(player, Permissions.MapTeleport);
            var canRemove = Can(player, Permissions.MapRemove);
            var canLoot = (kind == "tc" || kind == "st") && Can(player, Permissions.MapLoot);
            var deleteArmed = ad.MapObjDeleteConfirm == ad.MapObjSelected;

            const int rowH = 20, gap = 4, margin = 8, overflowH = 16;

            var px = NormToCanvas(WorldToNorm(entity.transform.position), ad.MapZoom);
            var panelRect = new CuiRectTransformComponent
            {
                AnchorMin = "0 0", AnchorMax = "0 0", OffsetMax = $"{px.x + 232} {px.y + 12}"
            };
            container.Add(new CuiElement
            {
                Parent = Layers.MapMarkers, Name = Layers.MapObj, DestroyUi = Layers.MapObj,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CSurface },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    panelRect
                }
            });

            UI_CloseX(container, Layers.MapObj, "pa.mapobjclose", "1 1", "1 1", "-24 -24", "0 0", Layers.MapObj + ".x");

            var y = -8;
            UI_Text(container, Layers.MapObj, $"{MapKindLabel(kind, player)} · {entity.ShortPrefabName}", 10, Fonts.Title,
                TextAnchor.UpperLeft, Palette.CText, "0 1", "1 1", $"10 {y - rowH}", $"-30 {y}");
            y -= rowH + gap;

            UI_Text(container, Layers.MapObj, MapHelper.PositionToString(entity.transform.position), 9, Fonts.Console,
                TextAnchor.UpperLeft, Palette.CText3, "0 1", "1 1", $"10 {y - rowH}", $"-10 {y}");
            y -= rowH + gap;

            if (canTeleport)
            {
                UI_Btn(container, Layers.MapObj, GetLocalizedMessage(TranslateKey.MapObjTeleport, player),
                    $"pa.mapobjtp {kind} {netId}", Palette.CElev, 10, Fonts.Title, TextAnchor.MiddleCenter,
                    Palette.CText, "0 1", "1 1", $"10 {y - rowH}", $"-10 {y}");
                y -= rowH + gap;
            }

            if (canRemove)
            {
                UI_Btn(container, Layers.MapObj,
                    GetLocalizedMessage(deleteArmed ? TranslateKey.MapObjDeleteConfirm : TranslateKey.MapObjDelete,
                        player), $"pa.mapobjdel {kind} {netId}", deleteArmed ? Colors.CDanger : Palette.CElev, 10,
                    Fonts.Title, TextAnchor.MiddleCenter, deleteArmed ? Palette.CAccentText : Colors.CDanger, "0 1",
                    "1 1", $"10 {y - rowH}", $"-10 {y}");
                y -= rowH + gap;
                if (deleteArmed)
                {
                    UI_Btn(container, Layers.MapObj, GetLocalizedMessage(TranslateKey.MapObjDeleteOk, player),
                        $"pa.mapobjdelok {kind} {netId}", Colors.CDanger, 10, Fonts.Title, TextAnchor.MiddleCenter,
                        Palette.CAccentText, "0 1", "1 1", $"10 {y - rowH}", $"-10 {y}");
                    y -= rowH + gap;
                }
            }

            if (canLoot)
            {
                UI_Btn(container, Layers.MapObj, GetLocalizedMessage(TranslateKey.MapObjLoot, player),
                    $"pa.mapobjloot {kind} {netId}", Palette.CElev, 10, Fonts.Title, TextAnchor.MiddleCenter,
                    Palette.CText, "0 1", "1 1", $"10 {y - rowH}", $"-10 {y}");
                y -= rowH + gap;
            }

            if (owners.Length == 0)
            {
                UI_Text(container, Layers.MapObj, "-", 9, Fonts.Title, TextAnchor.UpperLeft, Palette.CText3, "0 1", "1 1",
                    $"10 {y - rowH}", $"-10 {y}");
                y -= rowH;
            }
            else
            {
                var shown = Math.Min(owners.Length, 3);
                for (var i = 0; i < shown; i++)
                {
                    UI_Avatar(container, Layers.MapObj, owners[i].ToString(), 10, y - 2, 16);
                    if (canJumpToPlayer)
                        UI_Btn(container, Layers.MapObj, OwnerRowText(owners[i]), $"pa.popup {owners[i]}", Colors.Clear, 9,
                            Fonts.Title, TextAnchor.UpperLeft, Palette.CAccent, "0 1", "1 1", $"32 {y - rowH}",
                            $"-10 {y}");
                    else
                        UI_Text(container, Layers.MapObj, OwnerRowText(owners[i]), 9, Fonts.Title, TextAnchor.UpperLeft,
                            Palette.CText, "0 1", "1 1", $"32 {y - rowH}", $"-10 {y}");
                    y -= rowH;
                }

                if (owners.Length > shown)
                {
                    UI_Text(container, Layers.MapObj,
                        SafeFormat(GetLocalizedMessage(TranslateKey.MapObjOwnersMore, player), owners.Length - shown),
                        8, Fonts.Console, TextAnchor.UpperLeft, Palette.CText3, "0 1", "1 1",
                        $"10 {y - overflowH}", $"-10 {y}");
                    y -= overflowH;
                }
            }

            y -= margin;
            panelRect.OffsetMin = $"{px.x + 12} {px.y + y}";
        }

