            UI_Text(container, Layers.MapCard + ".more", GetLocalizedMessage(TranslateKey.MapDetails, player), 10, Fonts.Title,
                TextAnchor.MiddleCenter, Palette.CText, "0 0", "1 1");
        }

        private void UI_MapCardActions(CuiElementContainer container, BasePlayer player, BasePlayer target)
        {
            var rows = new List<string[]>();
            foreach (var def in MapActionsFor(player))
            {
                var live = MapActionEnabled(def[0], target.userID, player);
                rows.Add(new[]
                {
                    GetLocalizedMessage(def[1], player), def[2], MapActionColor(def[3]),
                    live ? $"pa.popup {target.userID} {def[0]}" : "", GetLocalizedMessage(def[4], player)
                });
            }

            foreach (var qb in QuickFor(player, QuickTarget.Player, QuickPlace.Map))
                rows.Add(new[]
                {
                    qb.Name, string.IsNullOrEmpty(qb.Icon) ? "assets/icons/gear.png" : qb.Icon, QuickColor(qb),
                    $"pa.qbrun {qb.Id} {target.userID}", qb.Name
                });

            var head = Layers.MapCard + ".acthead";
            container.Add(new CuiElement
            {
                Parent = Layers.MapCard, Name = head,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CPage },
                    new CuiOutlineComponent { Color = Palette.CBorderSoft, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = "7 -149", OffsetMax = "279 -137" }
                }
            });
            UI_Text(container, head, GetLocalizedMessage(TranslateKey.MapQuickActions, player), 9, Fonts.Title,
                TextAnchor.MiddleLeft, Palette.CText3, "0 0", "1 1", "5 0", "-70 0");
            UI_Text(container, head, rows.Count.ToString(), 9, Fonts.Console, TextAnchor.MiddleRight, Palette.CText2, "0 0",
                "1 1", "0 0", "-7 0");

            var scroll = UI_ScrollList(container, Layers.MapCard, "acts", 7, -151, 272, Positions.Map.ActListH, Positions.Map.ActRowH, 5,
                rows.Count, 3, 2, Palette.CPage, Palette.CBorderSoft, null, false, 2f);

            if (rows.Count == 0)
            {
                UI_Text(container, ScrollOf(scroll), GetLocalizedMessage(TranslateKey.MapNoActions, player), 9, Fonts.Body,
                    TextAnchor.MiddleCenter, Palette.CText3, "0 0", "1 1");
                return;
            }

            for (var i = 0; i < rows.Count; i++)
            {
                var live = !string.IsNullOrEmpty(rows[i][3]);
                var tint = live ? rows[i][2] : Palette.CText3;
                var cell = scroll + ".r" + i;
                container.Add(new CuiElement
                {
                    Parent = scroll, Name = cell,
                    Components =
                    {
                        new CuiImageComponent { Color = live ? WithAlpha(tint, 0.10f) : Colors.Clear },
                        new CuiOutlineComponent { Color = live ? WithAlpha(tint, 0.40f) : Palette.CBorderSoft, Distance = "1 1" },
                        new CuiRectTransformComponent { SetTransformIndex = i }
                    }
                });
                container.Add(new CuiElement
                {
                    Parent = cell,
                    Components =
                    {
                        new CuiImageComponent { Color = tint, Sprite = rows[i][1] },
                        new CuiRectTransformComponent { AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = "4 -6", OffsetMax = "16 6" }
                    }
                });
                UI_Text(container, cell, rows[i][0], 10, Fonts.Body, TextAnchor.MiddleLeft,
                    live ? Palette.CText : Palette.CText3, "0 0", "1 1", "20 0", "-4 0");
                if (!live)
                    continue;
                UI_Btn(container, cell, rows[i][3], Colors.Clear, "0 0", "1 1");
                UI_Tip(container, rows[i][4]);
            }
        }

        private float MapInterval()
        {
            var pct = Mathf.Clamp01(GetSlider(null, FieldKey.SecMapInterval, 0.2f));
            return Mathf.Clamp(pct * 5f, 0.5f, 5f);
        }

        private void MapTimerTick()
        {
            foreach (var p in BasePlayer.activePlayerList)
            {
                var ad = PeekAdmin(p.userID);
                if (ad == null || !ad.UiOpen || ad.MapPaused)
                    continue;
                if (GetPage(p) != "map")
                    continue;
                UI_MapRefresh(p);
            }

            _mapTimer = timer.Once(MapInterval(), MapTimerTick);
        }

        private void UI_MapRefresh(BasePlayer player)
        {
            if (player == null || PeekAdmin(player.userID)?.UiOpen != true || GetPage(player) != "map" ||
                !Can(player, Permissions.Map))
                return;
            var ad = GetAdmin(player.userID);
            if (!ad.MapDeepSea && Map._mapCrc == 0)
                return;
            ApplyTheme(player);
            var container = new CuiElementContainer();
            if (ad.MapDeepSea)
                UI_MapDeepMarkers(container, player, ad);
            else
                UI_MapMarkers(container, player);
            if (!ad.MapDeepSea)
                UI_MapObjMenu(container, player, ad);
            var target = ad.MapSelected == 0 ? null : FindActiveOrSleeping(ad.MapSelected);
            if (ad.MapCardShown != ad.MapSelected || target == null)
                UI_MapCard(container, player);
            else
                UI_MapCardLive(container, player, target);
            CuiHelper.AddUi(player, container);
        }

        private void UI_MapCardLive(CuiElementContainer container, BasePlayer player, BasePlayer target)
        {
            var chip = Layers.MapCard + ".state";
            var state = target.IsDead() ? "Dead" :
                target.IsWounded() ? "Wounded" :
                target.IsSleeping() ? "Sleeping" : "Online";
            var stateColor = target.IsDead() || target.IsWounded() ? Colors.CDanger :
                target.IsSleeping() ? Colors.CInfo : Colors.CSuccess;
            container.Add(new CuiElement { Name = chip + ".ic", Update = true, Components = { new CuiImageComponent { Color = stateColor } } });
            container.Add(new CuiElement { Name = chip + ".lbl", Update = true, Components = { new CuiTextComponent { Text = state, Color = stateColor } } });

            var maxHp = Mathf.Max(1f, target.MaxHealth());
            var hp = Mathf.Clamp01(target.health / maxHp);
            container.Add(new CuiElement
            {
                Name = Layers.MapCard + ".hpv", Update = true,
                Components = { new CuiTextComponent { Text = $"{Mathf.RoundToInt(target.health)} / {Mathf.RoundToInt(maxHp)}" } }
            });
            var hpFill = Mathf.Clamp(Mathf.RoundToInt(270f * hp), 0, 270);
            container.Add(new CuiElement
            {
                Name = Layers.MapCard + ".hp.f", Update = true,
                Components =
                {
                    new CuiImageComponent { Color = hp > 0.5f ? Colors.CSuccess : hp > 0.25f ? Colors.CWarn : Colors.CDanger },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "0 1", OffsetMin = "1 1", OffsetMax = $"{hpFill + 1} -1" }
                }
            });

            string[] values =
            {
                MapHelper.PositionToString(target.transform.position),
                target.currentTeam == 0 ? "-" : target.currentTeam.ToString(),
                $"{Mathf.RoundToInt(Vector3.Distance(target.transform.position, player.transform.position))} m"
            };
            for (var i = 0; i < values.Length; i++)
                container.Add(new CuiElement { Name = Layers.MapCard + ".stv" + i, Update = true, Components = { new CuiTextComponent { Text = values[i] } } });
        }

        private void UI_PageQuickButtons(CuiElementContainer container, BasePlayer player)
        {
            UI_Head(container, player, TranslateKey.QbTitle, TranslateKey.QbSub);
            var canEdit = Can(player, Permissions.Settings);
            var pw = Positions.BodyW - Positions.Pad * 2;
            var list = cfg?.QuickButtons ?? new List<QuickButton>();

            if (canEdit)
            {
                var add = Layers.Body + ".qb.add";
                UI_Btn(container, Layers.Body, GetLocalizedMessage(TranslateKey.QbNew, player), "pa.qbnew", Palette.CAccent,
                    11, Fonts.Title, TextAnchor.MiddleCenter, Palette.CAccentText, "1 1", "1 1",
                    $"{-Positions.Pad - 110} -46", $"{-Positions.Pad} -20", add);
            }

            const int rowH = 46;
            var root = UI_ScrollList(container, Layers.Body, "qb", Positions.Pad, -60, pw, Positions.BodyH - 76, rowH, 6,
                list.Count, 4, 1, null, null);

            if (list.Count == 0)
                UI_Text(container, ScrollOf(root), GetLocalizedMessage(TranslateKey.QbEmpty, player), 12, Fonts.Body,
                    TextAnchor.UpperCenter, Palette.CText3, "0 1", "1 1", "0 -60", "0 -20");

            for (var i = 0; i < list.Count; i++)
            {
                var qb = list[i];
                var row = root + ".r" + i;
                container.Add(new CuiElement
                {
                    Parent = root, Name = row,
                    Components =
                    {
                        new CuiImageComponent { Color = Palette.CSurface },
                        new CuiOutlineComponent { Color = qb.Enabled ? Palette.CBorder : Palette.CBorderSoft, Distance = "1 1" }
                    }
                });
                UI_QuickIcon(container, row, qb, qb.Enabled ? QuickColor(qb) : Palette.CText3, 18);
                UI_Text(container, row, string.IsNullOrEmpty(qb.Name) ? qb.Id : qb.Name, 12, Fonts.Title, TextAnchor.LowerLeft,
                    qb.Enabled ? Palette.CText : Palette.CText3, "0 0.5", "1 1", "36 0", "-320 -6");
                UI_Text(container, row, $"{QuickTargetLabel(player, qb.Target)}  ·  {QuickPlacesLabel(player, qb.Places)}", 9,
                    Fonts.Body, TextAnchor.UpperLeft, Palette.CText3, "0 0", "1 0.5", "36 4", "-320 0");
                UI_Text(container, row, qb.Command.Length > 44 ? qb.Command.Substring(0, 43) + "..." : qb.Command, 9,
                    Fonts.Console, TextAnchor.MiddleRight, Palette.CText2, "1 0", "1 1", "-460 0", "-186 0");

                if (!canEdit)
                    continue;
                UI_QuickRowButton(container, row, "pa.qbtoggle " + qb.Id,
                    qb.Enabled ? "assets/icons/circle_closed.png" : "assets/icons/circle_open.png",
                    qb.Enabled ? Colors.CSuccess : Palette.CText3, -178);
                UI_QuickRowButton(container, row, i == 0 ? "" : $"pa.qbmove {qb.Id} -1", "assets/icons/chevron_down.png",
                    i == 0 ? Palette.CText3 : Palette.CText2, -142, 180f);
                UI_QuickRowButton(container, row, i == list.Count - 1 ? "" : $"pa.qbmove {qb.Id} 1",
                    "assets/icons/chevron_down.png", i == list.Count - 1 ? Palette.CText3 : Palette.CText2, -106);
                UI_QuickRowButton(container, row, "pa.qbedit " + qb.Id, "assets/icons/gear.png", Palette.CAccent, -70);
                UI_QuickRowButton(container, row, "pa.qbdel " + qb.Id, "assets/icons/close.png", Colors.CDanger, -34);
            }
        }


        private static int QuickRows(int count, int cols) => count == 0 ? 0 : Mathf.CeilToInt((float)count / cols);

        private static int QuickBlockH(int count, int cols) =>
            count == 0 ? 0 : QuickRows(count, cols) * (Positions.Quick.RowH + Positions.Quick.RowGap);

        private void UI_QuickRow(CuiElementContainer container, string parent, List<QuickButton> list, ulong targetId, int x,
            int y, int w, int cols)
        {
            if (list.Count == 0)
                return;
            var cellW = (w - (cols - 1) * Positions.Quick.RowGap) / cols;
            var rows = (list.Count + cols - 1) / cols;
            var grid = parent + ".qgrid";
            container.Add(new CuiElement
            {
                Parent = parent, Name = grid, DestroyUi = grid,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{cellW} {Positions.Quick.RowH}", Spacing = $"{Positions.Quick.RowGap} {Positions.Quick.RowGap}",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = cols
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{x} {y - (rows * (Positions.Quick.RowH + Positions.Quick.RowGap) - Positions.Quick.RowGap)}",
                        OffsetMax = $"{x + w} {y}"
                    }
                }
            });
            for (var i = 0; i < list.Count; i++)
            {
                var qb = list[i];
                var color = QuickColor(qb);
                var b = grid + ".qr" + qb.Id;
                container.Add(new CuiElement
                {
                    Parent = grid, Name = b,
                    Components =
                    {
                        new CuiImageComponent { Color = WithAlpha(color, 0.10f) },
                        new CuiOutlineComponent { Color = WithAlpha(color, 0.45f), Distance = "1 1" }
                    }
                });
                UI_QuickIcon(container, b, qb, color, 14);
                UI_Text(container, b, qb.Name, 11, Fonts.Title, TextAnchor.MiddleLeft, Palette.CText, "0 0", "1 1", "32 0",
                    "-8 0");
                UI_Btn(container, b, $"pa.qbrun {qb.Id} {targetId}", Colors.Clear, "0 0", "1 1");
            }
        }

        private void UI_QuickConfirm(CuiElementContainer container, BasePlayer player)
        {
            var pending = PeekAdmin(player.userID)?.QuickConfirm;
            if (string.IsNullOrEmpty(pending))
                return;
            var parts = pending.Split(' ');
            var qb = FindQuick(parts[0]);
            if (qb == null)
                return;
            var root = Layers.Root + ".qbc";
            container.Add(new CuiElement
            {
                Parent = Layers.Root, Name = root, DestroyUi = root,
                Components =
                {
                    new CuiImageComponent { Color = "0 0 0 0.7" }, new CuiNeedsCursorComponent(),
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1" }
                }
            });
            var card = root + ".card";
            container.Add(new CuiElement
            {
                Parent = root, Name = card,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CBg },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = "-190 -66", OffsetMax = "190 66" }
                }
            });
            UI_Text(container, card, SafeFormat(GetLocalizedMessage(TranslateKey.QbConfirmQ, player), qb.Name), 12,
                Fonts.Title, TextAnchor.MiddleCenter, Palette.CText, "0 1", "1 1", "16 -70", "-16 -20");
            UI_Btn(container, card, GetLocalizedMessage(TranslateKey.QbCancel, player), "pa.qbcancel", Palette.CElev, 11,
                Fonts.Title, TextAnchor.MiddleCenter, Palette.CText2, "0 0", "0 0", "16 16", "180 42");
            UI_Btn(container, card, qb.Name, $"pa.qbrun {pending} 1", Palette.CAccent, 11, Fonts.Title,
                TextAnchor.MiddleCenter, Palette.CAccentText, "1 0", "1 0", "-180 16", "-16 42");
        }


        private void UI_QuickEditor(CuiElementContainer container, BasePlayer player)
        {
            var draft = PeekAdmin(player.userID)?.QuickDraft;
            if (draft == null)
            {
                container.Add(new CuiElement
                {
                    Parent = Layers.Root, Name = Layers.QuickEditor, DestroyUi = Layers.QuickEditor,
                    Components =
                    {
                        new CuiImageComponent { Color = Colors.Clear },
                        new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "0 0", OffsetMin = "0 0", OffsetMax = "0 0" }
                    }
                });
                return;
            }

            var root = Layers.QuickEditor;
            container.Add(new CuiElement
            {
                Parent = Layers.Root, Name = root, DestroyUi = root,
                Components =
                {
                    new CuiImageComponent { Color = "0 0 0 0.65" }, new CuiNeedsCursorComponent(),
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1" }
                }
            });
            UI_Btn(container, root, "pa.qbclose", Colors.Clear, "0 0", "1 1");

            const int cw = 640;
            const int ch = 470;
            var card = root + ".card";
            container.Add(new CuiElement
            {
                Parent = root, Name = card,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CBg },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = $"{-cw / 2} {-ch / 2}",
                        OffsetMax = $"{cw / 2} {ch / 2}"
                    }
                }
            });
            container.Add(new CuiPanel
            {
                Image = { Color = Palette.CSurface },
                RectTransform = { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = "0 -40", OffsetMax = "0 0" }
            }, card, card + ".h");
            UI_Text(container, card + ".h", GetLocalizedMessage(TranslateKey.QbEdit, player), 13, Fonts.Title,
                TextAnchor.MiddleLeft, Palette.CText, "0 0", "1 1", "16 0", "-40 0");
            var x = card + ".h.x";
            UI_CloseX(container, card + ".h", "pa.qbclose", "1 0.5", "1 0.5", "-34 -11", "-12 11", x);

            UI_QuickField(container, card, player, "qb.name", GetLocalizedMessage(TranslateKey.QbName, player), draft.Name, 16,
                -52, 300);
            UI_QuickField(container, card, player, "qb.perm", GetLocalizedMessage(TranslateKey.QbPerm, player),
                draft.Permission, 328, -52, 296);
            UI_QuickField(container, card, player, "qb.cmd", GetLocalizedMessage(TranslateKey.QbCmd, player), draft.Command, 16,
                -110, 608);
            UI_Text(container, card, GetLocalizedMessage(TranslateKey.QbPlaceholders, player), 9, Fonts.Console,
                TextAnchor.UpperLeft, Palette.CText3, "0 1", "1 1", "16 -186", "-16 -160");

            UI_Text(container, card, GetLocalizedMessage(TranslateKey.QbTarget, player), 10, Fonts.Body, TextAnchor.MiddleLeft,
                Palette.CText2, "0 1", "0 1", "16 -216", "180 -198");
            var targets = new[] { QuickTarget.Player, QuickTarget.Global, QuickTarget.Point };
            for (var i = 0; i < targets.Length; i++)
            {
                var on = draft.Target == targets[i];
                UI_Btn(container, card, QuickTargetLabel(player, targets[i]), on ? "" : $"pa.qbset target {targets[i]}",
                    on ? Palette.CAccent : Palette.CElev, 10, Fonts.Title, TextAnchor.MiddleCenter,
                    on ? Palette.CAccentText : Palette.CText2, "0 1", "0 1", $"{140 + i * 120} -222",
                    $"{140 + i * 120 + 114} -196");
            }

            UI_Text(container, card, GetLocalizedMessage(TranslateKey.QbPlaces, player), 10, Fonts.Body, TextAnchor.MiddleLeft,
                Palette.CText2, "0 1", "0 1", "16 -256", "180 -238");
            var places = new[] { QuickPlace.Popup, QuickPlace.Map, QuickPlace.Widget, QuickPlace.Dashboard };
            string[] placeKeys = { TranslateKey.QbPlacePopup, TranslateKey.QbPlaceMap, TranslateKey.QbPlaceWidget, TranslateKey.QbPlaceDashboard };
            for (var i = 0; i < places.Length; i++)
            {
                var on = (draft.Places & places[i]) != 0;
                UI_Btn(container, card, GetLocalizedMessage(placeKeys[i], player), $"pa.qbset place {places[i]}",
                    on ? Palette.CAccent : Palette.CElev, 10, Fonts.Title, TextAnchor.MiddleCenter,
                    on ? Palette.CAccentText : Palette.CText2, "0 1", "0 1", $"{140 + i * 120} -262",
                    $"{140 + i * 120 + 114} -236");
            }

            UI_Text(container, card, GetLocalizedMessage(TranslateKey.QbIcon, player), 10, Fonts.Body, TextAnchor.MiddleLeft,
                Palette.CText2, "0 1", "1 1", "16 -292", "-16 -274");
            const int cols = 16;
            var iconRows = (IconChoices.Length + cols - 1) / cols;
            var icons = card + ".icons";
