            {
                Parent = card, Name = icons, DestroyUi = icons,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = "34 34", Spacing = "4 4",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = cols
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"16 {-300 - (iconRows * 38 - 4)}",
                        OffsetMax = $"{16 + (cols * 38 - 4)} -300"
                    }
                }
            });
            for (var i = 0; i < IconChoices.Length; i++)
            {
                var on = draft.Icon == IconChoices[i];
                var cell = icons + ".ic" + i;
                container.Add(new CuiElement
                {
                    Parent = icons, Name = cell,
                    Components =
                    {
                        new CuiImageComponent { Color = on ? Palette.CAccent : Palette.CPage },
                        new CuiOutlineComponent { Color = on ? Palette.CAccent : Palette.CBorderSoft, Distance = "1 1" }
                    }
                });
                container.Add(new CuiElement
                {
                    Parent = cell,
                    Components =
                    {
                        new CuiImageComponent { Color = on ? Palette.CAccentText : Palette.CText2, Sprite = IconChoices[i] },
                        new CuiRectTransformComponent { AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = "-9 -9", OffsetMax = "9 9" }
                    }
                });
                if (on)
                    continue;
                UI_Btn(container, cell, $"pa.qbset icon {IconChoices[i]}", Colors.Clear, "0 0", "1 1");
            }

            var confirmOn = draft.Confirm;
            UI_Btn(container, card, GetLocalizedMessage(TranslateKey.QbConfirm, player), "pa.qbset confirm x",
                confirmOn ? Palette.CAccent : Palette.CElev, 10, Fonts.Title, TextAnchor.MiddleCenter,
                confirmOn ? Palette.CAccentText : Palette.CText2, "0 0", "0 0", "16 14", "196 40");
            UI_Btn(container, card, GetLocalizedMessage(TranslateKey.QbCancel, player), "pa.qbclose", Palette.CElev, 11,
                Fonts.Title, TextAnchor.MiddleCenter, Palette.CText2, "1 0", "1 0", "-296 14", "-156 40");
            UI_Btn(container, card, GetLocalizedMessage(TranslateKey.QbSave, player), "pa.qbsave", Palette.CAccent, 11,
                Fonts.Title, TextAnchor.MiddleCenter, Palette.CAccentText, "1 0", "1 0", "-146 14", "-16 40");
        }

