                -60, pw, 162);
            UI_ThemeCards(container, player, card, pw);

            var canVitals = permission.UserHasPermission(player.UserIDString, Permissions.CanDisableVitals);
            var vc = UI_Card(container, Layers.Body, GetLocalizedMessage(TranslateKey.AppVitals, player), Positions.Pad, -236,
                pw, 96);
