            {
                UI_Text(container, vc, GetLocalizedMessage(TranslateKey.AppVitalsLocked, player), 9, Fonts.Body,
                    TextAnchor.MiddleRight, Palette.CText3, "0 1", "1 1", "16 -28", "-34 -12");
                container.Add(new CuiElement
                {
