                        new CuiRectTransformComponent { AnchorMin = "1 1", AnchorMax = "1 1", OffsetMin = "-28 -27", OffsetMax = "-14 -13" }
                    }
                });
            }

            var vcw = (pw - 32 - 24) / 4;
            var vitals = vc + ".vitrow";
            container.Add(new CuiElement
            {
                Parent = vc, Name = vitals, DestroyUi = vitals,
