                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = StatusDefs.Length
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"16 {-46 - Positions.ToggleH}",
                        OffsetMax = $"{16 + (pw - 32)} -46"
                    }
                }
            });
            for (var i = 0; i < StatusDefs.Length; i++)
            {
                var s = StatusDefs[i];
                var cell = vitals + ".v" + i;
                container.Add(new CuiElement { Parent = vitals, Name = cell, Components = { new CuiImageComponent { Color = Colors.Clear } } });
                container.Add(new CuiElement
                {
                    Parent = cell,
                    Components =
                    {
                        new CuiImageComponent
                        {
                            Color = canVitals ? ColorToRustFormat(s.Color) : Palette.CText3,
                            Sprite = canVitals ? "assets/icons/circle_closed.png" : "assets/icons/lock.png"
                        },
                        new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = "0 -12", OffsetMax = "11 -1" }
                    }
                });
                var slot = cell + ".t";
                container.Add(new CuiElement
                {
                    Parent = cell, Name = slot,
