                        new CuiImageComponent { Color = Colors.Clear },
                        new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1", OffsetMin = "16 0", OffsetMax = "0 0" }
                    }
                });
                UI_Toggle(container, slot, player, "vit." + s.Key, s.Text, "", true, !canVitals);
