        private void UI_EspSizeRow(CuiElementContainer container, BasePlayer player, string card, int x, int y, int w)
        {
            UI_Text(container, card, GetLocalizedMessage(TranslateKey.AppEspSize, player), 10, Fonts.Body,
                TextAnchor.MiddleLeft, Palette.CText2, "0 1", "0 1", $"{x} {y - 14}", $"{x + w} {y}");
            var current = EspFontSize(player);
            var gap = 4;
            var cell = (w - (EspSizeChoices.Length - 1) * gap) / EspSizeChoices.Length;
            var sizes = card + ".espsz";
            container.Add(new CuiElement
            {
                Parent = card, Name = sizes, DestroyUi = sizes,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{cell} 22", Spacing = $"{gap} {gap}",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = EspSizeChoices.Length
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{x} {y - 18 - 22}",
                        OffsetMax = $"{x + w} {y - 18}"
                    }
                }
            });
            for (var i = 0; i < EspSizeChoices.Length; i++)
            {
                var size = EspSizeChoices[i];
