        private void UI_FontPicker(CuiElementContainer container, BasePlayer player)
        {
            var key = PeekAdmin(player.userID)?.FontPick;
            if (string.IsNullOrEmpty(key))
                return;
            if (Array.IndexOf(FontKeys, key) < 0)
                return;
            var root = Layers.Body + ".fontpick";
            container.Add(new CuiElement
            {
                Parent = Layers.Body, Name = root, DestroyUi = root,
                Components =
                {
                    new CuiImageComponent { Color = "0 0 0 0.6" }, new CuiNeedsCursorComponent(),
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1" }
                }
            });
            UI_Btn(container, root, "pa.fontpick", Colors.Clear, "0 0", "1 1");

            const int cardW = 380;
            const int cardH = 300;
            var card = root + ".card";
            container.Add(new CuiElement
            {
                Parent = root, Name = card,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CSurface },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = $"{-cardW / 2} {-cardH / 2}",
                        OffsetMax = $"{cardW / 2} {cardH / 2}"
                    }
                }
            });
            UI_Text(container, card,
                $"{GetLocalizedMessage(TranslateKey.AppFontPick, player)}  <color=#7E8AA0>{FontSlotLabel(player, key)}</color>",
                12, Fonts.Title, TextAnchor.MiddleLeft, Palette.CText, "0 1", "1 1", "16 -34", "-40 -10");
            var close = card + ".x";
            UI_CloseX(container, card, "pa.fontpick", "1 1", "1 1", "-34 -32", "-12 -10", close);

            var current = GetFont(player, key);
            for (var i = 0; i < Fonts.All.Length; i++)
            {
                var font = Fonts.All[i];
                var on = font == current;
                var y = -42 - i * 27;
                var row = card + ".fo" + i;
                container.Add(new CuiElement
                {
                    Parent = card, Name = row,
                    Components =
                    {
                        new CuiImageComponent { Color = on ? Palette.CAccentSoft : Palette.CPage },
                        new CuiOutlineComponent { Color = on ? Palette.CAccent : Palette.CBorderSoft, Distance = "1 1" },
                        new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = $"12 {y - 24}", OffsetMax = $"-12 {y}" }
                    }
                });
                var suffix = Fonts.HasCyrillic(font)
                    ? ""
                    : $"  <color=#7E8AA0>{GetLocalizedMessage(TranslateKey.AppFontNoCyr, player)}</color>";
                UI_Text(container, row, Fonts.Label(font) + suffix, 11, Fonts.File(font), TextAnchor.MiddleLeft, Palette.CText,
                    "0 0", "1 1", "10 0", "-10 0");
                UI_Btn(container, row, on ? "" : $"pa.fontset {key} {font}", Colors.Clear, "0 0", "1 1");
            }
        }

