        private void UI_PageSettings(CuiElementContainer container, BasePlayer player)
        {
            UI_Head(container, player, TranslateKey.SettingsTitle, TranslateKey.SettingsSub);
            if (!permission.UserHasPermission(player.UserIDString, Permissions.Settings))
            {
                UI_PrivateCard(container, player, Layers.Body, -60, Positions.BodyW - Positions.Pad * 2);
                UI_Locked(container, player, TranslateKey.LockedTitle, TranslateKey.LockedDesc, "assets/icons/gear.png",
                    -60 - Positions.Map.PrivateCardH - 14);
                return;
            }

            if (Backend == DataStorage.MySql && _db != null && _db.IsSql && !_storageBusy &&
                PeekAdmin(player.userID)?.StorageStatus == null)
            {
                GetAdmin(player.userID).StorageStatus = StorageState.Connecting;
                _db.Query(Sql.Builder.Append("SELECT 1"),
                    rows => SetStorageStatus(player, rows.Count > 0 ? StorageState.Connected : StorageState.Failed));
            }

            var root = UI_Scroll(container, Layers.Body, "settings", 0, -54, Positions.BodyW, Positions.BodyH - 54,
                SettingsHeight(player), null, null);
            UI_SettingsBody(container, player, root);
        }

        private int SettingsHeight(BasePlayer player)
        {
            var h = 0;
            h += (IsCollapsed(player, "priv") ? 38 : Positions.Map.PrivateCardH) + 14;
            h += (IsCollapsed(player, "dc") ? 38 : 540) + 14;
            h += (IsCollapsed(player, "wh") ? 38 : 608) + 14;
            h += (IsCollapsed(player, "bot") ? 38 : 632) + 14;
            h += (IsCollapsed(player, "mapact") ? 38 : Positions.Map.ActionsCardH) + 14;
            h += (IsCollapsed(player, "mapgrp") ? 38 : Positions.Map.GroupCardH) + 14;
            h += (IsCollapsed(player, "pie") ? 38 : PieCardH(PieRows(player).Count)) + 14;
            h += (IsCollapsed(player, "sec") ? 38 : 460) + 14;
            h += (IsCollapsed(player, "api") ? 38 : 100) + 14;
            h += (IsCollapsed(player, "st") ? 38 : 280) + 14;
            h += (IsCollapsed(player, "notify") ? 38 : 262) + 14;
            foreach (var sec in _extSections)
                if (sec.Settings != null)
                    h += (IsCollapsed(player, "ext." + sec.Id) ? 38 : sec.SettingsHeight?.Invoke(player) ?? 200) + 14;
            return h + 16;
        }

        private string StorageStatusInfo(BasePlayer player, out string color)
        {
            var key = PeekAdmin(player.userID)?.StorageStatus ??
                      (Backend == DataStorage.MySql ? StorageState.Connected : StorageState.None);
            switch (key)
            {
                case StorageState.Connecting:
                {
                    color = Colors.CWarn;
                    return GetLocalizedMessage(TranslateKey.StorageStConnecting, player);
                }
                case StorageState.Connected:
                {
                    color = Colors.CSuccess;
                    return GetLocalizedMessage(TranslateKey.StorageStConnected, player);
                }
                case StorageState.Migrating:
                {
                    color = Colors.CInfo;
                    return GetLocalizedMessage(TranslateKey.StorageStMigrating, player);
                }
                case StorageState.Failed:
                {
                    color = Colors.CDanger;
                    return GetLocalizedMessage(TranslateKey.StorageStFailed, player);
                }
                case StorageState.MigrateFailed:
                {
                    color = Colors.CDanger;
                    return GetLocalizedMessage(TranslateKey.StorageStMigrateFailed, player);
                }
                default:
                {
                    color = Palette.CText3;
                    return GetLocalizedMessage(TranslateKey.StorageStNone, player);
                }
            }
        }

        private void SetStorageStatus(BasePlayer player, StorageState state)
        {
            if (player == null)
                return;
            GetAdmin(player.userID).StorageStatus = state;
            RefreshSettings(player);
        }

        private void RefreshSettings(BasePlayer player)
        {
            if (player == null || PeekAdmin(player.userID)?.UiOpen != true || GetPage(player) != "settings")
                return;
            ApplyTheme(player);
            var container = new CuiElementContainer();
            UI_SettingsBody(container, player, SettingsContent);
            CuiHelper.AddUi(player, container);
        }

