            UI_Text(container, bot, GetLocalizedMessage(TranslateKey.DiscordRolesMute, player), 10, Fonts.Body,
                TextAnchor.UpperLeft, Palette.CText2, "0 1", "0 1", $"{rmX} -468", $"{rmX + rcw} -454");
            UI_Text(container, bot, GetLocalizedMessage(TranslateKey.DiscordRolesSuper, player), 10, Fonts.Body,
                TextAnchor.UpperLeft, Palette.CText2, "0 1", "0 1", $"{rsX} -468", $"{rsX + rcw} -454");
            var kickLabel = !hasRoles ? GetLocalizedMessage(TranslateKey.DiscordRolesHint, player)
                : kickSet.Count == 0 ? GetLocalizedMessage(TranslateKey.DiscordRolesNone, player)
                : kickSet.Count == 1 ? RoleColored(kickSet.First())
                : SafeFormat(GetLocalizedMessage(TranslateKey.DiscordRolesCount, player), kickSet.Count);
            UI_Btn(container, bot, "  " + kickLabel, hasRoles ? "pa.dcrole rkick" : "", Palette.CElev, 11, Fonts.Body,
                TextAnchor.MiddleLeft, kickSet.Count > 0 ? Palette.CText : Palette.CText3, "0 1", "0 1", $"{rkX} -496",
                $"{rkX + rcw} -470", bot + ".rkbtn");
            var muteLabel = !hasRoles ? GetLocalizedMessage(TranslateKey.DiscordRolesHint, player)
                : muteSet.Count == 0 ? GetLocalizedMessage(TranslateKey.DiscordRolesNone, player)
                : muteSet.Count == 1 ? RoleColored(muteSet.First())
                : SafeFormat(GetLocalizedMessage(TranslateKey.DiscordRolesCount, player), muteSet.Count);
            UI_Btn(container, bot, "  " + muteLabel, hasRoles ? "pa.dcrole rmute" : "", Palette.CElev, 11, Fonts.Body,
                TextAnchor.MiddleLeft, muteSet.Count > 0 ? Palette.CText : Palette.CText3, "0 1", "0 1", $"{rmX} -496",
                $"{rmX + rcw} -470", bot + ".rmbtn");
            var superLabel = !hasRoles ? GetLocalizedMessage(TranslateKey.DiscordRolesHint, player)
                : superId.Length == 0 ? GetLocalizedMessage(TranslateKey.DiscordRolesNone, player)
                : RoleColored(superId);
            UI_Btn(container, bot, "  " + superLabel, hasRoles ? "pa.dcrole rsuper" : "", Palette.CElev, 11, Fonts.Body,
                TextAnchor.MiddleLeft, superId.Length > 0 ? Palette.CText : Palette.CText3, "0 1", "0 1",
                $"{rsX} -496", $"{rsX + rcw} -470", bot + ".rsbtn");

            UI_SettingsSub(container, bot, GetLocalizedMessage(TranslateKey.DiscordStatusCfg, player), -522);
            string[] actk = { "playing", "watching", "listening", "competing" };
            string[] actl =
            {
                GetLocalizedMessage(TranslateKey.DiscordActPlaying, player),
                GetLocalizedMessage(TranslateKey.DiscordActWatching, player),
                GetLocalizedMessage(TranslateKey.DiscordActListening, player),
                GetLocalizedMessage(TranslateKey.DiscordActCompeting, player)
            };
            UI_SegmentRow(container, bot, player, FieldKey.DiscordActype, "playing", actk, actl, 16, -550, pw - 32, 26);
            UI_SettingsLabelInput(container, bot, player, FieldKey.DiscordActext,
                GetLocalizedMessage(TranslateKey.DiscordStatusText, player),
                "{online}/{maxonline} online · queue {queue}", 16, -582, pw - 32);

            if (roleDdOpen)
            {
                var which = ddOpen;
                var multi = which != "rsuper";
                var curSet = which == "rkick" ? kickSet : which == "rmute" ? muteSet : null;
                var ddX = which == "rkick" ? rkX : which == "rmute" ? rmX : rsX;
                var rdH = botBaseH - 508;
                var content = UI_ScrollList(container, bot, "roledd", ddX, -500, rcw, rdH, 28, 2,
                    Discord.Roles.Count + 1, 2, 1, Palette.CSurface, Palette.CBorderSoft);
                var rows = new List<string[]> { new[] { "none", GetLocalizedMessage(TranslateKey.DiscordRolesNone, player) } };
                rows.AddRange(Discord.Roles);
                for (var i = 0; i < rows.Count; i++)
                {
                    var rid = rows[i][0];
                    var sel = rid == "none"
                        ? (multi ? curSet.Count == 0 : superId.Length == 0)
                        : (multi ? curSet.Contains(rid) : rid == superId);
                    var rowName = content + ".r" + i;
                    var rowText = rows[i].Length > 2 ? ColorWrap(rows[i][1], rows[i][2]) : rows[i][1];
                    UI_Btn(container, content, "   " + rowText, $"pa.dcrolesel {which} {rid}",
                        i % 2 == 1 ? Palette.CElev : Colors.Clear, 11, Fonts.Body, TextAnchor.MiddleLeft,
                        sel ? Palette.CText : Palette.CText2, "0 1", "1 1", $"0 {-i * 30 - 28}", $"0 {-i * 30}",
                        rowName);
                    UI_CheckBox(container, rowName, sel);
                }
            }

            if (IsDropdownKey(ddOpen))
            {
                var opts = ddOpen == "guild" ? Discord.Guilds : Discord.Channels;
                var curId = DiscordInput(DropdownInputKey(ddOpen));
                var ox = ddOpen switch
                {
                    "guild" => 16 + dw + 16,
                    "cbans" => 16,
                    "cchat" => 16 + dw + 16,
                    "cact" => 16,
                    "cerr" => 16 + dw + 16,
                    _ => 16
                };
                var oy = ddOpen switch
                {
                    "guild" => -150,
                    "cbans" => -234,
                    "cchat" => -234,
                    "cact" => -286,
                    "cerr" => -286,
                    _ => -150
                };
                UI_DropdownOverlay(container, bot, player, ddOpen, curId, opts, ox, oy, dw - 8);
            }

            return y - botExpandedH - 14;
        }


        private int UI_PrivateCard(CuiElementContainer container, BasePlayer player, string root, int y, int pw)
        {
