        private static string[] MapActionDef(string key) => Array.Find(MapActionDefs, def => def[0] == key);

        private int UI_MapActionsCard(CuiElementContainer container, BasePlayer player, string root, int y, int pw)
        {
            var card = UI_SectionCard(container, root, player, "mapact",
                GetLocalizedMessage(TranslateKey.QbMapActions, player), Positions.Map.ActionsCardH, y, pw, out var col);
            if (col)
                return y - 38 - 14;
            var picked = MapActionDefs.Count(def => cfg != null && cfg.MapActions.Contains(def[0]));
            var counter = card + ".macount";
            container.Add(new CuiElement
            {
                Parent = card, Name = counter,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CElev },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "1 1", AnchorMax = "1 1", OffsetMin = "-140 -32", OffsetMax = "-16 -8" }
                }
            });
            UI_Text(container, counter,
                SafeFormat(GetLocalizedMessage(TranslateKey.MapActSelected, player), picked, MapActionDefs.Length),
                10, Fonts.Title, TextAnchor.MiddleCenter, Palette.CAccent, "0 0", "1 1");

            var cols = MapActionGroupTitles.Length;
            var chipW = (pw - 32 - (cols - 1) * Positions.Map.ActionsColGap) / cols;
            for (var g = 0; g < MapActionGroupTitles.Length; g++)
                UI_Text(container, card, GetLocalizedMessage(MapActionGroupTitles[g], player), 9, Fonts.Title,
                    TextAnchor.MiddleLeft, Palette.CText3, "0 1", "0 1",
                    $"{16 + g * (chipW + Positions.Map.ActionsColGap)} -60",
                    $"{16 + g * (chipW + Positions.Map.ActionsColGap) + chipW} -46");

            var gridH = Positions.Map.ActionsRows * Positions.Map.ActionsRowH + (Positions.Map.ActionsRows - 1) * Positions.Map.ActionsRowGap;
            var grid = card + ".magrid";
            container.Add(new CuiElement
            {
                Parent = card, Name = grid,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{chipW} {Positions.Map.ActionsRowH}",
                        Spacing = $"{Positions.Map.ActionsColGap} {Positions.Map.ActionsRowGap}",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Vertical,
                        ChildAlignment = TextAnchor.UpperLeft, Constraint = GridLayoutGroup.Constraint.FixedRowCount,
                        ConstraintCount = Positions.Map.ActionsRows
                    },
                    new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = $"16 {-60 - gridH}", OffsetMax = "-16 -60" }
                }
            });
            for (var i = 0; i < MapActionDefs.Length; i++)
            {
                var def = MapActionDefs[i];
                var key = def[0];
                var on = cfg != null && cfg.MapActions.Contains(key);
                var tint = MapActionColor(def[3]);
                var chip = card + ".ma" + i;
                container.Add(new CuiElement
                {
                    Parent = grid, Name = chip,
                    Components =
                    {
                        new CuiImageComponent { Color = on ? Palette.CElev : Colors.Clear },
                        new CuiOutlineComponent { Color = on ? tint : Palette.CBorder, Distance = "1 1" }
                    }
                });
                container.Add(new CuiElement
                {
                    Parent = chip,
                    Components =
                    {
                        new CuiImageComponent { Color = on ? tint : Palette.CText3, Sprite = def[2] },
                        new CuiRectTransformComponent { AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = "8 -6", OffsetMax = "20 6" }
                    }
                });
                UI_Text(container, chip, GetLocalizedMessage(def[1], player), 10, Fonts.Title, TextAnchor.MiddleLeft,
                    on ? tint : Palette.CText2, "0 0", "1 1", "26 0", "-34 0");
                UI_Text(container, chip, GetLocalizedMessage(on ? TranslateKey.MapActOn : TranslateKey.MapActOff, player), 8,
                    Fonts.Title, TextAnchor.MiddleRight, on ? tint : Palette.CText3, "0 0", "1 1", "0 0", "-8 0");
                UI_Btn(container, chip, $"pa.mapact {key}", Colors.Clear, "0 0", "1 1");
            }

            return y - Positions.Map.ActionsCardH - 14;
        }


        private int UI_MapGroupCard(CuiElementContainer container, BasePlayer player, string root, int y, int pw)
