        private static int PieCardH(int rows) => 56 + (rows + 1) / 2 * 36;

        private int UI_PieCard(CuiElementContainer container, BasePlayer player, string root, int y, int pw)
        {
            var rows = PieRows(player);
            var h = PieCardH(rows.Count);
            var card = UI_SectionCard(container, root, player, "pie",
                GetLocalizedMessage(TranslateKey.SettingsPie, player), h, y, pw, out var col);
            if (col)
                return y - 38 - 14;
            var colW = (pw - 48) / 2;
            var perCol = (rows.Count + 1) / 2;
            for (var i = 0; i < rows.Count; i++)
            {
                var x = i < perCol ? 16 : 32 + colW;
                var row = i < perCol ? i : i - perCol;
                UI_Toggle(container, card, player, PieKeyPrefix + rows[i][0], GetLocalizedMessage(rows[i][2], player),
                    GetLocalizedMessage(TranslateKey.SettingsPieD, player), true, x, -44 - row * 36, colW);
            }

            return y - h - 14;
        }

        private void UI_SettingsBody(CuiElementContainer container, BasePlayer player, string root)
        {
            var pw = Positions.BodyW - Positions.Pad * 2;
