                    GetLocalizedMessage(TranslateKey.SecurityHeatWindow, player), "60", 16, -198, 216);
                UI_SettingsLabelInput(container, sec, player, FieldKey.SecurityTemplates,
                    GetLocalizedMessage(TranslateKey.SecurityTemplates, player),
                    "Cheating | Toxicity | AFK | Teaming", 16, -246, pw - 32);
                UI_Toggle(container, sec, player, "sec.lockpa", GetLocalizedMessage(TranslateKey.SecurityLockPa, player),
                    GetLocalizedMessage(TranslateKey.SecurityLockPaD, player), false, 16, -296, pw - 32);
                UI_SettingsSub(container, sec, GetLocalizedMessage(TranslateKey.SecurityHammerBounds, player), -332);
                UI_SettingsLabelInput(container, sec, player, FieldKey.SecHammerInt,
                    GetLocalizedMessage(TranslateKey.HammerIntervalLabel, player), "0.25", 16, -358, 216);
