                UI_SettingsLabelInput(container, sec, player, FieldKey.SecHammerItem, "item", "hammer", 480, -358, 212);
                UI_SettingsLabelInput(container, sec, player, FieldKey.SecHammerCrate,
                    GetLocalizedMessage(TranslateKey.SecurityCrateSeconds, player), "60", 16, -406, 216);
            }

            y -= (secCol ? 38 : secH) + 14;

            const int apiH = 100;
            var api = UI_SectionCard(container, root, player, "api", GetLocalizedMessage(TranslateKey.SettingsApi, player),
                apiH, y, pw, out var apiCol);
            if (!apiCol)
            {
                UI_SettingsLabelInput(container, api, player, FieldKey.ApiSteamkey,
                    GetLocalizedMessage(TranslateKey.ApiSteamKey, player),
                    GetLocalizedMessage(TranslateKey.ApiSteamKeyPh, player), 16, -46, pw - 32, pass: true);
                UI_Tip(container, GetLocalizedMessage(TranslateKey.ApiSteamKeyD, player));
            }

            y -= (apiCol ? 38 : apiH) + 14;

            const int stH = 280;
            var st = UI_SectionCard(container, root, player, "st", GetLocalizedMessage(TranslateKey.SettingsStorage, player),
                stH, y, pw, out var stCol);
            if (!stCol)
            {
                string[] bk = { "json", "sqlite", "mysql" };
                for (var i = 0; i < bk.Length; i++)
                {
                    var on = bk[i] == stSel;
                    UI_Btn(container, st, bk[i].ToUpperInvariant(), $"pa.storagesel {bk[i]}",
                        on ? Palette.CAccent : Palette.CElev, 11, Fonts.Title, TextAnchor.MiddleCenter,
                        on ? Palette.CAccentText : Palette.CText2, "0 1", "0 1", $"{16 + i * 96} -72",
                        $"{16 + i * 96 + 90} -46", st + ".bk" + i);
                }

                var pendingSwitch = stSel != StorageId(cfg.Storage);
                var migrateReady = stSel != "mysql" ||
                                   (PeekAdmin(player.userID)?.StorageStatus == StorageState.Connected);
                UI_Text(container, st,
                    pendingSwitch ? GetLocalizedMessage(TranslateKey.StorageMigrateQ, player) : GetLocalizedMessage(TranslateKey.StorageNote, player),
                    9, Fonts.Body, TextAnchor.MiddleLeft, Palette.CText3, "0 1", "1 1", "316 -72", "-190 -46",
                    st + ".mig" + ".1790277387");
                if (pendingSwitch && PeekAdmin(player.userID)?.StorageConfirm == true)
                {
                    UI_Btn(container, st, GetLocalizedMessage(TranslateKey.ConfirmNo, player), "pa.storagemig 0",
                        Palette.CElev, 10, Fonts.Title, TextAnchor.MiddleCenter, Palette.CText2, "1 1", "1 1",
                        "-180 -72", "-100 -46");
                    UI_Btn(container, st, GetLocalizedMessage(TranslateKey.ConfirmYes, player), "pa.storagemig 1",
                        Colors.CSuccess, 10, Fonts.Title, TextAnchor.MiddleCenter, Palette.CAccentText, "1 1", "1 1",
                        "-92 -72", "-16 -46");
                }
                else if (pendingSwitch)
