                            Font = Fonts.Title, Align = TextAnchor.MiddleCenter,
                            Color = migrateReady ? Palette.CAccentText : Palette.CText3
                        },
                        RectTransform = { AnchorMin = "1 1", AnchorMax = "1 1", OffsetMin = "-180 -72", OffsetMax = "-16 -46" }
                    }, st);
                }

                if (mysql)
                {
                    var hw = (pw - 32 - 12) / 2;

                    UI_StorageCfgField(container, st, "host", GetLocalizedMessage(TranslateKey.StorageHost, player),
                        cfg.MySql.Host, 16, -90, hw, false);
