                        cfg.MySql.Database, 16, -144, hw, false);
                    UI_StorageCfgField(container, st, "user", GetLocalizedMessage(TranslateKey.StorageUser, player),
                        cfg.MySql.User, 16 + hw + 12, -144, hw, false);
                    UI_StorageCfgField(container, st, "password", GetLocalizedMessage(TranslateKey.StoragePass, player),
