                    var stText = StorageStatusInfo(player, out var stColor);
                    UI_Text(container, st, "●  " + stText, 11, Fonts.Title, TextAnchor.MiddleLeft, stColor, "0 1", "1 1",
                        "16 -270", $"{pw - 16} -252");
                }
                else
                {
                    UI_Text(container, st, GetLocalizedMessage(TranslateKey.StorageDesc + stSel, player), 11, Fonts.Body,
                        TextAnchor.UpperLeft, Palette.CText2, "0 1", "1 1", "16 -210", $"{pw - 16} -92");
                }
            }

            y -= (stCol ? 38 : stH) + 14;

            const int notifyH = 262;
            var ntf = UI_SectionCard(container, root, player, "notify",
                GetLocalizedMessage(TranslateKey.SettingsNotify, player), notifyH, y, pw, out var ntfCol);
            if (!ntfCol)
            {
