                string[] npk = { "auto", "notify", "ncp", "chat", "off" };
                string[] npl =
                {
                    GetLocalizedMessage(TranslateKey.NotifyProviderAuto, player),
                    GetLocalizedMessage(TranslateKey.NotifyProviderNotify, player),
                    GetLocalizedMessage(TranslateKey.NotifyProviderNcp, player),
                    GetLocalizedMessage(TranslateKey.NotifyProviderChat, player),
                    GetLocalizedMessage(TranslateKey.NotifyProviderOff, player)
                };
                UI_SegmentRow(container, ntf, player, FieldKey.NotifyProvider, "auto", npk, npl, 16, -60, pw - 32, 26);
                UI_Tip(container, GetLocalizedMessage(TranslateKey.NotifyProviderD, player));

                UI_SettingsSub(container, ntf, GetLocalizedMessage(TranslateKey.NotifySubNotify, player), -100);
                var tw = (pw - 32 - 24) / 3;
                UI_SettingsLabelInput(container, ntf, player, FieldKey.NotifySuccess,
                    GetLocalizedMessage(TranslateKey.NotifyTypeSuccess, player), "0", 16, -126, tw);
                UI_SettingsLabelInput(container, ntf, player, FieldKey.NotifyError,
                    GetLocalizedMessage(TranslateKey.NotifyTypeError, player), "1", 16 + tw + 12, -126, tw);
                UI_SettingsLabelInput(container, ntf, player, FieldKey.NotifyPlayer,
                    GetLocalizedMessage(TranslateKey.NotifyTypePlayer, player), "0", 16 + 2 * (tw + 12), -126, tw);

                UI_SettingsSub(container, ntf, GetLocalizedMessage(TranslateKey.NotifySubNcp, player), -180);
                UI_SettingsLabelInput(container, ntf, player, FieldKey.NcpSuccess,
                    GetLocalizedMessage(TranslateKey.NcpTypeSuccess, player), "3", 16, -206, tw);
                UI_SettingsLabelInput(container, ntf, player, FieldKey.NcpError,
                    GetLocalizedMessage(TranslateKey.NcpTypeError, player), "2", 16 + tw + 12, -206, tw);
                UI_SettingsLabelInput(container, ntf, player, FieldKey.NcpPlayer,
                    GetLocalizedMessage(TranslateKey.NcpTypePlayer, player), "0", 16 + 2 * (tw + 12), -206, tw);
            }

            y -= (ntfCol ? 38 : notifyH) + 14;
            foreach (var ext in _extSections)
            {
                if (ext.Settings == null)
                    continue;
                var extHeight = ext.SettingsHeight?.Invoke(player) ?? 200;
                var card = UI_SectionCard(container, root, player, "ext." + ext.Id, ext.Title?.Invoke(player) ?? ext.Id,
                    extHeight, y, pw, out var extCol);
                if (!extCol)
                    ext.Settings.Invoke(player, container, card, pw);
                y -= (extCol ? 38 : extHeight) + 14;
            }
