        private bool IsCollapsed(BasePlayer p, string key) =>
            p != null && PeekAdmin(p.userID)?.SettingsCollapsed?.Contains(key) == true;

        private string UI_SectionCard(CuiElementContainer container, string root, BasePlayer player,
            string key, string title, int expandedH, int y, int pw, out bool collapsed)
        {
            collapsed = IsCollapsed(player, key);
            var name = UI_SettingsCard(container, root, null, Positions.Pad, y, pw, collapsed ? 38 : expandedH,
                root + "." + key);
            UI_Btn(container, name, collapsed ? "▶" : "▼", $"pa.scollapse {key}", Colors.Clear, 11, Fonts.Title,
                TextAnchor.MiddleCenter, Palette.CText2, "0 1", "0 1", "8 -32", "30 -6");
            UI_Btn(container, name, title, $"pa.scollapse {key}", Colors.Clear, 12, Fonts.Title, TextAnchor.MiddleLeft,
                Palette.CText, "0 1", "1 1", "32 -36", "-160 0");
            if (!collapsed)
                container.Add(new CuiPanel
                {
                    Image = { Color = Palette.CBorder },
                    RectTransform = { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = "0 -37", OffsetMax = "0 -36" }
                }, name);
            return name;
        }

