        private void UI_Popup(CuiElementContainer container, BasePlayer player)
        {
            var sid = PeekAdmin(player.userID)?.Popup ?? 0;
            if (sid == 0)
            {
                container.Add(new CuiElement
                {
                    Parent = Layers.Root, Name = Layers.PopupRoot, DestroyUi = Layers.PopupRoot,
                    Components =
                    {
                        new CuiImageComponent { Color = Colors.Clear },
                        new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "0 0", OffsetMin = "0 0", OffsetMax = "0 0" }
                    }
                });
                return;
            }
            var pl = GetDropdownEntry(sid);
            var act = PeekAdmin(player.userID)?.PopupAction;

            var enabled = Array.ConvertAll(PopupActionDefs, def => PopupActionAllowed(player, def[0]));

            var comingSoon = new HashSet<string>();
            for (var i = 0; i < PopupActionDefs.Length; i++)
                if (!enabled[i])
                    comingSoon.Add(PopupActionDefs[i][0]);
            if (FindPopupAction("ban") != null)
                comingSoon.Remove("ban");
            if (FindPopupAction("freeze") != null)
                comingSoon.Remove("freeze");

            var online = FindOnline(sid) != null;
            var body = FindActiveOrSleeping(sid);
            var aliveBody = body != null && !body.IsDead();
            for (var i = 0; i < PopupActionDefs.Length; i++)
            {
                var k = PopupActionDefs[i][0];
                if (!enabled[i])
                    continue;
                if (!CanAction(player, k))
                    enabled[i] = false;
                if (sid == player.userID && (k == "inv" || k == "spectate"))
                    enabled[i] = false;
                if (!online && (k == "kick" || k == "spectate" || k == "inv" || k == "give" || k == "bp" ||
                                k == "mod" || k == "vitals"))
                    enabled[i] = false;
                if (!aliveBody && (k == "heal" || k == "kill" || k == "strip" || k == "tp" || k == "give" ||
                                   k == "inv" || k == "showmap"))
                    enabled[i] = false;
            }

            var isGive = act == "give";
            var isPerms = act == "perms";
            var isBp = act == "bp";
            var isMod = act == "mod";
            var isVitals = act == "vitals";
            var isEco = act == "eco";
            var isGrid = act == null;
            var quick = isGrid ? QuickFor(player, QuickTarget.Player, QuickPlace.Popup) : new List<QuickButton>();
            var quickRows = Mathf.Min(QuickRows(quick.Count, 2), Positions.Quick.PopupMaxRows);
            var quickBodyH = quickRows * (Positions.Quick.RowH + Positions.Quick.RowGap);
            var quickH = quick.Count == 0 ? 0 : quickBodyH + 24;
            var gridH = 64 + ((PopupActionDefs.Length + 1) / 2 - 1) * 48 + 40;
            var cw = isGive || isPerms || isBp || isMod || isVitals || isEco ? 700 : isGrid ? 720 : 440;
            var ch = isGive || isPerms || isBp || isMod || isVitals || isEco ? 470 :
                isGrid ? gridH + 30 + quickH :
                act == "mute" ? 490 :
                act == "kick" ? 410 : 360;

            container.Add(new CuiElement
            {
                Parent = Layers.Root, Name = Layers.PopupRoot, DestroyUi = Layers.PopupRoot,
                Components =
                {
                    new CuiImageComponent { Color = "0 0 0 0.65" }, new CuiNeedsCursorComponent(),
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1" }
                }
            });
            UI_Btn(container, Layers.PopupRoot, "pa.popup close", Colors.Clear, "0 0", "1 1");

            var card = Layers.Root + ".pop.card";
            container.Add(new CuiElement
            {
                Parent = Layers.PopupRoot, Name = card,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CSurface },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = $"{-cw / 2} {-ch / 2}",
                        OffsetMax = $"{cw / 2} {ch / 2}"
                    }
                }
            });

            container.Add(
                new CuiPanel
                {
                    Image = { Color = Palette.CElev },
                    RectTransform = { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = "0 -52", OffsetMax = "0 0" }
                }, card);
            container.Add(
                new CuiPanel
                {
                    Image = { Color = Palette.CAccent },
                    RectTransform = { AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = "0 -52", OffsetMax = "3 0" }
                }, card);
            UI_Avatar(container, card, pl.SteamId, 12, -10, 32);
            UI_Text(container, card, pl.DisplayName, 14, Fonts.Title, TextAnchor.LowerLeft, Palette.CText, "0 1", "1 1",
                "52 -29", "-48 -10");
            UI_Text(container, card, $"{pl.SteamId} · {GetLocalizedMessage(TranslateKey.DropdownManageTitle, player)}", 9,
                Fonts.Console, TextAnchor.UpperLeft, Palette.CText2, "0 1", "1 1", "52 -44", "-48 -29");
            UI_CloseX(container, card, "pa.popup close", "1 1", "1 1", "-40 -40", "-12 -12", card + ".x", 6);

            if (act == null)
            {
                UI_PopupGrid(container, card, 440, player, enabled, comingSoon);
                if (quick.Count > 0)
                {
                    UI_Text(container, card, GetLocalizedMessage(TranslateKey.QbActions, player), 11, Fonts.Title,
                        TextAnchor.MiddleLeft, Palette.CText2, "0 1", "1 1", $"12 {-gridH - 22}", $"-12 {-gridH - 4}");
                    if (QuickRows(quick.Count, 2) <= Positions.Quick.PopupMaxRows)
                        UI_QuickRow(container, card, quick, sid, 12, -gridH - 26, 440 - 24, 2);
                    else
                    {
                        var qs = UI_Scroll(container, card, "qbs", 12, -gridH - 26, 440 - 24, quickBodyH,
                            QuickBlockH(quick.Count, 2), null, null);
                        UI_QuickRow(container, qs, quick, sid, 0, 0, 440 - 24, 2);
                    }
                }

                UI_PopupStats(container, card, 452, cw, player, pl);
                return;
            }

            if (isGive)
            {
                UI_GivePicker(container, card, cw, ch, player, pl);
                return;
            }

            if (isBp)
            {
                UI_BlueprintPicker(container, card, cw, ch, player, pl);
                return;
            }

            if (isMod)
            {
                UI_ModifiersPicker(container, card, cw, ch, player, pl);
                return;
            }

            if (isVitals)
            {
                UI_VitalsPicker(container, card, cw, ch, player, pl);
                return;
            }

            if (isEco)
            {
                UI_EconomyPicker(container, card, cw, ch, player, pl);
                return;
            }

            if (act == "notes")
            {
                UI_NotesPicker(container, card, player, pl);
                return;
            }

            if (isPerms)
            {
                UI_PopupPerms(container, card, cw, ch, player, pl);
                return;
            }

            var actIdx = Array.FindIndex(PopupActionDefs, d => d[0] == act);
            if (actIdx >= 0 && enabled[actIdx])
            {
                var def = PopupActionDefs[actIdx];
                UI_PopupAction(container, card, cw, ch, player, pl, def[0], GetLocalizedMessage(def[1], player), def[3],
                    def[2] ?? Palette.CAccent, def[4]);
            }
        }

        private bool PopupActionAllowed(BasePlayer player, string key) => key switch
        {
            "ban" => CanPopupAction(player, "ban"),
            "freeze" => CanPopupAction(player, "freeze"),
            "showmap" => Can(player, Permissions.Map),
            _ => true
        };

        private void UI_PopupPerms(CuiElementContainer container, string card, int cw, int ch, BasePlayer player,
            DropdownEntry pl)
        {
            UI_PopupBack(container, card, player);
            UI_PickerTitle(container, card, player, TranslateKey.PopupPerms, pl);
            ulong.TryParse(pl.SteamId, out var sid);
            var id = sid.ToString();

            const int top = -96, leftX = 12, leftW = 226;
            var colH = ch + top - 12;
            var rightX = leftX + leftW + 10;
            var rightW = cw - 12 - rightX;

            UI_Text(container, card, GetLocalizedMessage(TranslateKey.PermsGroups, player), 11, Fonts.Title,
                TextAnchor.UpperLeft, Palette.CText2, "0 1", "0 1", $"{leftX} {top - 14}", $"{leftX + leftW} {top}");
            var userGroups = new HashSet<string>(permission.GetUserGroups(id) ?? Array.Empty<string>(),
                StringComparer.OrdinalIgnoreCase);
            var groups = (permission.GetGroups() ?? Array.Empty<string>())
                .OrderBy(g => g, StringComparer.OrdinalIgnoreCase).ToList();
            var gScroll = UI_Scroll(container, card, "upg", leftX, top - 20, leftW, colH - 20,
                Mathf.Max(groups.Count * 30 + 6, colH - 20), Palette.CPage, Palette.CBorder);
            for (var i = 0; i < groups.Count; i++)
            {
                var g = groups[i];
                var on = userGroups.Contains(g);
                var gy = -4 - i * 30;
                var rn = gScroll + ".g" + i;
                container.Add(new CuiElement
                {
                    Parent = gScroll, Name = rn,
                    Components =
                    {
                        new CuiImageComponent { Color = on ? Palette.CAccent : Palette.CElev2 },
                        new CuiOutlineComponent { Color = on ? Palette.CAccent : Palette.CBorder, Distance = "1 1" },
                        new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"8 {gy - 22}", OffsetMax = $"38 {gy - 2}" }
                    }
                });
                container.Add(new CuiElement
                {
                    Parent = rn,
                    Components =
                    {
                        new CuiImageComponent { Color = on ? Palette.CAccentText : Palette.CText2 },
                        new CuiRectTransformComponent
                        {
                            AnchorMin = on ? "1 0" : "0 0", AnchorMax = on ? "1 0" : "0 0",
                            OffsetMin = on ? "-18 2" : "2 2", OffsetMax = on ? "-2 18" : "18 18"
                        }
                    }
                });
                UI_Text(container, gScroll, g, 11, Fonts.Title, TextAnchor.MiddleLeft, on ? Palette.CText : Palette.CText2,
                    "0 1", "1 1", $"46 {gy - 24}", $"-6 {gy}");
                UI_Btn(container, gScroll, $"pa.usergroup {g}", Colors.Clear, "0 1", "1 1", $"6 {gy - 24}", $"-6 {gy}");
            }

            UI_Text(container, card, GetLocalizedMessage(TranslateKey.PermsUserperms, player), 11, Fonts.Title,
                TextAnchor.UpperLeft, Palette.CText2, "0 1", "1 1", $"{rightX} {top - 14}", $"{rightX + rightW} {top}");
            UI_Input(container, card, player, FieldKey.UserpermSearch, GetLocalizedMessage(TranslateKey.PermsSearchPh, player),
                rightX, top - 18, rightW, 26);
            var search = GetInput(player, FieldKey.UserpermSearch, "").Trim().ToLowerInvariant();
            var entries = PermEntries(search);
            var pScroll = UI_ScrollStack(container, card, "upp", rightX, top - 50, rightW, colH - 50,
                PermContentHeight(entries), 0, 4, Palette.CPage, Palette.CBorder);
            UI_PermList(container, pScroll, entries, p => permission.UserHasPermission(id, p), "pa.userperm",
                p => UserInheritedFrom(id, p));
        }

