        private void UI_PopupGrid(CuiElementContainer container, string card, int cw, BasePlayer player, bool[] states,
            HashSet<string> comingSoon)
        {
            const int cols = 2;
            var aw = (cw - 24 - (cols - 1) * 10) / cols;
            const int ah = 40;
            var rows = (PopupActionDefs.Length + cols - 1) / cols;
            var grid = card + ".agrid";
            container.Add(new CuiElement
            {
                Parent = card, Name = grid,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{aw} {ah}", Spacing = "10 8", StartCorner = GridLayoutGroup.Corner.UpperLeft,
                        StartAxis = GridLayoutGroup.Axis.Horizontal, ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = cols
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"12 {-64 - rows * (ah + 8) + 8}",
                        OffsetMax = $"{12 + cw - 24} -64"
                    }
                }
            });
            for (var i = 0; i < PopupActionDefs.Length; i++)
            {
                var key = PopupActionDefs[i][0];
                var enabled = states[i];
                var ic = PopupActionDefs[i][2] ?? Palette.CAccent;
                var b = card + ".a" + i;
                container.Add(new CuiElement
                {
                    Parent = grid, Name = b,
                    Components =
                    {
                        new CuiImageComponent { Color = enabled ? WithAlpha(ic, 0.10f) : Palette.CElev },
                        new CuiOutlineComponent { Color = enabled ? WithAlpha(ic, 0.45f) : Palette.CBorder, Distance = "1 1" }
                    }
                });
                container.Add(
                    new CuiPanel
                    {
                        Image = { Color = enabled ? ic : Palette.CElev2 },
                        RectTransform = { AnchorMin = "0 0", AnchorMax = "0 1", OffsetMin = "0 0", OffsetMax = "3 0" }
                    }, b);
                container.Add(
                    new CuiPanel
                    {
                        Image = { Color = enabled ? ic : Palette.CElev2 },
                        RectTransform = { AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = "10 -14", OffsetMax = "38 14" }
                    }, b, b + ".ic");
                container.Add(new CuiElement
                {
                    Parent = b + ".ic",
                    Components =
                    {
                        new CuiImageComponent { Color = enabled ? Palette.CAccentText : Palette.CText3, Sprite = PopupActionDefs[i][4] },
                        new CuiRectTransformComponent { AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = "-8 -8", OffsetMax = "8 8" }
                    }
                });
                UI_Text(container, b, GetLocalizedMessage(PopupActionDefs[i][1], player), 12, Fonts.Title,
                    TextAnchor.MiddleLeft, enabled ? Palette.CText : Palette.CText3, "0 0", "1 1", "48 0", "-8 0");
                if (!enabled && comingSoon != null && comingSoon.Contains(key))
                    UI_Text(container, b,
                        GetLocalizedMessage(key == "ban" || key == "freeze" ? TranslateKey.DiscordBanDlc : TranslateKey.PopupSoon, null),
                        8, Fonts.Title, TextAnchor.MiddleRight,
                        key == "ban" || key == "freeze" ? Palette.CAccent : Palette.CText3, "0 0", "1 1", "0 0",
                        "-10 0");
                UI_Btn(container, b, enabled ? $"pa.act {key}" : "", Colors.Clear, "0 0", "1 1");
                UI_Tip(container, GetLocalizedMessage(PopupActionDefs[i][5], player));
            }
        }

        private void UI_PopupStats(CuiElementContainer container, string card, int x0, int cw, BasePlayer player,
            DropdownEntry pl)
        {
            ulong.TryParse(pl.SteamId, out var sid);
            var bp = FindOnline(sid);
            _players.TryGetValue(sid, out var sp);

            var panel = card + ".stats";
            container.Add(new CuiElement
            {
                Parent = card, Name = panel, DestroyUi = panel,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CPage },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "0 1", OffsetMin = $"{x0} 12", OffsetMax = $"{cw - 12} -56" }
                }
            });
            UI_Text(container, panel, GetLocalizedMessage(TranslateKey.StatsTitle, player), 12, Fonts.Title,
                TextAnchor.UpperLeft, Palette.CText, "0 1", "1 1", "10 -24", "-10 -6");

            string status;
            string statusColor;
            if (bp == null)
            {
                status = GetLocalizedMessage(TranslateKey.StateOffline, player);
                statusColor = Palette.CText3;
            }
            else if (bp.IsDead())
            {
                status = GetLocalizedMessage(TranslateKey.StateDead, player);
                statusColor = Colors.CDanger;
            }
            else if (bp.IsWounded())
            {
                status = GetLocalizedMessage(TranslateKey.StateWounded, player);
                statusColor = Colors.CDanger;
            }
            else if (bp.IsSleeping())
            {
                status = GetLocalizedMessage(TranslateKey.StateSleeping, player);
                statusColor = Colors.CWarn;
            }
            else
            {
                status = GetLocalizedMessage(TranslateKey.StateOnline, player);
                statusColor = Colors.CSuccess;
            }

            var playSeconds = sp?.Playtime ?? 0;
            var session = bp != null ? PeekAdmin(sid) : null;
            if (session != null)
                playSeconds += (float)session.Session;
            var sessionTxt = session != null ? FormatPlaytime(session.Session) : "-";
            var groups = string.Join(", ", permission.GetUserGroups(pl.SteamId) ?? new string[0]);
            var conn = bp?.net?.connection;
            var ip = "-";
            if (conn != null && !string.IsNullOrEmpty(conn.ipaddress))
            {
                ip = conn.ipaddress;
                var portSep = ip.LastIndexOf(':');
                if (portSep > 0)
                    ip = ip.Substring(0, portSep);
            }

            var m = bp != null ? bp.metabolism : null;
            var muted = IsMuted(sid);

            var stat = new List<string[]>
            {
                new[] { "h", TranslateKey.StatConnection, null, null },
                new[] { "r", TranslateKey.StatStatus, status, statusColor },
                new[] { "r", TranslateKey.StatSteamId, pl.SteamId, null },
                new[] { "r", TranslateKey.StatPing, conn != null ? Network.Net.sv.GetAveragePing(conn) + " ms" : "-", null },
                new[] { "r", TranslateKey.StatSession, sessionTxt, null },
                new[] { "r", TranslateKey.StatPlaytime, FormatPlaytime(playSeconds), null },
                new[] { "r", TranslateKey.StatRustHours, RustHoursDisplay(sid, player), null },
                new[] { "r", TranslateKey.StatFirstSeen, sp != null ? FormatUnixDate(sp.FirstSeen) : "-", null },
                new[] { "r", TranslateKey.StatLastSeen, sp != null ? FormatUnixDate(sp.LastSeen) : "-", null },
                new[] { "r", TranslateKey.StatIp, ip, null },
                new[] { "r", TranslateKey.StatGroups, groups.Length > 0 ? groups : "-", null },
                new[]
                {
                    "r", TranslateKey.StatMuted,
                    GetLocalizedMessage(muted ? TranslateKey.CommonYes : TranslateKey.CommonNo, player),
                    muted ? Colors.CDanger : null
                }
            };

            var eco = HasPerm(player, Permissions.Economy) ? ActiveEconomy() : null;
            if (eco != null)
                stat.Add(new[] { "r", TranslateKey.StatBalance, GetEconomyBalanceValue(eco, sid, player), null });

            stat.Add(new[] { "h", TranslateKey.StatVitals, null, null });
            stat.AddRange(new List<string[]>
            {
                new[] { "r", TranslateKey.StatHealth, bp != null ? $"{Mathf.RoundToInt(bp.health)} / {Mathf.RoundToInt(bp.MaxHealth())}" : "-", null },
                new[] { "r", TranslateKey.StatHunger, m != null ? Mathf.RoundToInt(m.calories.value).ToString() : "-", null },
                new[] { "r", TranslateKey.StatThirst, m != null ? Mathf.RoundToInt(m.hydration.value).ToString() : "-", null },
                new[]
                {
                    "r", TranslateKey.StatRadiation, m != null ? Mathf.RoundToInt(m.radiation_poison.value).ToString() : "-",
                    m != null && m.radiation_poison.value > 1 ? Colors.CWarn : null
                },
                new[] { "r", TranslateKey.StatTemperature, m != null ? Mathf.RoundToInt(m.temperature.value) + "°C" : "-", null },
                new[] { "r", TranslateKey.StatWetness, m != null ? Mathf.RoundToInt(m.wetness.value * 100) + "%" : "-", null },
                new[]
                {
                    "r", TranslateKey.StatBleeding, m != null ? Mathf.RoundToInt(m.bleeding.value).ToString() : "-",
                    m != null && m.bleeding.value > 0 ? Colors.CDanger : null
                },
                new[] { "r", TranslateKey.StatPoison, m != null ? Mathf.RoundToInt(m.poison.value).ToString() : "-", null },
                new[] { "r", TranslateKey.StatComfort, m != null ? Mathf.RoundToInt(m.comfort.value * 100) + "%" : "-", null }
            });

            foreach (var sec in _extSections)
            {
                var extra = sec.CardRows?.Invoke(pl.SteamId) as List<string[]>;
                if (extra == null || extra.Count == 0)
                    continue;
                var insertAt = stat.FindIndex(r => r[0] == "h" && r[1] == TranslateKey.StatVitals);
                if (insertAt < 0)
                    insertAt = stat.Count;
                stat.InsertRange(insertAt, extra);
            }

            var headers = stat.Count(r => r[0] == "h");
            var contentH = 4 + headers * 24 + (stat.Count - headers) * 18 + 6;
            var clip = panel + ".clip";
            container.Add(new CuiElement
            {
                Parent = panel, Name = clip,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1", OffsetMin = "4 4", OffsetMax = "-4 -28" }
                }
            });
            var content = clip + ".c";
            container.Add(new CuiElement
            {
                Parent = clip, Name = content,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiScrollViewComponent
                    {
                        Horizontal = false, Vertical = true, MovementType = ScrollRect.MovementType.Clamped,
                        Inertia = true, ScrollSensitivity = 26f,
                        ContentTransform = new CuiRectTransform { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = $"0 {-contentH}", OffsetMax = "0 0" }
                    },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1" }
                }
            });
            var list = content + ".l";
            container.Add(new CuiElement
            {
                Parent = content, Name = list,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1" }
                }
            });

            var ipRevealed = PeekAdmin(player.userID)?.IpRevealed == true;
            var ipCanView = HasPerm(player, Permissions.ViewIp);

            var index = 0;
            var y = -4;
            foreach (var r in stat)
            {
                var label = GetLocalizedMessage(r[1], player);
                var rn = list + "." + index;
                var rowH = r[0] == "h" ? 24 : 18;
                container.Add(new CuiElement
                {
                    Parent = list, Name = rn,
                    Components =
                    {
                        new CuiImageComponent { Color = Colors.Clear },
                        new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = $"0 {y - rowH}", OffsetMax = $"0 {y}" }
                    }
                });
                index++;
                y -= rowH;

                if (r[0] == "h")
                {
                    UI_Text(container, rn, label.ToUpperInvariant(), 9, Fonts.Title, TextAnchor.LowerLeft, Palette.CAccent,
                        "0 1", "1 1", "6 -22", "-6 -4");
                    continue;
                }

                var isIp = r[1] == TranslateKey.StatIp;
                var maskIp = isIp && !ipRevealed;
                UI_Text(container, rn, label, 10, Fonts.Body, TextAnchor.MiddleLeft, Palette.CText2, "0 1", "0 1",
                    "10 -16", "110 0");
                UI_Text(container, rn, maskIp ? "••••••••" : r[2], 10, Fonts.Title, TextAnchor.MiddleRight,
                    maskIp ? Palette.CText3 : r[3] ?? Palette.CText, "0 1", "1 1", "108 -16",
                    $"{(maskIp ? -72 : -8)} 0");
                if (maskIp)
                    UI_Btn(container, rn, GetLocalizedMessage(TranslateKey.StatReveal, player),
                        ipCanView ? "pa.revealip" : "", Palette.CElev, 8, Fonts.Title, TextAnchor.MiddleCenter,
                        ipCanView ? Palette.CAccent : Palette.CText3, "1 1", "1 1", "-66 -16", "-8 0");
            }
        }

        [ServiceCommand("pa.revealip")]
        private void CommandRevealIp(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !Can(player, Permissions.Players) || !HasPerm(player, Permissions.ViewIp))
                return;
            GetAdmin(player.userID).IpRevealed = true;
            RefreshStats(player);
        }

        private void RefreshStats(BasePlayer player)
        {
            var sid = PeekAdmin(player.userID)?.Popup ?? 0;
            if (sid == 0 || PeekAdmin(player.userID)?.PopupAction != null)
                return;
            ApplyTheme(player);
            var container = new CuiElementContainer();
            UI_PopupStats(container, Layers.Root + ".pop.card", 452, 720, player, GetDropdownEntry(sid));
            CuiHelper.AddUi(player, container);
        }

        private void RefreshStatsFor(ulong target)
        {
            foreach (var admin in BasePlayer.activePlayerList)
            {
                if (admin == null)
                    continue;
                var ad = PeekAdmin(admin.userID);
                if (ad != null && ad.Popup == target && ad.PopupAction == null && ad.UiOpen)
                    RefreshStats(admin);
            }
        }

        private string SteamApiKey() => GetInput(null, FieldKey.ApiSteamkey, "").Trim();

        private string RustHoursDisplay(ulong sid, BasePlayer player = null)
        {
            if (string.IsNullOrEmpty(SteamApiKey()))
                return GetLocalizedMessage(TranslateKey.StatNoSteamKey, player);

            _players.TryGetValue(sid, out var sp);
            var now = DateTimeOffset.Now.ToUnixTimeSeconds();
            var stale = sp == null || sp.RustHoursFetched <= 0 || now - sp.RustHoursFetched > RustHoursTtl;
            if (stale && (sp == null || !sp.RustHoursPending))
                FetchRustHours(sid);
            _players.TryGetValue(sid, out sp);

            if (sp != null && sp.RustHoursMinutes >= 0)
            {
                var hours = sp.RustHoursMinutes / 60;
                return hours.ToString("N0", Ci) + " h";
            }

            if (sp != null && sp.RustHoursFailed)
                return "n/a";
            return "...";
        }

        private void FetchRustHours(ulong sid)
        {
            var key = SteamApiKey();
            if (string.IsNullOrEmpty(key))
                return;

            if (!_players.TryGetValue(sid, out var sp))
            {
                sp = new StoredPlayer();
                _players[sid] = sp;
            }

            if (sp.RustHoursPending)
                return;
            sp.RustHoursPending = true;

            var url = "https://api.steampowered.com/IPlayerService/GetOwnedGames/v1/?key=" + key +
                      "&steamid=" + sid + "&include_played_free_games=1&format=json";
            webrequest.Enqueue(url, null, (code, response) =>
            {
                sp.RustHoursPending = false;
                sp.RustHoursFetched = DateTimeOffset.Now.ToUnixTimeSeconds();
                if (code != 200 || string.IsNullOrEmpty(response))
                {
                    sp.RustHoursFailed = true;
                    RefreshStatsFor(sid);
                    return;
                }

                try
                {
                    var data = JsonConvert.DeserializeObject<SteamOwnedGames>(response);
                    var games = data?.response?.games;
                    var minutes = -1;
                    if (games != null)
                        foreach (var g in games)
                            if (g != null && g.appid == RustAppId)
                            {
                                minutes = g.playtime_forever;
                                break;
                            }

                    sp.RustHoursMinutes = minutes < 0 ? (games != null ? 0 : -1) : minutes;
                    sp.RustHoursFailed = games == null;
                    if (sp.RustHoursMinutes >= 0)
                        SavePlayersSoon();
                }
                catch (Exception ex)
                {
                    sp.RustHoursFailed = true;
                    PrintWarning($"[PowerfulAdmin] Steam hours parse failed for {sid}: {ex.Message}");
                }

                RefreshStatsFor(sid);
            }, this, Oxide.Core.Libraries.RequestMethod.GET);
        }

        private static string FormatPlaytime(double seconds)
        {
            if (seconds <= 0)
                return "-";
            var h = (int)(seconds / 3600);
            var m = (int)(seconds % 3600 / 60);
            return h > 0 ? $"{h}h {m}m" : $"{m}m";
        }

        private static string FormatUnixDate(long unix) =>
            unix <= 0 ? "-" : DateTimeOffset.FromUnixTimeSeconds(unix).LocalDateTime.ToString("yyyy-MM-dd HH:mm");

