        private void UI_NotesPicker(CuiElementContainer container, string card, BasePlayer player, DropdownEntry pl)
        {
            var target = ulong.TryParse(pl.SteamId, out var sid) ? FindOnline(sid) : null;
            var notes = NotesOf(target);
            UI_PopupBack(container, card, player);
            var content = UI_ScrollList(container, card, "notes", 12, -96, 416, 220, Positions.Map.NoteRowH - 2, 2, notes.Count, 2, 1,
                Palette.CPage, Palette.CBorder);
            if (notes.Count == 0)
                UI_Text(container, ScrollOf(content), GetLocalizedMessage(TranslateKey.MapNotesEmpty, player), 10, Fonts.Body,
                    TextAnchor.UpperLeft, Palette.CText3, "0 1", "1 1", "10 -40", "-10 -10");
            for (var i = 0; i < notes.Count; i++)
            {
                var note = notes[i];
                if (note == null)
                    continue;
                var row = content + ".n" + i;
                container.Add(new CuiElement { Parent = content, Name = row, Components = { new CuiImageComponent { Color = Colors.Clear } } });
                container.Add(
                    new CuiPanel
