            }
        }

        private static bool IsTogglableBlueprint(ItemDefinition d) =>
            d.Blueprint != null && d.Blueprint.userCraftable && !d.Blueprint.defaultBlueprint;

        private int CountUnlockedBlueprints(BasePlayer target)
        {
            var count = 0;
            foreach (var d in AllItems())
                if (IsTogglableBlueprint(d) && target.blueprints.IsUnlocked(d))
                    count++;
            return count;
        }

