        private static string ModValueDefault(float cur) =>
            cur != 0 ? cur.ToString("0.###", Ci) : "";

        private static Modifier FindActiveModifier(BasePlayer target, Modifier.ModifierType type) =>
            target.modifiers.All.Find(m => m != null && m.Type == type);

        private void UI_ModifierRow(CuiElementContainer container, BasePlayer player, BasePlayer target, string content, int i,
            Modifier.ModifierType type)
        {
            var active = FindActiveModifier(target, type);
            var isActive = active != null;
            var curVal = isActive ? active.Value : 0f;
            var remain = isActive ? Mathf.Max(0, Mathf.RoundToInt((float)active.TimeRemaining)) : 0;
            var rn = content + ".r" + i;
            var durVal = GetInput(player, FieldKey.PrefixModDur + i, isActive ? remain.ToString() : "600");
            var valVal = GetInput(player, FieldKey.PrefixModVal + i, isActive ? curVal.ToString("0.###") : "");

            container.Add(new CuiElement
            {
                Parent = content, Name = rn, DestroyUi = rn,
                Components = { new CuiImageComponent { Color = Palette.CElev }, new CuiRectTransformComponent { SetTransformIndex = i } }
            });
            UI_Text(container, rn, type.ToString().Replace('_', ' '), 10, Fonts.Title, TextAnchor.MiddleLeft, Palette.CText,
                "0 0", "1 1", "10 0", "-460 0");
            UI_Text(container, rn, ModifierStateText(isActive, curVal, remain), 9, Fonts.Title, TextAnchor.MiddleCenter,
                isActive ? Colors.CSuccess : Palette.CText3, "1 0.5", "1 0.5", "-454 -11", "-306 11", rn + ".st");
            void Box(string suffix, string boxOMin, string boxOMax, string text, TextAnchor align, string fieldOMin,
                string fieldOMax, int charsLimit, string command)
            {
                var b = rn + suffix;
                container.Add(new CuiElement
                {
                    Parent = rn, Name = b,
                    Components =
                    {
                        new CuiImageComponent { Color = Palette.CPage },
                        new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                        new CuiRectTransformComponent { AnchorMin = "1 0.5", AnchorMax = "1 0.5", OffsetMin = boxOMin, OffsetMax = boxOMax }
                    }
                });
                container.Add(new CuiElement
                {
                    Parent = b, Name = b + ".f",
                    Components =
                    {
                        new CuiInputFieldComponent
                        {
                            Text = text, FontSize = 10, Font = Fonts.Body, Align = align,
                            Color = Palette.CText, CharsLimit = charsLimit, NeedsKeyboard = true,
                            Command = ProtectCommand(command)
                        },
                        new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1", OffsetMin = fieldOMin, OffsetMax = fieldOMax }
                    }
                });
            }

            Box(".dur", "-300 -11", "-214 11", durVal, TextAnchor.MiddleCenter, "4 0", "-4 0", 10,
                $"pa.input {FieldKey.PrefixModDur}{i} ");
            Box(".in", "-208 -11", "-124 11", valVal, TextAnchor.MiddleLeft, "8 0", "-8 0", 12,
                $"pa.input {FieldKey.PrefixModVal}{i} ");
            UI_Btn(container, rn, GetLocalizedMessage(TranslateKey.ModifierApply, player), $"pa.mod set {i}",
                Colors.CSuccessSoft, 9, Fonts.Title, TextAnchor.MiddleCenter, Colors.CSuccess, "1 0.5", "1 0.5",
                "-118 -11", "-58 11");
            UI_Btn(container, rn, $"pa.mod del {i}", Colors.CDangerSoft, "1 0.5", "1 0.5", "-52 -11", "-10 11", rn + ".del");
            container.Add(new CuiElement
            {
                Parent = rn + ".del",
                Components =
                {
                    new CuiImageComponent { Color = Colors.CDanger, Sprite = "assets/icons/close.png" },
                    new CuiRectTransformComponent { AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5", OffsetMin = "-6 -6", OffsetMax = "6 6" }
                }
            });
        }

        private static string ModifierStateText(bool active, float value, int remain) =>
            active
                ? $"{value.ToString("0.###")} ({Mathf.RoundToInt(value * 100)}%) · {remain}s"
                : "0 (0%) · 0s";

        private void RefreshModifierRow(BasePlayer player, int idx)
        {
            if (PeekAdmin(player.userID)?.PopupAction != "mod")
                return;
            var sid = PeekAdmin(player.userID)?.Popup ?? 0;
            var target = sid != 0 ? FindOnline(sid) : null;
            if (target == null || target.modifiers == null)
                return;
            var types = (Modifier.ModifierType[])Enum.GetValues(typeof(Modifier.ModifierType));
            if (idx < 0 || idx >= types.Length)
                return;
            var active = FindActiveModifier(target, types[idx]);
            var isActive = active != null;
            var curVal = isActive ? active.Value : 0f;
            var remain = isActive ? Mathf.Max(0, Mathf.RoundToInt((float)active.TimeRemaining)) : 0;
            var rn = Layers.Root + ".pop.card.modlist.c.l.r" + idx;
            ApplyTheme(player);
            var container = new CuiElementContainer();
            container.Add(new CuiElement
            {
                Name = rn + ".st", Update = true,
                Components =
                {
                    new CuiTextComponent
                    {
                        Text = ModifierStateText(isActive, curVal, remain), FontSize = 9, Font = Fonts.Title,
                        Align = TextAnchor.MiddleCenter, Color = isActive ? Colors.CSuccess : Palette.CText3
                    }
                }
            });
            container.Add(new CuiElement
            {
                Name = rn + ".dur.f", Update = true,
                Components =
                {
                    new CuiInputFieldComponent
                    {
                        Text = GetInput(player, FieldKey.PrefixModDur + idx, isActive ? remain.ToString() : "600"),
                        FontSize = 10, Font = Fonts.Body, Align = TextAnchor.MiddleCenter, Color = Palette.CText,
                        CharsLimit = 10, NeedsKeyboard = true, Command = ProtectCommand($"pa.input {FieldKey.PrefixModDur}{idx} ")
                    }
                }
            });
            container.Add(new CuiElement
            {
                Name = rn + ".in.f", Update = true,
                Components =
                {
                    new CuiInputFieldComponent
                    {
                        Text = GetInput(player, FieldKey.PrefixModVal + idx, isActive ? curVal.ToString("0.###") : ""),
                        FontSize = 10, Font = Fonts.Body, Align = TextAnchor.MiddleLeft, Color = Palette.CText,
                        CharsLimit = 12, NeedsKeyboard = true, Command = ProtectCommand($"pa.input {FieldKey.PrefixModVal}{idx} ")
                    }
                }
            });
            CuiHelper.AddUi(player, container);
        }


        private static string VitFmt(float v, bool integer) =>
            integer
                ? Mathf.RoundToInt(v).ToString()
                : v.ToString("0.###", Ci);

        private static void VitalRead(BasePlayer target, VitalDef def, out float val, out float max, out bool hasMax)
        {
            hasMax = def.HasMax;
            switch (def.Kind)
            {
                case VitalKind.MaxHealth:
                {
                    val = target.MaxHealth();
                    max = 0f;
                    break;
                }
                case VitalKind.Health:
                {
                    val = target.health;
                    max = target.MaxHealth();
                    break;
                }
                default:
                {
                    var a = def.Attr(target.metabolism);
                    val = a.value;
                    max = a.max;
                    break;
                }
            }
        }

