        private void UI_VitalRow(CuiElementContainer container, BasePlayer player, BasePlayer target, string content, int i)
        {
            var def = VitalDefs[i];
            VitalRead(target, def, out var val, out var max, out var hasMax);
            var rn = content + ".r_" + def.Key;
            var valVal = GetInput(player, FieldKey.PrefixVitalVal + def.Key, VitFmt(val, def.Integer));
            var maxVal = hasMax ? GetInput(player, FieldKey.PrefixVitalMax + def.Key, VitFmt(max, def.Integer)) : "";
            var readout = def.Kind == VitalKind.MaxHealth
                ? VitFmt(val, def.Integer)
                : $"{VitFmt(val, def.Integer)} / {VitFmt(max, def.Integer)}";

            container.Add(new CuiElement
            {
                Parent = content, Name = rn, DestroyUi = rn,
                Components = { new CuiImageComponent { Color = Palette.CElev }, new CuiRectTransformComponent { SetTransformIndex = i } }
            });
            UI_Text(container, rn, def.Label, 10, Fonts.Title, TextAnchor.MiddleLeft, Palette.CText, "0 0", "1 1", "10 0",
                "-420 0");
            UI_Text(container, rn, readout, 9, Fonts.Title, TextAnchor.MiddleCenter, Colors.CSuccess, "1 0.5", "1 0.5",
                "-414 -11", "-300 11", rn + ".st");
            void Box(string suffix, string boxOMin, string boxOMax, string text, string command)
            {
                var b = rn + suffix;
                container.Add(new CuiElement
                {
                    Parent = rn, Name = b,
                    Components =
                    {
                        new CuiImageComponent { Color = Palette.CPage },
                        new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                        new CuiRectTransformComponent { AnchorMin = "1 0.5", AnchorMax = "1 0.5", OffsetMin = boxOMin, OffsetMax = boxOMax }
                    }
                });
                container.Add(new CuiElement
                {
                    Parent = b, Name = b + ".f",
                    Components =
                    {
                        new CuiInputFieldComponent
                        {
                            Text = text, FontSize = 10, Font = Fonts.Body, Align = TextAnchor.MiddleCenter,
                            Color = Palette.CText, CharsLimit = 10, NeedsKeyboard = true,
                            Command = ProtectCommand(command)
                        },
                        new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1", OffsetMin = "4 0", OffsetMax = "-4 0" }
