        private void RefreshVitalRow(BasePlayer player, string key)
        {
            if (PeekAdmin(player.userID)?.PopupAction != "vitals")
                return;
            var sid = PeekAdmin(player.userID)?.Popup ?? 0;
            var target = sid != 0 ? FindOnline(sid) : null;
            if (target == null || target.metabolism == null)
                return;
            var idx = VitalDefs.FindIndex(d => d.Key == key);
            if (idx < 0)
                return;
            var def = VitalDefs[idx];
            VitalRead(target, def, out var val, out var max, out var hasMax);
            var rn = Layers.Root + ".pop.card.vitlist.c.l.r_" + def.Key;
            ApplyTheme(player);
            var container = new CuiElementContainer();
            container.Add(new CuiElement
            {
                Name = rn + ".st", Update = true,
                Components =
                {
                    new CuiTextComponent
                    {
                        Text = def.Kind == VitalKind.MaxHealth
                            ? VitFmt(val, def.Integer)
                            : $"{VitFmt(val, def.Integer)} / {VitFmt(max, def.Integer)}",
                        FontSize = 9, Font = Fonts.Title, Align = TextAnchor.MiddleCenter, Color = Colors.CSuccess
                    }
                }
            });
            container.Add(new CuiElement
            {
                Name = rn + ".in.f", Update = true,
                Components =
                {
                    new CuiInputFieldComponent
                    {
                        Text = GetInput(player, FieldKey.PrefixVitalVal + def.Key, VitFmt(val, def.Integer)),
                        FontSize = 10, Font = Fonts.Body, Align = TextAnchor.MiddleCenter, Color = Palette.CText,
                        CharsLimit = 10, NeedsKeyboard = true,
                        Command = ProtectCommand($"pa.input {FieldKey.PrefixVitalVal}{def.Key} ")
                    }
                }
            });
            if (hasMax)
                container.Add(new CuiElement
                {
                    Name = rn + ".max.f", Update = true,
                    Components =
                    {
                        new CuiInputFieldComponent
                        {
                            Text = GetInput(player, FieldKey.PrefixVitalMax + def.Key, VitFmt(max, def.Integer)),
                            FontSize = 10, Font = Fonts.Body, Align = TextAnchor.MiddleCenter, Color = Palette.CText,
                            CharsLimit = 10, NeedsKeyboard = true,
                            Command = ProtectCommand($"pa.input {FieldKey.PrefixVitalMax}{def.Key} ")
                        }
                    }
                });
            CuiHelper.AddUi(player, container);
        }

        private void UI_EconomyPicker(CuiElementContainer container, string card, int cw, int ch, BasePlayer player,
