        {
            UI_PopupBack(container, card, player);
            UI_PickerTitle(container, card, player, TranslateKey.PopupEconomy, pl);

            var available = AvailableEconomies();
            var eco = PickedEconomy(player);
            if (eco == null)
            {
                UI_Text(container, card, GetLocalizedMessage(TranslateKey.EconomyNoProvider, player), 12, Fonts.Body,
                    TextAnchor.MiddleCenter, Palette.CText3, "0 0", "1 1", "12 12", "-12 -106");
                return;
            }

            ulong.TryParse(pl.SteamId, out var sid);
            const int gap = 8;
            var inner = cw - 24;

            UI_Text(container, card, GetLocalizedMessage(TranslateKey.EconomySource, player), 10, Fonts.Body,
                TextAnchor.MiddleLeft, Palette.CText2, "0 1", "1 1", "12 -110", "-12 -94");
