        [ServiceCommand("pa.ecopick")]
        private void CommandEcoPick(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(1) ||
                !permission.UserHasPermission(player.UserIDString, Permissions.Use))
                return;
            var name = arg.GetString(0);
            if (AvailableEconomies().Find(p => p.Name == name) == null)
                return;
            SetSelect(player.userID, FieldKey.EconomyPick, name);
            RefreshEcoPopup(player);
        }

        [ServiceCommand("pa.ecoamount")]
        private void CommandEcoAmount(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(1) ||
                !permission.UserHasPermission(player.UserIDString, Permissions.Use))
                return;
            if (!double.TryParse(arg.GetString(0), out var step))
                return;
            if (step <= 0)
            {
                SetInput(player.userID, FieldKey.EconomyAmount, "");
                RefreshEcoPopup(player);
                return;
            }

            double.TryParse(GetInput(player, FieldKey.EconomyAmount, ""), out var current);
            var total = current + step;
            SetInput(player.userID, FieldKey.EconomyAmount,
                total % 1d == 0d ? ((long)total).ToString() : total.ToString());
            RefreshEcoPopup(player);
        }

        [ServiceCommand("pa.ecoact")]
        private void CommandEcoAct(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(1) ||
                !permission.UserHasPermission(player.UserIDString, Permissions.Use))
                return;
            if (!HasPerm(player, Permissions.EconomyEdit))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageNoperm, player), NotifyKind.Error);
                return;
            }

            var sid = PeekAdmin(player.userID)?.Popup ?? 0;
            if (sid == 0)
                return;
            var eco = PickedEconomy(player);
            if (eco == null)
                return;
            if (eco.PlayerArg && FindOnline(sid) == null)
            {
                Notify(player, GetLocalizedMessage(TranslateKey.EconomyOnlineOnly, player), NotifyKind.Error);
                return;
            }

            if (!double.TryParse(GetInput(player, FieldKey.EconomyAmount, ""), out var amount) || amount <= 0)
            {
                Notify(player, GetLocalizedMessage(TranslateKey.EconomyBadAmount, player), NotifyKind.Error);
                return;
            }

            var mode = arg.GetString(0);
            var name = GetDropdownEntry(sid).DisplayName;
            bool ok;
            string okKey;
            if (mode == "give")
            {
                ok = eco.Add(sid, amount);
                okKey = TranslateKey.EconomyGaveOk;
            }
            else if (mode == "take")
            {
                ok = eco.Take(sid, amount);
                okKey = TranslateKey.EconomyTookOk;
            }
            else if (mode == "set")
            {
                ok = eco.Set(sid, amount);
                okKey = TranslateKey.EconomySetOk;
            }
            else
                return;

            var amountText = eco.IntegerCurrency ? ((long)amount).ToString() : amount.ToString();
            if (!ok)
            {
                Notify(player, GetLocalizedMessage(TranslateKey.EconomyOpFailed, player), NotifyKind.Error);
                AddLog(LogCategory.Err, $"{player.displayName}: economy {mode} {amountText} on {name} failed via {eco.Name}");
                return;
            }

            Notify(player, SafeFormat(GetLocalizedMessage(okKey, player), name, amountText));
            AddLog(LogCategory.Cmd, $"{player.displayName}: economy {mode} {amountText} ({eco.Name}) on {name}");
            DiscordEvent("d.s8", "d.hact", GetLocalizedMessage(TranslateKey.DiscordEco, null),
                $"**{mode}** {amountText} ({eco.Name})\n{GetLocalizedMessage(TranslateKey.DiscordMessageBy, null)} {DiscordUser(player)} · {name}",
                sid.ToString());
            RefreshEcoPopup(player);
        }

        [ServiceCommand("pa.stpoints")]
        private void CommandSkillPoints(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(1) ||
                !permission.UserHasPermission(player.UserIDString, Permissions.Use))
                return;
            if (!HasPerm(player, Permissions.EconomyEdit))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.MessageNoperm, player), NotifyKind.Error);
                return;
            }
            if (arg.GetString(0) != "give")
                return;

            var sid = PeekAdmin(player.userID)?.Popup ?? 0;
            if (sid == 0)
                return;
            var eco = PickedEconomy(player);
            if (eco == null || !eco.HasPoints)
                return;
            if (eco.PlayerArg && FindOnline(sid) == null)
            {
                Notify(player, GetLocalizedMessage(TranslateKey.EconomyOnlineOnly, player), NotifyKind.Error);
                return;
            }

            if (!int.TryParse(GetInput(player, FieldKey.SkillPointsAmount, ""), out var amount) || amount <= 0)
            {
                Notify(player, GetLocalizedMessage(TranslateKey.EconomyBadAmount, player), NotifyKind.Error);
                return;
            }

            var name = GetDropdownEntry(sid).DisplayName;
            if (!eco.AddPoints(sid, amount))
            {
                Notify(player, GetLocalizedMessage(TranslateKey.EconomyOpFailed, player), NotifyKind.Error);
                AddLog(LogCategory.Err, $"{player.displayName}: skill points give {amount} on {name} failed via {eco.Name}");
                return;
            }

            Notify(player, SafeFormat(GetLocalizedMessage(TranslateKey.SkillPointsGaveOk, player), name, amount.ToString()));
            AddLog(LogCategory.Cmd, $"{player.displayName}: skill points give {amount} ({eco.Name}) on {name}");
            DiscordEvent("d.s8", "d.hact", GetLocalizedMessage(TranslateKey.DiscordEco, null),
                $"**skill points give** {amount} ({eco.Name})\n{GetLocalizedMessage(TranslateKey.DiscordMessageBy, null)} {DiscordUser(player)} · {name}",
                sid.ToString());
            RefreshEcoPopup(player);
        }

        private void UI_GivePicker(CuiElementContainer container, string card, int cw, int ch, BasePlayer player,
            DropdownEntry pl)
        {
            UI_PopupBack(container, card, player);
            UI_PickerTitle(container, card, player, TranslateKey.PopupGive, pl, "-176 -60");
            UI_Segment(container, card, player, FieldKey.GiveBpmode, "item",
                GetLocalizedMessage(TranslateKey.GiveModeItem, player),
                "item", cw - 172, -60, 78, 24);
            UI_Segment(container, card, player, FieldKey.GiveBpmode, "bp", GetLocalizedMessage(TranslateKey.GiveModeBp, player),
                "item", cw - 90, -60, 78, 24);

            var geo = GiveLayout();
            var realCats = GiveCategories();
            var cats = new List<string> { "_fav", "_custom" };
            cats.AddRange(realCats);
            var curCat = GetSelect(player, FieldKey.GiveCat, realCats.Count > 0 ? realCats[0] : "_fav");
            var search = GetInput(player, FieldKey.GiveSearch, "").Trim();
            var step = int.TryParse(GetSelect(player, FieldKey.GiveStep, "1"), out var st) ? st : 1;
            var cart = GiveCart(player.userID);
            var fav = GiveFav(player.userID);

            const int catX = 12, catW = 132;

            UI_ScrollList(container, card, "gcat", catX, geo.Top, catW, geo.ColH, 24, 4, cats.Count, 6, 1, Palette.CPage,
                Palette.CBorder);
            UI_GiveCategoryRows(container, player, geo.CatName, cats, curCat);

            var searchW = geo.MidW - 108;
            var sb = card + ".gs";
            container.Add(new CuiElement
            {
                Parent = card, Name = sb,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CPage },
                    new CuiOutlineComponent { Color = Palette.CBorder, Distance = "1 1" },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{geo.MidX} {geo.Top - 28}",
                        OffsetMax = $"{geo.MidX + searchW} {geo.Top}"
                    }
                }
            });
            var searchEmpty = string.IsNullOrEmpty(search);
            container.Add(new CuiElement
            {
                Parent = sb,
                Components =
                {
                    new CuiInputFieldComponent
                    {
                        Text = searchEmpty ? GetLocalizedMessage(TranslateKey.GiveSearchPh, player) : search,
                        FontSize = 11, Font = Fonts.Body,
                        Align = TextAnchor.MiddleLeft, Color = searchEmpty ? Palette.CText3 : Palette.CText,
                        CharsLimit = 32,
                        NeedsKeyboard = true, Command = ProtectCommand("pa.givesearch ")
                    },
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "1 1", OffsetMin = "10 0", OffsetMax = "-8 0" }
                }
            });
            string[] steps = { "1", "100", "1000" };
            var stX = geo.MidX + searchW + 6;
            var stW = (geo.MidX + geo.MidW - stX - 4) / 3;
            string[] stepLabels = { "+1", "+100", "+1000" };
            UI_SegmentRow(container, card, player, FieldKey.GiveStep, "1", steps, stepLabels, stX, geo.Top,
                stW * 3 + 4, 28, 2);

            UI_GiveGrid(container, player, geo, curCat, step, cart, fav);

            UI_GiveCartCol(container, player, geo);

            if (PeekAdmin(player.userID)?.GiveCustomOpen == true)
                UI_GiveCustom(container, player);
        }

        private static string GiveCategoryIcon(string cat) =>
            cat == "_fav" ? "assets/icons/heart-white.png" : "assets/icons/backpack.png";

        private static string GiveCategoryIconColor(string cat, bool on) =>
            on ? Palette.CAccent : cat == "_fav" ? Colors.CDanger : Palette.CAccentH;

        private void UI_GiveCategoryState(CuiElementContainer container, BasePlayer player, string catContent,
            List<string> cats, string curCat)
        {
            for (var i = 0; i < cats.Count; i++)
            {
                var special = cats[i] == "_fav" || cats[i] == "_custom";
                var on = cats[i] == curCat;
                var rn = catContent + ".c" + i;
                var label = cats[i] == "_fav" ? GetLocalizedMessage(TranslateKey.GiveFav, player)
                    : cats[i] == "_custom" ? GetLocalizedMessage(TranslateKey.GiveCustomCat, player)
                    : cats[i];
                container.Add(new CuiElement { Name = rn, Update = true, Components = { new CuiImageComponent { Color = on ? Palette.CElev : Colors.Clear } } });
                container.Add(new CuiElement
                {
                    Name = rn + ".bar", Update = true,
                    Components = { new CuiImageComponent { Color = on ? Palette.CAccent : Colors.Clear } }
                });
                if (special)
                    container.Add(new CuiElement
                    {
                        Name = rn + ".ico", Update = true,
                        Components = { new CuiImageComponent { Color = GiveCategoryIconColor(cats[i], on), Sprite = GiveCategoryIcon(cats[i]) } }
                    });
                container.Add(new CuiElement
                {
                    Name = rn + ".lbl", Update = true,
                    Components =
                    {
                        new CuiTextComponent
                        {
                            Text = label, FontSize = 10, Font = Fonts.Title, Align = TextAnchor.MiddleLeft,
                            Color = on ? Palette.CAccent : Palette.CText2
                        }
                    }
                });
            }
        }

        private void UI_GiveCategoryRows(CuiElementContainer container, BasePlayer player, string catContent, List<string> cats,
            string curCat, string selectCommandPrefix = null)
        {
            for (var i = 0; i < cats.Count; i++)
            {
                var special = cats[i] == "_fav" || cats[i] == "_custom";
                var on = cats[i] == curCat;
                var rn = catContent + ".c" + i;
                var label = cats[i] == "_fav" ? GetLocalizedMessage(TranslateKey.GiveFav, player)
                    : cats[i] == "_custom" ? GetLocalizedMessage(TranslateKey.GiveCustomCat, player)
                    : cats[i];
                container.Add(new CuiElement
                {
                    Parent = catContent, Name = rn, DestroyUi = rn,
                    Components =
                    {
                        new CuiImageComponent { Color = on ? Palette.CElev : Colors.Clear },
                        new CuiRectTransformComponent { SetTransformIndex = i }
                    }
                });
                container.Add(
                    new CuiPanel
                    {
                        Image = { Color = on ? Palette.CAccent : Colors.Clear },
                        RectTransform = { AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = "0 -9", OffsetMax = "3 9" }
                    }, rn, rn + ".bar");
                if (special)
                    container.Add(new CuiElement
                    {
                        Parent = rn, Name = rn + ".ico",
                        Components =
                        {
                            new CuiImageComponent { Color = GiveCategoryIconColor(cats[i], on), Sprite = GiveCategoryIcon(cats[i]) },
                            new CuiRectTransformComponent { AnchorMin = "0 0.5", AnchorMax = "0 0.5", OffsetMin = "10 -7", OffsetMax = "24 7" }
                        }
                    });
                UI_Text(container, rn, label, 10, Fonts.Title, TextAnchor.MiddleLeft, on ? Palette.CAccent : Palette.CText2,
                    "0 0", "1 1", $"{(special ? 28 : 12)} 0", "-4 0", rn + ".lbl");
                var cmd = selectCommandPrefix != null
                    ? $"{selectCommandPrefix} {cats[i]}"
                    : $"pa.select {FieldKey.GiveCat} {cats[i]}";
                UI_Btn(container, rn, on ? "" : cmd, Colors.Clear, "0 0", "1 1", name: rn + ".btn");
            }
        }

        private void UI_GiveGrid(CuiElementContainer container, BasePlayer player, PickerLayout geo, string curCat, int step,
            List<CartEntry> cart, HashSet<string> fav)
        {
            var card = geo.Card;
            var emptyText = "";
            if (curCat == "_custom")
            {
                var customs = SavedCustoms(player.userID);
                var grid = UI_ScrollList(container, card, "gitems", geo.MidX, geo.GridY, geo.MidW, geo.GridH, geo.CellH,
                    geo.Gap, customs.Count, 4, geo.Gcols, Palette.CPage, Palette.CBorder);
                for (var j = 0; j < customs.Count; j++)
                    UI_GiveCustomCell(container, player, geo, grid, customs[j], j);
                if (customs.Count == 0)
                    emptyText = GetLocalizedMessage(TranslateKey.GiveNocustom, player);
            }
            else
            {
                var filtered = GiveFiltered(player);
                var grid = UI_ScrollList(container, card, "gitems", geo.MidX, geo.GridY, geo.MidW, geo.GridH, geo.CellH,
                    geo.Gap, filtered.Count, 4, geo.Gcols, Palette.CPage, Palette.CBorder);
                for (var j = 0; j < filtered.Count; j++)
                    UI_GiveCell(container, player, geo, grid, filtered[j], j, step, cart, fav);
                if (filtered.Count == 0)
                    emptyText = curCat == "_fav"
                        ? GetLocalizedMessage(TranslateKey.GiveNofav, player)
                        : GetLocalizedMessage(TranslateKey.GiveNoitems, player);
            }

            if (!string.IsNullOrEmpty(emptyText))
                container.Add(new CuiElement
                {
                    Parent = card, Name = card + ".gempty", DestroyUi = card + ".gempty",
                    Components =
                    {
                        new CuiTextComponent { Text = emptyText, FontSize = 11, Font = Fonts.Body, Align = TextAnchor.MiddleCenter, Color = Palette.CText3 },
                        new CuiRectTransformComponent
                        {
                            AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{geo.MidX} {geo.GridY - 100}",
                            OffsetMax = $"{geo.MidX + geo.MidW} {geo.GridY - 20}"
                        }
                    }
                });
        }

        private void GiveCategoryPartial(BasePlayer player)
        {
            if ((PeekAdmin(player.userID)?.Popup ?? 0) == 0 || !(PeekAdmin(player.userID)?.PopupAction == "give"))
            {
                UI_Open(player);
                return;
            }

            ApplyTheme(player);
            var container = new CuiElementContainer();
            var geo = GiveLayout();
            var realCats = GiveCategories();
            var cats = new List<string> { "_fav", "_custom" };
            cats.AddRange(realCats);
            var curCat = GetSelect(player, FieldKey.GiveCat, realCats.Count > 0 ? realCats[0] : "_fav");
            var step = int.TryParse(GetSelect(player, FieldKey.GiveStep, "1"), out var st) ? st : 1;
            var cart = GiveCart(player.userID);
            var fav = GiveFav(player.userID);
            CuiHelper.DestroyUi(player, geo.Card + ".gempty");
            UI_GiveCategoryState(container, player, geo.CatName, cats, curCat);
            UI_GiveGrid(container, player, geo, curCat, step, cart, fav);
            CuiHelper.AddUi(player, container);
        }

