        private void GivePartial(BasePlayer player, string only = null)
        {
            if ((PeekAdmin(player.userID)?.Popup ?? 0) == 0 || !(PeekAdmin(player.userID)?.PopupAction == "give"))
            {
                UI_Open(player);
                return;
            }

            ApplyTheme(player);
            var container = new CuiElementContainer();
            var geo = GiveLayout();
            var curCat = GetSelect(player, FieldKey.GiveCat, GiveCategories().FirstOrDefault() ?? "_fav");
            var step = int.TryParse(GetSelect(player, FieldKey.GiveStep, "1"), out var st) ? st : 1;
            UI_GiveCartCol(container, player, geo);

            if (only != "" && curCat != "_custom")
            {
                var cart = GiveCart(player.userID);
                var fav = GiveFav(player.userID);
                var filtered = GiveFiltered(player);
                if (only == null)
                    for (var j = 0; j < filtered.Count; j++)
                        UI_GiveCell(container, player, geo, geo.GridName, filtered[j], j, step, cart, fav);
                else
                {
                    var j = filtered.FindIndex(it => it.Shortname == only);
                    if (j >= 0)
                    {
                        var entry = cart.FirstOrDefault(x => x.Shortname == filtered[j].Shortname &&
                                                             x.SkinId == filtered[j].SkinId);
                        UI_GiveCellState(container, geo.GridName + ".it" + j, entry != null, entry?.Amount ?? 0,
                            fav.Contains(filtered[j].Shortname));
                    }
                }
            }
            else if (only == null && curCat == "_custom")
            {
                var customs = SavedCustoms(player.userID);
                for (var j = 0; j < customs.Count; j++)
                    UI_GiveCustomCell(container, player, geo, geo.GridName, customs[j], j);
            }

            CuiHelper.AddUi(player, container);
        }

