        private bool WidgetState(BasePlayer p, string key) => key switch
        {
            "vanish" => PeekAdmin(p.userID)?.Vanished == true,
            "esp" => GetToggle(p, "e.on", false),
            "god" => GetToggle(p, "f.god", false),
            "noclip" => GetToggle(p, "f.noclip", false),
            "hammer" => GetToggle(p, "f.hammer", false),
            "inspect" => GetToggle(p, "f.inspect", false),
            _ => false
        };

