        private List<AdminWidget> WidgetToggleList(BasePlayer player) =>
            AdminWidgets.Where(f => f.Key != "hammer" || Hammer.Can(player)).ToList();

        private static int WidgetToggleH(int count) => Mathf.CeilToInt(count / 2f) * 36;

        private void UI_WidgetToggles(CuiElementContainer container, BasePlayer player)
        {
