                    }
                });
                UI_Text(container, b, f.Label, 11, Fonts.Title, TextAnchor.MiddleLeft, on ? Palette.CAccent : Palette.CText2,
                    "0 0", "1 1", "10 0", "-26 0");
                container.Add(
                    new CuiPanel
                    {
                        Image = { Color = on ? Colors.CSuccess : Palette.CElev2 },
                        RectTransform = { AnchorMin = "1 0.5", AnchorMax = "1 0.5", OffsetMin = "-22 -6", OffsetMax = "-10 6" }
                    }, b);
                UI_Btn(container, b, $"pa.wtoggle {f.Key}", Colors.Clear, "0 0", "1 1");
            }
        }

