        private void UI_WidgetConsole(CuiElementContainer container, BasePlayer player, int shift)
        {
            var name = Layers.Widget + ".box";
            container.Add(new CuiElement
            {
                Parent = Layers.Widget, Name = name, DestroyUi = name,
                Components =
                {
                    new CuiImageComponent { Color = Palette.CPage },
                    new CuiOutlineComponent { Color = Palette.CBorderSoft, Distance = "1 1" },
                    new CuiRectTransformComponent { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = $"10 {-214 - shift}", OffsetMax = $"-10 {-124 - shift}" }
                }
            });

            if (!IsConsoleAllowed(player))
            {
                UI_Text(container, name, GetLocalizedMessage(TranslateKey.WidgetConsoleOff, player), 10, Fonts.Body,
                    TextAnchor.MiddleCenter, Palette.CText3, "0 0", "1 1", "8 0", "-8 0");
                GetAdmin(player.userID).WidgetConsoleSignature = "off";
                return;
            }

            var all = ConsoleSnapshot("all");
            var dl = all.Skip(Math.Max(0, all.Count - 5)).ToList();
            GetAdmin(player.userID).WidgetConsoleSignature = WidgetConsoleSignature(dl);
            if (dl.Count == 0)
                UI_Text(container, name, GetLocalizedMessage(TranslateKey.ConsoleEmpty, player), 10, Fonts.Body,
                    TextAnchor.MiddleCenter, Palette.CText3, "0 0", "1 1", "8 0", "-8 0");
            for (var i = 0; i < dl.Count; i++)
                UI_Text(container, name, dl[i].ToRich(), 9, Fonts.Console, TextAnchor.UpperLeft, Palette.CText, "0 1",
                    "1 1", $"8 {-8 - i * 16 - 14}", $"-8 {-8 - i * 16}");
        }

        private static string WidgetConsoleSignature(List<LogLine> lines) =>
            string.Join("|", lines.Select(l => l.Time + l.Text));

        private void RefreshWidgetControls(BasePlayer player)
        {
            if (PeekAdmin(player.userID)?.WidgetOpen != true)
                return;
            ApplyTheme(player);
            var container = new CuiElementContainer();
            if (PeekAdmin(player.userID)?.WidgetMini == true)
                UI_WidgetStatus(container, player);
            else
                UI_WidgetToggles(container, player);
            CuiHelper.AddUi(player, container);
        }

        private void RefreshWidgetConsole(BasePlayer player)
        {
            if (PeekAdmin(player.userID)?.WidgetOpen != true || PeekAdmin(player.userID)?.WidgetMini == true)
                return;
            ApplyTheme(player);
            var container = new CuiElementContainer();
            UI_WidgetConsole(container, player,
                QuickBlockH(QuickFor(player, QuickTarget.Global, QuickPlace.Widget).Count, 2) + WidgetShift(player));
            CuiHelper.AddUi(player, container);
        }

        private void RefreshWidgetFor(BasePlayer player)
        {
            if (player == null || PeekAdmin(player.userID)?.WidgetOpen != true)
                return;
            if (PeekAdmin(player.userID)?.WidgetMini == true || !IsConsoleAllowed(player))
                return;
            var all = ConsoleSnapshot("all");
            var dl = all.Skip(Math.Max(0, all.Count - 5)).ToList();
            var sig = WidgetConsoleSignature(dl);
            if (PeekAdmin(player.userID)?.WidgetConsoleSignature == sig)
                return;
            ApplyTheme(player);
            var container = new CuiElementContainer();
            UI_WidgetConsole(container, player,
                QuickBlockH(QuickFor(player, QuickTarget.Global, QuickPlace.Widget).Count, 2) + WidgetShift(player));
            CuiHelper.AddUi(player, container);
        }

        internal bool NeedsRefreshUiFor(BasePlayer player)
        {
            if (player == null || !player.IsConnected)
                return false;
            var panel = PeekAdmin(player.userID)?.UiOpen == true;
            var widget = PeekAdmin(player.userID)?.WidgetOpen == true;
            if (!panel && !widget)
                return false;
            ReconcileGodNoclip(player);
            if (panel)
            {
                RefreshConsoleFor(player);
                RefreshDashboardFor(player);
            }

            if (widget)
                RefreshWidgetFor(player);
            return true;
        }

        private void ShowNoteHint(BasePlayer player)
        {
            if (player == null || !player.IsConnected || !Can(player, Permissions.Map))
                return;
            if (!GetToggle(player, NoteHintKey, true))
                return;
            if (player.HasPlayerFlag(BasePlayer.PlayerFlags.ReceivingSnapshot))
            {
                timer.Once(3f, () => ShowNoteHint(player));
                return;
            }

            ApplyTheme(player);
            var container = new CuiElementContainer();
            container.Add(new CuiElement
            {
