        private void UI_TemplateChips(CuiElementContainer container, string parent, BasePlayer player, string reasonKey, int x,
            int y, int w)
        {
            var tpls = KickMuteTemplates();
            if (tpls.Count == 0)
                return;
            var n = Mathf.Min(tpls.Count, 6);
            var cw = (w - (n - 1) * 4) / n;
            var strip = parent + ".tpl" + reasonKey;
            container.Add(new CuiElement
            {
                Parent = parent, Name = strip, DestroyUi = strip,
                Components =
                {
                    new CuiImageComponent { Color = Colors.Clear },
                    new CuiGridLayoutGroupComponent
                    {
                        CellSize = $"{cw} 24", Spacing = "4 4",
                        StartCorner = GridLayoutGroup.Corner.UpperLeft, StartAxis = GridLayoutGroup.Axis.Horizontal,
                        ChildAlignment = TextAnchor.UpperLeft,
                        Constraint = GridLayoutGroup.Constraint.FixedColumnCount, ConstraintCount = n
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1", AnchorMax = "0 1", OffsetMin = $"{x} {y - 24}",
                        OffsetMax = $"{x + (n * (cw + 4) - 4)} {y}"
                    }
                }
            });
            for (var i = 0; i < n; i++)
                UI_Btn(container, strip, tpls[i], $"pa.tpl {reasonKey} {i}", Palette.CElev, 10, Fonts.Body,
                    TextAnchor.MiddleCenter, Palette.CText2, "0 0", "1 1");
        }

