        #region Config

        private ConfigData cfg;

        protected override void LoadDefaultConfig()
        {
            cfg = new ConfigData
            {
                Storage = DataStorage.Sqlite,
                MySql = new MySqlConf(),
                LastStorage = "",
                Settings = new GlobalSettings(),
                Version = Version
            };
            _global = cfg.Settings;
        }

        protected override void LoadConfig()
        {
            base.LoadConfig();
            try
            {
                cfg = Config.ReadObject<ConfigData>();
                if (cfg == null)
                    throw new Exception("config is null");
            }
            catch (Exception ex)
            {
                PrintError($"Configuration is invalid ({ex.Message}); loading defaults.");
                LoadDefaultConfig();
            }

            cfg.MySql ??= new MySqlConf();
            cfg.Settings ??= new GlobalSettings();

            if (cfg.Version < Version)
            {
                cfg.Version = Version;
                PrintWarning("Config was updated!");
            }

            _global = cfg.Settings;
            SaveConfig();
        }

        protected override void SaveConfig() => Config.WriteObject(cfg, true);

        private void SaveConfigSoon()
        {
            _saveConfigTimer?.Destroy();
            _saveConfigTimer = timer.Once(2f, SaveConfig);
        }

