        #region Data

        private Db NewDatabase(DataStorage backend) =>
            new Db(backend, this, $"{Title}.db", cfg.MySql, AddLog);

        private static void RunSequential(IEnumerable<Action<Action>> steps, Action done)
        {
            var list = steps as IList<Action<Action>> ?? steps.ToList();
            var index = 0;
            void Next()
            {
                if (index < list.Count)
                    list[index++](Next);
                else
                    done?.Invoke();
            }

            Next();
        }

        private void EnsureSchema(Db db, Action done)
        {
            var idCol = db.Backend == DataStorage.MySql
                ? "BIGINT AUTO_INCREMENT PRIMARY KEY"
                : "INTEGER PRIMARY KEY AUTOINCREMENT";
            var keyCol = db.Backend == DataStorage.MySql ? "VARCHAR(32)" : "TEXT";
            var tables = new[]
            {
                $"CREATE TABLE IF NOT EXISTS pa_players (steamid {keyCol} PRIMARY KEY, data TEXT)",
                $"CREATE TABLE IF NOT EXISTS pa_prefs (steamid {keyCol} PRIMARY KEY, data TEXT)",
                $"CREATE TABLE IF NOT EXISTS pa_logs (id {idCol}, ts TEXT, cat TEXT, msg TEXT)",
                $"CREATE TABLE IF NOT EXISTS pa_mutes (steamid {keyCol} PRIMARY KEY, data TEXT)"
            };
            RunSequential(tables.Select(sql => (Action<Action>)(next =>
                db.NonQuery(Sql.Builder.Append(sql), _ => next()))), done);
        }

        private void LoadAllFrom(Db db, Action done)
        {
            if (db.Backend == DataStorage.Json)
            {
                _players =
                    Interface.Oxide?.DataFileSystem?.ReadObject<Dictionary<ulong, StoredPlayer>>($"{Title}/Players") ??
                    new();
                _admins =
                    Interface.Oxide?.DataFileSystem
                        ?.ReadObject<Dictionary<ulong, AdminData>>($"{Title}/PlayerData") ?? new();
                _mutes =
                    Interface.Oxide?.DataFileSystem?.ReadObject<Dictionary<ulong, MuteEntry>>($"{Title}/Mutes") ??
                    new();
                done?.Invoke();
                return;
            }

            RunSequential(new List<Action<Action>>
            {
                next => db.Query(Sql.Builder.Append("SELECT steamid, data FROM pa_players"), rows =>
                {
                    var players = new Dictionary<ulong, StoredPlayer>();
                    foreach (var r in rows)
                        if (ulong.TryParse(r["steamid"]?.ToString(), out var sid))
                            try
                            {
                                var v = Newtonsoft.Json.JsonConvert.DeserializeObject<StoredPlayer>(
                                    r["data"]?.ToString() ?? "");
                                if (v != null)
                                    players[sid] = v;
                            }
                            catch (Exception ex)
                            {
                                PrintWarning($"Loading the player {sid} from the database failed: {ex.Message}");
                            }

                    _players = players;
                    next();
                }),
                next => db.Query(Sql.Builder.Append("SELECT steamid, data FROM pa_prefs"), rows2 =>
                {
                    var data = new Dictionary<ulong, AdminData>();
                    foreach (var r in rows2)
                        if (ulong.TryParse(r["steamid"]?.ToString(), out var sid))
                            try
                            {
                                var v = Newtonsoft.Json.JsonConvert.DeserializeObject<AdminData>(
                                    r["data"]?.ToString() ?? "");
                                if (v != null)
                                    data[sid] = v;
                            }
                            catch (Exception ex)
                            {
                                PrintWarning($"Loading the preferences of {sid} from the database failed: {ex.Message}");
                            }

                    _admins = data;
                    next();
                }),
                next => db.Query(Sql.Builder.Append("SELECT ts, cat, msg FROM pa_logs ORDER BY id DESC LIMIT 400"),
                    rows3 =>
                    {
                        var loaded = new List<LogLine>(rows3.Count);
                        for (var i = rows3.Count - 1; i >= 0; i--)
                            loaded.Add(new LogLine
                            {
                                Time = rows3[i]["ts"]?.ToString() ?? "",
                                Cat = Enum.TryParse<LogCategory>(rows3[i]["cat"]?.ToString(), true, out var lc)
                                    ? lc
                                    : LogCategory.Info,
                                Text = rows3[i]["msg"]?.ToString() ?? ""
                            });
                        _log.ReplaceAll(loaded);
                        next();
                    }),
                next => db.Query(Sql.Builder.Append("SELECT steamid, data FROM pa_mutes"), rows4 =>
                {
                    var mutes = new Dictionary<ulong, MuteEntry>();
                    foreach (var r in rows4)
                        if (ulong.TryParse(r["steamid"]?.ToString(), out var sid))
                            try
                            {
                                var v = Newtonsoft.Json.JsonConvert.DeserializeObject<MuteEntry>(
                                    r["data"]?.ToString() ?? "");
                                if (v != null)
                                    mutes[sid] = v;
                            }
                            catch (Exception ex)
                            {
                                PrintWarning($"Loading the mute of {sid} from the database failed: {ex.Message}");
                            }

                    _mutes = mutes;
                    next();
                })
            }, done);
        }

        private void SaveAllTo(Db db, Action done)
        {
            if (db.Backend == DataStorage.Json)
            {
                Interface.Oxide.DataFileSystem.WriteObject($"{Title}/Players", _players);
                Interface.Oxide.DataFileSystem.WriteObject($"{Title}/PlayerData", _admins);
                Interface.Oxide.DataFileSystem.WriteObject($"{Title}/Mutes", _mutes);
                done?.Invoke();
                return;
            }

            foreach (var kv in _players)
                db.Upsert("pa_players", kv.Key.ToString(), Newtonsoft.Json.JsonConvert.SerializeObject(kv.Value));
            foreach (var kv in _admins)
                db.Upsert("pa_prefs", kv.Key.ToString(), Newtonsoft.Json.JsonConvert.SerializeObject(kv.Value));
            foreach (var kv in _mutes)
                db.Upsert("pa_mutes", kv.Key.ToString(), Newtonsoft.Json.JsonConvert.SerializeObject(kv.Value));
            done?.Invoke();
        }

        private void InitStorage(Action done) => InitStorage(done, 0);

        private void InitStorage(Action done, int attempt)
        {
            cfg ??= new ConfigData();
            var target = cfg.Storage;

            _db = NewDatabase(target);
            if (!_db.IsSql)
            {
                InitStorageReady(done, target);
                return;
            }

            if (!_db.Open())
            {
                InitStorageUnavailable(done, target, attempt);
                return;
            }

            _db.Query(Sql.Builder.Append("SELECT 1"), rows =>
            {
                if (rows.Count == 0)
                {
                    _db.Close();
                    InitStorageUnavailable(done, target, attempt);
                    return;
                }

                InitStorageReady(done, target);
            });
        }

        private void InitStorageUnavailable(Action done, DataStorage target, int attempt)
        {
            if (attempt < StorageOpenAttempts)
            {
                _storageRetryTimer?.Destroy();
                _storageRetryTimer = timer.Once(StorageRetryFirstSeconds, () => InitStorage(done, attempt + 1));
                return;
            }

            var why = $"'{StorageId(target)}' storage unavailable, using json until it answers (check DB settings)";
            AddLog(LogCategory.Err, $"PowerfulAdmin: {why}");
            PrintError(why);
            _db = NewDatabase(DataStorage.Json);
            StorageRetrySoon(target, StorageRetryFirstSeconds);
            LoadAllFrom(_db, () => done?.Invoke());
        }

        private void InitStorageReady(Action done, DataStorage target)
        {
            var source = string.IsNullOrEmpty(cfg.LastStorage)
                ? DataStorage.Json
                : ParseStorage(cfg.LastStorage);
            var ctx = new StorageMigrationContext { Target = target, Source = source, Done = done };

            if (target == source)
            {
                if (_db.IsSql)
                    EnsureSchema(_db, () => LoadAllFrom(_db, () => StorageProceed(ctx)));
                else
                    LoadAllFrom(_db, () => StorageProceed(ctx));
            }
            else
            {
                ctx.SourceDb = NewDatabase(source);
                if (_db.IsSql)
                    EnsureSchema(_db, () => StorageAfterSchema(ctx));
                else
                    StorageAfterSchema(ctx);
            }
        }

        private void StorageRetrySoon(DataStorage target, float delay)
        {
            _storageRetryTimer?.Destroy();
            _storageRetryTimer = timer.Once(delay, () => StorageRetry(target, delay));
        }

        private void StorageRetryLater(DataStorage target, float delay) =>
            StorageRetrySoon(target, Mathf.Min(delay * 2f, StorageRetryMaxSeconds));

        private void StorageRetry(DataStorage target, float delay)
        {
            _storageRetryTimer = null;
            if (cfg == null || cfg.Storage != target || _db == null || _db.IsSql)
                return;

            var db = NewDatabase(target);
            if (!db.Open())
            {
                StorageRetryLater(target, delay);
                return;
            }

            db.Query(Sql.Builder.Append("SELECT 1"), rows =>
            {
                if (rows.Count == 0)
                {
                    db.Close();
                    StorageRetryLater(target, delay);
                    return;
                }

                var liveAdmins = _admins;
                var livePlayers = _players;
                EnsureSchema(db, () => LoadAllFrom(db, () =>
                {
                    StorageKeepOnline(liveAdmins, livePlayers);
                    _db?.Close();
                    _db = db;
                    cfg.LastStorage = StorageId(target);
                    SaveConfig();
                    var back = $"'{StorageId(target)}' storage answered, switched back from json";
                    AddLog(LogCategory.Info, $"PowerfulAdmin: {back}");
                    Puts(back);
                }));
            });
        }

        private void StorageKeepOnline(Dictionary<ulong, AdminData> admins, Dictionary<ulong, StoredPlayer> players)
        {
            foreach (var player in BasePlayer.activePlayerList)
            {
                if (player == null)
                    continue;
                if (admins.TryGetValue(player.userID, out var ad))
                    _admins[player.userID] = ad;
                if (players.TryGetValue(player.userID, out var sp))
                    _players[player.userID] = sp;
            }
        }

        private void StorageProceed(StorageMigrationContext ctx)
        {
            cfg.LastStorage = StorageId(ctx.Target);
            SaveConfig();
            ctx.Done?.Invoke();
        }

        private void StorageMigrate(StorageMigrationContext ctx) => LoadAllFrom(ctx.SourceDb, () =>
        {
            if (ctx.SourceDb.IsSql && _players.Count == 0 && _admins.Count == 0)
            {
                StorageKeepTarget(ctx, "returned no data");
                return;
            }

            SaveAllTo(_db, () =>
            {
                ctx.SourceDb.Close();
                AddLog(LogCategory.Info,
                    $"PowerfulAdmin: migrated data {StorageId(ctx.Source)} -> {StorageId(ctx.Target)}");
                StorageProceed(ctx);
            });
        });

        private void StorageKeepTarget(StorageMigrationContext ctx, string why)
        {
            ctx.SourceDb.Close();
            AddLog(LogCategory.Err,
                $"PowerfulAdmin: migration source '{StorageId(ctx.Source)}' {why}; kept '{StorageId(ctx.Target)}' data");
            LoadAllFrom(_db, () => StorageProceed(ctx));
        }

        private void StorageAfterSchema(StorageMigrationContext ctx)
        {
            if (!ctx.SourceDb.IsSql)
            {
                StorageMigrate(ctx);
                return;
            }

            if (!ctx.SourceDb.Open())
            {
                StorageKeepTarget(ctx, "could not open");
                return;
            }

            ctx.SourceDb.Query(Sql.Builder.Append("SELECT 1"), rows =>
            {
                if (rows.Count == 0)
                    StorageKeepTarget(ctx, "unreachable");
                else
                    EnsureSchema(ctx.SourceDb, () => StorageMigrate(ctx));
            });
        }

        private void SaveData()
        {
            if (_db == null)
                return;
            if (_db.Backend == DataStorage.Json)
            {
                Interface.Oxide.DataFileSystem.WriteObject($"{Title}/PlayerData", _admins);
                return;
            }

            foreach (var kv in _admins)
            {
                var json = JsonConvert.SerializeObject(kv.Value);
                if (kv.Value.PrefsSnapshot == json)
                    continue;
                _db.Upsert("pa_prefs", kv.Key.ToString(), json);
                kv.Value.PrefsSnapshot = json;
            }
        }

        private void SaveSoon()
        {
            _saveDataTimer?.Destroy();
            _saveDataTimer = timer.Once(2f, SaveData);
        }

        private void SavePlayers()
        {
            if (_db == null)
                return;
            if (_db.Backend == DataStorage.Json)
            {
                Interface.Oxide.DataFileSystem.WriteObject($"{Title}/Players", _players);
                return;
            }

            foreach (var kv in _players)
            {
                var json = JsonConvert.SerializeObject(kv.Value);
                if (_playersSnapshot.TryGetValue(kv.Key, out var prev) && prev == json)
                    continue;
                _db.Upsert("pa_players", kv.Key.ToString(), json);
                _playersSnapshot[kv.Key] = json;
            }
        }

        private void SavePlayersSoon()
        {
            _savePlayersTimer?.Destroy();
            _savePlayersTimer = timer.Once(5f, SavePlayers);
        }

        private void SaveMutes()
        {
            if (_db == null || _db.Backend == DataStorage.Json)
            {
                Interface.Oxide.DataFileSystem.WriteObject($"{Title}/Mutes", _mutes);
                return;
            }

            foreach (var kv in _mutes)
                _db.Upsert("pa_mutes", kv.Key.ToString(), Newtonsoft.Json.JsonConvert.SerializeObject(kv.Value));
        }

        private void SaveMutesSoon()
        {
            _saveMutesTimer?.Destroy();
            _saveMutesTimer = timer.Once(2f, SaveMutes);
        }

        private void MutePersistUpsert(ulong id, MuteEntry m)
        {
            if (_db == null || _db.Backend == DataStorage.Json)
                SaveMutesSoon();
            else
                _db.Upsert("pa_mutes", id.ToString(), Newtonsoft.Json.JsonConvert.SerializeObject(m));
        }

        private void MutePersistRemove(ulong id)
        {
            if (_db == null || _db.Backend == DataStorage.Json)
                SaveMutesSoon();
            else
                _db.NonQuery(Sql.Builder.Append("DELETE FROM pa_mutes WHERE steamid = @0", id.ToString()));
        }

        private AssetData _assets = new();

        private void LoadAssets()
        {
            try
            {
                _assets = Interface.Oxide.DataFileSystem.ReadObject<AssetData>($"{Title}/Assets") ?? new AssetData();
            }
            catch (Exception ex)
            {
                PrintError($"Loading the assets data failed ({ex.Message}); using defaults.");
                _assets = new AssetData();
            }
        }

        private void SaveAssets() => Interface.Oxide.DataFileSystem.WriteObject($"{Title}/Assets", _assets);

