        private object API_RelayChatToGame(string nick, string roleName, string roleColor, string message)
        {
            if (!IsDiscordOn() || !GetToggle(null, "d.dcgame", false))
                return null;
            if (string.IsNullOrWhiteSpace(message) || string.IsNullOrWhiteSpace(nick))
                return null;
            message = SanitizeChat(message);
            if (message.Length == 0)
                return null;
            nick = SanitizeChat(nick);
            roleName = SanitizeChat(roleName);

            var tag = "<color=#5865F2>[Discord]</color>";
            var rolePart = string.IsNullOrEmpty(roleName) ? "" : " " + ColorWrap("[" + roleName + "]", roleColor);
            var line = $"{tag}{rolePart} <color=#d7d9e0>{nick}</color>: <color=#b9bcc6>{message}</color>";
            foreach (var p in BasePlayer.activePlayerList)
                if (p != null)
                    p.ChatMessage(line);
            AddLog(LogCategory.Chat, $"[Discord] {nick}: {message}");
            return null;
        }

        private object API_SetChatBridge(bool on)
        {
            SetToggle(0, "d.dcgame", on);
            Discord.BotReconnect();
            RefreshSettingsRoles();
            return on;
        }

        private object API_ReopenPanel(BasePlayer player)
        {
            if (player != null && PeekAdmin(player.userID)?.UiOpen == true)
                UI_Open(player);
            return null;
        }

        private object API_RefreshPlayerCard(string steamId)
        {
            if (ulong.TryParse(steamId, out var sid))
                RefreshStatsFor(sid);
            return null;
        }

        private object API_SectionContext(BasePlayer player) => player != null ? BuildSectionContext(player) : null;

        private object API_AddSection(Dictionary<string, object> def)
        {
            if (def == null || !(def.TryGetValue("id", out var idObj) && idObj is string id && id.Length > 0))
                return false;
            var sec = new ExtSection
            {
                Id = id,
                Icon = def.TryGetValue("icon", out var ic) ? ic as string : "assets/icons/file.png",
                Category = def.TryGetValue("category", out var cat) ? cat as string : "nav.cat.manage",
                Permission = def.TryGetValue("permission", out var pm) ? pm as string : null,
                SettingsHeight = def.TryGetValue("settingsHeight", out var sh) ? sh as Func<BasePlayer, int> : null,
                Title = def.TryGetValue("title", out var t) ? t as Func<BasePlayer, string> : null,
                Hint = def.TryGetValue("hint", out var hn) ? hn as Func<BasePlayer, string> : null,
                Open = def.TryGetValue("open", out var op) ? op as Action<BasePlayer> : null,
                CardRows = def.TryGetValue("cardRows", out var cr) ? cr as Func<string, List<string[]>> : null,
                PopupActions = def.TryGetValue("popupActions", out var pb)
                    ? pb as Dictionary<string, Action<BasePlayer, ulong, string>>
                    : null,
                Settings = def.TryGetValue("settings", out var se)
                    ? se as Action<BasePlayer, CuiElementContainer, string, int>
                    : null
            };
            if (!string.IsNullOrEmpty(sec.Permission) && !permission.PermissionExists(sec.Permission))
                permission.RegisterPermission(sec.Permission, this);
            _extSections.RemoveAll(x => x.Id == id);
            _extSections.Add(sec);
            ReopenAllPanels();
            return true;
        }

        private object API_OpenSection(BasePlayer player, string id)
        {
            if (player == null || string.IsNullOrEmpty(id) || _extSections.All(x => x.Id != id))
                return false;
            GetAdmin(player.userID).ActivePage = id;
            GetAdmin(player.userID).LastPage = id;
            GetAdmin(player.userID).Popup = 0;
            GetAdmin(player.userID).PopupAction = null;
            SaveSoon();
            UI_Navigate(player);
            return true;
        }

        private object API_Notify(BasePlayer player, string message, bool isError = false)
        {
            if (player == null || string.IsNullOrEmpty(message))
                return null;
            Notify(player, message, isError ? NotifyKind.Error : NotifyKind.Success);
            return true;
        }

        private object API_Log(string message, string category = null)
        {
            if (string.IsNullOrEmpty(message))
                return false;
            var cat = Enum.TryParse<LogCategory>(category ?? "Cmd", true, out var lc) ? lc : LogCategory.Cmd;
            AddLog(cat, message);
            return true;
        }

        private object API_RefreshSettings(BasePlayer player)
        {
            if (player != null)
                RefreshSettings(player);
            return null;
        }

        private string API_RustHours(string steamId) =>
            ulong.TryParse(steamId, out var sid) ? RustHoursDisplay(sid) : "-";

        private object API_KnownPlayers()
        {
            var result = new List<string[]>();
            var seen = new HashSet<ulong>();
            foreach (var b in BasePlayer.activePlayerList
                         .Where(b => b != null)
                         .OrderBy(b => b.displayName, StringComparer.OrdinalIgnoreCase))
                if (seen.Add(b.userID))
                    result.Add(new[] { b.userID.ToString(), b.displayName, "1" });
            foreach (var kv in _players.OrderBy(kv => kv.Value.Name, StringComparer.OrdinalIgnoreCase))
                if (seen.Add(kv.Key))
                    result.Add(new[] { kv.Key.ToString(), string.IsNullOrEmpty(kv.Value.Name) ? kv.Key.ToString() : kv.Value.Name, "0" });
            return result;
        }

        private object API_RemoveSection(string id)
        {
            if (string.IsNullOrEmpty(id) || _extSections.RemoveAll(x => x.Id == id) == 0)
                return false;
            foreach (var b in BasePlayer.activePlayerList)
            {
                var ad = b != null ? PeekAdmin(b.userID) : null;
                if (ad == null || ad.ActivePage != id)
                    continue;
                ad.ActivePage = "dashboard";
                ad.LastPage = "dashboard";
            }

            ReopenAllPanels();
            return true;
        }

        private void ReopenAllPanels()
        {
            foreach (var b in BasePlayer.activePlayerList)
                if (b != null && PeekAdmin(b.userID)?.UiOpen == true)
                    UI_Open(b);
        }

        private string API_GetInput(string key) => GetInput(null, key, "");

        private bool API_GetToggle(string key, bool def) => GetToggle(null, key, def);

        private string API_GetSelect(string key, string def) => GetSelect(null, key, def);

        private void API_SetRoles(string encoded)
        {
            Discord.Roles.Clear();
            if (string.IsNullOrEmpty(encoded))
            {
                RefreshSettingsRoles();
                return;
            }

            foreach (var line in encoded.Split('\n'))
            {
                var parts = line.Split('\t');
                if (parts.Length < 2)
                    continue;
                var id = parts[0].Trim();
                var name = parts[1].Trim();
                var color = parts.Length > 2 ? parts[2].Trim() : "";
                if (id.Length > 0)
                    Discord.Roles.Add(new[] { id, name, color });
            }

            var valid = new HashSet<string>(Discord.Roles.Select(r => r[0]));
            if (valid.Count > 0)
            {
                var kick = string.Join(",", RoleSet(FieldKey.DiscordRkick).Where(valid.Contains));
                if (kick != DiscordInput(FieldKey.DiscordRkick))
                    SetInput(0, FieldKey.DiscordRkick, kick);
                var mute = string.Join(",", RoleSet(FieldKey.DiscordRmute).Where(valid.Contains));
                if (mute != DiscordInput(FieldKey.DiscordRmute))
                    SetInput(0, FieldKey.DiscordRmute, mute);
                var sup = DiscordInput(FieldKey.DiscordRsuper);
                if (sup.Length > 0 && !valid.Contains(sup))
                    SetInput(0, FieldKey.DiscordRsuper, "");
            }

            RefreshSettingsRoles();
        }


        private void API_SetChannels(string encoded)
        {
            ParseIdName(encoded, Discord.Channels);
            var valid = new HashSet<string>(Discord.Channels.Select(ch => ch[0]));
            if (valid.Count > 0)
                foreach (var key in new[] { "d.cbans", "d.cchat", "d.cact", "d.cerr" })
                {
                    var v = DiscordInput(key);
                    if (v.Length > 0 && !valid.Contains(v))
                        SetInput(0, key, "");
                }

            RefreshSettingsRoles();
        }

        private void API_SetGuilds(string encoded)
        {
            ParseIdName(encoded, Discord.Guilds);
            RefreshSettingsRoles();
        }

        private void API_SetBotStatus(string status)
        {
            _botStatus = Enum.TryParse<BotStatus>(status, true, out var st) ? st : BotStatus.Offline;
            foreach (var b in BasePlayer.activePlayerList)
                if (b != null && GetPage(b) == "settings" && PeekAdmin(b.userID)?.OpenDropdown == null &&
                    (PeekAdmin(b.userID)?.Popup ?? 0) == 0)
                    RefreshSettings(b);
        }

        private string API_Kick(string nick, string reason, string by, string comment = "")
        {
            if (string.IsNullOrWhiteSpace(nick))
                return "No player specified.";
            nick = nick.Trim();
            if (string.IsNullOrWhiteSpace(reason))
                reason = "Kicked from Discord";
            reason = reason.Trim();
            if (string.IsNullOrWhiteSpace(by))
                by = "Discord";

            var target = BasePlayer.Find(nick);
            if (target == null)
                return "Player '" + nick + "' not found online.";

            var name = target.displayName;
            var full = string.IsNullOrWhiteSpace(comment) ? reason : reason + " | " + comment.Trim();
            AddLog(LogCategory.Cmd, "[Discord] " + by + ": kicked " + name + " (" + full + ")");
            DiscordEvent("d.s1", "d.hbans", GetLocalizedMessage(TranslateKey.DiscordMessageKick, null),
                "**" + DiscordUser(target) + "** · " + full + "\n" +
                GetLocalizedMessage(TranslateKey.DiscordMessageBy, null) +
                " " + by + " (Discord)",
                target.UserIDString);
            target.Kick(reason);
            return "Kicked " + name + " (" + full + ").";
        }

        private string API_Mute(string nick, string duration, string reason, string by, string comment = "")
        {
            if (string.IsNullOrWhiteSpace(nick))
                return "No player specified.";
            nick = nick.Trim();
            if (string.IsNullOrWhiteSpace(by))
                by = "Discord";

            ulong targetId;
            string name;
            if (ulong.TryParse(nick, out var sid))
            {
                targetId = sid;
                name = GetDropdownEntry(sid).DisplayName;
            }
            else
            {
                var target = BasePlayer.Find(nick);
                if (target == null)
                    return "Player '" + nick + "' not found online (use a steamid to mute offline).";
                targetId = target.userID;
                name = target.displayName;
            }

            if (IsMuted(targetId))
                return name + " is already muted.";
            var dur = ParseDuration(duration);
            if (dur < 0)
                dur = 0;
            ApplyMute(null, targetId, name, reason, dur, comment, by);
            var durTxt = dur == 0 ? GetLocalizedMessage(TranslateKey.MutePerm, null) : FormatDuration(dur);
            return "Muted " + name + " (" + durTxt + ").";
        }

        #endregion
    }
}
